INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95691, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "只差一点就发生了，但是没有发生。", "primary_collocate": null, "pronunciation": "chà diǎn", "ipa": "ʈʂʰa˥˩ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "车来得太快，他差点就撞到了。", "target_word": "差点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我差点就赶上最后一班车。", "target_word": "差点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子差点掉到地上。", "target_word": "差点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她差点说出了那个秘密。", "target_word": "差点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他差点就把电脑摔了。", "target_word": "差点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗差点跑到马路上去。", "target_word": "差点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他差点就当上了经理。", "target_word": "差点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛最后，我们差点赢了。", "target_word": "差点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚我差点睡过头。", "target_word": "差点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门一开，猫差点跑出去了。", "target_word": "差点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "差点儿", "label": "儿化"}, {"form": "差點", "label": "繁体"}], "register": "口语", "sense_fingerprint": "只差一点就发生，但事情没有发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13e40e28-eddb-4b26-84f8-93c953de069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95691, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "差点", "is_correct": true, "explanation": "正确。差点表示车险些撞上但实际没有撞上；“差点就撞到了”是常见的固定说法。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作正在进行，与已经发生的“撞到了”矛盾。"}, {"text": "将", "is_correct": false, "explanation": "体貌：“将”表示将要发生，与已经发生的“撞到了”冲突。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰形容词或心理状态，不能直接修饰“撞到”这类动作。"}], "explanations": {"差点": "正确。差点表示车险些撞上但实际没有撞上；“差点就撞到了”是常见的固定说法。", "正在": "体貌：“正在”表示动作正在进行，与已经发生的“撞到了”矛盾。", "将": "体貌：“将”表示将要发生，与已经发生的“撞到了”冲突。", "很": "搭配：“很”修饰形容词或心理状态，不能直接修饰“撞到”这类动作。"}, "sentence_index": 0, "correct_answer": "差点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他差点把这张桌子搬走了，结果桌子真的被搬走了。", "explanation": "“差点”表示险些搬走却没有搬走，后面“真的被搬走了”说明已经发生，两者矛盾；表示已经发生应改用〈终于〉。"}, {"text": "我差点说出了那件事，最后真的说出来了。", "explanation": "“差点”表示险些说出却没有说出，后面“真的说出来了”说明已经发生，两者矛盾；表示已经发生应改用〈终于〉。"}, {"text": "他差点把窗户关上了，但窗户已经关上了。", "explanation": "“差点”表示险些关上却没有关上，后面“已经关上了”说明已经发生，前后矛盾；应改用〈早已〉表示已经发生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d869df1-ec3e-4030-9f24-3c0998b1eb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95691, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "差点", "is_correct": true, "explanation": "正确。差点表示只差一点就当上了经理但没有当上，符合语境。"}, {"text": "千万", "is_correct": false, "explanation": "搭配：“千万”多用于叮嘱或劝阻，不能用在已经发生的“当上经理”前面。"}, {"text": "一定", "is_correct": false, "explanation": "语义：“一定”表示确定会发生，与“差点就当上”所表达的未成功之意相反。"}, {"text": "依然", "is_correct": false, "explanation": "语义：“依然”表示状态延续，与“当上经理”这种一次性的变化不合。"}], "explanations": {"差点": "正确。差点表示只差一点就当上了经理但没有当上，符合语境。", "千万": "搭配：“千万”多用于叮嘱或劝阻，不能用在已经发生的“当上经理”前面。", "一定": "语义：“一定”表示确定会发生，与“差点就当上”所表达的未成功之意相反。", "依然": "语义：“依然”表示状态延续，与“当上经理”这种一次性的变化不合。"}, "sentence_index": 6, "correct_answer": "差点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们差点解散了这支队伍，结果队伍真的解散了。", "explanation": "“差点”表示险些解散却没有解散，后面“真的解散了”说明已经发生，两者矛盾；表示已经发生应改用〈终于〉。"}, {"text": "门一开，猫差点跑出去了，结果它真的跑出去了。", "explanation": "“差点”表示险些跑出去却没有跑，后面“真的跑出去了”说明已经发生，两者矛盾；表示已经发生应改用〈早已〉。"}, {"text": "我差点把成绩单交上去了，结果成绩单已经交上去了。", "explanation": "“差点”表示险些交上却没有交，后面“已经交上去了”说明已经发生，前后矛盾；应改用〈早已〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d869df1-ec3e-4030-9f24-3c0998b1eb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95691, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我差点了赶不上末班车。", "corrected_sentence": "我差点赶不上末班车。", "error_description": "错误形式是“差点了赶不上”，正确形式是“差点赶不上”。“差点”表示事情没有发生，后面不能加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d869df1-ec3e-4030-9f24-3c0998b1eb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95691, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她差点差点拿到那份工作，最后却落选了。", "corrected_sentence": "她差点拿到那份工作，最后却落选了。", "error_description": "错误形式是“差点差点拿到”，正确形式是“差点拿到”。“差点”只能出现一次，重复使用不符合语法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d869df1-ec3e-4030-9f24-3c0998b1eb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
