INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95693, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人们去拜神或佛的房子。", "primary_collocate": null, "pronunciation": "miào", "ipa": "miɑʊ̯˥˩", "syllable_count": 1, "sentences": [{"text": "新年的时候，很多人去庙里拜佛。", "target_word": "庙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座庙在河边，人们常去那里。", "target_word": "庙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我奶奶每个月都去庙里烧香。", "target_word": "庙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个庙不大，但是很干净。", "target_word": "庙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在庙里为家人祈祷。", "target_word": "庙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里有一座小庙，我们路过时进去看了看。", "target_word": "庙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "庙里很安静，大家都小声说话。", "target_word": "庙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们走了一个小时才到那座庙。", "target_word": "庙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从我家到庙只要十分钟。", "target_word": "庙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座庙里的老人给我们倒了茶。", "target_word": "庙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "廟", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人们去拜神或佛的房子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d8c84b-ccc7-4628-aee4-528ffa806d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95693, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "庙", "is_correct": true, "explanation": "正确。庙：人们去拜神或拜佛的房子。"}, {"text": "闹", "is_correct": false, "explanation": "nào 与 miào 声母不同（n 与 m），意思是吵闹，不是庙。"}, {"text": "秒", "is_correct": false, "explanation": "miǎo（第三声）与 miào（第四声）声调不同，意思是时间单位“秒”，不是庙。"}, {"text": "掉", "is_correct": false, "explanation": "diào 与 miào 声母不同（d 与 m），意思是掉落，不是庙。"}, {"text": "面", "is_correct": false, "explanation": "miàn 与 miào 韵母不同（-an 与 -ao），意思是面条或脸面，不是庙。"}], "explanations": {"庙": "正确。庙：人们去拜神或拜佛的房子。", "闹": "nào 与 miào 声母不同（n 与 m），意思是吵闹，不是庙。", "秒": "miǎo（第三声）与 miào（第四声）声调不同，意思是时间单位“秒”，不是庙。", "掉": "diào 与 miào 声母不同（d 与 m），意思是掉落，不是庙。", "面": "miàn 与 miào 韵母不同（-an 与 -ao），意思是面条或脸面，不是庙。"}, "sentence_index": null, "correct_answer": "庙"}, "level_3": {"options": [{"text": "庙", "is_correct": true, "explanation": "正确。庙是拜佛的地方，“去……里拜佛”与庙相合。"}, {"text": "教堂", "is_correct": false, "explanation": "搭配：“拜佛”的场所是庙，教堂是基督教场所，不说“去教堂里拜佛”。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市是购物的地方，不是拜佛的场所。"}, {"text": "饭馆", "is_correct": false, "explanation": "语义：饭馆是吃饭的地方，不能用来拜佛。"}], "explanations": {"庙": "正确。庙是拜佛的地方，“去……里拜佛”与庙相合。", "教堂": "搭配：“拜佛”的场所是庙，教堂是基督教场所，不说“去教堂里拜佛”。", "超市": "语义：超市是购物的地方，不是拜佛的场所。", "饭馆": "语义：饭馆是吃饭的地方，不能用来拜佛。"}, "sentence_index": 0, "correct_answer": "庙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这颗庙不大，但是很干净。", "explanation": "这里不宜用〈颗〉，庙可用〈座〉或〈个〉。“颗”用于小而圆的东西，如珠子、果实，庙不用“颗”。"}, {"text": "这片庙在河边，人们常去那里。", "explanation": "这里不宜用〈片〉，庙可用〈座〉或〈个〉。“片”用于平而薄的东西，如叶子、云，庙不用“片”。"}, {"text": "这支庙不大，但是很干净。", "explanation": "这里不宜用〈支〉，庙可用〈座〉或〈个〉。“支”用于细长的物件，如笔、香，庙不用“支”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95693, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "庙", "is_correct": true, "explanation": "正确。庙：人们去拜神或拜佛的房子。"}, {"text": "苗", "is_correct": false, "explanation": "miáo（第二声）与 miào（第四声）声调不同，意思是幼苗，不是庙。"}, {"text": "报", "is_correct": false, "explanation": "bào 与 miào 声母不同（b 与 m），意思是报纸或报告，不是庙。"}, {"text": "票", "is_correct": false, "explanation": "piào 与 miào 声母不同（p 与 m），意思是票据，不是庙。"}, {"text": "描", "is_correct": false, "explanation": "miáo（第二声）与 miào（第四声）声调不同，意思是描画，不是庙。"}], "explanations": {"庙": "正确。庙：人们去拜神或拜佛的房子。", "苗": "miáo（第二声）与 miào（第四声）声调不同，意思是幼苗，不是庙。", "报": "bào 与 miào 声母不同（b 与 m），意思是报纸或报告，不是庙。", "票": "piào 与 miào 声母不同（p 与 m），意思是票据，不是庙。", "描": "miáo（第二声）与 miào（第四声）声调不同，意思是描画，不是庙。"}, "sentence_index": null, "correct_answer": "庙"}, "level_3": {"options": [{"text": "庙", "is_correct": true, "explanation": "正确。庙是可以安静的宗教场所，与“很安静，大家都小声说话”相合。"}, {"text": "工地", "is_correct": false, "explanation": "语义：工地机器声响大，与“很安静”“小声说话”冲突。"}, {"text": "游乐场", "is_correct": false, "explanation": "语义：游乐场人多、声音大，不会很安静，与句意冲突。"}, {"text": "猫", "is_correct": false, "explanation": "搭配：“……里”要求是能容纳人或事物的处所，猫不是处所。"}], "explanations": {"庙": "正确。庙是可以安静的宗教场所，与“很安静，大家都小声说话”相合。", "工地": "语义：工地机器声响大，与“很安静”“小声说话”冲突。", "游乐场": "语义：游乐场人多、声音大，不会很安静，与句意冲突。", "猫": "搭配：“……里”要求是能容纳人或事物的处所，猫不是处所。"}, "sentence_index": 6, "correct_answer": "庙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家附近有一朵庙，人们常去那里。", "explanation": "这里应该用〈座〉。“朵”用于花、云等，庙不用“朵”。"}, {"text": "那根庙很高，人们常在它下面拍照。", "explanation": "这里应该用〈座〉。“根”用于细长的东西，如柱子、绳子，庙不用“根”。"}, {"text": "那台庙很旧，人们还在那里烧香。", "explanation": "这里应该用〈座〉。“台”用于机器和设备，庙不用“台”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95693, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们每年冬天都庙里许愿。", "corrected_sentence": "他们每年冬天都在庙里许愿。", "error_description": "介词错误：表示处所的“庙里”前要加介词“在”，应说“在庙里许愿”，不能说“庙里许愿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95693, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们走到前庙，才发现门关了。", "corrected_sentence": "我们走到庙前，才发现门关了。", "error_description": "方位词位置错误：表示“庙的前面”要说“庙前”，不能说“前庙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
