INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95694, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供奉神佛或祖先的建筑。", "primary_collocate": null, "pronunciation": "miào", "ipa": "miɑʊ̯˥˩", "syllable_count": 1, "sentences": [{"text": "山上有一座很老的庙。", "target_word": "庙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座庙里供着一尊佛。", "target_word": "庙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的人每年都去庙里拜神。", "target_word": "庙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座庙里的和尚每天早上敲钟。", "target_word": "庙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座庙是为了纪念祖先才盖的。", "target_word": "庙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在山下的庙前拍了照。", "target_word": "庙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座庙的门很大，也很旧。", "target_word": "庙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "庙里有很多人在烧香。", "target_word": "庙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座庙已经有五百年的历史了。", "target_word": "庙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷小时候常去那个庙。", "target_word": "庙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "廟", "label": "繁体"}], "register": "中性", "sense_fingerprint": "供奉神佛或祖先的建筑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d8c84b-ccc7-4628-aee4-528ffa806d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95694, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "庙", "is_correct": true, "explanation": "正确。庙：供奉神佛或祖先的建筑。"}, {"text": "苗", "is_correct": false, "explanation": "miáo（第二声）与 miào（第四声）声调不同，意思是幼苗，不是庙。"}, {"text": "秒", "is_correct": false, "explanation": "miǎo（第三声）与 miào（第四声）声调不同，意思是时间单位“秒”，不是庙。"}, {"text": "票", "is_correct": false, "explanation": "piào 与 miào 声母不同（p 与 m），意思是票据，不是庙。"}, {"text": "掉", "is_correct": false, "explanation": "diào 与 miào 声母不同（d 与 m），意思是掉落，不是庙。"}], "explanations": {"庙": "正确。庙：供奉神佛或祖先的建筑。", "苗": "miáo（第二声）与 miào（第四声）声调不同，意思是幼苗，不是庙。", "秒": "miǎo（第三声）与 miào（第四声）声调不同，意思是时间单位“秒”，不是庙。", "票": "piào 与 miào 声母不同（p 与 m），意思是票据，不是庙。", "掉": "diào 与 miào 声母不同（d 与 m），意思是掉落，不是庙。"}, "sentence_index": null, "correct_answer": "庙"}, "level_3": {"options": [{"text": "庙", "is_correct": true, "explanation": "正确。庙是供奉神佛的建筑，可用量词“座”，与“山上”“很老”相合。"}, {"text": "猫", "is_correct": false, "explanation": "搭配：量词“座”用于山、建筑等，不用于动物，应说“只”。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是现代器械，不会是山上很老的古建筑。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：量词“座”不用于椅子，应说“把”。"}], "explanations": {"庙": "正确。庙是供奉神佛的建筑，可用量词“座”，与“山上”“很老”相合。", "猫": "搭配：量词“座”用于山、建筑等，不用于动物，应说“只”。", "电脑": "语义：电脑是现代器械，不会是山上很老的古建筑。", "椅子": "搭配：量词“座”不用于椅子，应说“把”。"}, "sentence_index": 0, "correct_answer": "庙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "后山有一只很老的庙。", "explanation": "这里应该用〈座〉。庙是建筑，量词用“座”；“只”多用于动物和小件物品，不能用于庙。"}, {"text": "村口有一条很老的庙。", "explanation": "这里应该用〈座〉。“条”用于细长的东西，如河、路、鱼，庙不用“条”。"}, {"text": "村口有一张很老的庙。", "explanation": "这里应该用〈座〉。“张”用于平面的东西，如桌子、纸，庙不用“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
