INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95695, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在心里面。", "primary_collocate": null, "pronunciation": "xīn xià", "ipa": "ɕin˥ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "他心下盘算着明天的事。", "target_word": "心下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我心下记着你的话，一直没忘。", "target_word": "心下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心下想了很久，还是决定去。", "target_word": "心下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李心下暗想，这个人我见过。", "target_word": "心下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心下默默地数着数字。", "target_word": "心下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人心下感谢，嘴上却只说了声好。", "target_word": "心下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我心下嘀咕，他今天怎么这么晚。", "target_word": "心下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心下打定主意，明天就去找老板。", "target_word": "心下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子心下害怕，不敢说话。", "target_word": "心下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心下一直想着那次旅行。", "target_word": "心下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "心下：在心里面，表示想法、打算、情绪只在内心活动而没有说出口", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc47c301-ed4a-4c66-ad41-95bf2b4b9f5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95695, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心下", "is_correct": true, "explanation": "“心下”表示在心里面，与“盘算”搭配，符合句意。"}, {"text": "大声", "is_correct": false, "explanation": "搭配：“大声”修饰说、喊，不能修饰“盘算”。"}, {"text": "脚下", "is_correct": false, "explanation": "语义：“脚下”是地面的位置，不能用来表示心里的盘算。"}, {"text": "手上", "is_correct": false, "explanation": "语义：“手上”不能表示心里的盘算，“手上盘算”说不通。"}], "explanations": {"心下": "“心下”表示在心里面，与“盘算”搭配，符合句意。", "大声": "搭配：“大声”修饰说、喊，不能修饰“盘算”。", "脚下": "语义：“脚下”是地面的位置，不能用来表示心里的盘算。", "手上": "语义：“手上”不能表示心里的盘算，“手上盘算”说不通。"}, "sentence_index": 0, "correct_answer": "心下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子的心下摆着一张大桌子。", "explanation": "这里应该用〈中心〉。“心下”指在心里面，不能指空间的中间位置。"}, {"text": "我的心下压力很大，需要放松。", "explanation": "这里应该用〈心里〉。“心下”只作状语表示在心里面，不能加“的”当作名词来用。"}, {"text": "我唯一的心下是家人平安。", "explanation": "这里应该用〈心愿〉。“心下”只表示在心里面，不能充当“心愿”这样的名词作主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95695, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心下", "is_correct": true, "explanation": "“心下”表示在心里面，与“嘀咕”搭配，符合句意：我心里暗自抱怨。"}, {"text": "脸上", "is_correct": false, "explanation": "体貌：“脸上”指外表，不能说“脸上嘀咕”。"}, {"text": "桌子上", "is_correct": false, "explanation": "语义：嘀咕是心里的念头，不能放在桌子上，句意说不通。"}, {"text": "眼前", "is_correct": false, "explanation": "语义：“眼前”指视线所及的位置，不能用来表示心里嘀咕。"}], "explanations": {"心下": "“心下”表示在心里面，与“嘀咕”搭配，符合句意：我心里暗自抱怨。", "脸上": "体貌：“脸上”指外表，不能说“脸上嘀咕”。", "桌子上": "语义：嘀咕是心里的念头，不能放在桌子上，句意说不通。", "眼前": "语义：“眼前”指视线所及的位置，不能用来表示心里嘀咕。"}, "sentence_index": 6, "correct_answer": "心下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这束花是我的一点心下，请收下。", "explanation": "这里应该用〈心意〉。“心下”只表示在心里面，不能当作表示情意的名词用。"}, {"text": "这块木板的心下裂了一条缝。", "explanation": "这里应该用〈中间〉。“心下”只表示在心里面，不能指物体的中间部位。"}, {"text": "他心下大声说：“我不同意！”", "explanation": "这里应该用〈当面〉。“心下”指只在心里面、没有说出口，不能和“大声说”一起用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95695, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家心下地都很着急，却没人说话。", "corrected_sentence": "大家心下都很着急，却没人说话。", "error_description": "错误形式：“心下”后多加了“地”。正确形式：“大家心下都很着急”。“心下”作状语，后面不加“地”，应紧接在“都”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95695, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他心下的一直记挂着那次旅行。", "corrected_sentence": "他心下一直记挂着那次旅行。", "error_description": "助词错误：“心下”是状语，后面不能加“的”，应说“他心下一直记挂着那次旅行”，不能说“他心下的一直记挂着那次旅行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
