INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95696, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心里。", "primary_collocate": null, "pronunciation": "xīn xià", "ipa": "ɕin˥ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "他心下很高兴，脸上却没有笑。", "target_word": "心下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了这话，我心下一惊。", "target_word": "心下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心下明白，这件事不能再等了。", "target_word": "心下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没说话，心下却很不满意。", "target_word": "心下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嘴上不说，心下早就有了主意。", "target_word": "心下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到孩子回来，妈妈心下才放心。", "target_word": "心下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我心下想，他一定是忘了。", "target_word": "心下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心下难过，却不想让别人知道。", "target_word": "心下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心下暗暗高兴，没有告诉朋友。", "target_word": "心下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到那个消息，大家心下都很害怕。", "target_word": "心下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "心下：指内心，常作状语，放在动词或形容词前，表示心里怎么想、怎么感受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc47c301-ed4a-4c66-ad41-95bf2b4b9f5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95696, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心下", "is_correct": true, "explanation": "“心下”表示在心里面，句意是心里很高兴，脸上却没有笑，符合句意。"}, {"text": "手里", "is_correct": false, "explanation": "语义：高兴不能存放在手里，“手里很高兴”说不通。"}, {"text": "桌子上", "is_correct": false, "explanation": "语义：高兴不能放在桌子上，“桌子上很高兴”说不通。"}, {"text": "身上", "is_correct": false, "explanation": "体貌：“身上”指身体的外表，不能表示心里的高兴。"}], "explanations": {"心下": "“心下”表示在心里面，句意是心里很高兴，脸上却没有笑，符合句意。", "手里": "语义：高兴不能存放在手里，“手里很高兴”说不通。", "桌子上": "语义：高兴不能放在桌子上，“桌子上很高兴”说不通。", "身上": "体貌：“身上”指身体的外表，不能表示心里的高兴。"}, "sentence_index": 0, "correct_answer": "心下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子的心下坏了，要修一修。", "explanation": "这里应该用〈中间〉。“心下”只表示在心里面，不能指物体的中间部位。"}, {"text": "他的心下很健康，不容易被打倒。", "explanation": "这里应该用〈心理〉。“心下”只表示在心里面，不能修饰“很健康”这样的状态。"}, {"text": "这份礼物是我的一点心下。", "explanation": "这里应该用〈心意〉。“心下”只表示在心里面，不能当作表示情意的名词用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95696, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心下", "is_correct": true, "explanation": "“心下”表示在心里面，与“想”搭配，符合句意：我心里这样想。"}, {"text": "嘴里", "is_correct": false, "explanation": "语义：嘴里是说话的地方，“嘴里想”说不通。"}, {"text": "大声", "is_correct": false, "explanation": "搭配：“大声”修饰说、喊，不能修饰“想”。"}, {"text": "地上", "is_correct": false, "explanation": "语义：“地上”是位置，不能表示心里的想法，“地上想”说不通。"}], "explanations": {"心下": "“心下”表示在心里面，与“想”搭配，符合句意：我心里这样想。", "嘴里": "语义：嘴里是说话的地方，“嘴里想”说不通。", "大声": "搭配：“大声”修饰说、喊，不能修饰“想”。", "地上": "语义：“地上”是位置，不能表示心里的想法，“地上想”说不通。"}, "sentence_index": 6, "correct_answer": "心下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子摔了一跤，心下被撞得很疼。", "explanation": "这里的“心下”指心窝，即心口下方的部位，与“在心里面”不是同一个意思。"}, {"text": "院子的心下有一棵大树，很多人来乘凉。", "explanation": "这里应该用〈中间〉。“心下”只表示在心里面，不能指空间的中间位置。"}, {"text": "今天我的心下很好。", "explanation": "这里应该用〈心情〉。“心下”只表示在心里面，不能修饰“很好”这样的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95696, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他心下地很着急，却没有说出来。", "corrected_sentence": "他心下很着急，却没有说出来。", "error_description": "错误形式：“心下”后多加了“地”。正确形式：“他心下很着急”。“心下”作状语，后面不加“地”，直接放在“很”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95696, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她心下的一直惦记着孩子。", "corrected_sentence": "她心下一直惦记着孩子。", "error_description": "助词错误：“心下”是状语，后面不能加“的”，应说“她心下一直惦记着孩子”，不能说“她心下的一直惦记着孩子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95697, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
