INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95698, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "击败；使倒下。", "primary_collocate": null, "pronunciation": "dǎ dǎo", "ipa": "ta˨˩˦ tau̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "那次失败没有打倒他，他又站了起来。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想打倒所有的对手，拿第一名。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，小王打倒了去年的冠军。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "困难没能打倒他，他还是笑着生活。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能被这点困难打倒。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生活中的困难从来没有打倒过他。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么多困难都没有打倒她。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小公司想打倒大公司，不太容易。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病不会打倒他的，他很有信心。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我要打倒他，拿回我的第一名。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打倒了", "label": "完成体"}, {"form": "打倒过", "label": "经历体"}, {"form": "打不倒", "label": "可能补语（否定）"}], "register": "中性", "sense_fingerprint": "打倒：在比赛、竞争或困境中击败对方，使其失败", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25ffb014-c98c-44e0-81a7-bd5a6b2f207a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95698, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打倒", "is_correct": true, "explanation": "正确：“打倒”在比赛或竞争中指击败对方。"}, {"text": "打到", "is_correct": false, "explanation": "dào（第四声）与 dǎo（第三声）声调不同，意思是“打中、击到某处”，不是“击败对方”。"}, {"text": "达到", "is_correct": false, "explanation": "dá（第二声）与 dǎ（第三声）、dào（第四声）与 dǎo（第三声）声调都不同，意思是“达到某个标准或地点”。"}, {"text": "大道", "is_correct": false, "explanation": "dà（第四声）与 dǎ（第三声）、dào（第四声）与 dǎo（第三声）声调都不同，意思是“宽阔的道路”。"}, {"text": "打好", "is_correct": false, "explanation": "hǎo 与 dǎo 的声母不同（h 与 d），意思是“做得好、练好”。"}], "explanations": {"打倒": "正确：“打倒”在比赛或竞争中指击败对方。", "打到": "dào（第四声）与 dǎo（第三声）声调不同，意思是“打中、击到某处”，不是“击败对方”。", "达到": "dá（第二声）与 dǎ（第三声）、dào（第四声）与 dǎo（第三声）声调都不同，意思是“达到某个标准或地点”。", "大道": "dà（第四声）与 dǎ（第三声）、dào（第四声）与 dǎo（第三声）声调都不同，意思是“宽阔的道路”。", "打好": "hǎo 与 dǎo 的声母不同（h 与 d），意思是“做得好、练好”。"}, "sentence_index": null, "correct_answer": "打倒"}, "level_3": {"options": [{"text": "打倒", "is_correct": true, "explanation": "正确：“打倒”在这里指失败使人垮掉，与“又站了起来”相呼应。"}, {"text": "打印", "is_correct": false, "explanation": "语义：“打印”指把文字印在纸上，用于人说不通。"}, {"text": "打湿", "is_correct": false, "explanation": "语义：“打湿”表示使物体沾水，与“失败”无关，说不通。"}, {"text": "打招呼", "is_correct": false, "explanation": "配价：“打招呼”不能直接带“他”作宾语，要说“跟他打招呼”。"}], "explanations": {"打倒": "正确：“打倒”在这里指失败使人垮掉，与“又站了起来”相呼应。", "打印": "语义：“打印”指把文字印在纸上，用于人说不通。", "打湿": "语义：“打湿”表示使物体沾水，与“失败”无关，说不通。", "打招呼": "配价：“打招呼”不能直接带“他”作宾语，要说“跟他打招呼”。"}, "sentence_index": 0, "correct_answer": "打倒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他自己不小心打倒了。", "explanation": "这里应该用〈摔倒〉。〈打倒〉需要有施事把别人击倒，不能用于自己跌倒。"}, {"text": "他想办法打倒了局面。", "explanation": "这里应该用〈打开〉。局面可以打开、打破，不能说打倒局面。"}, {"text": "这家公司打倒了一个新的市场。", "explanation": "这里应该用〈打开〉。市场可以打开，不能说打倒市场；〈打倒〉的宾语是对手或困难。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95698, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打开", "is_correct": false, "explanation": "语义：“打开”表示使闭合的东西张开，用于对手说不通。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：“打碎”多接“希望”“计划”“纪录”等，直接接“对手”不通。"}, {"text": "打盹", "is_correct": false, "explanation": "配价：“打盹”是不及物动词，不能带“对手”作宾语。"}, {"text": "打倒", "is_correct": true, "explanation": "正确：“打倒”指困难使人垮掉；“没有打倒她”表示她没有被困难击败。"}], "explanations": {"打开": "语义：“打开”表示使闭合的东西张开，用于对手说不通。", "打碎": "搭配：“打碎”多接“希望”“计划”“纪录”等，直接接“对手”不通。", "打盹": "配价：“打盹”是不及物动词，不能带“对手”作宾语。", "打倒": "正确：“打倒”指困难使人垮掉；“没有打倒她”表示她没有被困难击败。"}, "sentence_index": 6, "correct_answer": "打倒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一拳把那只气球打倒了。", "explanation": "这里应该用〈打爆〉。气球被击打会爆裂，不会倒下；〈打倒〉的宾语应是人或困难。"}, {"text": "大家终于打倒了沉默。", "explanation": "这里应该用〈打破〉。沉默可以打破，不能说打倒沉默。"}, {"text": "他想了很久，终于打倒了一个好办法。", "explanation": "这里应该用〈想出〉。办法是想出来的，不能说打倒办法；〈打倒〉的宾语是对手或困难。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这点困难打不倒了他，他还是很乐观。", "corrected_sentence": "这点困难打不倒他，他还是很乐观。", "error_description": "可能补语「打不倒」已表示无法击倒，后面不能再加表示完成的「了」，说「打不倒了他」自相矛盾，应去掉「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次失败没有他打倒。", "corrected_sentence": "这次失败没有把他打倒。", "error_description": "“把”字句要用“把”引出宾语，应说“没有把他打倒”；这里漏掉了“把”，句子不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95699, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95699, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95699, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "很多人抢着说价钱，谁说得最高，东西就卖给谁。", "primary_collocate": null, "pronunciation": "pāi mài", "ipa": "pʰaɪ̯˥ maɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "那幅画拍卖的时候，很多人一直喊价。", "target_word": "拍卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天他们拍卖一张旧桌子，价钱越喊越高。", "target_word": "拍卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的手表拍卖时，有三个人抢着要。", "target_word": "拍卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说下周我们班要拍卖旧书。", "target_word": "拍卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在广场上拍卖水果，谁出的钱多就给谁。", "target_word": "拍卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具太受欢迎了，只能拍卖。", "target_word": "拍卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次看人拍卖东西，觉得很有意思。", "target_word": "拍卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想拍卖那块表，看看谁给的钱最多。", "target_word": "拍卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们一起拍卖自己不用的衣服。", "target_word": "拍卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张老照片拍卖的价格是一千块钱。", "target_word": "拍卖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拍卖了", "label": "体标"}, {"form": "拍卖过", "label": "体标"}, {"form": "拍賣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "众人抢着喊价，价高者得", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d8c84b-ccc7-4628-aee4-528ffa806d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95699, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拍卖", "is_correct": true, "explanation": "正确。“那幅画拍卖的时候，很多人一直喊价”，拍卖指众人抢价。"}, {"text": "修复", "is_correct": false, "explanation": "语义：修复是修理损坏的东西，不涉及一直喊价。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：欣赏时不会一直喊价，与句中的喊价不合。"}, {"text": "雕刻", "is_correct": false, "explanation": "语义：雕刻是用刀在木头、石头上刻东西，与“很多人一直喊价”不合。"}], "explanations": {"拍卖": "正确。“那幅画拍卖的时候，很多人一直喊价”，拍卖指众人抢价。", "修复": "语义：修复是修理损坏的东西，不涉及一直喊价。", "欣赏": "语义：欣赏时不会一直喊价，与句中的喊价不合。", "雕刻": "语义：雕刻是用刀在木头、石头上刻东西，与“很多人一直喊价”不合。"}, "sentence_index": 0, "correct_answer": "拍卖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校把这些旧书拍卖给了孤儿院，都是免费的。", "explanation": "这里应该用〈赠送〉。拍卖要公开竞价、价高者得，白送给孤儿院应说“赠送”，“都是免费的”也与拍卖相矛盾。"}, {"text": "这家公司把旧电脑拍卖给了山区学校，一分钱也没收。", "explanation": "这里应该用〈捐助〉。拍卖要公开竞价、卖给出价最高的人，无偿资助山区学校应说“捐助”。"}, {"text": "我们在公园里拍卖了一张合影。", "explanation": "这里应该用〈拍照〉。拍卖是公开竞价卖出物品，给大家拍合影应说“拍照”，不能说“拍卖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95699, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拍卖", "is_correct": true, "explanation": "正确。“我第一次看人拍卖东西”，拍卖与“看人……东西”相合。"}, {"text": "驯养", "is_correct": false, "explanation": "搭配：“驯养”的对象是动物，不能用于东西。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”的对象是动物，不能说饲养东西。"}, {"text": "迎接", "is_correct": false, "explanation": "语义：“迎接”的对象一般是人或客人，不能说迎接东西。"}], "explanations": {"拍卖": "正确。“我第一次看人拍卖东西”，拍卖与“看人……东西”相合。", "驯养": "搭配：“驯养”的对象是动物，不能用于东西。", "饲养": "搭配：“饲养”的对象是动物，不能说饲养东西。", "迎接": "语义：“迎接”的对象一般是人或客人，不能说迎接东西。"}, "sentence_index": 6, "correct_answer": "拍卖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "有人在使劲拍卖门，把我吵醒了。", "explanation": "这里应该用〈敲〉。拍卖指公开竞价卖物，敲门要说“敲”。"}, {"text": "我们把这本书拍卖给了同学，他看完还要还给我。", "explanation": "这里应该用〈借〉。拍卖是把东西卖断，看完还要还回来应说“借”。"}, {"text": "他每个月都交房租，拍卖了一间小屋。", "explanation": "这里应该用〈出租〉。拍卖是一次性把小屋卖给出价最高的人，每月收租金应说“出租”，不能说“拍卖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95699, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们拍卖了过一张旧桌子。", "corrected_sentence": "他们拍卖过一张旧桌子。", "error_description": "体标错误：“了”和“过”不能这样连用，表示经历只用“过”，应说“拍卖过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95699, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那张老照片拍卖着一次。", "corrected_sentence": "那张老照片拍卖过一次。", "error_description": "错误：表示曾经发生过的经历要用“过”，“着”表示动作的持续，不能与“一次”搭配。应说“拍卖过一次”，不能说“拍卖着一次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
