INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95700, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95700, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "公开竞价，把物品卖给出价最高的人。", "primary_collocate": null, "pronunciation": "pāi mài", "ipa": "pʰaɪ̯˥ maɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "这幅古画明天下午要拍卖。", "target_word": "拍卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把家里的旧钟拿去拍卖了。", "target_word": "拍卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校想拍卖这些旧桌子，给孩子们买书。", "target_word": "拍卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老房子今年春天拍卖过一次。", "target_word": "拍卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行准备拍卖他没还钱的房子。", "target_word": "拍卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们拍卖了一块地，价钱很高。", "target_word": "拍卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只花瓶将在北京拍卖。", "target_word": "拍卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想拍卖我收藏的邮票。", "target_word": "拍卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要拍卖这辆旧汽车，谁出价高就卖给谁。", "target_word": "拍卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家把自己的画拿出来拍卖，钱都捐给了学校。", "target_word": "拍卖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拍卖了", "label": "体标"}, {"form": "拍卖过", "label": "体标"}, {"form": "拍賣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "公开竞价，物品卖给出价最高者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d8c84b-ccc7-4628-aee4-528ffa806d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95700, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拍卖", "is_correct": true, "explanation": "正确。“古画明天下午要拍卖”，拍卖指公开竞价卖出，与句意相合。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：古画不能跳舞，与“明天下午要”的安排不合。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：古画不会睡觉，句子说的是古画的去向。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“唱”的对象是歌，不能以“古画”为对象。"}], "explanations": {"拍卖": "正确。“古画明天下午要拍卖”，拍卖指公开竞价卖出，与句意相合。", "跳舞": "语义：古画不能跳舞，与“明天下午要”的安排不合。", "睡觉": "语义：古画不会睡觉，句子说的是古画的去向。", "唱歌": "搭配：“唱”的对象是歌，不能以“古画”为对象。"}, "sentence_index": 0, "correct_answer": "拍卖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把老房子拍卖给了朋友，说好以后还给他。", "explanation": "这里应该用〈借〉。拍卖是把东西卖断，说好以后还回来应说“借”。"}, {"text": "我们在山上拍卖了一张全家福。", "explanation": "这里应该用〈拍照〉。拍卖是公开竞价卖出物品，给全家拍照应说“拍照”，不能说“拍卖”。"}, {"text": "我把旧自行车拍卖给了邻居，我们说好一口价一百块。", "explanation": "这里应该用〈出售〉。拍卖要公开竞价、价高者得，事先说好一口价的交易应说“出售”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95700, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拍卖", "is_correct": true, "explanation": "正确。“这只花瓶将在北京拍卖”，拍卖与花瓶相合。"}, {"text": "出生", "is_correct": false, "explanation": "语义：花瓶是物品，不会出生。"}, {"text": "生病", "is_correct": false, "explanation": "语义：花瓶不会生病，与句意不合。"}, {"text": "施工", "is_correct": false, "explanation": "搭配：“施工”的主语是施工队或工程，不以“花瓶”为主语。"}], "explanations": {"拍卖": "正确。“这只花瓶将在北京拍卖”，拍卖与花瓶相合。", "出生": "语义：花瓶是物品，不会出生。", "生病": "语义：花瓶不会生病，与句意不合。", "施工": "搭配：“施工”的主语是施工队或工程，不以“花瓶”为主语。"}, "sentence_index": 6, "correct_answer": "拍卖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这本旧书拍卖给了学校，不收一分钱。", "explanation": "这里应该用〈赠送〉。拍卖要公开竞价、卖给出价最高的人，白白送给学校应说“赠送”，“不收一分钱”也与拍卖相矛盾。"}, {"text": "老师把奖品拍卖给了学生，每人一份，都是免费的。", "explanation": "这里应该用〈发〉。拍卖是公开竞价卖出物品，免费给每个学生一份奖品应说“发”。"}, {"text": "他把车库拍卖给了邻居，每月收租金。", "explanation": "这里应该用〈出租〉。拍卖是一次性把车库卖给出价最高的人，每月收租金应说“出租”，不能说“拍卖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95700, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这幅画已经拍卖了掉。", "corrected_sentence": "这幅画已经拍卖掉了。", "error_description": "补语位置错误：结果补语“掉”要紧接动词，应说“拍卖掉了”，不能说“拍卖了掉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95700, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些旧邮票下周在网上拍卖了。", "corrected_sentence": "这些旧邮票下周在网上拍卖。", "error_description": "错误：“下周”指将来，动作还没发生，不能与动态助词“了”搭配。应说“下周在网上拍卖”，不能说“下周在网上拍卖了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95701, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
