INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95703, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说话的时候，说到某件事或某个人。", "primary_collocate": null, "pronunciation": "tí jí", "ipa": "tʰi˧˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "他在会上没有提及这件事。", "target_word": "提及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲课时提及了一位老作家。", "target_word": "提及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从不在我面前提及她的过去。", "target_word": "提及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会的时候，经理提及明年的计划。", "target_word": "提及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电话里提及了你的名字。", "target_word": "提及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈很少提及自己年轻时的事。", "target_word": "提及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手在采访中提及了他的家人。", "target_word": "提及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在演讲中提及了三个新办法。", "target_word": "提及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你刚才提及的那本书叫什么名字？", "target_word": "提及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都没有提及他迟到的事。", "target_word": "提及", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提及了", "label": "体标"}, {"form": "提及过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "说话时说到某件事或某个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d8c84b-ccc7-4628-aee4-528ffa806d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95703, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "提及", "is_correct": true, "explanation": "正确答案：提及（tí jí），意思是说到某件事或某个人。"}, {"text": "体积", "is_correct": false, "explanation": "tǐ jī（第三声、第一声）与 tí jí（第二声、第二声）两个音节的声调都不同，意思是物体所占空间的大小。"}, {"text": "梯级", "is_correct": false, "explanation": "tī（第一声）与 tí（第二声）声调不同，第二音节 jí 不变，意思是台阶或等级。"}, {"text": "题记", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是题写在作品上的文字。"}, {"text": "体己", "is_correct": false, "explanation": "tǐ jǐ 与 tí jí 两个音节的声调都不同，意思是私房钱。"}], "explanations": {"提及": "正确答案：提及（tí jí），意思是说到某件事或某个人。", "体积": "tǐ jī（第三声、第一声）与 tí jí（第二声、第二声）两个音节的声调都不同，意思是物体所占空间的大小。", "梯级": "tī（第一声）与 tí（第二声）声调不同，第二音节 jí 不变，意思是台阶或等级。", "题记": "jì（第四声）与 jí（第二声）声调不同，意思是题写在作品上的文字。", "体己": "tǐ jǐ 与 tí jí 两个音节的声调都不同，意思是私房钱。"}, "sentence_index": null, "correct_answer": "提及"}, "level_3": {"options": [{"text": "出席", "is_correct": false, "explanation": "配价：“出席”要求接会议、典礼一类的场合，不能接“这件事”。"}, {"text": "提及", "is_correct": true, "explanation": "提及：说到这件事，与句意相符。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”接的是活动、比赛，不能接“这件事”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”接的是房间、场地，不能接“这件事”。"}], "explanations": {"出席": "配价：“出席”要求接会议、典礼一类的场合，不能接“这件事”。", "提及": "提及：说到这件事，与句意相符。", "举办": "搭配：“举办”接的是活动、比赛，不能接“这件事”。", "打扫": "搭配：“打扫”接的是房间、场地，不能接“这件事”。"}, "sentence_index": 0, "correct_answer": "提及"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试，我的成绩提及了十分。", "explanation": "这里应该用〈提高〉。提及是说到某件事或某个人，不能表示成绩的上升；成绩、水平的提升要用提高。"}, {"text": "这个月我的体重提及了三公斤。", "explanation": "这里应该用〈增加〉。提及不能表示重量或数量的增加，体重、人数等数量变化要用增加。"}, {"text": "他用力提及了那个沉重的箱子。", "explanation": "这里应该用〈提起〉，表示用手拿起。提及只用于说话时说到某件事，不能表示搬动东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95703, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "辞退", "is_correct": false, "explanation": "语义：“辞退”指解雇员工，不能用于采访中谈家人的语境。"}, {"text": "提及", "is_correct": true, "explanation": "提及：说到他的家人，与句意相符。"}, {"text": "设计", "is_correct": false, "explanation": "搭配：“设计”接的是方案、房屋等，不能接“家人”。"}, {"text": "逮捕", "is_correct": false, "explanation": "语义：“逮捕”指依法拘押人员，与谈家人的语境不符。"}], "explanations": {"辞退": "语义：“辞退”指解雇员工，不能用于采访中谈家人的语境。", "提及": "提及：说到他的家人，与句意相符。", "设计": "搭配：“设计”接的是方案、房屋等，不能接“家人”。", "逮捕": "语义：“逮捕”指依法拘押人员，与谈家人的语境不符。"}, "sentence_index": 6, "correct_answer": "提及"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的职位在去年提及了两级。", "explanation": "这里应该用〈提升〉。提及是说到某件事，不能表示职位的上升；职位、级别的上升要用提升。"}, {"text": "我们的火车提及了半个小时。", "explanation": "这里应该用〈提前〉。提及不能表示时间的提早，火车比原定时间早开要用提前。"}, {"text": "这次改造以后，地铁提及了三成。", "explanation": "这里应该用〈提速〉。提及不能表示速度的提高，地铁跑得更快要用提速。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95703, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在报告里没有提及了那位老师的名字。", "corrected_sentence": "他在报告里没有提及那位老师的名字。", "error_description": "错误：“没有”否定时后面不能带“了”。应说“没有提及”，不能说“没有提及了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95703, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从不提及了他的家人。", "corrected_sentence": "我从不提及他的家人。", "error_description": "错误：“从不”表示从来没有这样做过，不能与动态助词“了”搭配。应说“从不提及”，不能说“从不提及了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
