INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95706, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拾起；拿起地上的东西。", "primary_collocate": null, "pronunciation": "jiǎn", "ipa": "tɕjɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "他弯腰捡起地上的笔。", "target_word": "捡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上有一张纸，请捡起来。", "target_word": "捡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子在公园里捡树叶。", "target_word": "捡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我捡了一个红色的球。", "target_word": "捡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在路上捡到一个钱包。", "target_word": "捡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把地上的垃圾捡走。", "target_word": "捡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她蹲下来捡东西。", "target_word": "捡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗捡回了我的帽子。", "target_word": "捡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边的孩子在捡贝壳。", "target_word": "捡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我从来没捡过钱。", "target_word": "捡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "捡了", "label": "体标"}, {"form": "捡过", "label": "体标"}, {"form": "捡捡", "label": "重叠"}, {"form": "捡起来", "label": "复合"}], "register": "中性", "sense_fingerprint": "拾起地上的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '246cb159-8ced-40af-9dd4-ae34aecf1ef8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95706, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "捡", "is_correct": true, "explanation": "捡（jiǎn）：拾起地上的东西，即本词。"}, {"text": "尖", "is_correct": false, "explanation": "尖（jiān，第一声）与捡（jiǎn，第三声）声调不同，意思是“尖锐”。"}, {"text": "件", "is_correct": false, "explanation": "件（jiàn，第四声）与捡（jiǎn，第三声）声调不同，是量词，意思是“物品、事情”。"}, {"text": "讲", "is_correct": false, "explanation": "讲（jiǎng）与捡（jiǎn）韵母不同：ang 与 an 不同，意思是“讲述”。"}, {"text": "浅", "is_correct": false, "explanation": "浅（qiǎn）与捡（jiǎn）声母不同：q 与 j 不同，意思是“浅”。"}, {"text": "见", "is_correct": false, "explanation": "见（jiàn，第四声）与捡（jiǎn，第三声）声调不同，意思是“看见”。"}], "explanations": {"捡": "捡（jiǎn）：拾起地上的东西，即本词。", "尖": "尖（jiān，第一声）与捡（jiǎn，第三声）声调不同，意思是“尖锐”。", "件": "件（jiàn，第四声）与捡（jiǎn，第三声）声调不同，是量词，意思是“物品、事情”。", "讲": "讲（jiǎng）与捡（jiǎn）韵母不同：ang 与 an 不同，意思是“讲述”。", "浅": "浅（qiǎn）与捡（jiǎn）声母不同：q 与 j 不同，意思是“浅”。", "见": "见（jiàn，第四声）与捡（jiǎn，第三声）声调不同，意思是“看见”。"}, "sentence_index": null, "correct_answer": "捡"}, "level_3": {"options": [{"text": "捡", "is_correct": true, "explanation": "捡：拾起地上的东西，与“弯腰”和“地上”的语境相符。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢起”需要用脚，与“弯腰”的动作不符。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂起”指悬挂，地上的笔不能被“挂”起来。"}, {"text": "吹", "is_correct": false, "explanation": "语义：“吹”指用气流使物体飘动，与弯腰用手拾笔的情境不符。"}], "explanations": {"捡": "捡：拾起地上的东西，与“弯腰”和“地上”的语境相符。", "踢": "搭配：“踢起”需要用脚，与“弯腰”的动作不符。", "挂": "搭配：“挂起”指悬挂，地上的笔不能被“挂”起来。", "吹": "语义：“吹”指用气流使物体飘动，与弯腰用手拾笔的情境不符。"}, "sentence_index": 0, "correct_answer": "捡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我爬到树上捡了一个苹果。", "explanation": "这里应该用〈摘〉。摘指从植物上取下果实，捡指拾起掉在地上的东西。"}, {"text": "小猫捡住了那只老鼠。", "explanation": "这里应该用〈抓〉。捡只用于拾起静止地上的东西，抓住乱跑的老鼠要用抓。"}, {"text": "他捡起了摔倒的老人。", "explanation": "这里应该用〈扶〉。捡用于拾起物品，扶起摔倒的人要用扶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95706, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "捡", "is_correct": true, "explanation": "捡（jiǎn）：拾起地上的东西，即本词。"}, {"text": "肩", "is_correct": false, "explanation": "肩（jiān，第一声）与捡（jiǎn，第三声）声调不同，意思是“肩膀”。"}, {"text": "健", "is_correct": false, "explanation": "健（jiàn，第四声）与捡（jiǎn，第三声）声调不同，意思是“健康”。"}, {"text": "奖", "is_correct": false, "explanation": "奖（jiǎng）与捡（jiǎn）韵母不同：ang 与 an 不同，意思是“奖励”。"}, {"text": "险", "is_correct": false, "explanation": "险（xiǎn）与捡（jiǎn）声母不同：x 与 j 不同，意思是“危险”。"}, {"text": "建", "is_correct": false, "explanation": "建（jiàn，第四声）与捡（jiǎn，第三声）声调不同，意思是“建造”。"}], "explanations": {"捡": "捡（jiǎn）：拾起地上的东西，即本词。", "肩": "肩（jiān，第一声）与捡（jiǎn，第三声）声调不同，意思是“肩膀”。", "健": "健（jiàn，第四声）与捡（jiǎn，第三声）声调不同，意思是“健康”。", "奖": "奖（jiǎng）与捡（jiǎn）韵母不同：ang 与 an 不同，意思是“奖励”。", "险": "险（xiǎn）与捡（jiǎn）声母不同：x 与 j 不同，意思是“危险”。", "建": "建（jiàn，第四声）与捡（jiǎn，第三声）声调不同，意思是“建造”。"}, "sentence_index": null, "correct_answer": "捡"}, "level_3": {"options": [{"text": "捡", "is_correct": true, "explanation": "捡：拾起地上的东西，与“蹲下来”取物的情境相符。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”指使东西落地破碎，与“蹲下来”取物的情境相反。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌，“唱东西”不成立，句子不通。"}, {"text": "掀", "is_correct": false, "explanation": "搭配：“掀”多用于揭开盖子、被子等覆盖物，不能泛指“东西”。"}], "explanations": {"捡": "捡：拾起地上的东西，与“蹲下来”取物的情境相符。", "摔": "语义：“摔”指使东西落地破碎，与“蹲下来”取物的情境相反。", "唱": "搭配：“唱”的对象是歌，“唱东西”不成立，句子不通。", "掀": "搭配：“掀”多用于揭开盖子、被子等覆盖物，不能泛指“东西”。"}, "sentence_index": 6, "correct_answer": "捡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把那张大沙发捡到了楼上。", "explanation": "这里应该用〈搬〉。捡指拾起地上的小件东西，把大件的沙发搬上楼要用搬。"}, {"text": "他把杯子里的水捡进了盆里。", "explanation": "这里应该用〈倒〉。捡用于拾取物体，水是液体，把水从杯子里转入盆里要用倒。"}, {"text": "他把钉子捡进了墙里。", "explanation": "这里应该用〈钉〉。捡指拾起东西，把钉子敲进墙里要用钉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在路边捡了到一支钢笔。", "corrected_sentence": "我在路边捡到了一支钢笔。", "error_description": "“捡了到”错误：结果补语“到”应紧跟动词，写作“捡到了”，“了”放在补语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地上的钱是我的捡。", "corrected_sentence": "地上的钱是我捡的。", "error_description": "“我的捡”错误：“的”应放在动词后，构成“我捡的”，修饰“钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
