INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95707, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一些人用力气赶走管国家的人，自己来管。", "primary_collocate": null, "pronunciation": "zhèng biàn", "ipa": "tʂɤŋ˥˩ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "那个国家昨天发生了政变。", "target_word": "政变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队发动政变，赶走了总统。", "target_word": "政变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想通过政变推翻政府，但是没有成功。", "target_word": "政变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那个小国又有人搞政变了。", "target_word": "政变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政变以后，新的领导人出现了。", "target_word": "政变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场政变只用了一个晚上。", "target_word": "政变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写了一次很有名的政变。", "target_word": "政变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政变发生时，很多人躲在家里。", "target_word": "政变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位国王因为政变离开了国家。", "target_word": "政变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们没有选举，而是用政变上台。", "target_word": "政变", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场政变", "label": "量词"}, {"form": "政變", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有人用力量赶走管国家的人，自己掌权", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '849abdb4-e94e-41e7-b194-cd99807ededa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95707, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "政变", "is_correct": true, "explanation": "正确答案：政变（zhèng biàn）。"}, {"text": "争辩", "is_correct": false, "explanation": "zhēng（第一声）与 zhèng（第四声）声调不同，意思是争辩。"}, {"text": "正面", "is_correct": false, "explanation": "miàn 与 biàn 声母不同（m 与 b），意思是正面。"}, {"text": "政见", "is_correct": false, "explanation": "jiàn 与 biàn 声母不同（j 与 b），意思是政治主张。"}], "explanations": {"政变": "正确答案：政变（zhèng biàn）。", "争辩": "zhēng（第一声）与 zhèng（第四声）声调不同，意思是争辩。", "正面": "miàn 与 biàn 声母不同（m 与 b），意思是正面。", "政见": "jiàn 与 biàn 声母不同（j 与 b），意思是政治主张。"}, "sentence_index": null, "correct_answer": "政变"}, "level_3": {"options": [{"text": "政变", "is_correct": true, "explanation": "“政变”指少数人用武力夺取政权，与“发生”搭配，符合句意。"}, {"text": "选举", "is_correct": false, "explanation": "搭配：“选举”通常说“举行”，不能说“发生”。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：婚礼是私人喜事，不能在国家层面“发生”。"}, {"text": "演唱会", "is_correct": false, "explanation": "语义：演唱会是娱乐活动，与国家层面的重大事件不符。"}], "explanations": {"政变": "“政变”指少数人用武力夺取政权，与“发生”搭配，符合句意。", "选举": "搭配：“选举”通常说“举行”，不能说“发生”。", "婚礼": "语义：婚礼是私人喜事，不能在国家层面“发生”。", "演唱会": "语义：演唱会是娱乐活动，与国家层面的重大事件不符。"}, "sentence_index": 0, "correct_answer": "政变"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "歹徒闯进银行，发动了政变，抢走了现金。", "explanation": "这里应该用〈抢劫〉。抢劫是用暴力抢夺财物，政变是用武力夺取国家政权，两者目标完全不同。"}, {"text": "两国因为边界问题爆发了政变。", "explanation": "这里应该用〈战争〉。政变是一国之内少数人夺取政权，两国因边界问题开战属于战争。"}, {"text": "当地农民发动政变，要求减免税收。", "explanation": "这里应该用〈叛乱〉。政变的目标是夺取政权；农民因税收问题反抗，属于叛乱，不是夺权。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95707, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "政变", "is_correct": true, "explanation": "正确答案：政变（zhèng biàn）。"}, {"text": "正电", "is_correct": false, "explanation": "diàn 与 biàn 声母不同（d 与 b），意思是正电。"}, {"text": "正片", "is_correct": false, "explanation": "piàn 与 biàn 声母不同（p 与 b），意思是正像的胶片。"}, {"text": "正版", "is_correct": false, "explanation": "bǎn 与 biàn 韵母、声调不同，意思是正式授权出版的版本。"}], "explanations": {"政变": "正确答案：政变（zhèng biàn）。", "正电": "diàn 与 biàn 声母不同（d 与 b），意思是正电。", "正片": "piàn 与 biàn 声母不同（p 与 b），意思是正像的胶片。", "正版": "bǎn 与 biàn 韵母、声调不同，意思是正式授权出版的版本。"}, "sentence_index": null, "correct_answer": "政变"}, "level_3": {"options": [{"text": "政变", "is_correct": true, "explanation": "“政变”是一种重大事件，可以“有名”，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的体貌特征，不是能被称为“一次很有名的”事件。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“有名”一般不修饰雨。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是身体指标，不是能被书写、被称为“有名”的事件。"}], "explanations": {"政变": "“政变”是一种重大事件，可以“有名”，符合句意。", "身高": "语义：身高是人的体貌特征，不是能被称为“一次很有名的”事件。", "雨": "搭配：“有名”一般不修饰雨。", "体温": "语义：体温是身体指标，不是能被书写、被称为“有名”的事件。"}, "sentence_index": 6, "correct_answer": "政变"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人在秋天发动政变，反抗老板的剥削。", "explanation": "这里应该用〈罢工〉。罢工是工人停工反抗老板，政变是少数人用武力夺取国家政权。"}, {"text": "学生在学校发动政变，抗议食堂涨价。", "explanation": "这里应该用〈抗议活动〉。政变的目标是夺取国家政权，学生抗议食堂涨价不是夺权。"}, {"text": "两党通过投票完成了一场政变，平稳交接了权力。", "explanation": "语义：政变必须以武力夺取政权，投票后平稳交接权力不属于政变。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95707, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "少数人想政变，夺取政权。", "corrected_sentence": "少数人想发动政变，夺取政权。", "error_description": "“政变”是名词，不能直接作谓语。错误形式：想政变；正确形式：想发动政变。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95707, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们通过一顿政变夺取了权力。", "corrected_sentence": "他们通过一场政变夺取了权力。", "error_description": "量词错误：“政变”应用“场”，不能用“顿”（“顿”用于饭食或责骂）。错误形式：一顿；正确形式：一场。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
