INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95708, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "少数人用武力夺取国家政权的行动。", "primary_collocate": null, "pronunciation": "zhèng biàn", "ipa": "tʂɤŋ˥˩ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "军方在首都发动了政变。", "target_word": "政变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场政变造成了严重的混乱。", "target_word": "政变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府宣布已经平息政变。", "target_word": "政变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政变领导人被关进了监狱。", "target_word": "政变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在书中分析了这次政变的原因。", "target_word": "政变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国政府谴责了这场政变。", "target_word": "政变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少数军官策划政变，被及时发现了。", "target_word": "政变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政变失败后，几名军官逃往国外。", "target_word": "政变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合国呼吁各方反对政变。", "target_word": "政变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次政变改变了这个国家的历史。", "target_word": "政变", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场政变", "label": "量词"}, {"form": "政變", "label": "繁体"}], "register": "书面", "sense_fingerprint": "少数人以武力夺取国家政权的行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '849abdb4-e94e-41e7-b194-cd99807ededa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95708, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "政变", "is_correct": true, "explanation": "正确答案：政变（zhèng biàn）。"}, {"text": "争辩", "is_correct": false, "explanation": "zhēng（第一声）与 zhèng（第四声）声调不同，意思是争辩。"}, {"text": "正面", "is_correct": false, "explanation": "miàn 与 biàn 声母不同（m 与 b），意思是正面。"}, {"text": "政见", "is_correct": false, "explanation": "jiàn 与 biàn 声母不同（j 与 b），意思是政治主张。"}], "explanations": {"政变": "正确答案：政变（zhèng biàn）。", "争辩": "zhēng（第一声）与 zhèng（第四声）声调不同，意思是争辩。", "正面": "miàn 与 biàn 声母不同（m 与 b），意思是正面。", "政见": "jiàn 与 biàn 声母不同（j 与 b），意思是政治主张。"}, "sentence_index": null, "correct_answer": "政变"}, "level_3": {"options": [{"text": "政变", "is_correct": true, "explanation": "“政变”指少数人以武力夺取政权，与“发动”搭配，符合句意。"}, {"text": "招聘", "is_correct": false, "explanation": "搭配：“发动”不跟“招聘”搭配。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：婚礼是私人喜事，不能被“发动”。"}, {"text": "演唱会", "is_correct": false, "explanation": "语义：演唱会是娱乐活动，与军方发动的重大行动不符。"}], "explanations": {"政变": "“政变”指少数人以武力夺取政权，与“发动”搭配，符合句意。", "招聘": "搭配：“发动”不跟“招聘”搭配。", "婚礼": "语义：婚礼是私人喜事，不能被“发动”。", "演唱会": "语义：演唱会是娱乐活动，与军方发动的重大行动不符。"}, "sentence_index": 0, "correct_answer": "政变"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "因为涨价，城里发生了政变，商店被砸了。", "explanation": "这里应该用〈暴乱〉。政变是少数人夺取政权；因物价上涨而砸店属于暴乱，不是夺权。"}, {"text": "两国因为争夺一座岛屿而发动政变。", "explanation": "这里应该用〈战争〉。政变是一国之内少数人夺取政权，两国争夺岛屿属于战争。"}, {"text": "大家投票决定换届，完成了一场政变。", "explanation": "语义：政变以武力夺权，投票换届不属于政变。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95708, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "政变", "is_correct": true, "explanation": "正确答案：政变（zhèng biàn）。"}, {"text": "正电", "is_correct": false, "explanation": "diàn 与 biàn 声母不同（d 与 b），意思是正电。"}, {"text": "正片", "is_correct": false, "explanation": "piàn 与 biàn 声母不同（p 与 b），意思是正像的胶片。"}, {"text": "正版", "is_correct": false, "explanation": "bǎn 与 biàn 韵母、声调不同，意思是正式授权出版的版本。"}], "explanations": {"政变": "正确答案：政变（zhèng biàn）。", "正电": "diàn 与 biàn 声母不同（d 与 b），意思是正电。", "正片": "piàn 与 biàn 声母不同（p 与 b），意思是正像的胶片。", "正版": "bǎn 与 biàn 韵母、声调不同，意思是正式授权出版的版本。"}, "sentence_index": null, "correct_answer": "政变"}, "level_3": {"options": [{"text": "政变", "is_correct": true, "explanation": "“政变”是军官秘密策划的夺权行动，与“策划”搭配，符合句意。"}, {"text": "彩虹", "is_correct": false, "explanation": "语义：彩虹是自然景象，不能被人“策划”。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是自然现象，不能被人“策划”。"}, {"text": "疾病", "is_correct": false, "explanation": "语义：疾病不能被人“策划”，与句中的军官行为不符。"}], "explanations": {"政变": "“政变”是军官秘密策划的夺权行动，与“策划”搭配，符合句意。", "彩虹": "语义：彩虹是自然景象，不能被人“策划”。", "地震": "语义：地震是自然现象，不能被人“策划”。", "疾病": "语义：疾病不能被人“策划”，与句中的军官行为不符。"}, "sentence_index": 6, "correct_answer": "政变"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那次政变持续了十年，人民生活很苦。", "explanation": "这里应该用〈内战〉。内战可以持续多年，政变是短时间的夺权行动。"}, {"text": "两个小偷在夜里发动了政变，偷走了一台电视。", "explanation": "这里应该用〈盗窃〉。盗窃是偷偷拿走他人财物，政变是用武力夺取国家政权，两者毫无关系。"}, {"text": "大家用抽签决定领导人，这次政变很公平。", "explanation": "语义：政变必须以武力夺取政权，抽签产生领导人不属于政变。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
