INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95708, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "军官们通过一顿政变掌握了国家权力。", "corrected_sentence": "军官们通过一场政变掌握了国家权力。", "error_description": "量词错误：“政变”应用“场”，不能用“顿”（“顿”用于饭食或责骂）。错误形式：一顿；正确形式：一场。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
