INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95711, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对人或动物很坏，一点也不心疼。", "primary_collocate": null, "pronunciation": "cán rěn", "ipa": "tsʰan˧˥ ʐən˨˩", "syllable_count": 2, "sentences": [{"text": "不给小狗吃饭，这样做太残忍了。", "target_word": "残忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一点也不心疼动物，真残忍。", "target_word": "残忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得让小猫一直关在箱子里很残忍。", "target_word": "残忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人对自己的孩子很残忍。", "target_word": "残忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事里的国王十分残忍。", "target_word": "残忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他残忍地拒绝了生病的朋友。", "target_word": "残忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说，打骂孩子是残忍的。", "target_word": "残忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到猫受伤，他还笑，太残忍了。", "target_word": "残忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对小动物残忍的人，我不愿和他交朋友。", "target_word": "残忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种残忍的游戏，应该禁止。", "target_word": "残忍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "殘忍", "label": "繁体"}, {"form": "残忍地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "对人或动物很坏、一点不心疼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a65ce783-209c-496d-8375-67116e6f7c33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95711, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "残忍", "is_correct": true, "explanation": "残忍形容狠毒、不心疼，与“不给小狗吃饭，这样做太……了”的语境相符。"}, {"text": "可爱", "is_correct": false, "explanation": "语义：“可爱”与“不给小狗吃饭”的行为相矛盾。"}, {"text": "精彩", "is_correct": false, "explanation": "搭配：“精彩”多用于表演、比赛，不说“这样做太精彩了”。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”与“不给小狗吃饭”的行为相矛盾。"}], "explanations": {"残忍": "残忍形容狠毒、不心疼，与“不给小狗吃饭，这样做太……了”的语境相符。", "可爱": "语义：“可爱”与“不给小狗吃饭”的行为相矛盾。", "精彩": "搭配：“精彩”多用于表演、比赛，不说“这样做太精彩了”。", "温柔": "语义：“温柔”与“不给小狗吃饭”的行为相矛盾。"}, "sentence_index": 0, "correct_answer": "残忍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜很残忍，大家都不爱吃。", "explanation": "这里应该用〈难吃〉。残忍形容狠毒，不能用来形容菜的味道。"}, {"text": "他小时候因为生病残忍了。", "explanation": "这里应该用〈残疾〉。残忍形容狠毒，不能说人因病而残忍。"}, {"text": "这位教练的哨子很残忍。", "explanation": "这里应该用〈响亮〉。残忍形容狠毒，不能用来形容哨声的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95711, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "残忍", "is_correct": true, "explanation": "残忍形容狠毒、毫无怜悯，与“大家都说，打骂孩子是……的”的语境相符。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”指风趣，与“打骂孩子”的语境不符。"}, {"text": "富有", "is_correct": false, "explanation": "搭配：“富有”指财产多或有某种特质，不能修饰“打骂孩子”。"}, {"text": "温暖", "is_correct": false, "explanation": "语义：“温暖”与“打骂孩子”的语境相矛盾。"}], "explanations": {"残忍": "残忍形容狠毒、毫无怜悯，与“大家都说，打骂孩子是……的”的语境相符。", "幽默": "语义：“幽默”指风趣，与“打骂孩子”的语境不符。", "富有": "搭配：“富有”指财产多或有某种特质，不能修饰“打骂孩子”。", "温暖": "语义：“温暖”与“打骂孩子”的语境相矛盾。"}, "sentence_index": 6, "correct_answer": "残忍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布的颜色很残忍。", "explanation": "这里应该用〈鲜艳〉。残忍形容狠毒，不能用来形容颜色。"}, {"text": "他在事故中残忍了。", "explanation": "这里应该用〈残废〉。残忍形容人狠毒，不能用来说身体因事故残废。"}, {"text": "这首歌的节奏很残忍。", "explanation": "这里应该用〈欢快〉。残忍形容狠毒，不能用来形容节奏的快慢或欢快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95711, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把小狗很残忍。", "corrected_sentence": "他对小狗很残忍。", "error_description": "介词误用：“残忍”是形容词，不能用“把”引出对象，应用介词“对”，正确形式为“对小狗很残忍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95711, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他残忍得伤害了小猫。", "corrected_sentence": "他残忍地伤害了小猫。", "error_description": "语法错误：“残忍”作状语时要用“地”，不能用“得”（“得”用于动词后作补语）。正确形式为“残忍地伤害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
