INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95712, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "狠毒；对人或动物毫不怜悯。", "primary_collocate": null, "pronunciation": "cán rěn", "ipa": "tsʰan˧˥ ʐən˨˩", "syllable_count": 2, "sentences": [{"text": "这个坏人对小孩太残忍了。", "target_word": "残忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的做法非常残忍。", "target_word": "残忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争是残忍的。", "target_word": "残忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打动物是一件很残忍的事。", "target_word": "残忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个老板对工人很残忍。", "target_word": "残忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他残忍地把小鸟关在笼子里。", "target_word": "残忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到这么残忍的画面，我不敢再看。", "target_word": "残忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么能这么残忍？", "target_word": "残忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的坏人又狠又残忍。", "target_word": "残忍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样对待老人，真是太残忍了。", "target_word": "残忍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "殘忍", "label": "繁体"}, {"form": "残忍地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "狠毒、毫无怜悯的性格或做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a65ce783-209c-496d-8375-67116e6f7c33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95712, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "残忍", "is_correct": true, "explanation": "残忍指狠毒、毫不怜悯，与“坏人”和“太……了”的语境相符。"}, {"text": "友好", "is_correct": false, "explanation": "语义：“坏人对小孩友好”与“坏人”的语境相矛盾。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”形容性情或环境，不能用来说“对小孩太安静了”。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“坏人对小孩温柔”与“坏人”的语境相矛盾。"}], "explanations": {"残忍": "残忍指狠毒、毫不怜悯，与“坏人”和“太……了”的语境相符。", "友好": "语义：“坏人对小孩友好”与“坏人”的语境相矛盾。", "安静": "搭配：“安静”形容性情或环境，不能用来说“对小孩太安静了”。", "温柔": "语义：“坏人对小孩温柔”与“坏人”的语境相矛盾。"}, "sentence_index": 0, "correct_answer": "残忍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他因为车祸残忍了。", "explanation": "这里应该用〈残疾〉。残忍形容人狠毒、毫无怜悯，不能说因车祸而残忍；“残疾”才指身体机能受损。"}, {"text": "这杯咖啡很残忍。", "explanation": "这里应该用〈苦〉。残忍形容狠毒的行为或性格，不能用来形容咖啡的味道。"}, {"text": "他的字写得很残忍。", "explanation": "这里应该用〈潦草〉。残忍形容狠毒，不能用来形容字迹的潦草或工整。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95712, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "残忍", "is_correct": true, "explanation": "残忍形容狠毒、毫无怜悯，与“看到这么……的画面，我不敢再看”的语境相符。"}, {"text": "无聊", "is_correct": false, "explanation": "语义：“无聊”指没有意思，不会让人不敢再看，与语境相矛盾。"}, {"text": "温馨", "is_correct": false, "explanation": "语义：温馨的画面令人愉快，不会让人不敢再看。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能说“这么清脆的画面”。"}], "explanations": {"残忍": "残忍形容狠毒、毫无怜悯，与“看到这么……的画面，我不敢再看”的语境相符。", "无聊": "语义：“无聊”指没有意思，不会让人不敢再看，与语境相矛盾。", "温馨": "语义：温馨的画面令人愉快，不会让人不敢再看。", "清脆": "搭配：“清脆”形容声音，不能说“这么清脆的画面”。"}, "sentence_index": 6, "correct_answer": "残忍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的腿残忍了，走路要拄拐。", "explanation": "这里应该用〈残废〉。残忍形容人狠毒，不能用来说腿因伤残废。"}, {"text": "他很残忍，摔倒了也不哭。", "explanation": "这里应该用〈坚强〉。残忍指狠毒，不能用来形容意志坚定、不轻易哭。"}, {"text": "病情很残忍。", "explanation": "这里应该用〈严重〉。残忍形容人或动物的狠毒，不能用来形容病情的程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95712, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个人把动物很残忍。", "corrected_sentence": "这个人对动物很残忍。", "error_description": "介词误用：“残忍”是形容词，不能用“把”字结构引出对象，应用介词“对”引出对象，正确形式为“对动物很残忍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95712, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她残忍得对待那只小猫。", "corrected_sentence": "她残忍地对待那只小猫。", "error_description": "语法错误：“残忍”作状语时要用“地”，不能用“得”（“得”用于动词后作补语）。正确形式为“残忍地对待”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
