INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95713, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "拿钱帮别人去杀人的人。", "primary_collocate": null, "pronunciation": "shā shǒu", "ipa": "ʂa˥ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他是一个职业杀手，很少说话。", "target_word": "杀手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个杀手拿了钱，却没有去杀人。", "target_word": "杀手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影里，杀手走进了一家小饭馆。", "target_word": "杀手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥喜欢看杀手的电影。", "target_word": "杀手", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "听说他年轻时做过杀手。", "target_word": "杀手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杀手把枪放在桌子上，看着我们。", "target_word": "杀手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家人请来杀手，是为了对付仇人。", "target_word": "杀手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一名女杀手，也是一位好妈妈。", "target_word": "杀手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察正在到处找那个杀手。", "target_word": "杀手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个杀手最后自己去了警察局。", "target_word": "杀手", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "职业杀手", "label": "复合"}], "register": "中性", "sense_fingerprint": "拿钱替人杀人的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1895556-f649-4d14-bbf1-60be23bb54b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95713, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "杀手", "is_correct": true, "explanation": "正确答案。杀手 shā shǒu，指拿钱替人杀人的人。"}, {"text": "撒手", "is_correct": false, "explanation": "sā（第一声）与 shā（第一声）声母不同，s 与 sh；意思是“松手、放手”，不是杀手。"}, {"text": "插手", "is_correct": false, "explanation": "chā（第一声）与 shā（第一声）声母不同，ch 与 sh；意思是“插进去参与或干预”。"}, {"text": "扎手", "is_correct": false, "explanation": "zhā（第一声）与 shā（第一声）声母不同，zh 与 sh；意思是“扎人、棘手”。"}], "explanations": {"杀手": "正确答案。杀手 shā shǒu，指拿钱替人杀人的人。", "撒手": "sā（第一声）与 shā（第一声）声母不同，s 与 sh；意思是“松手、放手”，不是杀手。", "插手": "chā（第一声）与 shā（第一声）声母不同，ch 与 sh；意思是“插进去参与或干预”。", "扎手": "zhā（第一声）与 shā（第一声）声母不同，zh 与 sh；意思是“扎人、棘手”。"}, "sentence_index": null, "correct_answer": "杀手"}, "level_3": {"options": [{"text": "杀手", "is_correct": true, "explanation": "正确：杀手指拿钱替人杀人的人，符合“职业”且“很少说话”的人物描写。"}, {"text": "主持人", "is_correct": false, "explanation": "语义：主持人的工作要多说话，与“很少说话”矛盾。"}, {"text": "演说家", "is_correct": false, "explanation": "语义：演说家以多说话为职业，与“很少说话”矛盾。"}, {"text": "小孩", "is_correct": false, "explanation": "搭配：“职业”一般不修饰小孩，“职业小孩”说不通。"}], "explanations": {"杀手": "正确：杀手指拿钱替人杀人的人，符合“职业”且“很少说话”的人物描写。", "主持人": "语义：主持人的工作要多说话，与“很少说话”矛盾。", "演说家": "语义：演说家以多说话为职业，与“很少说话”矛盾。", "小孩": "搭配：“职业”一般不修饰小孩，“职业小孩”说不通。"}, "sentence_index": 0, "correct_answer": "杀手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一名杀手，每天负责开车送客人。", "explanation": "这里应该用〈司机〉。杀手是受雇杀人的人，开车送客人是司机的工作。"}, {"text": "我感冒的时候，杀手每次都给我开药。", "explanation": "这里应该用〈医生〉。杀手不开药，给病人开药的是医生。"}, {"text": "这家餐厅请了一个杀手，专门负责做菜。", "explanation": "这里应该用〈厨师〉。杀手是受雇杀人的人，做菜的是厨师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95713, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杀手", "is_correct": true, "explanation": "正确：杀手指拿钱替人杀人的人，被请来对付仇人符合语境。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书，不能被请来对付仇人。"}, {"text": "保姆", "is_correct": false, "explanation": "搭配：“请来保姆”的目的是照顾家务，与“为了对付仇人”的用途不搭。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是地方，不能被请来做事，也不能对付仇人。"}], "explanations": {"杀手": "正确：杀手指拿钱替人杀人的人，被请来对付仇人符合语境。", "课本": "语义：课本是书，不能被请来对付仇人。", "保姆": "搭配：“请来保姆”的目的是照顾家务，与“为了对付仇人”的用途不搭。", "花园": "语义：花园是地方，不能被请来做事，也不能对付仇人。"}, "sentence_index": 6, "correct_answer": "杀手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一根杀手，很少说话。", "explanation": "这里应该用〈个〉或〈名〉。量词“根”多用于细长的东西，指人的杀手不能这样用。"}, {"text": "我家门口停着一辆杀手。", "explanation": "这里应该用〈个〉或〈名〉。量词“辆”多用于车辆，不用于指人的杀手。"}, {"text": "院子里站着一棵杀手，一动不动。", "explanation": "这里应该用〈个〉或〈名〉。量词“棵”多用于植物，不用于指人的杀手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95713, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一把职业杀手，专门替人办事，很少露面。", "corrected_sentence": "他是一名职业杀手，专门替人办事，很少露面。", "error_description": "量词错误：指人的“杀手”应用“名”或“个”，不能用“把”（“把”多用于有柄的物品）。正确说法：一名职业杀手。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95713, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他接了一单生意，成了一名职业杀手们。", "corrected_sentence": "他接了一单生意，成了一名职业杀手。", "error_description": "复数错误：“们”不能与“一名”这样的数量词连用，指一个人时不能说“一名职业杀手们”。正确说法：成了一名职业杀手。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
