INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95714, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "受雇杀人的人。", "primary_collocate": null, "pronunciation": "shā shǒu", "ipa": "ʂa˥ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "电影里的杀手每次都戴着黑帽子。", "target_word": "杀手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人花很多钱请了一个杀手。", "target_word": "杀手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察昨天抓到了那个杀手。", "target_word": "杀手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个杀手只做一件事，就是拿钱杀人。", "target_word": "杀手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他小时候很怕电影里的杀手。", "target_word": "杀手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那本小说讲的是一个年轻杀手的故事。", "target_word": "杀手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "杀手收了钱，晚上就去了他家。", "target_word": "杀手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "杀手在门外等了一整夜。", "target_word": "杀手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板雇了两个杀手，要除掉那个证人。", "target_word": "杀手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察说，这个杀手已经离开了这座城市。", "target_word": "杀手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "职业杀手", "label": "复合"}], "register": "中性", "sense_fingerprint": "受雇杀人的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1895556-f649-4d14-bbf1-60be23bb54b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95714, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "杀手", "is_correct": true, "explanation": "正确答案。杀手 shā shǒu，指受雇杀人的人。"}, {"text": "撒手", "is_correct": false, "explanation": "sā（第一声）与 shā（第一声）声母不同，s 与 sh；意思是“松手、放手”，不是杀手。"}, {"text": "插手", "is_correct": false, "explanation": "chā（第一声）与 shā（第一声）声母不同，ch 与 sh；意思是“插进去参与或干预”。"}, {"text": "扎手", "is_correct": false, "explanation": "zhā（第一声）与 shā（第一声）声母不同，zh 与 sh；意思是“扎人、棘手”。"}], "explanations": {"杀手": "正确答案。杀手 shā shǒu，指受雇杀人的人。", "撒手": "sā（第一声）与 shā（第一声）声母不同，s 与 sh；意思是“松手、放手”，不是杀手。", "插手": "chā（第一声）与 shā（第一声）声母不同，ch 与 sh；意思是“插进去参与或干预”。", "扎手": "zhā（第一声）与 shā（第一声）声母不同，zh 与 sh；意思是“扎人、棘手”。"}, "sentence_index": null, "correct_answer": "杀手"}, "level_3": {"options": [{"text": "杀手", "is_correct": true, "explanation": "正确：杀手指受雇杀人的人，符合电影里戴黑帽子的角色。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会戴帽子，“电影里的窗户每次都戴着黑帽子”说不通。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，不是能戴帽子的人或物，与“戴着黑帽子”不符。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不会戴帽子，“电影里的椅子每次都戴着黑帽子”说不通。"}], "explanations": {"杀手": "正确：杀手指受雇杀人的人，符合电影里戴黑帽子的角色。", "窗户": "语义：窗户不会戴帽子，“电影里的窗户每次都戴着黑帽子”说不通。", "数学": "语义：数学是学科，不是能戴帽子的人或物，与“戴着黑帽子”不符。", "椅子": "语义：椅子不会戴帽子，“电影里的椅子每次都戴着黑帽子”说不通。"}, "sentence_index": 0, "correct_answer": "杀手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一名杀手，每天负责搜集各国的情报。", "explanation": "这里应该用〈特工〉。杀手是受雇杀人的人，搜集情报是特工的工作，不能说成“杀手”。"}, {"text": "我家请了一个杀手，每天负责做饭。", "explanation": "这里应该用〈厨师〉。杀手不做饭，负责做饭的是厨师。"}, {"text": "公司请了一名杀手，负责保护老板的安全。", "explanation": "这里应该用〈保镖〉。杀手是受雇杀人的人，保护人身安全的是保镖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95714, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杀手", "is_correct": true, "explanation": "正确：杀手指受雇杀人的人，收钱后去杀人符合语境。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不会收钱，也不会晚上去别人家，与句中人物的行为不符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能收钱，也不能去别人家。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：“收了钱”要求施事是能收钱的人，“报纸”作施事搭配不当。"}], "explanations": {"杀手": "正确：杀手指受雇杀人的人，收钱后去杀人符合语境。", "树": "语义：树不会收钱，也不会晚上去别人家，与句中人物的行为不符。", "窗户": "语义：窗户不能收钱，也不能去别人家。", "报纸": "搭配：“收了钱”要求施事是能收钱的人，“报纸”作施事搭配不当。"}, "sentence_index": 6, "correct_answer": "杀手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门外站着一把杀手，很少说话。", "explanation": "这里应该用〈个〉或〈名〉。杀手指人，量词“把”多用于有柄的物品，不能用于人。"}, {"text": "那个老人是一只杀手，常年住在山里。", "explanation": "这里应该用〈个〉或〈名〉。量词“只”多用于动物，不用于指人的杀手。"}, {"text": "他身边跟着一条杀手，很少说话。", "explanation": "这里应该用〈个〉或〈名〉。量词“条”多用于细长的东西或动物，不用于指人的杀手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95714, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个人是一只杀手，专门替别人除掉对手。", "corrected_sentence": "那个人是一名杀手，专门替别人除掉对手。", "error_description": "量词错误：“杀手”指人，应用“名”或“个”，不能用“只”（“只”多用于动物）。正确说法：一名杀手。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95714, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个人昨天晚上成了一名的杀手，拿了很多钱。", "corrected_sentence": "那个人昨天晚上成了一名杀手，拿了很多钱。", "error_description": "“一名”与“杀手”之间不能加“的”，应说“一名杀手”，不能说“一名的杀手”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
