INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95715, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用水把东西洗干净。", "primary_collocate": null, "pronunciation": "qīng xǐ", "ipa": "tɕʰiŋ˥ ɕi˨˩˦", "syllable_count": 2, "sentences": [{"text": "请把杯子清洗干净。", "target_word": "清洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天清洗蔬菜。", "target_word": "清洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈正清洗着窗帘。", "target_word": "清洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃水果以前要先清洗。", "target_word": "清洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把车清洗了一遍。", "target_word": "清洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些盘子需要用热水清洗。", "target_word": "清洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你清洗过这条毛巾吗？", "target_word": "清洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们一起清洗地毯。", "target_word": "清洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里的锅要经常清洗。", "target_word": "清洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请清洗一下盒子。", "target_word": "清洗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "清洗了", "label": "体标：了"}, {"form": "清洗过", "label": "体标：过"}, {"form": "清洗着", "label": "体标：着"}], "register": "通用", "sense_fingerprint": "用水把物品洗干净", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b283c72b-36cb-4649-9609-b1e6be703ed2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95715, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "清洗", "is_correct": true, "explanation": "正确：“清洗”指用水把东西洗干净，与释义一致。"}, {"text": "清晰", "is_correct": false, "explanation": "声调不同：xǐ（第三声）与 xī（第一声）声调不同，“清晰”意思是清楚、明白。"}, {"text": "惊喜", "is_correct": false, "explanation": "声母不同：j 与 q 声母不同，“惊喜”意思是又惊又喜。"}, {"text": "清醒", "is_correct": false, "explanation": "韵母不同：xǐng 比 xǐ 多了后鼻音 ng，“清醒”意思是头脑清楚、不迷糊。"}], "explanations": {"清洗": "正确：“清洗”指用水把东西洗干净，与释义一致。", "清晰": "声调不同：xǐ（第三声）与 xī（第一声）声调不同，“清晰”意思是清楚、明白。", "惊喜": "声母不同：j 与 q 声母不同，“惊喜”意思是又惊又喜。", "清醒": "韵母不同：xǐng 比 xǐ 多了后鼻音 ng，“清醒”意思是头脑清楚、不迷糊。"}, "sentence_index": null, "correct_answer": "清洗"}, "level_3": {"options": [{"text": "摔", "is_correct": false, "explanation": "语义：“摔”会打破杯子，不能使杯子变干净。"}, {"text": "清洗", "is_correct": true, "explanation": "正确：“清洗干净”指用水洗去脏东西，与句意相符。"}, {"text": "装", "is_correct": false, "explanation": "搭配：“装”是把东西放进容器，不能说“装干净”。"}, {"text": "拿", "is_correct": false, "explanation": "语义：“拿”是取物，不能使杯子变干净。"}], "explanations": {"摔": "语义：“摔”会打破杯子，不能使杯子变干净。", "清洗": "正确：“清洗干净”指用水洗去脏东西，与句意相符。", "装": "搭配：“装”是把东西放进容器，不能说“装干净”。", "拿": "语义：“拿”是取物，不能使杯子变干净。"}, "sentence_index": 0, "correct_answer": "清洗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把杯子清洗成了蓝色。", "explanation": "这里应该用〈染〉。“清洗”只表示用水去掉污物，不能改变东西的颜色。"}, {"text": "工厂安装了新设备，用来清洗空气。", "explanation": "这里应该用〈净化〉。“清洗”指用水洗去污物，空气不能用水洗，应该用“净化”。"}, {"text": "晚上我喜欢清洗个热水澡。", "explanation": "这里应该用〈洗澡〉。“洗澡”是固定说法，不能说“清洗澡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95715, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，毛巾不能吃。"}, {"text": "清洗", "is_correct": true, "explanation": "正确：“清洗过”表示曾用水洗过这条毛巾，与问句语境一致。"}, {"text": "读", "is_correct": false, "explanation": "语义：“读”的对象是文字，不能用于毛巾。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱这条毛巾”。"}], "explanations": {"吃": "搭配：“吃”的对象是食物，毛巾不能吃。", "清洗": "正确：“清洗过”表示曾用水洗过这条毛巾，与问句语境一致。", "读": "语义：“读”的对象是文字，不能用于毛巾。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱这条毛巾”。"}, "sentence_index": 6, "correct_answer": "清洗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请清洗一下时间。", "explanation": "这里应该用〈节省〉。“清洗”指用水洗去污物，时间不能被清洗。"}, {"text": "请清洗一下这个问题。", "explanation": "这里应该用〈回答〉。“清洗”指用水洗去污物，问题不能被清洗。"}, {"text": "请清洗一下音量。", "explanation": "这里应该用〈调节〉。“清洗”指用水洗去污物，音量不能被清洗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95715, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从不清洗过这个杯子。", "corrected_sentence": "我从没清洗过这个杯子。", "error_description": "错误：“不”用错了。表示没有发生过的经历应该用“没”，应说“从没清洗过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95715, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我正清洗过那条围巾。", "corrected_sentence": "我清洗过那条围巾。", "error_description": "错误：“正”表示动作正在进行，与表示经历的“过”冲突，两者不能同时出现。正确：“我清洗过那条围巾。”应去掉“正”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
