INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95716, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用水等洗去脏东西。", "primary_collocate": null, "pronunciation": "qīng xǐ", "ipa": "tɕʰiŋ˥ ɕi˨˩˦", "syllable_count": 2, "sentences": [{"text": "他用清水清洗伤口。", "target_word": "清洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在清洗墙上的脏东西。", "target_word": "清洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药水能清洗油污。", "target_word": "清洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请清洗一下鞋上的泥。", "target_word": "清洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器的外壳要定期用水清洗。", "target_word": "清洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用洗洁精清洗锅里的油。", "target_word": "清洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生先清洗了我的手。", "target_word": "清洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清洗过的杯子放在桌上。", "target_word": "清洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用清水清洗了船身上的油污。", "target_word": "清洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用刷子清洗地板上的污渍。", "target_word": "清洗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "清洗了", "label": "体标：了"}, {"form": "清洗过", "label": "体标：过"}, {"form": "清洗着", "label": "体标：着"}], "register": "通用", "sense_fingerprint": "用水或清洁剂洗去污垢、油污、灰尘", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b283c72b-36cb-4649-9609-b1e6be703ed2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95716, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "清洗", "is_correct": true, "explanation": "正确：“清洗”指用水或清洗剂洗去污垢，与释义一致。"}, {"text": "清晰", "is_correct": false, "explanation": "声调不同：xǐ（第三声）与 xī（第一声）声调不同，“清晰”意思是清楚、明白。"}, {"text": "惊喜", "is_correct": false, "explanation": "声母不同：j 与 q 声母不同，“惊喜”意思是又惊又喜。"}, {"text": "清醒", "is_correct": false, "explanation": "韵母不同：xǐng 比 xǐ 多了后鼻音 ng，“清醒”意思是头脑清楚、不迷糊。"}], "explanations": {"清洗": "正确：“清洗”指用水或清洗剂洗去污垢，与释义一致。", "清晰": "声调不同：xǐ（第三声）与 xī（第一声）声调不同，“清晰”意思是清楚、明白。", "惊喜": "声母不同：j 与 q 声母不同，“惊喜”意思是又惊又喜。", "清醒": "韵母不同：xǐng 比 xǐ 多了后鼻音 ng，“清醒”意思是头脑清楚、不迷糊。"}, "sentence_index": null, "correct_answer": "清洗"}, "level_3": {"options": [{"text": "包扎", "is_correct": false, "explanation": "搭配：“包扎”是用纱布裹住伤口，不能说“用清水包扎”。"}, {"text": "清洗", "is_correct": true, "explanation": "正确：“清洗”指用清水冲洗伤口，与句意相符。"}, {"text": "缝合", "is_correct": false, "explanation": "语义：“缝合”是用针线缝起伤口，不能用清水完成。"}, {"text": "贴", "is_correct": false, "explanation": "搭配：“贴”是把东西粘在表面，不能说“用清水贴伤口”。"}], "explanations": {"包扎": "搭配：“包扎”是用纱布裹住伤口，不能说“用清水包扎”。", "清洗": "正确：“清洗”指用清水冲洗伤口，与句意相符。", "缝合": "语义：“缝合”是用针线缝起伤口，不能用清水完成。", "贴": "搭配：“贴”是把东西粘在表面，不能说“用清水贴伤口”。"}, "sentence_index": 0, "correct_answer": "清洗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请清洗一下这份合同。", "explanation": "这里应该用〈审核〉。“清洗”指用水等洗去脏东西，合同不能被清洗。"}, {"text": "请清洗一下这次的成绩。", "explanation": "这里应该用〈提高〉。“清洗”指洗去污垢，成绩不能被清洗。"}, {"text": "请清洗一下这个问题。", "explanation": "这里应该用〈回答〉。“清洗”指洗去污垢，问题不能被清洗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95716, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摔", "is_correct": false, "explanation": "语义：“摔”会让手受伤，与“医生先”的治疗语境相矛盾。"}, {"text": "清洗", "is_correct": true, "explanation": "正确：“清洗”指医生先用水或清洁剂洗手，与句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物或药，不能说“吃我的手”。"}, {"text": "挠", "is_correct": false, "explanation": "语义：“挠”是抓痒，不是医生的治疗动作。"}], "explanations": {"摔": "语义：“摔”会让手受伤，与“医生先”的治疗语境相矛盾。", "清洗": "正确：“清洗”指医生先用水或清洁剂洗手，与句意相符。", "吃": "搭配：“吃”的对象是食物或药，不能说“吃我的手”。", "挠": "语义：“挠”是抓痒，不是医生的治疗动作。"}, "sentence_index": 6, "correct_answer": "清洗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每晚都给孩子清洗澡。", "explanation": "这里应该说〈洗澡〉。“清洗”指用水去污，不能和“澡”搭配，“洗澡”才是固定说法。"}, {"text": "他们坐在桌边清洗牌。", "explanation": "这里应该说〈洗牌〉。“清洗”指用水去污，“牌”不能用“清洗”，洗牌才是固定说法。"}, {"text": "她把头发清洗成了金色。", "explanation": "这里应该用〈染〉。“清洗”是去掉污物，不能改变头发的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95716, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从不清洗过这台机器。", "corrected_sentence": "我从没清洗过这台机器。", "error_description": "错误：“不”用错了。表示没有发生过的经历应该用“没”，应说“从没清洗过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95716, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正清洗过门口的台阶。", "corrected_sentence": "他清洗过门口的台阶。", "error_description": "错误：“正”表示动作正在进行，与表示经历的“过”冲突，两者不能同时出现。正确：“他清洗过门口的台阶。”应去掉“正”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
