INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95717, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把不要的东西全部拿走。", "primary_collocate": null, "pronunciation": "qīng chú", "ipa": "tɕʰiŋ˥ ʈʂʰu˧˥", "syllable_count": 2, "sentences": [{"text": "工人正在清除路上的雪。", "target_word": "清除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把房间里的垃圾清除干净。", "target_word": "清除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们清除了河里的脏东西。", "target_word": "清除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，我们清除院子里的草。", "target_word": "清除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅清除了机器里的灰。", "target_word": "清除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪后，大家一起清除路面的冰。", "target_word": "清除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要先清除桌子上的东西。", "target_word": "清除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清洁工每天清除街上的垃圾。", "target_word": "清除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把花园里的树叶清除干净了。", "target_word": "清除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们清除了仓库里的旧东西。", "target_word": "清除", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "清除了", "label": "体标（了）"}, {"form": "清除过", "label": "体标（过）"}, {"form": "清除掉", "label": "结果补语"}, {"form": "清除干净", "label": "结果补语"}], "register": "中性", "sense_fingerprint": "把垃圾、积雪等不要的东西全部拿走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03215d03-95c8-4cd4-8139-5091553db1e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95717, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "擦亮", "is_correct": false, "explanation": "搭配：“擦亮”用于物体表面，不能用于路上的雪。"}, {"text": "清除", "is_correct": true, "explanation": "正确：“清除”表示把路上的雪全部拿走，符合句意。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指观赏美景，与工人正在干活的语境不符。"}, {"text": "眺望", "is_correct": false, "explanation": "搭配：“眺望”的对象是远处的景色，不能说眺望路上的雪。"}], "explanations": {"擦亮": "搭配：“擦亮”用于物体表面，不能用于路上的雪。", "清除": "正确：“清除”表示把路上的雪全部拿走，符合句意。", "欣赏": "语义：“欣赏”指观赏美景，与工人正在干活的语境不符。", "眺望": "搭配：“眺望”的对象是远处的景色，不能说眺望路上的雪。"}, "sentence_index": 0, "correct_answer": "清除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "秋天到了，农民在地里清除了成熟的玉米。", "explanation": "这里应该用〈收获〉。清除表示把不要的东西拿走，成熟的玉米是要收获的，不能说清除。"}, {"text": "学校清除了那场精彩的演出。", "explanation": "这里应该用〈举办〉。清除表示把不要的东西拿走，精彩的演出应当举办，不能清除。"}, {"text": "我们在岸边清除了大海。", "explanation": "这里应该用〈观赏〉。清除表示把不要的东西拿走，大海不能被清除，应说观赏大海。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95717, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聆听", "is_correct": false, "explanation": "配价：“聆听”的对象是声音或话语，不能说聆听桌子上的东西。"}, {"text": "喂养", "is_correct": false, "explanation": "语义：“喂养”指饲养动物，与桌子上的东西不相关。"}, {"text": "清除", "is_correct": true, "explanation": "正确：“清除”表示把桌子上的东西拿走，符合句意。"}, {"text": "吞下", "is_correct": false, "explanation": "搭配：“吞下”多用于食物，不能说吞下桌子上的东西。"}], "explanations": {"聆听": "配价：“聆听”的对象是声音或话语，不能说聆听桌子上的东西。", "喂养": "语义：“喂养”指饲养动物，与桌子上的东西不相关。", "清除": "正确：“清除”表示把桌子上的东西拿走，符合句意。", "吞下": "搭配：“吞下”多用于食物，不能说吞下桌子上的东西。"}, "sentence_index": 6, "correct_answer": "清除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在山顶清除了清新的空气。", "explanation": "这里应该用〈呼吸〉。清除表示把不要的东西拿走，清新的空气是要呼吸的，不能清除。"}, {"text": "我们今天清除了美好的阳光。", "explanation": "这里应该用〈享受〉。清除表示把不要的东西拿走，美好的阳光应当享受。"}, {"text": "大家向新人清除了美好的祝福。", "explanation": "这里应该用〈送上〉。清除表示拿走不要的东西，祝福是要送给对方的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95717, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把厨房的灰清除了干净了。", "corrected_sentence": "妈妈把厨房的灰清除干净了。", "error_description": "错误：“清除”和“干净”之间多了“了”；正确：“清除干净了”。结果补语“干净”必须紧跟动词“清除”，中间不能插入“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95717, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "环卫工人正在清除了小区里的落叶。", "corrected_sentence": "环卫工人正在清除小区里的落叶。", "error_description": "错误：“正在”表示动作进行中，不能和表示完成的“了”一起用在“清除”后；正确：去掉“了”，说“正在清除小区里的落叶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
