INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95720, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "国家、种族等不再存在；消失。", "primary_collocate": null, "pronunciation": "miè wáng", "ipa": "mjɛ˥˩ wɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "那个古老的王国早就灭亡了。", "target_word": "灭亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恐龙为什么会灭亡？", "target_word": "灭亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争让这个小国走向灭亡。", "target_word": "灭亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上有很多国家灭亡过。", "target_word": "灭亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个民族没有灭亡，还保留着自己的文化。", "target_word": "灭亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们担心自己的国家会灭亡。", "target_word": "灭亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秦朝灭亡以后，汉朝建立了。", "target_word": "灭亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小国如果不团结，就会灭亡。", "target_word": "灭亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家为什么灭亡，书上写得很清楚。", "target_word": "灭亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个民族在战争中灭亡了。", "target_word": "灭亡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "灭亡了", "label": "体标"}, {"form": "灭亡过", "label": "体标"}, {"form": "滅亡", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "国家、种族等不再存在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d8c84b-ccc7-4628-aee4-528ffa806d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95720, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出版", "is_correct": false, "explanation": "搭配：“出版”接的是书刊、报纸，不能接“王国”。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指人离开工作岗位，不能用于王国。"}, {"text": "灭亡", "is_correct": true, "explanation": "灭亡：古老的王国早已不再存在，与句意相符。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是人或动物的疾病，不能用于王国。"}], "explanations": {"出版": "搭配：“出版”接的是书刊、报纸，不能接“王国”。", "退休": "语义：“退休”指人离开工作岗位，不能用于王国。", "灭亡": "灭亡：古老的王国早已不再存在，与句意相符。", "感冒": "语义：“感冒”是人或动物的疾病，不能用于王国。"}, "sentence_index": 0, "correct_answer": "灭亡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那些难民为了躲避战争而灭亡。", "explanation": "这里应该用〈逃亡〉。灭亡指国家、种族不再存在，不能用于人离开家乡。"}, {"text": "这位老人在睡梦中灭亡了。", "explanation": "这里应该用〈死亡〉。灭亡只用于国家、种族等，不用于个人生命的结束。"}, {"text": "他为了保护战友而灭亡了。", "explanation": "这里应该用〈牺牲〉。灭亡不能用于个人为了他人而献出生命。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95720, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出生", "is_correct": false, "explanation": "语义：“出生”用于人或动物，不能用于朝代。"}, {"text": "开幕", "is_correct": false, "explanation": "搭配：“开幕”接的是会议、展览等活动，不能用于朝代。"}, {"text": "灭亡", "is_correct": true, "explanation": "灭亡：秦朝不再存在之后汉朝才建立，与句意相符。"}, {"text": "迷路", "is_correct": false, "explanation": "语义：“迷路”指人在路上找不到方向，不能用于朝代。"}], "explanations": {"出生": "语义：“出生”用于人或动物，不能用于朝代。", "开幕": "搭配：“开幕”接的是会议、展览等活动，不能用于朝代。", "灭亡": "灭亡：秦朝不再存在之后汉朝才建立，与句意相符。", "迷路": "语义：“迷路”指人在路上找不到方向，不能用于朝代。"}, "sentence_index": 6, "correct_answer": "灭亡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那家小饭馆开了三年，去年灭亡了。", "explanation": "这里应该用〈倒闭〉。灭亡只用于国家、种族等不再存在，商店、饭馆停止经营要用倒闭。"}, {"text": "夜里的蜡烛灭亡了。", "explanation": "这里应该用〈熄灭〉。灭亡不能用于火焰的熄灭，蜡烛火焰熄灭要用熄灭。"}, {"text": "那只流浪猫一夜之间灭亡了。", "explanation": "这里应该用〈消失〉。灭亡不用于个别动物的离开，没有了踪影要用消失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95720, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个部落如果不团结，就会灭亡着。", "corrected_sentence": "这个部落如果不团结，就会灭亡。", "error_description": "错误：“灭亡”是结果性动词，不能带“着”表示动作持续。应说“就会灭亡”，不能说“就会灭亡着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95720, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个部落曾经灭亡了过，后来又重新建立了。", "corrected_sentence": "那个部落曾经灭亡过，后来又重新建立了。", "error_description": "错误：表示经历的“过”不能和“了”同时使用。应说“灭亡过”，不能说“灭亡了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
