INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95722, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "隐瞒真相，用假话欺骗别人。", "primary_collocate": null, "pronunciation": "mēng", "ipa": "/mɤŋ˥˥/", "syllable_count": 1, "sentences": [{"text": "你别想蒙我，我不会相信的。", "target_word": "蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用假话蒙了老师。", "target_word": "蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖假货，蒙了很多客人。", "target_word": "蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想蒙过检查，但是老师发现了。", "target_word": "蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明想蒙妈妈，说作业丢了。", "target_word": "蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想蒙大家，可是大家都不信。", "target_word": "蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不会做就说不会，不要蒙人。", "target_word": "蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看出他在蒙她，就生气了。", "target_word": "蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别听他的，他是在蒙你。", "target_word": "蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卖水果的人想蒙我，把坏苹果放在下面。", "target_word": "蒙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "蒙了", "label": "体标"}, {"form": "蒙过", "label": "体标"}, {"form": "蒙骗", "label": "复合"}], "register": "口语", "sense_fingerprint": "隐瞒真相、说假话欺骗别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48a21a23-df6a-4cf9-ac6b-c8fd9560ff2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95722, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蒙", "is_correct": true, "explanation": "本词 mēng（第一声），意思是欺骗、隐瞒真相。"}, {"text": "猛", "is_correct": false, "explanation": "měng（第三声）与 mēng（第一声）声调不同，意思是凶猛。"}, {"text": "梦", "is_correct": false, "explanation": "mèng（第四声）与 mēng（第一声）声调不同，意思是梦境。"}, {"text": "闷", "is_correct": false, "explanation": "mēn 与 mēng 韵尾不同（n/ng），意思是烦闷。"}], "explanations": {"蒙": "本词 mēng（第一声），意思是欺骗、隐瞒真相。", "猛": "měng（第三声）与 mēng（第一声）声调不同，意思是凶猛。", "梦": "mèng（第四声）与 mēng（第一声）声调不同，意思是梦境。", "闷": "mēn 与 mēng 韵尾不同（n/ng），意思是烦闷。"}, "sentence_index": null, "correct_answer": "蒙"}, "level_3": {"options": [{"text": "咬", "is_correct": false, "explanation": "语义：咬是用牙齿夹住，与“相信”的语境不符，句意不通。"}, {"text": "蒙", "is_correct": true, "explanation": "蒙表示欺骗，与“我不会相信”的语境相呼应。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物或物体，不能用于人。"}, {"text": "修", "is_correct": false, "explanation": "语义：修是修理，与“相信”的语境不符。"}], "explanations": {"咬": "语义：咬是用牙齿夹住，与“相信”的语境不符，句意不通。", "蒙": "蒙表示欺骗，与“我不会相信”的语境相呼应。", "洗": "搭配：“洗”的对象是衣物或物体，不能用于人。", "修": "语义：修是修理，与“相信”的语境不符。"}, "sentence_index": 0, "correct_answer": "蒙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他蒙了一个好消息，很高兴。", "explanation": "这里应该用〈听到〉。听到消息要说“听到”，“蒙”表示欺骗，不能用于消息。"}, {"text": "他蒙了我的钱包，把它拿走了。", "explanation": "这里应该用〈偷〉。偷是把别人的东西拿走，蒙指欺骗或遮盖，不能用于钱包。"}, {"text": "他蒙了错误，不想承担责任。", "explanation": "这里应该用〈掩盖〉。蒙表示欺骗，不能与“错误”搭配，说“掩盖错误”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d401d5-0fd2-43a5-8297-a17638e858c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95722, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "蒙", "is_correct": true, "explanation": "本词 mēng（第一声），意思是欺骗、隐瞒真相。"}, {"text": "崩", "is_correct": false, "explanation": "bēng（第一声）与 mēng 声母不同（b/m），意思是崩塌。"}, {"text": "灯", "is_correct": false, "explanation": "dēng（第一声）与 mēng 声母不同（d/m），意思是灯。"}, {"text": "风", "is_correct": false, "explanation": "fēng（第一声）与 mēng 声母不同（f/m），意思是风。"}], "explanations": {"蒙": "本词 mēng（第一声），意思是欺骗、隐瞒真相。", "崩": "bēng（第一声）与 mēng 声母不同（b/m），意思是崩塌。", "灯": "dēng（第一声）与 mēng 声母不同（d/m），意思是灯。", "风": "fēng（第一声）与 mēng 声母不同（f/m），意思是风。"}, "sentence_index": null, "correct_answer": "蒙"}, "level_3": {"options": [{"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能用于人。"}, {"text": "蒙", "is_correct": true, "explanation": "蒙人表示欺骗别人，与“不会做就说不会”的语境相符。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣物，不能用于人。"}, {"text": "翻", "is_correct": false, "explanation": "语义：翻是翻动或越过，与“不要……人”的语境不符，句意不通。"}], "explanations": {"煮": "搭配：“煮”的对象是食物，不能用于人。", "蒙": "蒙人表示欺骗别人，与“不会做就说不会”的语境相符。", "穿": "搭配：“穿”的对象是衣物，不能用于人。", "翻": "语义：翻是翻动或越过，与“不要……人”的语境不符，句意不通。"}, "sentence_index": 6, "correct_answer": "蒙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他蒙了一个大错，很后悔。", "explanation": "这里应该用〈犯〉。犯错要说“犯”，蒙表示欺骗或遮盖，不能表示“犯错”。"}, {"text": "他蒙了老师的帮助。", "explanation": "这里应该用〈感谢〉。蒙指欺骗，不能与“帮助”搭配，说“感谢老师的帮助”才对。"}, {"text": "他蒙了朋友的礼物，很开心。", "explanation": "这里应该用〈收到〉。收到礼物要说“收到”，蒙表示欺骗或遮盖，不能表示接收。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d401d5-0fd2-43a5-8297-a17638e858c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他又蒙我了一次。", "corrected_sentence": "他又蒙了我一次。", "error_description": "“了”应紧跟动词“蒙”，放在宾语“我”后面说不通。正确为「他又蒙了我一次。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d401d5-0fd2-43a5-8297-a17638e858c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他蒙我过两次。", "corrected_sentence": "他蒙过我两次。", "error_description": "“过”应紧跟动词“蒙”，“蒙我过”说不通。正确为「他蒙过我两次。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d401d5-0fd2-43a5-8297-a17638e858c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
