INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95726, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "在合作或配合中彼此默契，没有隔阂或脱节。", "primary_collocate": null, "pronunciation": "wú jiàn", "ipa": "u˧˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "两个公司合作无间，生意越做越好。", "target_word": "无间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队员们配合无间，很快赢了比赛。", "target_word": "无间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们合作无间，一个星期就做完了。", "target_word": "无间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩配合无间，像一个人一样。", "target_word": "无间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板和员工合作无间，工作很开心。", "target_word": "无间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里的三个人配合无间，菜很快做好了。", "target_word": "无间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对搭档合作无间，已经一起工作十年了。", "target_word": "无间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家合作无间，终于完成了任务。", "target_word": "无间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在场上配合无间，大家都夸他们。", "target_word": "无间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国一直合作无间，关系很好。", "target_word": "无间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "合作无间", "label": "复合"}, {"form": "配合无间", "label": "复合"}, {"form": "無間", "label": "繁体"}], "register": "书面", "sense_fingerprint": "形容词：合作、配合没有隔阂、毫无间隙（合作无间）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03215d03-95c8-4cd4-8139-5091553db1e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95726, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无间", "is_correct": true, "explanation": "正确答案。无间：wú jiàn，形容配合默契、没有隔阂。"}, {"text": "无限", "is_correct": false, "explanation": "xiàn（x 声母）与 jiàn（j 声母）声母不同，意思是没有限度，不是配合默契。"}, {"text": "物件", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是物品，与配合无关。"}, {"text": "午间", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）、jiān（第一声）与 jiàn（第四声）声调都不同，意思是中午前后。"}, {"text": "舞剑", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是挥舞宝剑。"}], "explanations": {"无间": "正确答案。无间：wú jiàn，形容配合默契、没有隔阂。", "无限": "xiàn（x 声母）与 jiàn（j 声母）声母不同，意思是没有限度，不是配合默契。", "物件": "wù（第四声）与 wú（第二声）声调不同，意思是物品，与配合无关。", "午间": "wǔ（第三声）与 wú（第二声）、jiān（第一声）与 jiàn（第四声）声调都不同，意思是中午前后。", "舞剑": "wǔ（第三声）与 wú（第二声）声调不同，意思是挥舞宝剑。"}, "sentence_index": null, "correct_answer": "无间"}, "level_3": {"options": [{"text": "无间", "is_correct": true, "explanation": "正确答案。无间：合作配合没有隔阂，与“生意越做越好”相合。"}, {"text": "不畅", "is_correct": false, "explanation": "语义：“不畅”指不顺利，与“生意越做越好”矛盾。"}, {"text": "疏远", "is_correct": false, "explanation": "搭配：“合作”不说“疏远”，“疏远”指关系不亲近，与“生意越做越好”的合作前景矛盾。"}, {"text": "敷衍", "is_correct": false, "explanation": "语义：“敷衍”指应付了事，与“生意越做越好”不符。"}], "explanations": {"无间": "正确答案。无间：合作配合没有隔阂，与“生意越做越好”相合。", "不畅": "语义：“不畅”指不顺利，与“生意越做越好”矛盾。", "疏远": "搭配：“合作”不说“疏远”，“疏远”指关系不亲近，与“生意越做越好”的合作前景矛盾。", "敷衍": "语义：“敷衍”指应付了事，与“生意越做越好”不符。"}, "sentence_index": 0, "correct_answer": "无间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这台机器很无间。", "explanation": "这里应该用〈熟练〉。无间用于人与人之间的配合或关系，不用来形容对机器的操作。"}, {"text": "这条路的交通很无间。", "explanation": "这里应该用〈顺畅〉。无间不用来形容交通状况，交通应说顺畅。"}, {"text": "这块布料的颜色很无间。", "explanation": "这里应该用〈均匀〉。无间用于人与人之间的配合，不用来形容颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95726, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "无间", "is_correct": true, "explanation": "正确答案。无间：wú jiàn，形容配合默契、没有隔阂。"}, {"text": "无线", "is_correct": false, "explanation": "xiàn（x 声母）与 jiàn（j 声母）声母不同，意思是不用导线，与配合无关。"}, {"text": "无价", "is_correct": false, "explanation": "jià 比 jiàn 少了韵尾 n，意思是价值极高，与配合无关。"}, {"text": "五件", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是五件东西，是数量短语。"}], "explanations": {"无间": "正确答案。无间：wú jiàn，形容配合默契、没有隔阂。", "无线": "xiàn（x 声母）与 jiàn（j 声母）声母不同，意思是不用导线，与配合无关。", "无价": "jià 比 jiàn 少了韵尾 n，意思是价值极高，与配合无关。", "五件": "wǔ（第三声）与 wú（第二声）声调不同，意思是五件东西，是数量短语。"}, "sentence_index": null, "correct_answer": "无间"}, "level_3": {"options": [{"text": "无间", "is_correct": true, "explanation": "正确答案。无间：合作没有隔阂，与“已经一起工作十年了”相合。"}, {"text": "短暂", "is_correct": false, "explanation": "语义：“短暂”指时间不长，与“已经一起工作十年了”矛盾。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“合作”不说“粗糙”，“粗糙”形容质地或做事不细致。"}, {"text": "散乱", "is_correct": false, "explanation": "搭配：“合作”不说“散乱”，“散乱”形容东西分散、没有条理。"}], "explanations": {"无间": "正确答案。无间：合作没有隔阂，与“已经一起工作十年了”相合。", "短暂": "语义：“短暂”指时间不长，与“已经一起工作十年了”矛盾。", "粗糙": "搭配：“合作”不说“粗糙”，“粗糙”形容质地或做事不细致。", "散乱": "搭配：“合作”不说“散乱”，“散乱”形容东西分散、没有条理。"}, "sentence_index": 6, "correct_answer": "无间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个问题解释得很无间。", "explanation": "这里应该用〈清楚〉。无间不用来形容解释是否明白。"}, {"text": "他做作业很无间。", "explanation": "这里应该用〈认真〉。无间用于人与人之间的配合，不用来形容做事的态度。"}, {"text": "房间打扫得很无间。", "explanation": "这里应该用〈整洁〉。无间不用来形容房间干净与否。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们是配合无间好搭档。", "corrected_sentence": "他们是配合无间的好搭档。", "error_description": "“配合无间”修饰名词“搭档”时中间要加“的”，应说“配合无间的好搭档”，不能说“配合无间好搭档”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这对配合无间地老同事很有名。", "corrected_sentence": "这对配合无间的老同事很有名。", "error_description": "结构助词错误：修饰名词“老同事”应用“的”，不能用“地”（“地”用于修饰动词）。应说“配合无间的老同事”，不说“配合无间地老同事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95727, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "快乐", "is_correct": true, "explanation": "快乐与烦恼意思相反，是反义词。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明形容头脑灵活，与烦恼的意思没有反义关系。"}, {"text": "认真", "is_correct": false, "explanation": "认真形容做事专心，与烦恼没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮形容外貌或事物好看，与烦恼没有反义关系。"}], "correct_answer": "快乐", "explanations": {"快乐": "快乐与烦恼意思相反，是反义词。", "聪明": "聪明形容头脑灵活，与烦恼的意思没有反义关系。", "认真": "认真形容做事专心，与烦恼没有反义关系。", "漂亮": "漂亮形容外貌或事物好看，与烦恼没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95727, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "快乐", "is_correct": true, "explanation": "快乐与烦恼意思相反，是反义词。"}, {"text": "勇敢", "is_correct": false, "explanation": "勇敢形容不怕困难、胆量大，与烦恼没有反义关系。"}, {"text": "大方", "is_correct": false, "explanation": "大方形容举止不拘束或不吝啬，与烦恼没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚形容明白、不模糊，与烦恼没有反义关系。"}], "correct_answer": "快乐", "explanations": {"快乐": "快乐与烦恼意思相反，是反义词。", "勇敢": "勇敢形容不怕困难、胆量大，与烦恼没有反义关系。", "大方": "大方形容举止不拘束或不吝啬，与烦恼没有反义关系。", "清楚": "清楚形容明白、不模糊，与烦恼没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95727, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "烦恼是心里有事想不通，不开心的感觉。", "primary_collocate": null, "pronunciation": "fán nǎo", "ipa": "fan˧˥ nɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我有一个小烦恼。", "target_word": "烦恼", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每个人都有自己的烦恼。", "target_word": "烦恼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友不理我，这是我现在的烦恼。", "target_word": "烦恼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听音乐能让我忘掉烦恼。", "target_word": "烦恼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他今天没有烦恼，笑得很开心。", "target_word": "烦恼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不知道怎么跟妈妈说我的烦恼。", "target_word": "烦恼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试多了，同学们的烦恼也多了。", "target_word": "烦恼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把烦恼写在本子上，心里好多了。", "target_word": "烦恼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子也有烦恼，只是我们不知道。", "target_word": "烦恼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有烦恼的时候，我喜欢和好朋友聊天。", "target_word": "烦恼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "煩惱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "日常小事想不通而不开心的感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '277212ec-c05c-4f82-b617-5b3b2e2110c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95727, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "烦恼", "is_correct": true, "explanation": "烦恼指心里有事想不通、不开心的感觉，可以说“一个小烦恼”，句意通顺。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：“海洋”很大，与前面的“小”矛盾，不能说“小海洋”。"}, {"text": "雨水", "is_correct": false, "explanation": "搭配：“雨水”是不可数的物质，不用量词“个”计量，不说“一个小雨水”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不可用量词“个”计量，不说“一个小天气”。"}], "explanations": {"烦恼": "烦恼指心里有事想不通、不开心的感觉，可以说“一个小烦恼”，句意通顺。", "海洋": "语义：“海洋”很大，与前面的“小”矛盾，不能说“小海洋”。", "雨水": "搭配：“雨水”是不可数的物质，不用量词“个”计量，不说“一个小雨水”。", "天气": "搭配：“天气”不可用量词“个”计量，不说“一个小天气”。"}, "sentence_index": 0, "correct_answer": "烦恼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天太热了，他烦恼得满头大汗。", "explanation": "这里应该用〈热〉。烦恼指心里有事想不通、不开心，不表示身体因天热而出汗。"}, {"text": "这部电影太好笑了，他烦恼得笑个不停。", "explanation": "这里应该用〈开心〉。烦恼表示心里放不下的忧虑，与“笑个不停”的快乐正好相反。"}, {"text": "听到敲门声，他烦恼地跳了起来。", "explanation": "这里应该用〈惊慌〉。烦恼表示心里有事想不通、放不下，不表示突然受惊、慌张的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95727, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烦恼", "is_correct": true, "explanation": "“同学们的烦恼也多了”表示心里的忧愁增多，与“考试多了”呼应，句意通顺。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”一般说“高了”“矮了”，不说“多了”。"}, {"text": "年纪", "is_correct": false, "explanation": "搭配：“年纪”一般说“大了”，不说“同学们的年纪也多了”。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：“眼睛”是身体器官，不会因为“考试多了”而“多了”，与语境不合。"}], "explanations": {"烦恼": "“同学们的烦恼也多了”表示心里的忧愁增多，与“考试多了”呼应，句意通顺。", "身高": "搭配：“身高”一般说“高了”“矮了”，不说“多了”。", "年纪": "搭配：“年纪”一般说“大了”，不说“同学们的年纪也多了”。", "眼睛": "体貌：“眼睛”是身体器官，不会因为“考试多了”而“多了”，与语境不合。"}, "sentence_index": 6, "correct_answer": "烦恼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿到冠军奖杯，烦恼地向大家挥手。", "explanation": "这里应该用〈自豪〉。烦恼表示心里放不下的忧虑，与拿到冠军时的自豪不符。"}, {"text": "听到好消息，他烦恼得说不出话。", "explanation": "这里应该用〈激动〉。烦恼指心里不安、想不开，与好消息带来的兴奋不符。"}, {"text": "他考了第一名，十分烦恼。", "explanation": "这里应该用〈得意〉。烦恼表示心里有事想不通，与考第一名的喜悦正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95727, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我一直在想这件事，心里有一条烦恼。", "corrected_sentence": "我一直在想这件事，心里有一个烦恼。", "error_description": "错误：“一条烦恼”；正确：“一个烦恼”。“烦恼”的量词用“个”，“条”用于细长的事物，不能用来数烦恼。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95727, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于把心里的烦恼的说了出来。", "corrected_sentence": "他终于把心里的烦恼说了出来。", "error_description": "错误：“烦恼的说了出来”；正确：“烦恼说了出来”。“把”字句中，宾语“烦恼”后直接接动词“说”，中间多出的“的”应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
