INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95728, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95728, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心里苦闷、忧愁，不能得到安宁的情绪。", "primary_collocate": null, "pronunciation": "fán nǎo", "ipa": "fan˧˥ nɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他心里的烦恼，没有人能懂。", "target_word": "烦恼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "失去工作后，他的烦恼越来越多。", "target_word": "烦恼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里睡不着，是因为心里有太多烦恼。", "target_word": "烦恼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些烦恼像一块大石头压在她心上。", "target_word": "烦恼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她笑着说，没有什么烦恼是过不去的。", "target_word": "烦恼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人一个人住，心里常常有说不出的烦恼。", "target_word": "烦恼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了很久，还是没办法摆脱烦恼。", "target_word": "烦恼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生病给全家人带来了很多烦恼。", "target_word": "烦恼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸看着窗外，脸上全是烦恼。", "target_word": "烦恼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对他来说，没钱交学费是最大的烦恼。", "target_word": "烦恼", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "煩惱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "苦闷忧愁、内心不得安宁的沉重情绪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '277212ec-c05c-4f82-b617-5b3b2e2110c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95728, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "烦恼", "is_correct": true, "explanation": "“心里的烦恼”指内心苦闷、不得安宁的沉重情绪，与“没有人能懂”呼应，句意通顺。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：“西瓜”是水果，不能藏在心里，与“心里的”搭配不通。"}, {"text": "数学", "is_correct": false, "explanation": "语义：“数学”是学科，不是心里的情绪，不说“心里的数学”。"}, {"text": "面容", "is_correct": false, "explanation": "体貌：“面容”指外貌，不在心里，与“心里的”矛盾。"}], "explanations": {"烦恼": "“心里的烦恼”指内心苦闷、不得安宁的沉重情绪，与“没有人能懂”呼应，句意通顺。", "西瓜": "语义：“西瓜”是水果，不能藏在心里，与“心里的”搭配不通。", "数学": "语义：“数学”是学科，不是心里的情绪，不说“心里的数学”。", "面容": "体貌：“面容”指外貌，不在心里，与“心里的”矛盾。"}, "sentence_index": 0, "correct_answer": "烦恼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一家人团圆时，他烦恼地拍起了手。", "explanation": "这里应该用〈高兴〉。烦恼表示心里放不下的苦闷，与团圆时的快乐正好相反。"}, {"text": "一看见桌上的蛋糕，他烦恼得直咽口水。", "explanation": "这里应该用〈馋〉。烦恼是心里放不下的忧虑，不表示对食物的渴望。"}, {"text": "半夜听到响声，他烦恼得不敢睁眼。", "explanation": "这里应该用〈害怕〉。烦恼指心里的苦闷和不安，不表示因恐惧而不敢睁眼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95728, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烦恼", "is_correct": true, "explanation": "“摆脱烦恼”是常见搭配，与“没办法”呼应，表示无法摆脱心里的苦闷。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“摆脱”后接的是负担或状态，不说“摆脱空气”。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：“太阳”不是可以摆脱的烦扰，与“想了很久”的语境不合。"}, {"text": "脸", "is_correct": false, "explanation": "体貌：“脸”是身体的部位，不能说“摆脱脸”。"}], "explanations": {"烦恼": "“摆脱烦恼”是常见搭配，与“没办法”呼应，表示无法摆脱心里的苦闷。", "空气": "搭配：“摆脱”后接的是负担或状态，不说“摆脱空气”。", "太阳": "语义：“太阳”不是可以摆脱的烦扰，与“想了很久”的语境不合。", "脸": "体貌：“脸”是身体的部位，不能说“摆脱脸”。"}, "sentence_index": 6, "correct_answer": "烦恼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他得到了奖学金，烦恼得跳起来。", "explanation": "这里应该用〈高兴〉。烦恼表示心里不安，与得到奖学金的喜悦相反。"}, {"text": "他拿到了心仪的礼物，烦恼得直发抖。", "explanation": "这里应该用〈兴奋〉。烦恼表示心里不安、想不开，与拿到心仪礼物时的兴奋不符。"}, {"text": "我躺在海边晒太阳，烦恼得眯起了眼睛。", "explanation": "这里应该用〈舒服〉。烦恼指心里的忧愁不安，不用来形容身心放松的舒适感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他小时候也有过一本烦恼。", "corrected_sentence": "他小时候也有过一个烦恼。", "error_description": "错误：“一本烦恼”；正确：“一个烦恼”。“烦恼”的量词用“个”，“本”用于书册，不能用来数烦恼。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他心里的烦恼多的数不清。", "corrected_sentence": "他心里的烦恼多得数不清。", "error_description": "错误：“多的数不清”；正确：“多得数不清”。“多”后面的程度补语要用“得”，不用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
