INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95729, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天掉了一只牙。", "corrected_sentence": "我昨天掉了一颗牙。", "error_description": "量词错误：“牙”应该用“颗”，不能用“只”，“只”用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95729, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家宝宝的牙已经长出来过。", "corrected_sentence": "我家宝宝的牙已经长出来了。", "error_description": "体标错误：“过”表示经历，这里说的是牙已经长出、变化已完成，应用“了”，说“长出来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
