INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95733, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生涯是一个人做某一件事做了很多年的日子。", "primary_collocate": null, "pronunciation": "shēng yá", "ipa": "ʂɤŋ˥ ja˧˥", "syllable_count": 2, "sentences": [{"text": "他的教师生涯一共有三十年。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在球场上度过了二十年的运动生涯。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，当兵的生涯让他学会了坚强。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的工作生涯才刚刚开始。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位演员的舞台生涯超过四十年。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "退休以后，他常常回忆自己的医生生涯。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的写作生涯很长，写了二十多本书。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王的司机生涯从二十岁开始。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的歌手生涯很成功，大家都喜欢她。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他结束了十年的足球生涯，开了一家小店。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一个人长年做某件事所度过的日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ce3a876-3c1d-44d7-b39d-01649e9db7d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95733, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生涯", "is_correct": true, "explanation": "正确。生涯指一个人长年做某件事的时期，可以说“教师生涯”，“一共有三十年”说明时长。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历指受教育的程度，不能持续“三十年”，与“一共有三十年”的时长说法冲突。"}, {"text": "年纪", "is_correct": false, "explanation": "搭配：“年纪”说的是年龄，不说“教师年纪一共有三十年”，与“教师”后面的时期说法不搭配。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是性格特点，不是可以计算年数的时期，与句子的时长不符。"}], "explanations": {"生涯": "正确。生涯指一个人长年做某件事的时期，可以说“教师生涯”，“一共有三十年”说明时长。", "学历": "语义：学历指受教育的程度，不能持续“三十年”，与“一共有三十年”的时长说法冲突。", "年纪": "搭配：“年纪”说的是年龄，不说“教师年纪一共有三十年”，与“教师”后面的时期说法不搭配。", "脾气": "语义：脾气是性格特点，不是可以计算年数的时期，与句子的时长不符。"}, "sentence_index": 0, "correct_answer": "生涯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次去西藏的旅行是我最难忘的生涯。", "explanation": "这里应该用〈经历〉。生涯指长年从事某件事的时期，一次旅行不能叫生涯。"}, {"text": "毕业以后，我送给老师一份好生涯。", "explanation": "这里应该用〈礼物〉。生涯是抽象的一段时期，不能一份一份地送人，应说“礼物”。"}, {"text": "这个夏天的生涯很短暂。", "explanation": "这里应该用〈时光〉。生涯指长年从事某事的一段时期，用于一个夏天这样的短暂时间不合适。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95733, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生涯", "is_correct": true, "explanation": "正确。“写作生涯”指长年从事写作的时期，与“很长”和“写了二十多本书”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有长短，不能说“写作颜色很长”，也与写书无关。"}, {"text": "发音", "is_correct": false, "explanation": "语义：发音是说话的声音，不是写作的时期，“写作发音很长”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身体高矮，不能用来形容写作，句子说“很长”也不通。"}], "explanations": {"生涯": "正确。“写作生涯”指长年从事写作的时期，与“很长”和“写了二十多本书”相合。", "颜色": "语义：颜色没有长短，不能说“写作颜色很长”，也与写书无关。", "发音": "语义：发音是说话的声音，不是写作的时期，“写作发音很长”说不通。", "身高": "体貌：“身高”指人的身体高矮，不能用来形容写作，句子说“很长”也不通。"}, "sentence_index": 6, "correct_answer": "生涯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛只用了十分钟，却是他的足球生涯。", "explanation": "这里应该用〈时刻〉。生涯指长年从事某事的一段时期，只用十分钟的比赛不能叫生涯，应说“时刻”。"}, {"text": "他把自己的生涯放进了行李箱。", "explanation": "这里应该用〈物品〉。生涯是抽象的一段时期，不是可以装进行李箱的具体东西，应说“物品”。"}, {"text": "妈妈把他的生涯洗干净，晾在阳台上。", "explanation": "这里应该用〈衣服〉。生涯是抽象的一段时期，不能洗涤、晾晒，此处应说“衣服”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95733, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在这所学校度过了一场漫长的生涯。", "corrected_sentence": "他在这所学校度过了一段漫长的生涯。", "error_description": "量词错误：“生涯”应该用“段”，不能用“场”。“场”用于比赛、演出等事件，“一场漫长的生涯”错误，应改为“一段漫长的生涯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95733, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的教师生涯结束起来，她转行做了编辑。", "corrected_sentence": "她的教师生涯结束了，她转行做了编辑。", "error_description": "补语错误：表示事情已经完成，“结束”后应用“了”，不能用“起来”。错误句是“结束起来”，正确句是“结束了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95734, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95734, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95734, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人从事某种活动或职业的经历和时期。", "primary_collocate": null, "pronunciation": "shēng yá", "ipa": "ʂɤŋ˥ ja˧˥", "syllable_count": 2, "sentences": [{"text": "在大学的学习生涯中，她认识了很多朋友。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的职业生涯很顺利。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师的教学生涯充满了快乐。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在军队的生涯给他留下了很多回忆。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想写一本书，讲讲自己的律师生涯。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位运动员的生涯里有过很多次比赛。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚开始工作的那几年，是我职业生涯最难的时候。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的政治生涯在五十岁时结束了。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的校园生涯从今天开始，我有点紧张。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的生涯很辛苦，但是他很喜欢。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "人从事某种活动或职业的经历和时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ce3a876-3c1d-44d7-b39d-01649e9db7d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95734, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生涯", "is_correct": true, "explanation": "正确。“学习生涯”指在某段时间内的学习经历和时期，“大学的学习”与之搭配。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的重量，不是一段学习的时期，与句子意思不符。"}, {"text": "饭量", "is_correct": false, "explanation": "语义：饭量指吃饭的多少，与“学习”的时期无关，句子说不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“学习”后面不能接“价格”，“学习价格”的搭配不通。"}], "explanations": {"生涯": "正确。“学习生涯”指在某段时间内的学习经历和时期，“大学的学习”与之搭配。", "体重": "语义：体重是身体的重量，不是一段学习的时期，与句子意思不符。", "饭量": "语义：饭量指吃饭的多少，与“学习”的时期无关，句子说不通。", "价格": "搭配：“学习”后面不能接“价格”，“学习价格”的搭配不通。"}, "sentence_index": 0, "correct_answer": "生涯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个周末的生涯很短暂。", "explanation": "这里应该用〈时光〉。生涯指长时间从事某活动或职业的时期，用于一个周末这样的短时间不合适。"}, {"text": "他在军队的生涯只用了十分钟，就结束了训练。", "explanation": "这里应该用〈时间〉。生涯指长时间的一段时期，十分钟这样的短时间应说“时间”。"}, {"text": "他把军队的生涯装进了书包。", "explanation": "这里应该用〈照片〉。生涯是抽象的一段时期，不是可以装进书包的具体东西，应说“照片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95734, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生涯", "is_correct": true, "explanation": "正确。“职业生涯”指长期从事某种职业的时期，与“最难的时候”相合。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历是受教育的程度，不是工作的时期，“职业学历最难的时候”说不通。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：“脸色”指面部的神情，不能用来说职业阶段，句子不通。"}, {"text": "年纪", "is_correct": false, "explanation": "语义：年纪指年龄，不是工作的一段时期，“职业年纪最难”不符合句意。"}], "explanations": {"生涯": "正确。“职业生涯”指长期从事某种职业的时期，与“最难的时候”相合。", "学历": "语义：学历是受教育的程度，不是工作的时期，“职业学历最难的时候”说不通。", "脸色": "体貌：“脸色”指面部的神情，不能用来说职业阶段，句子不通。", "年纪": "语义：年纪指年龄，不是工作的一段时期，“职业年纪最难”不符合句意。"}, "sentence_index": 6, "correct_answer": "生涯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都给自己的生涯浇水。", "explanation": "这里应该用〈植物〉。生涯是一段时期，不能浇水，浇水的对象应是植物。"}, {"text": "这次体检只用了一个小时，却是他的医生生涯。", "explanation": "这里应该用〈经历〉。生涯指长期从事某职业的时期，一次一个小时的体检不能称为生涯，应说“经历”。"}, {"text": "他把医生的生涯打碎，扔进了垃圾桶。", "explanation": "这里应该用〈碗〉。生涯是抽象的一段时期，不能打碎、扔掉，此处应换成可以打碎的具体器物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95734, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在工厂的一座生涯里，学会了很多技术。", "corrected_sentence": "他在工厂的一段生涯里，学会了很多技术。", "error_description": "量词错误：“生涯”应该用“段”，不能用“座”。“座”用于山、楼等大型固定物，“一座生涯”错误，应改为“一段生涯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95734, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的职业生涯在五十岁时结束着。", "corrected_sentence": "他的职业生涯在五十岁时结束了。", "error_description": "体标错误：“结束”表示动作已经完成，不能加“着”，应说“结束了”。错误句是“结束着”，正确句是“结束了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
