INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95737, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "省级是比市大的一级。一个省里最大的那一级就叫省级。", "primary_collocate": null, "pronunciation": "shěng jí", "ipa": "ʂɤŋ˨˩˦ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "这是省级医院。", "target_word": "省级", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "省级比市级大。", "target_word": "省级", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "省级领导来我们市了。", "target_word": "省级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "县级归市管，市级归省级管。", "target_word": "省级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办公室比市级高，是省级的。", "target_word": "省级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们市的文化馆升成了省级单位。", "target_word": "省级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先是县级，再是市级，最后是省级。", "target_word": "省级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全省最大的医院，也就是省级医院，在省会。", "target_word": "省级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里解决不了的事，可以向省级部门反映。", "target_word": "省级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学是省级重点学校，比市里的学校级别高。", "target_word": "省级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "省級", "label": "繁体"}], "register": "书面", "sense_fingerprint": "行政级别中比市级大、一省之内最高的一级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a78e25c3-ee67-45e4-a792-d0210b249480') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95737, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "省级", "is_correct": true, "explanation": "省级 shěng jí 是正确答案，指比市级大、一省之内最高的一级。"}, {"text": "升级", "is_correct": false, "explanation": "升级 shēng jí（第一声）与 shěng jí（第三声）声调不同，意思是提升一级。"}, {"text": "省际", "is_correct": false, "explanation": "省际 shěng jì（第四声）与 shěng jí（第二声）末字声调不同，意思是省与省之间。"}, {"text": "声级", "is_correct": false, "explanation": "声级 shēng jí（第一声）与 shěng jí（第三声）声调不同，意思是声音的强弱等级。"}], "explanations": {"省级": "省级 shěng jí 是正确答案，指比市级大、一省之内最高的一级。", "升级": "升级 shēng jí（第一声）与 shěng jí（第三声）声调不同，意思是提升一级。", "省际": "省际 shěng jì（第四声）与 shěng jí（第二声）末字声调不同，意思是省与省之间。", "声级": "声级 shēng jí（第一声）与 shěng jí（第三声）声调不同，意思是声音的强弱等级。"}, "sentence_index": null, "correct_answer": "省级"}, "level_3": {"options": [{"text": "省级", "is_correct": true, "explanation": "省级修饰医院，表示省一级的医院，句意通顺。"}, {"text": "甜", "is_correct": false, "explanation": "语义：甜指味道，不能用来描述医院的级别。"}, {"text": "辣", "is_correct": false, "explanation": "语义：辣指刺激味觉的感受，用在医院上不合常理。"}, {"text": "嫩", "is_correct": false, "explanation": "搭配：嫩多用于食物、植物，不修饰医院。"}], "explanations": {"省级": "省级修饰医院，表示省一级的医院，句意通顺。", "甜": "语义：甜指味道，不能用来描述医院的级别。", "辣": "语义：辣指刺激味觉的感受，用在医院上不合常理。", "嫩": "搭配：嫩多用于食物、植物，不修饰医院。"}, "sentence_index": 0, "correct_answer": "省级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家住在省级，离市区很近。", "explanation": "省级表示行政级别，不是地名，不能说住在省级。这里误把级别当成了地方。"}, {"text": "这家酒店的省级很高，客人都很满意。", "explanation": "这里应该用〈档次〉。省级是具体的行政级别名称，不能泛指酒店的档次高低；说档次高，要用“档次”。"}, {"text": "这个孩子是省级的，每天都很乖。", "explanation": "这里应该用〈听话〉。省级是行政级别，不用来形容孩子的性格和表现，形容孩子的表现要用听话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95737, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "省级", "is_correct": true, "explanation": "省级填在句末，表示最高的一级，句意通顺。"}, {"text": "湿", "is_correct": false, "explanation": "语义：湿指含有水分，与行政级别无关。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：瘦形容人或物的体型，不用来表示级别。"}, {"text": "软", "is_correct": false, "explanation": "搭配：软形容质地或性情，不说软级别。"}], "explanations": {"省级": "省级填在句末，表示最高的一级，句意通顺。", "湿": "语义：湿指含有水分，与行政级别无关。", "瘦": "体貌：瘦形容人或物的体型，不用来表示级别。", "软": "搭配：软形容质地或性情，不说软级别。"}, "sentence_index": 6, "correct_answer": "省级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的省级很长。", "explanation": "省级是行政级别，不表示河流的长度，这里把级别说成了长短，误用了词义。"}, {"text": "她的画的省级很高，参加了很多展览。", "explanation": "这里应该用〈精美〉。省级是具体的行政级别名称，不能泛指画作的好坏；评价画作要用“精美”。"}, {"text": "他跑步的省级很快。", "explanation": "省级不表示速度，用在“跑步”的快慢上是误用，与级别的意思无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95737, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我表哥的单位是很省级机关。", "corrected_sentence": "我表哥的单位是省级机关。", "error_description": "错误：在区别词“省级”前加了程度副词“很”。正确：应为“是省级机关”。省级是区别词，只修饰名词，不能受“很”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95737, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份文件是很省级部门发的。", "corrected_sentence": "这份文件是省级部门发的。", "error_description": "错误：在区别词“省级”前加了程度副词“很”。正确：应为“是省级部门发的”。省级是区别词，不能受“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
