INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95738, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "属于省一级的；级别在省这一层的。", "primary_collocate": null, "pronunciation": "shěng jí", "ipa": "ʂɤŋ˨˩˦ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "这是省级比赛。", "target_word": "省级", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次考试是省级统一考试。", "target_word": "省级", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这片湿地是省级保护区。", "target_word": "省级", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他得了省级奖。", "target_word": "省级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她是省级运动员，每天都要训练。", "target_word": "省级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他参加了省级数学比赛，拿到了第一名。", "target_word": "省级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府给这个村发了省级补助。", "target_word": "省级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师获得过省级教学奖。", "target_word": "省级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的画拿过省级比赛的金奖。", "target_word": "省级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家博物馆已经成为省级文物保护单位。", "target_word": "省级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "省級", "label": "繁体"}], "register": "书面", "sense_fingerprint": "定语：属于省一级的（比赛、奖项、单位等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a78e25c3-ee67-45e4-a792-d0210b249480') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95738, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "省级", "is_correct": true, "explanation": "省级 shěng jí 是正确答案，指属于省一级的。"}, {"text": "升级", "is_correct": false, "explanation": "升级 shēng jí（第一声）与 shěng jí（第三声）声调不同，意思是提升一级。"}, {"text": "省际", "is_correct": false, "explanation": "省际 shěng jì（第四声）与 shěng jí（第二声）末字声调不同，意思是省与省之间。"}, {"text": "声级", "is_correct": false, "explanation": "声级 shēng jí（第一声）与 shěng jí（第三声）声调不同，意思是声音的强弱等级。"}], "explanations": {"省级": "省级 shěng jí 是正确答案，指属于省一级的。", "升级": "升级 shēng jí（第一声）与 shěng jí（第三声）声调不同，意思是提升一级。", "省际": "省际 shěng jì（第四声）与 shěng jí（第二声）末字声调不同，意思是省与省之间。", "声级": "声级 shēng jí（第一声）与 shěng jí（第三声）声调不同，意思是声音的强弱等级。"}, "sentence_index": null, "correct_answer": "省级"}, "level_3": {"options": [{"text": "省级", "is_correct": true, "explanation": "省级修饰比赛，表示属于省一级的比赛，句意通顺。"}, {"text": "甜", "is_correct": false, "explanation": "语义：甜指味道，不能用来修饰比赛。"}, {"text": "辣", "is_correct": false, "explanation": "语义：辣指刺激味觉的感受，不能用来修饰比赛。"}, {"text": "嫩", "is_correct": false, "explanation": "搭配：嫩多用于食物、植物，不修饰比赛。"}], "explanations": {"省级": "省级修饰比赛，表示属于省一级的比赛，句意通顺。", "甜": "语义：甜指味道，不能用来修饰比赛。", "辣": "语义：辣指刺激味觉的感受，不能用来修饰比赛。", "嫩": "搭配：嫩多用于食物、植物，不修饰比赛。"}, "sentence_index": 0, "correct_answer": "省级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛的省级很高，大家都很激动。", "explanation": "这里应该用〈级别〉。省级是某一个具体的行政级别名称，不能用来泛指比赛的级别高低，说级别高要用级别。"}, {"text": "他是省级的好人，很热心。", "explanation": "省级说的是所属的级别，不用来评价人的品德，这里误用为性格的评价。"}, {"text": "这位运动员是省级选手，代表国家参加了奥运会。", "explanation": "这里应该用〈国家级〉。省级指属于省一级的，代表国家参加奥运会的选手应是国家级，不能说省级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95738, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "省级", "is_correct": true, "explanation": "省级修饰补助，表示省一级的补助，句意通顺。"}, {"text": "湿", "is_correct": false, "explanation": "语义：湿指含有水分，与补助无关。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：瘦形容人或物的体型，不能修饰补助。"}, {"text": "软", "is_correct": false, "explanation": "搭配：软形容质地或性情，不说软补助。"}], "explanations": {"省级": "省级修饰补助，表示省一级的补助，句意通顺。", "湿": "语义：湿指含有水分，与补助无关。", "瘦": "体貌：瘦形容人或物的体型，不能修饰补助。", "软": "搭配：软形容质地或性情，不说软补助。"}, "sentence_index": 6, "correct_answer": "省级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个博物馆非常省级，很多人来参观。", "explanation": "这里应该用〈有名〉。省级表示所属的行政级别，只能修饰名词，不能受“非常”修饰作谓语；说博物馆受欢迎要用有名。"}, {"text": "这位同学是省级的，每天都很努力。", "explanation": "这里应该用〈认真〉。省级是行政级别，不用来形容学生的学习态度，形容学习态度要用认真。"}, {"text": "我每天早上都在省级跑步。", "explanation": "这里应该用〈在公园〉。省级是行政级别，不是地点，不能说在省级跑步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她参加了很省级数学竞赛。", "corrected_sentence": "她参加了省级数学竞赛。", "error_description": "错误：在区别词“省级”前加了程度副词“很”。正确：应为“省级数学竞赛”。省级是区别词，只修饰名词，不能受“很”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位画家获得了很省级金奖。", "corrected_sentence": "这位画家获得了省级金奖。", "error_description": "错误：在区别词“省级”前加了程度副词“很”。正确：应为“省级金奖”。省级是区别词，不能受“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
