INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95739, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "空调是一种机器。热的时候它能吹冷风，冷的时候能吹暖风。", "primary_collocate": null, "pronunciation": "kōng tiáo", "ipa": "kʰʊŋ˥ tʰiɑʊ̯˧˥", "syllable_count": 2, "sentences": [{"text": "夏天太热，请打开空调。", "target_word": "空调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里有一台空调。", "target_word": "空调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空调坏了，房间很热。", "target_word": "空调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天空调能吹暖风。", "target_word": "空调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把空调关了。", "target_word": "空调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台空调吹出的风很冷。", "target_word": "空调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把空调开小一点。", "target_word": "空调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家买了两台新空调。", "target_word": "空调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上我不开空调睡觉。", "target_word": "空调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空调的声音太大了。", "target_word": "空调", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "空調", "label": "繁体"}, {"form": "中央空调", "label": "复合"}], "register": "口语", "sense_fingerprint": "日常家用的吹冷风、暖风的机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b283c72b-36cb-4649-9609-b1e6be703ed2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95739, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空调", "is_correct": true, "explanation": "空调可以在夏天制冷，符合“太热”和“打开”的语境。"}, {"text": "暖气", "is_correct": false, "explanation": "语义：暖气用于制热，夏天太热时打开它只会更热，句意不通。"}, {"text": "电炉", "is_correct": false, "explanation": "语义：电炉只能加热，夏天太热时打开会加重炎热，与“请打开”的意图相反。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：冰箱用来冷藏食物，不用来给房间降温，不能与“太热，请打开”搭配。"}], "explanations": {"空调": "空调可以在夏天制冷，符合“太热”和“打开”的语境。", "暖气": "语义：暖气用于制热，夏天太热时打开它只会更热，句意不通。", "电炉": "语义：电炉只能加热，夏天太热时打开会加重炎热，与“请打开”的意图相反。", "冰箱": "搭配：冰箱用来冷藏食物，不用来给房间降温，不能与“太热，请打开”搭配。"}, "sentence_index": 0, "correct_answer": "空调"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我口渴了，想喝一杯空调。", "explanation": "这里应该用〈饮料〉。“喝”的对象是饮料等液体，空调是调节温度的机器，不能喝。"}, {"text": "山上的空调很新鲜，我们深深地呼吸。", "explanation": "这里应该用〈空气〉。“新鲜”形容的是空气，空调是调节温度的机器，不能说新鲜。"}, {"text": "洗完头后，我用空调护理头发。", "explanation": "这里应该用〈护发素〉。护发素是护理头发的产品，空调是调节温度的机器，不能用来护理头发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95739, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空调", "is_correct": true, "explanation": "空调有档位可以调小，“开小一点”正好描述调节风力或温度。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板没有开关或档位，不能开小，句意不通。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶不能开关，也没有可以调小的功能。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子没有开关或档位，不能“开小一点”，句意不通。"}], "explanations": {"空调": "空调有档位可以调小，“开小一点”正好描述调节风力或温度。", "黑板": "语义：黑板没有开关或档位，不能开小，句意不通。", "花瓶": "语义：花瓶不能开关，也没有可以调小的功能。", "椅子": "语义：椅子没有开关或档位，不能“开小一点”，句意不通。"}, "sentence_index": 6, "correct_answer": "空调"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套房子的空调很宽敞，住着很舒服。", "explanation": "这里应该用〈空间〉。“宽敞”形容的是空间，空调是调节温度的机器，不能说宽敞。"}, {"text": "空调的冷冻室里放着很多冰块。", "explanation": "这里应该用〈冰箱〉。冷冻室是冰箱的一部分，用来冻食物；空调只调节室内温度，没有冷冻室。"}, {"text": "他说的都是空调，没有一句实在的。", "explanation": "这里应该用〈空话〉。空话指没有实际内容的话，空调是调节温度的机器，不能指说的话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95739, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把空调高调了一点。", "corrected_sentence": "我把空调调高了一点。", "error_description": "错误：“高调”，补语“高”放在了动词前。正确：“调高”。动补结构中，补语“高”应放在动词之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95739, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家的空调修了过。", "corrected_sentence": "我家的空调修过了。", "error_description": "错误：“修了过”，“过”与“了”的顺序颠倒。正确：“修过了”。表示经历过的动作，“过”紧跟动词，“了”放在句末。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
