INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95740, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "能调节室内温度和湿度的设备。", "primary_collocate": null, "pronunciation": "kōng tiáo", "ipa": "kʰʊŋ˥ tʰiɑʊ̯˧˥", "syllable_count": 2, "sentences": [{"text": "这台空调能调节湿度。", "target_word": "空调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的空调可以控制温度。", "target_word": "空调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店安装了一台空调。", "target_word": "空调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在修理办公室的空调。", "target_word": "空调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种空调很省电。", "target_word": "空调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空调让屋里又凉快又干燥。", "target_word": "空调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请定期清洗空调的过滤网。", "target_word": "空调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的空调要保持一样的温度。", "target_word": "空调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上订了一台空调。", "target_word": "空调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新空调可以自动调节温度。", "target_word": "空调", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "空調", "label": "繁体"}, {"form": "中央空调", "label": "复合"}], "register": "通用", "sense_fingerprint": "调节室内温度和湿度的设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b283c72b-36cb-4649-9609-b1e6be703ed2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95740, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空调", "is_correct": true, "explanation": "空调是能调节室内温度和湿度的设备，符合句意。"}, {"text": "烤箱", "is_correct": false, "explanation": "语义：烤箱用来加热食物，不能调节室内湿度。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱用于冷藏食物，不调节室内湿度，句意不通。"}, {"text": "洗衣机", "is_correct": false, "explanation": "搭配：“调节湿度”的对象是室内环境设备，不说洗衣机能调节湿度。"}], "explanations": {"空调": "空调是能调节室内温度和湿度的设备，符合句意。", "烤箱": "语义：烤箱用来加热食物，不能调节室内湿度。", "冰箱": "语义：冰箱用于冷藏食物，不调节室内湿度，句意不通。", "洗衣机": "搭配：“调节湿度”的对象是室内环境设备，不说洗衣机能调节湿度。"}, "sentence_index": 0, "correct_answer": "空调"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上骑空调去上班。", "explanation": "这里应该用〈自行车〉。“骑”的对象是自行车等交通工具，空调是调节温度的设备，不能骑。"}, {"text": "早上的空调很新鲜，我们去公园散步。", "explanation": "这里应该用〈空气〉。“新鲜”形容的是空气，空调是调节温度的机器，不能说新鲜。"}, {"text": "他的计划只是空调，没法实现。", "explanation": "这里应该用〈空想〉。空想指不切实际的想法，计划没法实现就是空想；空调是机器，不能指想法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95740, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空调", "is_correct": true, "explanation": "空调有过滤网，需要定期清洗，符合句意。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶没有过滤网，无法清洗其过滤网。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发没有过滤网，不需要清洗过滤网。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：“过滤网”是过滤空气或水的部件，不与窗帘搭配。"}], "explanations": {"空调": "空调有过滤网，需要定期清洗，符合句意。", "花瓶": "语义：花瓶没有过滤网，无法清洗其过滤网。", "沙发": "语义：沙发没有过滤网，不需要清洗过滤网。", "窗帘": "搭配：“过滤网”是过滤空气或水的部件，不与窗帘搭配。"}, "sentence_index": 6, "correct_answer": "空调"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "阳台的空调很宽敞，能放下一张桌子。", "explanation": "这里应该用〈空间〉。“宽敞”“能放下东西”说的是空间，空调是机器，不能用来形容大小。"}, {"text": "空调的保鲜盒里放着剩菜。", "explanation": "这里应该用〈冰箱〉。保鲜盒是冰箱里装食物的容器，空调不能用来存放剩菜。"}, {"text": "他的话全是空调，没有一句实在的。", "explanation": "这里应该用〈空话〉。空话指没有实际内容的话，空调是调节温度的机器，不能指话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95740, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家新装了一座空调。", "corrected_sentence": "我家新装了一台空调。", "error_description": "错误：量词“座”。正确：“台”。“座”用于山、桥、楼等大型固定物，空调应该用“台”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95740, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "房间里开了着空调，很凉快。", "corrected_sentence": "房间里开着空调，很凉快。", "error_description": "错误：“开了着空调”，动词“开”后多加了“了”。正确：“开着空调”。“着”表示状态持续，不与“了”同用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
