INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95741, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "第一时间就是事情一发生，马上就去做。", "primary_collocate": null, "pronunciation": "dì yī shí jiān", "ipa": "ti˥˩ i˥ ʂʐ̩˧˥ tɕjɛn˥", "syllable_count": 4, "sentences": [{"text": "地震发生后，他第一时间给家人打了电话。", "target_word": "第一时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一时间看到了你的信息。", "target_word": "第一时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生第一时间赶到了现场。", "target_word": "第一时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出了事，请你第一时间告诉我。", "target_word": "第一时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一时间把好消息告诉了妈妈。", "target_word": "第一时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到下雨，她第一时间收了衣服。", "target_word": "第一时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者第一时间发回了报道。", "target_word": "第一时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发现问题，我们要第一时间解决。", "target_word": "第一时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师第一时间回复了我的问题。", "target_word": "第一时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友生病了，我第一时间去看他。", "target_word": "第一时间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "第一時間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "第一时间：事情一发生就马上去做，常作状语放在动词前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc47c301-ed4a-4c66-ad41-95bf2b4b9f5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95741, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "第一时间", "is_correct": true, "explanation": "正确：“第一时间”表示事情一发生就马上去做，与“地震发生后”的紧接语境相合。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来，与“地震发生后”以及已完成的“打了电话”矛盾。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”指很久以前，与“地震发生后”紧接着打电话的语境不符。"}, {"text": "半天", "is_correct": false, "explanation": "搭配：“半天”表示持续的时长，不能直接修饰“打电话”这种瞬时动作。"}], "explanations": {"第一时间": "正确：“第一时间”表示事情一发生就马上去做，与“地震发生后”的紧接语境相合。", "明天": "语义：“明天”指将来，与“地震发生后”以及已完成的“打了电话”矛盾。", "去年": "语义：“去年”指很久以前，与“地震发生后”紧接着打电话的语境不符。", "半天": "搭配：“半天”表示持续的时长，不能直接修饰“打电话”这种瞬时动作。"}, "sentence_index": 0, "correct_answer": "第一时间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他第一时间的工作地点在北京。", "explanation": "这里“第一时间”表示时刻，不能修饰“工作地点”这样的地点名词。"}, {"text": "这是我第一时间吃北京烤鸭。", "explanation": "这里应该用〈第一次〉，说某件事初次发生。第一时间指事情发生后马上，不表示“第一次”。"}, {"text": "这门课的第一时间是周一上午。", "explanation": "这里的“第一时间”指课程安排中的时段，与“事情一发生就马上去做”的意思无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95741, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "第一时间", "is_correct": true, "explanation": "正确：“第一时间”表示事情发生后最先的时刻，与“记者”的即时报道相合。"}, {"text": "下周", "is_correct": false, "explanation": "语义：“下周”指将来，与已完成的“发回了”冲突。"}, {"text": "从未", "is_correct": false, "explanation": "语义：“从未”表示从来没有，与“发回了”的完成语气矛盾。"}, {"text": "明年", "is_correct": false, "explanation": "语义：“明年”指未来，与“发回了”的完成语气矛盾。"}], "explanations": {"第一时间": "正确：“第一时间”表示事情发生后最先的时刻，与“记者”的即时报道相合。", "下周": "语义：“下周”指将来，与已完成的“发回了”冲突。", "从未": "语义：“从未”表示从来没有，与“发回了”的完成语气矛盾。", "明年": "语义：“明年”指未来，与“发回了”的完成语气矛盾。"}, "sentence_index": 6, "correct_answer": "第一时间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这列火车第一时间到站了。", "explanation": "这里应该用〈准时〉。第一时间表示事情一发生就马上，不能用来说按时刻到站。"}, {"text": "这个计划的第一时间很长。", "explanation": "这里第一时间只表示事情发生后马上的瞬间，不能指一段时长，也不能作名词充当主语来描述时间的长短。"}, {"text": "他第一时间慢慢地走过来。", "explanation": "这里第一时间表示立即，与表示缓慢进行的“慢慢地”相矛盾，此处误把它当成了表示进程的副词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95741, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈第一时间地给我打了电话。", "corrected_sentence": "妈妈第一时间给我打了电话。", "error_description": "错误形式：“第一时间”后多加了“地”。正确形式：“妈妈第一时间给我打了电话”。时间状语“第一时间”后不加“地”，直接修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95741, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学很第一时间借给了我笔记。", "corrected_sentence": "同学第一时间借给了我笔记。", "error_description": "错误形式：“很”加在“第一时间”前。正确形式：“同学第一时间借给了我笔记”。“第一时间”是时间状语，表示动作紧接着发生，不能受程度副词“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
