INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95742, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事情发生后最先的时刻，表示立即、毫不拖延。", "primary_collocate": null, "pronunciation": "dì yī shí jiān", "ipa": "ti˥˩ i˥ ʂʐ̩˧˥ tɕjɛn˥", "syllable_count": 4, "sentences": [{"text": "他在第一时间做出了决定。", "target_word": "第一时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防员在第一时间冲进了大楼。", "target_word": "第一时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息我是第一时间知道的。", "target_word": "第一时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情刚发生，他就在第一时间通知了所有人。", "target_word": "第一时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察第一时间封锁了路口。", "target_word": "第一时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情一发生，大家都在第一时间想办法。", "target_word": "第一时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她收到成绩，第一时间发给了爸爸。", "target_word": "第一时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在第一时间把问题告诉老师。", "target_word": "第一时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要在第一时间救人。", "target_word": "第一时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的车坏了，第一时间打给了修车店。", "target_word": "第一时间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "第一時間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "第一时间：事情发生后最先的时刻，强调立即、不拖延，可与“在”连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc47c301-ed4a-4c66-ad41-95bf2b4b9f5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95742, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "第一时间", "is_correct": true, "explanation": "正确：“在第一时间”表示事情发生后最先的时刻，符合“他做出决定”的即时语境。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来，与已完成的“做出了”冲突。"}, {"text": "下个月", "is_correct": false, "explanation": "语义：“下个月”是未来时间，与“了”的完成语气矛盾。"}, {"text": "整整一天", "is_correct": false, "explanation": "搭配：“在”后接的时间词要表示时点，“整整一天”是时长，不能说“在整整一天做出决定”。"}], "explanations": {"第一时间": "正确：“在第一时间”表示事情发生后最先的时刻，符合“他做出决定”的即时语境。", "明天": "语义：“明天”指将来，与已完成的“做出了”冲突。", "下个月": "语义：“下个月”是未来时间，与“了”的完成语气矛盾。", "整整一天": "搭配：“在”后接的时间词要表示时点，“整整一天”是时长，不能说“在整整一天做出决定”。"}, "sentence_index": 0, "correct_answer": "第一时间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在第一时间的办公室里工作。", "explanation": "这里“第一时间”表示事情发生后最先的时刻，不能修饰“办公室”这样的地点名词。"}, {"text": "他在第一时间的家乡风景很美。", "explanation": "这里“第一时间”表示时刻，不能修饰“家乡”这样的地点名词。"}, {"text": "他在第一时间的年轻时代很努力。", "explanation": "这里应该用〈年轻时〉。第一时间指事情发生的紧接时刻，不能指一段人生阶段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "第一时间", "is_correct": true, "explanation": "正确：“第一时间”表示事情发生后最先的时刻，与“收到成绩”后马上发出的语境相合。"}, {"text": "下周", "is_correct": false, "explanation": "语义：“下周”指将来，与已完成的“发给了”矛盾。"}, {"text": "从未", "is_correct": false, "explanation": "语义：“从未”表示从来没有，与“发给了”的完成语气矛盾。"}, {"text": "明年", "is_correct": false, "explanation": "语义：“明年”指未来，与“发给了”的完成语气冲突。"}], "explanations": {"第一时间": "正确：“第一时间”表示事情发生后最先的时刻，与“收到成绩”后马上发出的语境相合。", "下周": "语义：“下周”指将来，与已完成的“发给了”矛盾。", "从未": "语义：“从未”表示从来没有，与“发给了”的完成语气矛盾。", "明年": "语义：“明年”指未来，与“发给了”的完成语气冲突。"}, "sentence_index": 6, "correct_answer": "第一时间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的车坏了，第一时间的修车店就在路口。", "explanation": "这里应该用〈附近的〉修饰修车店。“第一时间”只能修饰动作，不能修饰地点名词。"}, {"text": "他的车坏了，第一时间的修理时间很长。", "explanation": "这里“第一时间”表示事情发生后最先的瞬间，不能用来指一段时长。"}, {"text": "他的车坏了，他第一时间慢慢地打给了修车店。", "explanation": "这里第一时间表示立即，不能与表示缓慢进行的“慢慢地”搭配，此处误把它当成了表示进程的副词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电话一响，她在第一时间的接了起来。", "corrected_sentence": "电话一响，她在第一时间接了起来。", "error_description": "错误形式：“第一时间”后多加了“的”。正确形式：“电话一响，她在第一时间接了起来”。“在第一时间”作状语，其后不能加“的”，直接接动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她接到电话，很第一时间去了医院。", "corrected_sentence": "她接到电话，第一时间去了医院。", "error_description": "错误形式：“很”加在“第一时间”前。正确形式：“她接到电话，第一时间去了医院”。“第一时间”是时间状语，表示动作紧接着发生，不能受程度副词“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
