INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95744, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示作罢，不再追究或不再继续做某事。", "primary_collocate": null, "pronunciation": "suàn le", "ipa": "swan˥˩ lə", "syllable_count": 2, "sentences": [{"text": "天太冷了，我们不去了，算了。", "target_word": "算了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店太贵，算了，去别的店吧。", "target_word": "算了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车太多了，算了，我们走路去吧。", "target_word": "算了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想来就算了，不用叫他了。", "target_word": "算了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事就算了，以后别再提了。", "target_word": "算了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排队的人太多，算了，不买了。", "target_word": "算了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不愿意帮忙就算了，我自己做。", "target_word": "算了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买不到票就算了，我们在家看电视。", "target_word": "算了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太晚了，算了，明天再做吧。", "target_word": "算了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不还钱，我也不想追究了，算了。", "target_word": "算了", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "作罢，不再追究或不再继续做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a720de0-ac80-4bf6-b407-5b4e7acb898f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95744, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "算了", "is_correct": true, "explanation": "算了（suàn le）：表示作罢，不再追究或不再继续做某事。"}, {"text": "赚了", "is_correct": false, "explanation": "声母 s 与 zh 不同，意思是“挣到（钱）”。"}, {"text": "转了", "is_correct": false, "explanation": "声母 s 与 zh 不同（转 读 zhuàn 或 zhuǎn），意思是“转动、转向”。"}, {"text": "拴了", "is_correct": false, "explanation": "声母 s 与 sh 不同，声调也不同（第四声与第一声），意思是“拴住、系上”。"}], "explanations": {"算了": "算了（suàn le）：表示作罢，不再追究或不再继续做某事。", "赚了": "声母 s 与 zh 不同，意思是“挣到（钱）”。", "转了": "声母 s 与 zh 不同（转 读 zhuàn 或 zhuǎn），意思是“转动、转向”。", "拴了": "声母 s 与 sh 不同，声调也不同（第四声与第一声），意思是“拴住、系上”。"}, "sentence_index": null, "correct_answer": "算了"}, "level_3": {"options": [{"text": "算了", "is_correct": true, "explanation": "“算了”表示作罢，与“天太冷了，我们不去了”的语境相符。"}, {"text": "去了", "is_correct": false, "explanation": "语义：“去了”与前面的“不去了”矛盾，句意不通。"}, {"text": "出发了", "is_correct": false, "explanation": "语义：“出发了”表示开始去，与“我们不去了”矛盾。"}, {"text": "抢了", "is_correct": false, "explanation": "配价：“抢”要带宾语（抢什么），“抢了”句末缺少宾语。"}], "explanations": {"算了": "“算了”表示作罢，与“天太冷了，我们不去了”的语境相符。", "去了": "语义：“去了”与前面的“不去了”矛盾，句意不通。", "出发了": "语义：“出发了”表示开始去，与“我们不去了”矛盾。", "抢了": "配价：“抢”要带宾语（抢什么），“抢了”句末缺少宾语。"}, "sentence_index": 0, "correct_answer": "算了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这笔账我算了三遍，还是不对。", "explanation": "这里的〈算了〉是“计算完毕”的意思，不是“作罢、不再追究”。"}, {"text": "我跟他算了账，他还欠我两百块。", "explanation": "这里的〈算了〉是“清算账目”的意思，与“作罢、不再追究”无关。"}, {"text": "他找先生算了一卦，说今年会发财。", "explanation": "这里的〈算了〉是“算卦”的意思，与“作罢、不再追究”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95744, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "算了", "is_correct": true, "explanation": "算了（suàn le）：表示作罢，不再追究或不再继续做某事。"}, {"text": "酸了", "is_correct": false, "explanation": "声调不同（suàn 第四声，suān 第一声），意思是“变酸”。"}, {"text": "散了", "is_correct": false, "explanation": "suàn 少了韵母中的 u，意思是“散开、分散”。"}, {"text": "涮了", "is_correct": false, "explanation": "声母 s 与 sh 不同，意思是“用热汤烫洗”。"}, {"text": "钻了", "is_correct": false, "explanation": "声母 s 与 z 不同，意思是“钻进去、钻了空子”。"}], "explanations": {"算了": "算了（suàn le）：表示作罢，不再追究或不再继续做某事。", "酸了": "声调不同（suàn 第四声，suān 第一声），意思是“变酸”。", "散了": "suàn 少了韵母中的 u，意思是“散开、分散”。", "涮了": "声母 s 与 sh 不同，意思是“用热汤烫洗”。", "钻了": "声母 s 与 z 不同，意思是“钻进去、钻了空子”。"}, "sentence_index": null, "correct_answer": "算了"}, "level_3": {"options": [{"text": "算了", "is_correct": true, "explanation": "“就算了”表示作罢，与“你不愿意帮忙”的语境相符。"}, {"text": "帮了", "is_correct": false, "explanation": "语义：“帮了”与“不愿意帮忙”矛盾，句意不通。"}, {"text": "哭了", "is_correct": false, "explanation": "语义：“哭了”与“帮忙”的语境无关，句意不通。"}, {"text": "夺了", "is_correct": false, "explanation": "配价：“夺”要带宾语（夺什么），“夺了”后面缺少宾语。"}], "explanations": {"算了": "“就算了”表示作罢，与“你不愿意帮忙”的语境相符。", "帮了": "语义：“帮了”与“不愿意帮忙”矛盾，句意不通。", "哭了": "语义：“哭了”与“帮忙”的语境无关，句意不通。", "夺了": "配价：“夺”要带宾语（夺什么），“夺了”后面缺少宾语。"}, "sentence_index": 6, "correct_answer": "算了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行的费用我算了一下，超出预算。", "explanation": "这里的〈算了〉是“计算”的意思，不是“作罢、不再追究”。"}, {"text": "那个人算了我的八字，说我命好。", "explanation": "这里的〈算了〉是“算命”的意思，与“作罢、不再追究”无关。"}, {"text": "这些零钱我算了半天，还是不够。", "explanation": "这里的〈算了〉是“计算”的意思，与“作罢、不再想”的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95744, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次就算了了，别再提了。", "corrected_sentence": "这次就算了，别再提了。", "error_description": "错误：“了”多用了一个。“算了”是一个词，后面不能再加“了”，应为“这次就算了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95744, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "算了了吧，不去就不去。", "corrected_sentence": "算了吧，不去就不去。", "error_description": "错误：“了”多用了一个。“算了吧”已表示作罢，不能再加“了”，应为“算了吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
