INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95747, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "绕就是围着一个东西转圈，或者不走直的路，走弯弯的路。", "primary_collocate": null, "pronunciation": "rào", "ipa": "ɻɑʊ̯˥˩", "syllable_count": 1, "sentences": [{"text": "孩子们绕着树跑。", "target_word": "绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球绕着太阳转。", "target_word": "绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们绕着湖走了一圈。", "target_word": "绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面在修路，我们绕了很远才到家。", "target_word": "绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路不直，要绕很大的弯。", "target_word": "绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟绕着房子飞来飞去。", "target_word": "绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了买面包，他绕了一大圈。", "target_word": "绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这儿走过去不用绕，很近。", "target_word": "绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的人绕着花走。", "target_word": "绕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我绕到学校后面去找他。", "target_word": "绕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "绕了", "label": "完成体"}, {"form": "绕着", "label": "持续体"}, {"form": "绕过", "label": "结果补语"}], "register": "中性", "sense_fingerprint": "围着东西转圈；不走直路而走弯路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a720de0-ac80-4bf6-b407-5b4e7acb898f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95747, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "绕", "is_correct": true, "explanation": "rào（第四声），意思是围着东西转圈或走弯路，是本题的目标词。"}, {"text": "饶", "is_correct": false, "explanation": "ráo（第二声）与 rào（第四声）声调不同，意思是饶恕、饶舌。"}, {"text": "扰", "is_correct": false, "explanation": "rǎo（第三声）与 rào（第四声）声调不同，意思是打扰、干扰。"}, {"text": "闹", "is_correct": false, "explanation": "nào 与 rào 声母不同（n 与 r），意思是吵闹。"}, {"text": "烙", "is_correct": false, "explanation": "lào 与 rào 声母不同（l 与 r），意思是用烧热的器具烤熟食物，如烙饼。"}], "explanations": {"绕": "rào（第四声），意思是围着东西转圈或走弯路，是本题的目标词。", "饶": "ráo（第二声）与 rào（第四声）声调不同，意思是饶恕、饶舌。", "扰": "rǎo（第三声）与 rào（第四声）声调不同，意思是打扰、干扰。", "闹": "nào 与 rào 声母不同（n 与 r），意思是吵闹。", "烙": "lào 与 rào 声母不同（l 与 r），意思是用烧热的器具烤熟食物，如烙饼。"}, "sentence_index": null, "correct_answer": "绕"}, "level_3": {"options": [{"text": "绕", "is_correct": true, "explanation": "绕：围着树转圈跑，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说吃树。"}, {"text": "修", "is_correct": false, "explanation": "语义：修是修理、修建的意思，与“树”和“跑”的句意都不搭。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮料，不能说喝树。"}], "explanations": {"绕": "绕：围着树转圈跑，符合句意。", "吃": "搭配：“吃”的对象是食物，不能说吃树。", "修": "语义：修是修理、修建的意思，与“树”和“跑”的句意都不搭。", "喝": "搭配：“喝”的对象是饮料，不能说喝树。"}, "sentence_index": 0, "correct_answer": "绕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这句话太绕了，我念不清楚。", "explanation": "这里的〈绕〉是“绕口、复杂难懂”的意思，不是“围着东西转圈或绕行”。"}, {"text": "他说话太绕，我不明白他的意思。", "explanation": "这里的〈绕〉是“说话复杂、不直接”的意思，不是“围着东西转圈或绕行”。"}, {"text": "这道题绕来绕去，我看了半天也没懂。", "explanation": "这里的〈绕〉是“绕来绕去、复杂难懂”的意思，不是“围着东西转圈或绕行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95747, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "绕", "is_correct": true, "explanation": "rào（第四声），意思是围着东西转圈或走弯路，是本题的目标词。"}, {"text": "照", "is_correct": false, "explanation": "zhào 与 rào 声母不同（zh 与 r），意思是照射、照片。"}, {"text": "涝", "is_correct": false, "explanation": "lào 与 rào 声母不同（l 与 r），意思是雨水过多造成的水灾。"}, {"text": "酪", "is_correct": false, "explanation": "lào 与 rào 声母不同（l 与 r），意思是奶酪一类的食品。"}], "explanations": {"绕": "rào（第四声），意思是围着东西转圈或走弯路，是本题的目标词。", "照": "zhào 与 rào 声母不同（zh 与 r），意思是照射、照片。", "涝": "lào 与 rào 声母不同（l 与 r），意思是雨水过多造成的水灾。", "酪": "lào 与 rào 声母不同（l 与 r），意思是奶酪一类的食品。"}, "sentence_index": null, "correct_answer": "绕"}, "level_3": {"options": [{"text": "绕", "is_correct": true, "explanation": "绕：绕了一大圈，表示走了一个很大的弯路，符合句意。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能说写一大圈。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦是抹去表面的动作，与“为了买面包”的句意不合。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物、身体等，不能说洗一大圈。"}], "explanations": {"绕": "绕：绕了一大圈，表示走了一个很大的弯路，符合句意。", "写": "搭配：“写”的对象是文字，不能说写一大圈。", "擦": "语义：擦是抹去表面的动作，与“为了买面包”的句意不合。", "洗": "搭配：“洗”的对象是衣物、身体等，不能说洗一大圈。"}, "sentence_index": 6, "correct_answer": "绕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的话太绕了，我没听明白。", "explanation": "这里的〈绕〉是“绕口、说得太复杂”的意思，不是“围着东西转圈或绕行”。"}, {"text": "毛线把小猫的腿绕住了。", "explanation": "这里的〈绕〉是“缠住”的意思，不是“围着东西转圈或绕行”。"}, {"text": "这份说明写得太绕，大家都看不懂。", "explanation": "这里的〈绕〉是“绕来绕去、复杂难懂”的意思，不是“围着东西转圈或绕行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95747, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他绕着着操场跑了两圈。", "corrected_sentence": "他绕着操场跑了两圈。", "error_description": "错误：“着”多用了一个。“绕着”后面不能再加“着”，应为“绕着操场跑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95747, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他绕了到车站后面去接朋友。", "corrected_sentence": "他绕到了车站后面去接朋友。", "error_description": "“了”放错了位置。“绕”和补语“到”之间不能加“了”，应说“绕到了车站后面”，了放在补语后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
