INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95749, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "老大是家里最先出生的孩子，是哥哥或者姐姐。", "primary_collocate": null, "pronunciation": "lǎo dà", "ipa": "lɑʊ̯˨˩˦ tɑ˥˩", "syllable_count": 2, "sentences": [{"text": "我哥哥是家里的老大。", "target_word": "老大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老大已经工作了，老二还在上学。", "target_word": "老大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她家有三个孩子，老大是女儿。", "target_word": "老大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我是老大，所以要照顾弟弟妹妹。", "target_word": "老大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家的老大今年十岁了。", "target_word": "老大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老大比老二大三岁。", "target_word": "老大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老大喜欢画画，老三喜欢唱歌。", "target_word": "老大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是不是家里的老大？", "target_word": "老大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老大对妹妹很好，常常带她玩儿。", "target_word": "老大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐是老大，我是最小的。", "target_word": "老大", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "家里最先出生的孩子，哥哥或姐姐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a720de0-ac80-4bf6-b407-5b4e7acb898f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95749, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老大", "is_correct": true, "explanation": "老大（lǎo dà）：家里最先出生的孩子，哥哥或姐姐。"}, {"text": "好大", "is_correct": false, "explanation": "lǎo 与 hǎo 声母不同，意思是“很大、多么大”，不是“老大”。"}, {"text": "老爸", "is_correct": false, "explanation": "dà 与 bà 声母不同，意思是“爸爸”，不是家里最先出生的孩子。"}, {"text": "老打", "is_correct": false, "explanation": "dǎ 与 dà 声调不同，意思是“总是打”，不是“老大”。"}], "explanations": {"老大": "老大（lǎo dà）：家里最先出生的孩子，哥哥或姐姐。", "好大": "lǎo 与 hǎo 声母不同，意思是“很大、多么大”，不是“老大”。", "老爸": "dà 与 bà 声母不同，意思是“爸爸”，不是家里最先出生的孩子。", "老打": "dǎ 与 dà 声调不同，意思是“总是打”，不是“老大”。"}, "sentence_index": null, "correct_answer": "老大"}, "level_3": {"options": [{"text": "老大", "is_correct": true, "explanation": "“老大”指家里最先出生的孩子，与“哥哥”的身份相符。"}, {"text": "弟弟", "is_correct": false, "explanation": "语义：“弟弟”是比哥哥小的人，与“我哥哥”矛盾。"}, {"text": "叔叔", "is_correct": false, "explanation": "语义：“叔叔”是父亲的弟弟，不能是哥哥的身份。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“是……的”后要接指人的身份名词，“电视”不能表示家里的身份。"}], "explanations": {"老大": "“老大”指家里最先出生的孩子，与“哥哥”的身份相符。", "弟弟": "语义：“弟弟”是比哥哥小的人，与“我哥哥”矛盾。", "叔叔": "语义：“叔叔”是父亲的弟弟，不能是哥哥的身份。", "电视": "搭配：“是……的”后要接指人的身份名词，“电视”不能表示家里的身份。"}, "sentence_index": 0, "correct_answer": "老大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家有三朵老大，都很可爱。", "explanation": "这里应该用〈个〉或〈位〉。“朵”用于花，不能用来数人。"}, {"text": "我家的老大是我最小的弟弟。", "explanation": "这里的〈老大〉指最小的弟弟，与“排行第一”的意思相反，应说〈老幺〉。"}, {"text": "这辆车是我们家的老大。", "explanation": "这里把〈老大〉的排行义用到了汽车上，此处应说〈主力〉，表示“最主要的一辆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95749, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老大", "is_correct": true, "explanation": "“老大”指兄弟姐妹中排行第一的人，与后面的“老三”相符，且能喜欢画画。"}, {"text": "独生子", "is_correct": false, "explanation": "语义：“独生子”没有兄弟姐妹，与后面的“老三”矛盾。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：“小狗”是动物，不能“喜欢画画”，句意不合。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“喜欢”要求有意识的人作主语，“电脑”不能说“喜欢画画”。"}], "explanations": {"老大": "“老大”指兄弟姐妹中排行第一的人，与后面的“老三”相符，且能喜欢画画。", "独生子": "语义：“独生子”没有兄弟姐妹，与后面的“老三”矛盾。", "小狗": "语义：“小狗”是动物，不能“喜欢画画”，句意不合。", "电脑": "搭配：“喜欢”要求有意识的人作主语，“电脑”不能说“喜欢画画”。"}, "sentence_index": 6, "correct_answer": "老大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "姐姐是我们公司的老大，大家都听她的。", "explanation": "这里的〈老大〉是“团体头领”的意思，不是“家里最先出生的孩子”，这一义项在此不适用。"}, {"text": "我哥哥是家里的老大，他比我小三岁。", "explanation": "这里说哥哥是老大，却比我小三岁，与“最先出生”的意思矛盾。"}, {"text": "我们班的老大是那个最矮的男孩。", "explanation": "这里的〈老大〉是“班里头领”的意思，不是家里排行的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95749, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家有一只老大，她很能干。", "corrected_sentence": "我家有一位老大，她很能干。", "error_description": "错误：量词“只”用错。“只”用于动物等，指人的“老大”应用“位”或“个”，应为“一位老大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95749, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我是家里的老大，我有两个哥哥。", "corrected_sentence": "我是家里的老大，我有两个弟弟。", "error_description": "错误：“老大”是家里最先出生的孩子，不可能有哥哥。应改为“我有两个弟弟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
