INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95751, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "老虎是一种很大的动物。它身上有黑色的条纹，会吃肉，很凶。", "primary_collocate": null, "pronunciation": "lǎo hǔ", "ipa": "lau˨˩˦ xu˨˩˦", "syllable_count": 2, "sentences": [{"text": "动物园里有一只大老虎。", "target_word": "老虎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎身上有黑色的条纹。", "target_word": "老虎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎会吃肉，也很凶。", "target_word": "老虎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天在动物园看到了老虎。", "target_word": "老虎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只老虎正在睡觉。", "target_word": "老虎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友有点怕老虎。", "target_word": "老虎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎比猫大很多。", "target_word": "老虎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他画了一只老虎。", "target_word": "老虎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎跑得很快。", "target_word": "老虎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看过老虎吃肉。", "target_word": "老虎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "头", "label": "量词"}, {"form": "小老虎", "label": "复合"}], "register": "口语", "sense_fingerprint": "身上有黑色条纹、会吃肉、很凶的大动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc47c301-ed4a-4c66-ad41-95bf2b4b9f5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95751, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老虎", "is_correct": true, "explanation": "正确：身上有黑色条纹、会吃肉的大型猫科动物。"}, {"text": "老鼠", "is_correct": false, "explanation": "shǔ 与 hǔ 声母不同（sh 与 h），意思是老鼠。"}, {"text": "老母", "is_correct": false, "explanation": "mǔ 与 hǔ 声母不同（m 与 h），意思是年老的母亲。"}, {"text": "老土", "is_correct": false, "explanation": "tǔ 与 hǔ 声母不同（t 与 h），意思是陈旧、不时髦。"}], "explanations": {"老虎": "正确：身上有黑色条纹、会吃肉的大型猫科动物。", "老鼠": "shǔ 与 hǔ 声母不同（sh 与 h），意思是老鼠。", "老母": "mǔ 与 hǔ 声母不同（m 与 h），意思是年老的母亲。", "老土": "tǔ 与 hǔ 声母不同（t 与 h），意思是陈旧、不时髦。"}, "sentence_index": null, "correct_answer": "老虎"}, "level_3": {"options": [{"text": "船", "is_correct": false, "explanation": "语义：船不是动物，动物园里不会出现一只大船。"}, {"text": "鞋", "is_correct": false, "explanation": "搭配：鞋一般成双，“一只大鞋”与动物园的语境不搭。"}, {"text": "老虎", "is_correct": true, "explanation": "正确：动物园里的大型动物，用量词“只”。"}, {"text": "手", "is_correct": false, "explanation": "语义：手是身体部位，不是动物园里的动物。"}], "explanations": {"船": "语义：船不是动物，动物园里不会出现一只大船。", "鞋": "搭配：鞋一般成双，“一只大鞋”与动物园的语境不搭。", "老虎": "正确：动物园里的大型动物，用量词“只”。", "手": "语义：手是身体部位，不是动物园里的动物。"}, "sentence_index": 0, "correct_answer": "老虎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天在动物园看到了一只老虎，它的鬃毛很长。", "explanation": "这里应该用〈狮子〉。鬃毛是狮子的特征，老虎身上没有鬃毛。"}, {"text": "我今天在动物园看到了一只老虎，它身上有黑色的斑点。", "explanation": "这里应该用〈豹子〉。斑点是豹子的特征，老虎身上是条纹。"}, {"text": "我今天在动物园看到了一只老虎，它喜欢成群地生活。", "explanation": "这里应该用〈狼〉。狼喜欢成群地生活，老虎通常独居。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95751, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蚂蚁", "is_correct": false, "explanation": "体貌：蚂蚁的体型比猫小得多，不能说“比猫大很多”。"}, {"text": "老虎", "is_correct": true, "explanation": "正确：老虎的体型比猫大很多。"}, {"text": "蚊子", "is_correct": false, "explanation": "体貌：蚊子的体型远小于猫，“比猫大很多”不成立。"}, {"text": "硬币", "is_correct": false, "explanation": "语义：硬币没有可比的体积，不能拿来和猫比大小。"}], "explanations": {"蚂蚁": "体貌：蚂蚁的体型比猫小得多，不能说“比猫大很多”。", "老虎": "正确：老虎的体型比猫大很多。", "蚊子": "体貌：蚊子的体型远小于猫，“比猫大很多”不成立。", "硬币": "语义：硬币没有可比的体积，不能拿来和猫比大小。"}, "sentence_index": 6, "correct_answer": "老虎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我看过一只老虎吃竹子。", "explanation": "这里应该用〈熊猫〉。竹子是熊猫的主要食物，老虎吃肉。"}, {"text": "我看过一只老虎用长鼻子卷东西吃。", "explanation": "这里应该用〈大象〉。用长鼻子卷东西的是大象，老虎没有长鼻子。"}, {"text": "我看过一只老虎喵喵地叫。", "explanation": "这里应该用〈猫〉。喵喵叫是猫的叫声，老虎是吼叫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95751, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条老虎睡得很香。", "corrected_sentence": "那只老虎睡得很香。", "error_description": "错误：量词用错。老虎应用量词“只”，不能用“条”（“条”多用于蛇、鱼等细长的动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95751, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几只老虎们在睡觉。", "corrected_sentence": "几只老虎在睡觉。", "error_description": "错误：名词前已有数量词“几只”，后面不能再加“们”，应说“几只老虎”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
