INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95752, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种大型猛兽，身上有黄黑相间的条纹，肉食，力量很大。", "primary_collocate": null, "pronunciation": "lǎo hǔ", "ipa": "lau˨˩˦ xu˨˩˦", "syllable_count": 2, "sentences": [{"text": "老虎是森林里的猛兽。", "target_word": "老虎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只老虎的力量非常大。", "target_word": "老虎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎的条纹是黄色和黑色的。", "target_word": "老虎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎跳得很远。", "target_word": "老虎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎靠吃肉长大。", "target_word": "老虎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里有老虎，晚上别出去。", "target_word": "老虎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电视上看过老虎抓鹿。", "target_word": "老虎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎看着我，我很紧张。", "target_word": "老虎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只老虎很重，有两百公斤。", "target_word": "老虎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎喜欢独自生活。", "target_word": "老虎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "头", "label": "量词"}, {"form": "母老虎", "label": "复合"}], "register": "中性", "sense_fingerprint": "黄黑相间条纹、肉食、力量很大的大型猛兽", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc47c301-ed4a-4c66-ad41-95bf2b4b9f5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95752, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老虎", "is_correct": true, "explanation": "正确：黄黑相间条纹、肉食、力量很大的大型猛兽。"}, {"text": "老鼠", "is_correct": false, "explanation": "shǔ 与 hǔ 声母不同（sh 与 h），意思是老鼠。"}, {"text": "老母", "is_correct": false, "explanation": "mǔ 与 hǔ 声母不同（m 与 h），意思是年老的母亲。"}, {"text": "老土", "is_correct": false, "explanation": "tǔ 与 hǔ 声母不同（t 与 h），意思是陈旧、不时髦。"}], "explanations": {"老虎": "正确：黄黑相间条纹、肉食、力量很大的大型猛兽。", "老鼠": "shǔ 与 hǔ 声母不同（sh 与 h），意思是老鼠。", "老母": "mǔ 与 hǔ 声母不同（m 与 h），意思是年老的母亲。", "老土": "tǔ 与 hǔ 声母不同（t 与 h），意思是陈旧、不时髦。"}, "sentence_index": null, "correct_answer": "老虎"}, "level_3": {"options": [{"text": "兔子", "is_correct": false, "explanation": "语义：兔子性情温顺，不是森林里的猛兽。"}, {"text": "绵羊", "is_correct": false, "explanation": "语义：绵羊是家畜，不是猛兽。"}, {"text": "老虎", "is_correct": true, "explanation": "正确：森林里的大型猛兽。"}, {"text": "蝴蝶", "is_correct": false, "explanation": "体貌：蝴蝶体型很小，与“猛兽”的形象不符。"}], "explanations": {"兔子": "语义：兔子性情温顺，不是森林里的猛兽。", "绵羊": "语义：绵羊是家畜，不是猛兽。", "老虎": "正确：森林里的大型猛兽。", "蝴蝶": "体貌：蝴蝶体型很小，与“猛兽”的形象不符。"}, "sentence_index": 0, "correct_answer": "老虎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那只老虎的鬃毛又长又密，很威风。", "explanation": "这里应该用〈狮子〉。鬃毛是狮子的特征，老虎身上没有鬃毛。"}, {"text": "那只老虎身上有黑色的圆斑，跑得很快。", "explanation": "这里应该用〈豹子〉。圆斑是豹子的特征，老虎身上是条纹。"}, {"text": "那几只老虎喜欢成群地生活。", "explanation": "这里应该用〈狼〉。狼喜欢成群地生活，老虎通常独居。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95752, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鸡", "is_correct": false, "explanation": "语义：鸡不会抓鹿，句子说不通。"}, {"text": "老虎", "is_correct": true, "explanation": "正确：老虎有爪子，能抓鹿。"}, {"text": "鸭子", "is_correct": false, "explanation": "搭配：鸭子没有能抓物的爪子，“抓”不能搭配“鸭子”。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼生活在水里，不能“抓鹿”。"}], "explanations": {"鸡": "语义：鸡不会抓鹿，句子说不通。", "老虎": "正确：老虎有爪子，能抓鹿。", "鸭子": "搭配：鸭子没有能抓物的爪子，“抓”不能搭配“鸭子”。", "鱼": "语义：鱼生活在水里，不能“抓鹿”。"}, "sentence_index": 6, "correct_answer": "老虎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那只老虎的脖子很长，能吃到高处的树叶。", "explanation": "这里应该用〈长颈鹿〉。脖子长、吃高处树叶的是长颈鹿，老虎不是。"}, {"text": "那只老虎最爱吃香蕉。", "explanation": "这里应该用〈猴子〉。香蕉是猴子最爱吃的，老虎吃肉。"}, {"text": "那只老虎张开翅膀，在天上飞过了山头。", "explanation": "这里应该用〈鸟〉。老虎没有翅膀，张开翅膀飞的是鸟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95752, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只老虎们的力量很大，谁都怕它。", "corrected_sentence": "那只老虎的力量很大，谁都怕它。", "error_description": "错误：“那只”表示单数，后面不能再加表示复数的“们”，应说“那只老虎”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95752, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一匹老虎抓鹿抓得很快。", "corrected_sentence": "一只老虎抓鹿抓得很快。", "error_description": "错误：量词用错。老虎应用量词“只”，不能用“匹”（“匹”多用于马、骡等）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
