INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95753, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自便是你想怎么做就怎么做，不用别人管。", "primary_collocate": null, "pronunciation": "zì biàn", "ipa": "tsɨ˥˩ piɛn˥˩", "syllable_count": 2, "sentences": [{"text": "桌上有茶，请自便。", "target_word": "自便", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我要先去开会，你自便吧。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰箱里有水果，你们自便。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想看书或者看电视，都请自便。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我还要工作，你们先吃，请自便。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人来了，他说：“别客气，自便吧。”", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "屋里的书很多，喜欢哪本请自便。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不陪你了，饮料在桌上，你自便。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃完饭想走的人可以先走，请自便。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "主人笑着说：“到了这儿就像在家一样，请自便。”", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "主人对客人说：想怎样就怎样，不必拘礼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a78e25c3-ee67-45e4-a792-d0210b249480') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95753, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自便", "is_correct": true, "explanation": "自便（zì biàn）意思是想怎么做就怎么做，不用别人管，是正确答案。"}, {"text": "自编", "is_correct": false, "explanation": "自编（zì biān）与自便（zì biàn）声调不同，意思是自己编写。"}, {"text": "自贬", "is_correct": false, "explanation": "自贬（zì biǎn）与自便（zì biàn）声调不同，意思是自我贬低。"}, {"text": "字面", "is_correct": false, "explanation": "字面（zì miàn）与自便（zì biàn）声母不同（m 与 b），意思是文字的表面意思。"}, {"text": "自限", "is_correct": false, "explanation": "自限（zì xiàn）与自便（zì biàn）声母不同（x 与 b），意思是自我限制。"}], "explanations": {"自便": "自便（zì biàn）意思是想怎么做就怎么做，不用别人管，是正确答案。", "自编": "自编（zì biān）与自便（zì biàn）声调不同，意思是自己编写。", "自贬": "自贬（zì biǎn）与自便（zì biàn）声调不同，意思是自我贬低。", "字面": "字面（zì miàn）与自便（zì biàn）声母不同（m 与 b），意思是文字的表面意思。", "自限": "自限（zì xiàn）与自便（zì biàn）声母不同（x 与 b），意思是自我限制。"}, "sentence_index": null, "correct_answer": "自便"}, "level_3": {"options": [{"text": "自便", "is_correct": true, "explanation": "“自便”是动词，表示请对方随意，用在“请自便”中，符合句意。"}, {"text": "走", "is_correct": false, "explanation": "语义：“请走”是请对方离开，与“桌上有茶”的邀请语境相反。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”与“桌上有茶”毫无关系，句子语义不通。"}, {"text": "听", "is_correct": false, "explanation": "配价：“听”要接听的对象作宾语，句中没有可听之物，“请听”不成立。"}], "explanations": {"自便": "“自便”是动词，表示请对方随意，用在“请自便”中，符合句意。", "走": "语义：“请走”是请对方离开，与“桌上有茶”的邀请语境相反。", "哭": "语义：“哭”与“桌上有茶”毫无关系，句子语义不通。", "听": "配价：“听”要接听的对象作宾语，句中没有可听之物，“请听”不成立。"}, "sentence_index": 0, "correct_answer": "自便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间很自便，你们可以随便坐。", "explanation": "这里应该用〈方便〉。“方便”可形容环境便利；“自便”指按自己意愿行事，不形容房间。"}, {"text": "你们想吃什么就自便点，我先走了。", "explanation": "这里应该用〈随便〉。“随便点”是常见说法；“自便”后不能接动词“点”。"}, {"text": "你自便说几句就行，不用太正式。", "explanation": "这里应该用〈随便〉。“随便说几句”是常见说法，“自便”不能修饰“说几句”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95753, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "自便", "is_correct": true, "explanation": "自便（zì biàn）意思是想怎么做就怎么做，不用别人管，是正确答案。"}, {"text": "自建", "is_correct": false, "explanation": "自建（zì jiàn）与自便（zì biàn）声母不同（j 与 b），意思是自己建造。"}, {"text": "自陷", "is_correct": false, "explanation": "自陷（zì xiàn）与自便（zì biàn）声母不同（x 与 b），意思是自己陷入。"}, {"text": "自炼", "is_correct": false, "explanation": "自炼（zì liàn）与自便（zì biàn）声母不同（l 与 b），意思是自我修炼。"}], "explanations": {"自便": "自便（zì biàn）意思是想怎么做就怎么做，不用别人管，是正确答案。", "自建": "自建（zì jiàn）与自便（zì biàn）声母不同（j 与 b），意思是自己建造。", "自陷": "自陷（zì xiàn）与自便（zì biàn）声母不同（x 与 b），意思是自己陷入。", "自炼": "自炼（zì liàn）与自便（zì biàn）声母不同（l 与 b），意思是自我修炼。"}, "sentence_index": null, "correct_answer": "自便"}, "level_3": {"options": [{"text": "自便", "is_correct": true, "explanation": "“自便”是动词，表示请对方随意，用在“请自便”中，符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与“喜欢哪本”的挑选语境不符，“请扔”讲不通。"}, {"text": "忘", "is_correct": false, "explanation": "语义：“忘”是忘记，句中没有可忘的对象，语义不通。"}, {"text": "卖", "is_correct": false, "explanation": "配价：“卖”要接卖出的东西作宾语，句中“请卖”不成立。"}], "explanations": {"自便": "“自便”是动词，表示请对方随意，用在“请自便”中，符合句意。", "扔": "语义：“扔”是丢弃，与“喜欢哪本”的挑选语境不符，“请扔”讲不通。", "忘": "语义：“忘”是忘记，句中没有可忘的对象，语义不通。", "卖": "配价：“卖”要接卖出的东西作宾语，句中“请卖”不成立。"}, "sentence_index": 6, "correct_answer": "自便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "主人笑着说：“这里的自便很重要。”", "explanation": "这里应该用〈自由〉。“自由”可作名词；“自便”是动词，不能用“的”组成名词词组作主语。"}, {"text": "主人笑着说：“我家的客厅很自便。”", "explanation": "这里应该用〈舒适〉。“舒适”可形容环境；“自便”指请客人随意，不形容房间。"}, {"text": "主人笑着说：“请大家自便饭菜。”", "explanation": "这里应该用〈品尝〉。“自便”是不及物动词，不能带宾语“饭菜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95753, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "客厅有椅子，请自便了。", "corrected_sentence": "客厅有椅子，请自便。", "error_description": "“自便”用于请对方随意的祈使说法，句末不能加“了”，应说“请自便”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95753, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "客人来了，请自便过，别拘束。", "corrected_sentence": "客人来了，请自便，别拘束。", "error_description": "“自便”用于请对方随意的祈使说法，后面不能加“过”，应说“请自便”；“过”表示经历，与请人随意的语境不合。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
