INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95754, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "随自己的意愿行事，不加拘束。", "primary_collocate": null, "pronunciation": "zì biàn", "ipa": "tsɨ˥˩ piɛn˥˩", "syllable_count": 2, "sentences": [{"text": "去留自便，我们不勉强你。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "参加不参加，你自便。", "target_word": "自便", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "会后大家可以自由活动，去哪儿自便。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里没有规定，穿什么衣服都自便。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说我们走不走自便，他不管。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理说，周末加不加班自便。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家来去自便，不用跟主人打招呼。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上课不能自便，要听老师的话。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店没有规矩，进店后怎么看、怎么选都自便。", "target_word": "自便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会很随意，吃饭喝茶都由客人自便。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "按自己的意愿行事，不受约束", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a78e25c3-ee67-45e4-a792-d0210b249480') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95754, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自便", "is_correct": true, "explanation": "自便（zì biàn）意思是按自己的意愿行事，不受约束，是正确答案。"}, {"text": "自编", "is_correct": false, "explanation": "自编（zì biān）与自便（zì biàn）声调不同，意思是自己编写。"}, {"text": "自贬", "is_correct": false, "explanation": "自贬（zì biǎn）与自便（zì biàn）声调不同，意思是自我贬低。"}, {"text": "字面", "is_correct": false, "explanation": "字面（zì miàn）与自便（zì biàn）声母不同（m 与 b），意思是文字的表面意思。"}, {"text": "自限", "is_correct": false, "explanation": "自限（zì xiàn）与自便（zì biàn）声母不同（x 与 b），意思是自我限制。"}], "explanations": {"自便": "自便（zì biàn）意思是按自己的意愿行事，不受约束，是正确答案。", "自编": "自编（zì biān）与自便（zì biàn）声调不同，意思是自己编写。", "自贬": "自贬（zì biǎn）与自便（zì biàn）声调不同，意思是自我贬低。", "字面": "字面（zì miàn）与自便（zì biàn）声母不同（m 与 b），意思是文字的表面意思。", "自限": "自限（zì xiàn）与自便（zì biàn）声母不同（x 与 b），意思是自我限制。"}, "sentence_index": null, "correct_answer": "自便"}, "level_3": {"options": [{"text": "自便", "is_correct": true, "explanation": "“自便”是动词，表示按自己的意愿行事，用在“去留自便”中，符合句意。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”后要接议题作宾语，“去留讨论”搭配不当，句子不通。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”指游泳或游玩，与“去留”的决定无关，句子语义不通。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”与“去留”毫不相干，句子语义不通。"}], "explanations": {"自便": "“自便”是动词，表示按自己的意愿行事，用在“去留自便”中，符合句意。", "讨论": "搭配：“讨论”后要接议题作宾语，“去留讨论”搭配不当，句子不通。", "游": "语义：“游”指游泳或游玩，与“去留”的决定无关，句子语义不通。", "睡": "语义：“睡”与“去留”毫不相干，句子语义不通。"}, "sentence_index": 0, "correct_answer": "自便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里没有规定，穿衣服很自便。", "explanation": "这里应该用〈自由〉。“自由”可形容穿着不受限；“自便”是动词，不能用“很”修饰“穿衣服”。"}, {"text": "这里没有规定，他的衣服颜色自便。", "explanation": "这里应该用〈随意〉。“随意”可修饰事物；“自便”是动词，不能作谓语描写颜色。"}, {"text": "这里很自便，穿什么衣服都行。", "explanation": "这里应该用〈方便〉。“方便”可形容环境便利；“自便”指按自己意愿行事，不形容地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95754, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "自便", "is_correct": true, "explanation": "自便（zì biàn）意思是按自己的意愿行事，不受约束，是正确答案。"}, {"text": "自建", "is_correct": false, "explanation": "自建（zì jiàn）与自便（zì biàn）声母不同（j 与 b），意思是自己建造。"}, {"text": "自陷", "is_correct": false, "explanation": "自陷（zì xiàn）与自便（zì biàn）声母不同（x 与 b），意思是自己陷入。"}, {"text": "自炼", "is_correct": false, "explanation": "自炼（zì liàn）与自便（zì biàn）声母不同（l 与 b），意思是自我修炼。"}], "explanations": {"自便": "自便（zì biàn）意思是按自己的意愿行事，不受约束，是正确答案。", "自建": "自建（zì jiàn）与自便（zì biàn）声母不同（j 与 b），意思是自己建造。", "自陷": "自陷（zì xiàn）与自便（zì biàn）声母不同（x 与 b），意思是自己陷入。", "自炼": "自炼（zì liàn）与自便（zì biàn）声母不同（l 与 b），意思是自我修炼。"}, "sentence_index": null, "correct_answer": "自便"}, "level_3": {"options": [{"text": "自便", "is_correct": true, "explanation": "“自便”是动词，表示按自己的意愿行事，用在“来去自便”中，符合句意。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”表示伤心流泪，与“来去”的自由出入不符，句子语义不通。"}, {"text": "吵", "is_correct": false, "explanation": "语义：“吵”表示喧闹，与“不用打招呼”的语境不合，句子语义不通。"}, {"text": "喊", "is_correct": false, "explanation": "搭配：“喊”一般要接声音内容或对象，“来去喊”搭配不当。"}], "explanations": {"自便": "“自便”是动词，表示按自己的意愿行事，用在“来去自便”中，符合句意。", "哭": "语义：“哭”表示伤心流泪，与“来去”的自由出入不符，句子语义不通。", "吵": "语义：“吵”表示喧闹，与“不用打招呼”的语境不合，句子语义不通。", "喊": "搭配：“喊”一般要接声音内容或对象，“来去喊”搭配不当。"}, "sentence_index": 6, "correct_answer": "自便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚会很随意，客人的自便很多。", "explanation": "这里应该用〈自由〉。“自由”可作名词，“自便”是动词，不能用“的”组成名词词组。"}, {"text": "晚会很随意，客人走动很自便。", "explanation": "这里应该用〈自在〉。“自在”可形容行动舒适；“自便”指按自己意愿行事，不能这样形容走动。"}, {"text": "晚会很随意，大家聊天很自便。", "explanation": "这里应该用〈随便〉。“随便聊天”是常见说法；“自便”不用来形容聊天的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次聚会去不去，你自便了吧。", "corrected_sentence": "这次聚会去不去，你自便吧。", "error_description": "“自便”用于请对方随意的说法，句中不能加“了”，应说“你自便吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "进了房间，你们尽管自便过。", "corrected_sentence": "进了房间，你们尽管自便。", "error_description": "“自便”后不能加“过”，应说“你们尽管自便”；“过”表示经历，与请对方随意的语境不合。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
