INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95755, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自动化是机器自己就能做事，不用人一直动手。", "primary_collocate": null, "pronunciation": "zì dòng huà", "ipa": "tsɨ˥˩ tʊŋ˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "农业也在慢慢走向自动化。", "target_word": "自动化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了自动化，工人不用一直动手了。", "target_word": "自动化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个港口的自动化做得非常好。", "target_word": "自动化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自动化的机器不需要人一直看着。", "target_word": "自动化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条旧生产线现在已经实现了自动化。", "target_word": "自动化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们介绍了自动化的好处。", "target_word": "自动化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自动化让工作变得更轻松了。", "target_word": "自动化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂还没有实现自动化。", "target_word": "自动化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想研究机器人和自动化。", "target_word": "自动化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "随着自动化的发展，很多工作变了。", "target_word": "自动化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "自動化", "label": "繁体"}, {"form": "办公自动化", "label": "复合"}], "register": "中性", "sense_fingerprint": "机器自己做事、人不必一直动手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ea03b26-13d4-42c6-b4dd-6754678089d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95755, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音乐", "is_correct": false, "explanation": "语义：“音乐”不是农业的发展方向，句子不通。"}, {"text": "自动化", "is_correct": true, "explanation": "正确：自动化，指机器自己做事、人不必一直动手，符合“农业走向……”的发展方向。"}, {"text": "表演", "is_correct": false, "explanation": "搭配：“走向表演”不是农业的发展趋势，搭配不当。"}, {"text": "酒店", "is_correct": false, "explanation": "语义：“酒店”与农业的发展方向无关，句子说不通。"}], "explanations": {"音乐": "语义：“音乐”不是农业的发展方向，句子不通。", "自动化": "正确：自动化，指机器自己做事、人不必一直动手，符合“农业走向……”的发展方向。", "表演": "搭配：“走向表演”不是农业的发展趋势，搭配不当。", "酒店": "语义：“酒店”与农业的发展方向无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "自动化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次晚会的自动化很热闹，大家都很开心。", "explanation": "这里应该用〈气氛〉。“自动化”指机器无需人操作，形容晚会热闹要说气氛热烈。"}, {"text": "我每天早上自动化地起床。", "explanation": "这里应该用〈按时〉。“自动化”指机器无需人操作，人每天按时起床要说按时。"}, {"text": "老板的自动化很严格，大家都有点怕他。", "explanation": "这里应该用〈作风〉。“自动化”指机器无需人操作，形容人的管理风格要说作风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95755, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雨水", "is_correct": false, "explanation": "语义：“雨水”不能让工作变得轻松，句子语义不通。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“蛋糕”不是能让工作轻松的事物，与主语搭配不当。"}, {"text": "自动化", "is_correct": true, "explanation": "正确：自动化，指机器自己做事，所以“自动化让工作变得更轻松了”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”与工作轻不轻松无关，句子说不通。"}], "explanations": {"雨水": "语义：“雨水”不能让工作变得轻松，句子语义不通。", "蛋糕": "搭配：“蛋糕”不是能让工作轻松的事物，与主语搭配不当。", "自动化": "正确：自动化，指机器自己做事，所以“自动化让工作变得更轻松了”。", "河流": "语义：“河流”与工作轻不轻松无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "自动化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学校的自动化很多，每个教室都有。", "explanation": "这里应该用〈设备〉。“自动化”是一种技术或过程，不能说数量很多；教室里的机器要说设备。"}, {"text": "这件毛衣是我妈妈自动化织的。", "explanation": "这里应该用〈手工〉。“自动化”指机器无需人操作，妈妈亲手织的要用手工。"}, {"text": "这个问题自动化就解决了。", "explanation": "这里应该用〈自然〉。问题“自然就解决了”是事情自己发展；“自动化”指机器自己运作，不能说问题自动化解决。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95755, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只新的自动化。", "corrected_sentence": "这是一种新的自动化。", "error_description": "“自动化”是抽象名词，量词应用“种”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95755, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个车间终于实现着自动化。", "corrected_sentence": "这个车间终于实现了自动化。", "error_description": "“终于”表示动作最后完成，要用“了”，不能用“着”（“着”表示持续），应说“终于实现了自动化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
