INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95757, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "举动是一个人做出来的事或动作。", "primary_collocate": null, "pronunciation": "jǔ dòng", "ipa": "tɕy˨˩˦ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他的举动让大家很吃惊。", "target_word": "举动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的这个举动很可爱。", "target_word": "举动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不明白他为什么有这样的举动。", "target_word": "举动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个举动说明他很关心你。", "target_word": "举动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在车上给老人让座，这个举动很好。", "target_word": "举动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察发现他有奇怪的举动。", "target_word": "举动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样的举动会伤害朋友。", "target_word": "举动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在看他的举动。", "target_word": "举动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的举动像个小孩子。", "target_word": "举动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做出了一个很大胆的举动。", "target_word": "举动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "举動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个人做出来的事或动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d8c84b-ccc7-4628-aee4-528ffa806d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95757, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "举动", "is_correct": true, "explanation": "正确：“举动”指人做出的事或动作，可以作“他的……让大家很吃惊”的主语。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是人做的事，不能说“他的天气”让人吃惊。"}, {"text": "水分", "is_correct": false, "explanation": "语义：水分指物质中所含的水，不是人的言行，不能让大家吃惊。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“让大家很吃惊”要求主语是人的言行，“钥匙”不能与之搭配。"}], "explanations": {"举动": "正确：“举动”指人做出的事或动作，可以作“他的……让大家很吃惊”的主语。", "天气": "语义：天气是自然现象，不是人做的事，不能说“他的天气”让人吃惊。", "水分": "语义：水分指物质中所含的水，不是人的言行，不能让大家吃惊。", "钥匙": "搭配：“让大家很吃惊”要求主语是人的言行，“钥匙”不能与之搭配。"}, "sentence_index": 0, "correct_answer": "举动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "为了解决堵车问题，市政府出台了一个新的举动。", "explanation": "这里应该用〈措施〉。举动指人做出的动作，政府为解决问题采取的办法要用〈措施〉。"}, {"text": "他想出了一个很好的举动来解决这个难题。", "explanation": "这里应该用〈办法〉。办法指解决问题的方式，想出解决难题的方式要用〈办法〉，举动指人做出的动作。"}, {"text": "他脸上露出了奇怪的举动。", "explanation": "这里应该用〈表情〉。表情指脸上显出的神情，脸上的神色要用〈表情〉，举动指人做出的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95757, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "举动", "is_correct": true, "explanation": "正确：“举动”指人做出的行为，符合“你这样的……会伤害朋友”的语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是物体的属性，不会伤害朋友，不能作“你这样的……会伤害朋友”的主语。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高属于外貌特征，不能表示会伤害朋友的做法。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不是人的言行，不能伤害朋友。"}], "explanations": {"举动": "正确：“举动”指人做出的行为，符合“你这样的……会伤害朋友”的语境。", "颜色": "语义：颜色是物体的属性，不会伤害朋友，不能作“你这样的……会伤害朋友”的主语。", "身高": "体貌：身高属于外貌特征，不能表示会伤害朋友的做法。", "书包": "语义：书包是物品，不是人的言行，不能伤害朋友。"}, "sentence_index": 6, "correct_answer": "举动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对朋友的举动很深，大家都能感觉到。", "explanation": "这里应该用〈感情〉。深形容感情的程度，对朋友的感情很深要用〈感情〉，举动指人做出的动作。"}, {"text": "他说话的举动很平静，大家都能接受。", "explanation": "这里应该用〈语气〉。平静形容说话的口气，说话时的口气要用〈语气〉，举动指人做出的动作。"}, {"text": "他的举动很精湛，做的家具很结实。", "explanation": "这里应该用〈手艺〉。精湛形容技艺高超，做家具的技艺要用〈手艺〉，举动指人做出的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95757, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只举动真让人佩服。", "corrected_sentence": "这个举动真让人佩服。", "error_description": "量词错误：“举动”的量词应是“个”，“只”多用于动物、手等，不能修饰“举动”。应改为“这个举动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95757, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他突然做出了一只举动，大家都没反应过来。", "corrected_sentence": "他突然做出了一个举动，大家都没反应过来。", "error_description": "量词错误：“举动”的量词应是“个”，“只”多用于动物、手等，不能修饰“举动”。应说“一个举动”，不能说“一只举动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
