INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95758, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人的行动或动作。", "primary_collocate": null, "pronunciation": "jǔ dòng", "ipa": "tɕy˨˩˦ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老人的举动很慢，但是很稳。", "target_word": "举动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明今天的举动有点奇怪。", "target_word": "举动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他突然的举动吓了我一跳。", "target_word": "举动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没有说话，只是看着他的举动。", "target_word": "举动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用举动告诉我，她很生气。", "target_word": "举动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的举动看起来很不安。", "target_word": "举动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种举动在会议上不太合适。", "target_word": "举动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得他的举动不像大人。", "target_word": "举动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向前走了一步，这个举动很勇敢。", "target_word": "举动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要做危险的举动。", "target_word": "举动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "举動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人的行动或动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d8c84b-ccc7-4628-aee4-528ffa806d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95758, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "举动", "is_correct": true, "explanation": "正确：“举动”指人的行动或动作，可以用“很慢，但是很稳”来描述。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能说“很慢”，也不能说“很稳”，与句中的描述不搭。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是钱数，不能用“很慢，但是很稳”来形容。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是外貌特征，不能与“很慢，但是很稳”的描述相搭。"}], "explanations": {"举动": "正确：“举动”指人的行动或动作，可以用“很慢，但是很稳”来描述。", "颜色": "语义：颜色不能说“很慢”，也不能说“很稳”，与句中的描述不搭。", "价格": "语义：价格是钱数，不能用“很慢，但是很稳”来形容。", "身高": "体貌：身高是外貌特征，不能与“很慢，但是很稳”的描述相搭。"}, "sentence_index": 0, "correct_answer": "举动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她穿了一件红色的举动，非常漂亮。", "explanation": "这里应该用〈衣服〉。穿的是衣服，举动指人的行动或动作。"}, {"text": "这本书的举动很有意思，我一口气看完了。", "explanation": "这里应该用〈内容〉。书里写的东西要用内容，举动指人的行动或动作。"}, {"text": "这碗汤的举动很鲜，大家都喝完了。", "explanation": "这里应该用〈味道〉。鲜形容食物的味道，汤的味道要用〈味道〉，举动指人做出的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95758, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "举动", "is_correct": true, "explanation": "正确：“举动”指人的行为，可以作“这种……在会议上不太合适”的主语。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是物品，不是人的做法，不能作“这种……在会议上不太合适”的主语。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是外貌特征，不能描述在会议上是否合适。"}, {"text": "水分", "is_correct": false, "explanation": "语义：水分是物质含量，不是人的做法，不能作主语。"}], "explanations": {"举动": "正确：“举动”指人的行为，可以作“这种……在会议上不太合适”的主语。", "钥匙": "语义：钥匙是物品，不是人的做法，不能作“这种……在会议上不太合适”的主语。", "身高": "体貌：身高是外貌特征，不能描述在会议上是否合适。", "水分": "语义：水分是物质含量，不是人的做法，不能作主语。"}, "sentence_index": 6, "correct_answer": "举动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的举动很洪亮，老远就能听见。", "explanation": "这里应该用〈声音〉。洪亮形容声音响亮，声音的大小要用〈声音〉，举动指人做出的动作。"}, {"text": "他的举动很工整，老师都夸他。", "explanation": "这里应该用〈字迹〉。工整形容字写得整齐，字的样子要用〈字迹〉，举动指人做出的动作。"}, {"text": "他的举动很精湛，做的木雕很漂亮。", "explanation": "这里应该用〈手艺〉。精湛形容技艺高超，做木雕的技艺要用〈手艺〉，举动指人做出的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95758, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条举动在医院里很危险。", "corrected_sentence": "这种举动在医院里很危险。", "error_description": "量词错误：“条”用于细长物品，不能修饰“举动”。这里应该用“这种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95758, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小心地做出了一只举动，没让人发现。", "corrected_sentence": "他小心地做出了一个举动，没让人发现。", "error_description": "量词错误：“举动”的量词应是“个”，“只”多用于动物、手等，不能修饰“举动”。应说“一个举动”，不能说“一只举动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f799686-9053-4c6a-a211-b8edfd7dd2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
