INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95759, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "艺人是会唱歌、跳舞或表演的人，靠这个工作。", "primary_collocate": null, "pronunciation": "yì rén", "ipa": "i˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "这位艺人会唱歌，也会跳舞。", "target_word": "艺人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个艺人每天都要练习唱歌。", "target_word": "艺人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "艺人上台以前，先化了妆。", "target_word": "艺人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多年轻人想当艺人，因为可以上电视。", "target_word": "艺人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位艺人唱歌很好听，粉丝都喜欢他。", "target_word": "艺人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "艺人的工作很忙，常常要去别的城市表演。", "target_word": "艺人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一个有名的艺人，在街上总有人找她拍照。", "target_word": "艺人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司帮艺人安排演出和拍广告。", "target_word": "艺人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不是学生，是靠表演赚钱的艺人。", "target_word": "艺人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的朋友是艺人，上个月刚在北京开了演唱会。", "target_word": "艺人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "街头艺人", "label": "复合"}, {"form": "藝人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "靠唱歌、跳舞或表演为职业的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82cc745d-1222-4f0a-989c-21513a148a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95759, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "艺人", "is_correct": true, "explanation": "艺人：会唱歌、跳舞或表演、靠这个工作的人。"}, {"text": "一人", "is_correct": false, "explanation": "一人（yī，第一声）与艺人（yì，第四声）第一个音节声调不同，意思是一个人。"}, {"text": "宜人", "is_correct": false, "explanation": "宜人（yí，第二声）与艺人（yì，第四声）第一个音节声调不同，意思是让人感到舒服。"}, {"text": "怡人", "is_correct": false, "explanation": "怡人（yí，第二声）与艺人（yì，第四声）第一个音节声调不同，意思是令人愉快，多用于景色。"}], "explanations": {"艺人": "艺人：会唱歌、跳舞或表演、靠这个工作的人。", "一人": "一人（yī，第一声）与艺人（yì，第四声）第一个音节声调不同，意思是一个人。", "宜人": "宜人（yí，第二声）与艺人（yì，第四声）第一个音节声调不同，意思是让人感到舒服。", "怡人": "怡人（yí，第二声）与艺人（yì，第四声）第一个音节声调不同，意思是令人愉快，多用于景色。"}, "sentence_index": null, "correct_answer": "艺人"}, "level_3": {"options": [{"text": "艺人", "is_correct": true, "explanation": "艺人：会唱歌、会跳舞，靠表演为生，符合句中的描述。"}, {"text": "石像", "is_correct": false, "explanation": "语义：石像不会唱歌跳舞，与句意矛盾。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不会唱歌跳舞，与后半句矛盾。"}, {"text": "植物人", "is_correct": false, "explanation": "语义：植物人无法唱歌跳舞，与后半句矛盾。"}], "explanations": {"艺人": "艺人：会唱歌、会跳舞，靠表演为生，符合句中的描述。", "石像": "语义：石像不会唱歌跳舞，与句意矛盾。", "婴儿": "语义：婴儿不会唱歌跳舞，与后半句矛盾。", "植物人": "语义：植物人无法唱歌跳舞，与后半句矛盾。"}, "sentence_index": 0, "correct_answer": "艺人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位著名的艺人，靠写小说生活，从来不上台表演。", "explanation": "这里应该用〈作家〉。艺人指从事表演艺术的人，靠写小说生活、不表演的人要说作家。"}, {"text": "我的妈妈是一位艺人，在小学教数学。", "explanation": "这里应该用〈老师〉。艺人指靠表演工作的人，教书的人要说老师。"}, {"text": "我的叔叔是一位艺人，靠卖自己画的画生活。", "explanation": "这里应该用〈画家〉。艺人指靠唱歌、跳舞或表演工作的人，靠画画为生的要说画家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350f2f16-9181-4dea-b588-0b385c893b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95759, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "艺人", "is_correct": true, "explanation": "艺人：有名、会表演的人，常有人找他拍照，符合句意。"}, {"text": "路人", "is_correct": false, "explanation": "语义：路人并不以出名著称，与“有名”矛盾。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人不会因出名而被人找去拍照，与句意矛盾。"}, {"text": "陌生人", "is_correct": false, "explanation": "搭配：“陌生人”与“有名”不能搭配，前后矛盾。"}], "explanations": {"艺人": "艺人：有名、会表演的人，常有人找他拍照，符合句意。", "路人": "语义：路人并不以出名著称，与“有名”矛盾。", "病人": "语义：病人不会因出名而被人找去拍照，与句意矛盾。", "陌生人": "搭配：“陌生人”与“有名”不能搭配，前后矛盾。"}, "sentence_index": 6, "correct_answer": "艺人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位艺人是国家队的长跑选手，每天训练准备比赛。", "explanation": "这里应该用〈运动员〉。艺人指从事表演艺术的人，参加比赛训练的人要说运动员。"}, {"text": "这家饭店的艺人做的面条很好吃。", "explanation": "这里应该用〈厨师〉。艺人指表演艺术的人，做饭的人要说厨师。"}, {"text": "我爸爸是一位艺人，每天开出租车拉客人。", "explanation": "这里应该用〈司机〉。艺人指表演艺术的人，开车载客为业的要说司机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350f2f16-9181-4dea-b588-0b385c893b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95759, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们是两只艺人，经常一起参加节目。", "corrected_sentence": "他们是两位艺人，经常一起参加节目。", "error_description": "量词错误：“艺人”指人，量词应用“位”或“个”，不能用“只”。正确说法是“两位艺人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350f2f16-9181-4dea-b588-0b385c893b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95759, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市里有一个很有名艺人，常常在电视上唱歌。", "corrected_sentence": "这个城市里有一个很有名的艺人，常常在电视上唱歌。", "error_description": "修饰语漏“的”：“很有名”修饰“艺人”时要加“的”，应说“很有名的艺人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350f2f16-9181-4dea-b588-0b385c893b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
