INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95761, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "裤子是穿在腿上的衣服。有两个裤腿。", "primary_collocate": null, "pronunciation": "kù zi", "ipa": "kʰu˥˩ tsɿ", "syllable_count": 2, "sentences": [{"text": "我今天穿了一条黑色的裤子。", "target_word": "裤子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裤子太长了，要剪短一点。", "target_word": "裤子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的裤子上有一块红色的东西。", "target_word": "裤子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天我喜欢穿厚裤子。", "target_word": "裤子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我买了一条新裤子。", "target_word": "裤子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小弟弟把裤子弄湿了。", "target_word": "裤子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裤子的两个裤腿不一样长。", "target_word": "裤子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗好的裤子挂在阳台上。", "target_word": "裤子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的裤子太大，要用皮带。", "target_word": "裤子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面很冷，你要穿裤子，别穿短裙。", "target_word": "裤子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "褲子", "label": "繁体"}], "register": "中性", "sense_fingerprint": "穿在腿上、有两个裤腿的衣服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97fe4c13-4834-4860-bdf7-8fe0ba852eb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95761, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "裤子", "is_correct": true, "explanation": "正确答案。裤子是穿在腿上、有两个裤腿的衣服。"}, {"text": "兔子", "is_correct": false, "explanation": "tù（第四声）与 kù（第四声）声母不同（t 与 k），意思是兔子。"}, {"text": "肚子", "is_correct": false, "explanation": "dù（第四声）与 kù（第四声）声母不同（d 与 k），意思是肚子。"}, {"text": "路子", "is_correct": false, "explanation": "lù（第四声）与 kù（第四声）声母不同（l 与 k），意思是门路。"}, {"text": "铺子", "is_correct": false, "explanation": "pù（第四声）与 kù（第四声）声母不同（p 与 k），意思是铺子。"}], "explanations": {"裤子": "正确答案。裤子是穿在腿上、有两个裤腿的衣服。", "兔子": "tù（第四声）与 kù（第四声）声母不同（t 与 k），意思是兔子。", "肚子": "dù（第四声）与 kù（第四声）声母不同（d 与 k），意思是肚子。", "路子": "lù（第四声）与 kù（第四声）声母不同（l 与 k），意思是门路。", "铺子": "pù（第四声）与 kù（第四声）声母不同（p 与 k），意思是铺子。"}, "sentence_index": null, "correct_answer": "裤子"}, "level_3": {"options": [{"text": "裤子", "is_correct": true, "explanation": "正确答案。裤子是穿在身上的衣服，量词用“条”，与“穿”和“黑色的”搭配。"}, {"text": "帽子", "is_correct": false, "explanation": "搭配：帽子要说“戴”，量词用“顶”，不能说“穿了一条黑色的帽子”。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是背在身上的，不是穿在身上的东西，句中“穿了”说不通。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：手套要说“戴”，量词用“双”，不能说“穿了一条”。"}], "explanations": {"裤子": "正确答案。裤子是穿在身上的衣服，量词用“条”，与“穿”和“黑色的”搭配。", "帽子": "搭配：帽子要说“戴”，量词用“顶”，不能说“穿了一条黑色的帽子”。", "书包": "语义：书包是背在身上的，不是穿在身上的东西，句中“穿了”说不通。", "手套": "搭配：手套要说“戴”，量词用“双”，不能说“穿了一条”。"}, "sentence_index": 0, "correct_answer": "裤子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只裤子。", "explanation": "这里应该用〈条〉。裤子用量词“条”，“只”用于动物或成对器官中的一个，不用于裤子。"}, {"text": "我买了一根裤子。", "explanation": "这里应该用〈条〉。“根”用于绳子等细长的东西，裤子用量词“条”。"}, {"text": "我买了一双裤子。", "explanation": "这里应该用〈条〉。“双”用于成对的鞋袜等，裤子用量词“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95761, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "裤子", "is_correct": true, "explanation": "正确答案。裤子是穿在腿上、有两个裤腿的衣服。"}, {"text": "褥子", "is_correct": false, "explanation": "rù（第四声）与 kù（第四声）声母不同（r 与 k），意思是铺在床上的垫子。"}, {"text": "柱子", "is_correct": false, "explanation": "zhù（第四声）与 kù（第四声）声母不同（zh 与 k），意思是建筑物里竖着的支撑物。"}, {"text": "扣子", "is_correct": false, "explanation": "kòu（第四声）与 kù（第四声）韵母不同（ou 与 u），意思是扣子。"}], "explanations": {"裤子": "正确答案。裤子是穿在腿上、有两个裤腿的衣服。", "褥子": "rù（第四声）与 kù（第四声）声母不同（r 与 k），意思是铺在床上的垫子。", "柱子": "zhù（第四声）与 kù（第四声）声母不同（zh 与 k），意思是建筑物里竖着的支撑物。", "扣子": "kòu（第四声）与 kù（第四声）韵母不同（ou 与 u），意思是扣子。"}, "sentence_index": null, "correct_answer": "裤子"}, "level_3": {"options": [{"text": "裤子", "is_correct": true, "explanation": "正确答案。裤子有两个裤腿，量词用“条”，与“这条”搭配。"}, {"text": "上衣", "is_correct": false, "explanation": "搭配：上衣的量词是“件”，不说“这条上衣”；而且上衣没有裤腿。"}, {"text": "裙子", "is_correct": false, "explanation": "语义：裙子没有裤腿，与“两个裤腿不一样长”的描述矛盾。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘不是穿的东西，也没有裤腿，句子说不通。"}], "explanations": {"裤子": "正确答案。裤子有两个裤腿，量词用“条”，与“这条”搭配。", "上衣": "搭配：上衣的量词是“件”，不说“这条上衣”；而且上衣没有裤腿。", "裙子": "语义：裙子没有裤腿，与“两个裤腿不一样长”的描述矛盾。", "窗帘": "语义：窗帘不是穿的东西，也没有裤腿，句子说不通。"}, "sentence_index": 6, "correct_answer": "裤子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一块裤子。", "explanation": "这里应该用〈条〉。“块”用于块状或片状的东西，裤子用量词“条”。"}, {"text": "我买了一枚裤子。", "explanation": "这里应该用〈条〉。“枚”用于硬币、徽章等小件的东西，裤子用量词“条”。"}, {"text": "我买了一支裤子。", "explanation": "这里应该用〈条〉。“支”用于笔、枪等细长的东西，裤子用量词“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95761, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天穿了一只蓝色的裤子。", "corrected_sentence": "我昨天穿了一条蓝色的裤子。", "error_description": "量词错误：裤子应用量词“条”，“只”用于动物或成对器官中的一个，不能修饰裤子。正确的说法是“一条蓝色的裤子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95761, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹把她的裤子们都洗干净了。", "corrected_sentence": "妹妹把她的裤子都洗干净了。", "error_description": "词尾错误：“们”只用于指人的名词，不能加在“裤子”后面。正确的说法是“她的裤子都洗干净了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
