INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95765, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95765, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "说明会是大家坐在一起，听人把一件事讲清楚的会。", "primary_collocate": null, "pronunciation": "shuō míng huì", "ipa": "ʂwo˥ miŋ˧˥ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "明天晚上有一个说明会。", "target_word": "说明会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去听说明会吧。", "target_word": "说明会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说明会开了两个小时。", "target_word": "说明会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁来主持今天的说明会？", "target_word": "说明会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没来说明会，所以不知道。", "target_word": "说明会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说明会的地方在三楼。", "target_word": "说明会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次说明会，讲了新的规定。", "target_word": "说明会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区开了说明会，大家都去了。", "target_word": "说明会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说明会上有人问了价格。", "target_word": "说明会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我记下了说明会的时间。", "target_word": "说明会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场说明会", "label": "量词"}, {"form": "說明會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大家一起听人把一件事讲清楚的会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '849abdb4-e94e-41e7-b194-cd99807ededa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95765, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说明会", "is_correct": true, "explanation": "“说明会”是大家一起听人讲清事情的会，可以“有一个”，符合句意。"}, {"text": "日出", "is_correct": false, "explanation": "语义：日出在早晨，与“晚上”冲突。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的体貌特征，不能“有一个”安排在某个晚上。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历是资格，不是可以举行的活动。"}], "explanations": {"说明会": "“说明会”是大家一起听人讲清事情的会，可以“有一个”，符合句意。", "日出": "语义：日出在早晨，与“晚上”冲突。", "身高": "语义：身高是人的体貌特征，不能“有一个”安排在某个晚上。", "学历": "语义：学历是资格，不是可以举行的活动。"}, "sentence_index": 0, "correct_answer": "说明会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的说明会决出了三名代表，大家为他们鼓掌。", "explanation": "这里应该用〈选拔赛〉。说明会是讲清事情的会，不评比、不选出代表。"}, {"text": "新人在礼堂里举行了说明会，大家很开心。", "explanation": "这里应该用〈婚礼〉。说明会是讲清事情的会，不用于婚礼等庆典。"}, {"text": "说明会上，乐队演奏了三首歌，观众很兴奋。", "explanation": "这里应该用〈音乐会〉。说明会是讲解事情，不是演奏和表演。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95765, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说明会", "is_correct": true, "explanation": "“说明会”是讲清事情的会，句中“讲了新的规定”与之相符。"}, {"text": "晚饭", "is_correct": false, "explanation": "语义：晚饭是饮食，不能“讲了新的规定”。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是物品，不能讲规定。"}, {"text": "天气", "is_correct": false, "explanation": "配价：“讲”的主体需要能说话，天气不能讲规定。"}], "explanations": {"说明会": "“说明会”是讲清事情的会，句中“讲了新的规定”与之相符。", "晚饭": "语义：晚饭是饮食，不能“讲了新的规定”。", "眼镜": "语义：眼镜是物品，不能讲规定。", "天气": "配价：“讲”的主体需要能说话，天气不能讲规定。"}, "sentence_index": 6, "correct_answer": "说明会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家在说明会上争相举牌，价格越抬越高。", "explanation": "这里应该用〈拍卖会〉。说明会是讲清事情的会，没有举牌竞价的环节。"}, {"text": "大家在说明会上低头默哀，不时擦眼泪。", "explanation": "这里应该用〈葬礼〉。说明会不用于哀悼，句子里的情境与说明会不符。"}, {"text": "他在说明会上打了一场篮球，赢了比赛。", "explanation": "语义：说明会是讲清事情的会，不是比赛，也不能打球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95765, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天晚上我们开一顿新员工说明会。", "corrected_sentence": "明天晚上我们开一场新员工说明会。", "error_description": "量词错误：“说明会”应用“场”，不能用“顿”（“顿”用于饭食或责骂）。错误形式：一顿；正确形式：一场。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95765, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我参加了一顿说明会。", "corrected_sentence": "我参加了一场说明会。", "error_description": "量词错误：“说明会”应用“场”，不能用“顿”（“顿”用于饭食或责骂）。错误形式：一顿；正确形式：一场。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
