INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95766, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为向相关人员介绍、解释某项事情而召开的会议。", "primary_collocate": null, "pronunciation": "shuō míng huì", "ipa": "ʂwo˥ miŋ˧˥ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "学校下周三开家长说明会。", "target_word": "说明会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司为新员工举办了说明会。", "target_word": "说明会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我报名参加了留学说明会。", "target_word": "说明会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说明会上，老师介绍了课程安排。", "target_word": "说明会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场说明会一个小时就结束了。", "target_word": "说明会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行邀请客户参加贷款说明会。", "target_word": "说明会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说明会八点开始，请不要迟到。", "target_word": "说明会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在说明会上回答了很多问题。", "target_word": "说明会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂开说明会，告诉大家搬家的事。", "target_word": "说明会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听完说明会，我决定报名。", "target_word": "说明会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场说明会", "label": "量词"}, {"form": "說明會", "label": "繁体"}], "register": "书面", "sense_fingerprint": "为向相关人员介绍、解释事情而召开的会议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '849abdb4-e94e-41e7-b194-cd99807ededa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95766, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说明会", "is_correct": true, "explanation": "“说明会”是为介绍、解释事情而召开的会，与“开家长”搭配，符合句意。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是针对学生的，不是给家长开的会。"}, {"text": "葬礼", "is_correct": false, "explanation": "语义：葬礼是哀悼逝者的仪式，不是学校为家长举办的活动。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是物品，不是可以召开的活动。"}], "explanations": {"说明会": "“说明会”是为介绍、解释事情而召开的会，与“开家长”搭配，符合句意。", "考试": "语义：考试是针对学生的，不是给家长开的会。", "葬礼": "语义：葬礼是哀悼逝者的仪式，不是学校为家长举办的活动。", "眼镜": "语义：眼镜是物品，不是可以召开的活动。"}, "sentence_index": 0, "correct_answer": "说明会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家在说明会上低头默哀，不时擦眼泪。", "explanation": "这里应该用〈葬礼〉。葬礼是哀悼逝者的仪式，说明会是讲解事情的会，不用于哀悼。"}, {"text": "班里在说明会上唱歌跳舞，大家玩得很开心。", "explanation": "这里应该用〈联欢会〉。说明会是讲解事情的会，不是唱歌跳舞的活动。"}, {"text": "学生们在说明会上考试，写了两个小时的卷子。", "explanation": "这里应该用〈考场〉。说明会是讲解事情的会，不是学生答题的场合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95766, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说明会", "is_correct": true, "explanation": "“说明会”是有固定时间开始的会，与“八点开始”搭配，符合句意。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，不是可以定时开始的活动。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“八点开始”不能用于天气。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典是工具书，不会“八点开始”。"}], "explanations": {"说明会": "“说明会”是有固定时间开始的会，与“八点开始”搭配，符合句意。", "感冒": "语义：感冒是疾病，不是可以定时开始的活动。", "天气": "搭配：“八点开始”不能用于天气。", "字典": "语义：字典是工具书，不会“八点开始”。"}, "sentence_index": 6, "correct_answer": "说明会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场说明会上，一幅名画卖到了一百万。", "explanation": "这里应该用〈拍卖会〉。说明会是讲清事情的会，不用于拍卖物品。"}, {"text": "他在说明会上跑了第一名，拿到了金牌。", "explanation": "这里应该用〈运动会〉。说明会不比赛，也不评名次。"}, {"text": "明星们在说明会上走红毯，记者拍了很多照片。", "explanation": "这里应该用〈首映式〉。说明会用于讲解事情，不是明星走红毯的场合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校下周三开一顿家长说明会。", "corrected_sentence": "学校下周三开一场家长说明会。", "error_description": "量词错误：“说明会”应用“场”，不能用“顿”（“顿”用于饭食或责骂）。错误形式：一顿；正确形式：一场。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我参加了一本说明会。", "corrected_sentence": "我参加了一场说明会。", "error_description": "量词错误：“说明会”应用“场”，不能用“本”（“本”用于书册）。错误形式：一本；正确形式：一场。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
