INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95767, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "谈到是说话的时候说起了某件事。", "primary_collocate": null, "pronunciation": "tán dào", "ipa": "tʰan˧˥ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "吃饭时，我们谈到了小时候的事。", "target_word": "谈到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友谈到了他的新家。", "target_word": "谈到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在电话里谈到了周末的安排。", "target_word": "谈到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谈到音乐，她的眼睛亮了。", "target_word": "谈到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷谈到以前的生活，笑了。", "target_word": "谈到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王谈到了自己的孩子。", "target_word": "谈到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "聊天时他谈到过想去中国。", "target_word": "谈到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谈到这家饭店，大家都说好吃。", "target_word": "谈到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有谈到价钱的事。", "target_word": "谈到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她谈到那次考试，还是有点儿紧张。", "target_word": "谈到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "谈到了", "label": "体标"}, {"form": "谈到过", "label": "体标"}, {"form": "談到", "label": "繁体"}], "register": "中性", "sense_fingerprint": "谈到：说话的时候说起某件事，多用于聊天中顺带说起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc47c301-ed4a-4c66-ad41-95bf2b4b9f5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95767, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谈到", "is_correct": true, "explanation": "正确：“谈到”表示吃饭聊天时说起小时候的事，与“我们”的谈话语境相合。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是机器或物品，“小时候的事”不能被修理。"}, {"text": "发明", "is_correct": false, "explanation": "搭配：“发明”的对象是新事物，不能用于说起“小时候的事”。"}, {"text": "逃离", "is_correct": false, "explanation": "语义：“逃离”是摆脱，与吃饭时的谈话无关，不能表示提及往事。"}], "explanations": {"谈到": "正确：“谈到”表示吃饭聊天时说起小时候的事，与“我们”的谈话语境相合。", "修理": "搭配：“修理”的对象是机器或物品，“小时候的事”不能被修理。", "发明": "搭配：“发明”的对象是新事物，不能用于说起“小时候的事”。", "逃离": "语义：“逃离”是摆脱，与吃饭时的谈话无关，不能表示提及往事。"}, "sentence_index": 0, "correct_answer": "谈到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "飞机谈到了机场。", "explanation": "这里应该用〈抵达〉。谈到只表示说话时说起某事，不能表示飞机到达某处。"}, {"text": "小猫谈到了我的脚。", "explanation": "这里应该用〈碰到〉。谈到表示言谈中提及，不能表示身体接触。"}, {"text": "钥匙谈到了地上。", "explanation": "这里应该用〈掉到〉。谈到是说话时提及，不能表示物体落在地上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95767, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谈到", "is_correct": true, "explanation": "正确：“谈到”表示聊天时提到过想去中国，与“过”搭配，符合语境。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”针对场所或物品，不能与“想去中国”这种意愿搭配。"}, {"text": "切开", "is_correct": false, "explanation": "语义：“切开”是切割实物，与“想去中国”的意愿毫无联系。"}, {"text": "割断", "is_correct": false, "explanation": "搭配：“割断”的对象是绳子等具体物体，不能接“想去中国”。"}], "explanations": {"谈到": "正确：“谈到”表示聊天时提到过想去中国，与“过”搭配，符合语境。", "打扫": "搭配：“打扫”针对场所或物品，不能与“想去中国”这种意愿搭配。", "切开": "语义：“切开”是切割实物，与“想去中国”的意愿毫无联系。", "割断": "搭配：“割断”的对象是绳子等具体物体，不能接“想去中国”。"}, "sentence_index": 6, "correct_answer": "谈到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把画谈到了墙上。", "explanation": "这里应该用〈挂到〉。谈到表示提及话题，不能表示把东西挂在某个地方。"}, {"text": "小球谈到了床下面。", "explanation": "这里应该用〈滚到〉。谈到是言谈中提及，不能表示球滚动到某处。"}, {"text": "他的眼镜谈到了窗台上。", "explanation": "这里应该用〈放到〉。谈到是言谈中提及，不能表示物体被放在某处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95767, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们谈到了过那件事。", "corrected_sentence": "我们谈到了那件事。", "error_description": "错误形式：“谈到了”之后又加“过”，“了”与“过”两个体标同时出现。正确形式：“谈到了那件事”，只用“了”，不再加“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95767, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们没谈到了这个问题。", "corrected_sentence": "我们没谈到这个问题。", "error_description": "错误形式：“没”否定“谈到”之后又加了“了”，“没”与“了”不能共现。正确形式：“我们没谈到这个问题”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
