INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95768, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在谈话中提到或涉及某件事。", "primary_collocate": null, "pronunciation": "tán dào", "ipa": "tʰan˧˥ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "谈到工作，他的话就多了起来。", "target_word": "谈到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们刚才谈到了你的计划。", "target_word": "谈到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师谈到过这个问题。", "target_word": "谈到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家聊天时谈到了旅行。", "target_word": "谈到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谈到钱，他马上不说话了。", "target_word": "谈到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谈到孩子，妈妈脸上有了笑容。", "target_word": "谈到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上谈到了学校的变化。", "target_word": "谈到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你刚才谈到的那本书叫什么名字？", "target_word": "谈到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谈到明天的比赛，他有点儿担心。", "target_word": "谈到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们昨天没有谈到这件事。", "target_word": "谈到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "谈到了", "label": "体标"}, {"form": "谈到过", "label": "体标"}, {"form": "談到", "label": "繁体"}], "register": "中性", "sense_fingerprint": "谈到：谈话中提到或涉及某个话题，后面接话题或事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc47c301-ed4a-4c66-ad41-95bf2b4b9f5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95768, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谈到", "is_correct": true, "explanation": "正确：“谈到”表示谈话中提及工作这个话题，与后句“话就多了起来”相合。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：“烹饪”的对象是食材，不能说“烹饪工作”。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是机器或物品，不能说“修理工作”。"}, {"text": "打开", "is_correct": false, "explanation": "搭配：“打开”的对象应是门窗、包装等，不能说“打开工作”。"}], "explanations": {"谈到": "正确：“谈到”表示谈话中提及工作这个话题，与后句“话就多了起来”相合。", "烹饪": "搭配：“烹饪”的对象是食材，不能说“烹饪工作”。", "修理": "搭配：“修理”的对象是机器或物品，不能说“修理工作”。", "打开": "搭配：“打开”的对象应是门窗、包装等，不能说“打开工作”。"}, "sentence_index": 0, "correct_answer": "谈到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的手谈到了桌子。", "explanation": "这里应该用〈碰到〉。谈到只表示言谈中提及，不能用“他的手”作主语表示身体接触。"}, {"text": "他的帽子谈到了床上。", "explanation": "这里应该用〈落到〉。谈到只表示言谈中提及，不能表示物体落到某处。"}, {"text": "这块石头谈到了水里。", "explanation": "这里应该用〈掉到〉。谈到只能用于言谈，不能表示物体落入某处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95768, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谈到", "is_correct": true, "explanation": "正确：“谈到”表示在会上提及“学校的变化”这一话题，与后面的“了”搭配。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”的对象是房屋、道路等实体，不能说“修建了学校的变化”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”针对场所或物品，“学校的变化”不能被打扫。"}, {"text": "割断", "is_correct": false, "explanation": "语义：“割断”是切开实物，与会上讨论变化的语境毫不相关。"}], "explanations": {"谈到": "正确：“谈到”表示在会上提及“学校的变化”这一话题，与后面的“了”搭配。", "修建": "搭配：“修建”的对象是房屋、道路等实体，不能说“修建了学校的变化”。", "打扫": "搭配：“打扫”针对场所或物品，“学校的变化”不能被打扫。", "割断": "语义：“割断”是切开实物，与会上讨论变化的语境毫不相关。"}, "sentence_index": 6, "correct_answer": "谈到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨点谈到了地上。", "explanation": "这里应该用〈落到〉。谈到是言谈中提及，不能表示物体落下来到达某处。"}, {"text": "他终于谈到了一口新鲜空气。", "explanation": "这里应该用〈吸到〉。谈到的对象是话题，不能与“一口新鲜空气”这样的具体事物搭配作宾语。"}, {"text": "他把画谈到了墙上。", "explanation": "这里应该用〈挂到〉。谈到表示提及话题，不能表示把东西挂在某个地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95768, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他谈到了过自己的爱好。", "corrected_sentence": "他谈到了自己的爱好。", "error_description": "错误形式：“谈到了”之后又加“过”，“了”与“过”两个体标同时标记同一动作。正确形式：“谈到了自己的爱好”，只用“了”，不再加“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95768, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们没谈到了那个问题。", "corrected_sentence": "我们没谈到那个问题。", "error_description": "错误形式：“没”否定“谈到”之后又加了“了”，“没”与“了”不能共现。正确形式：“没谈到那个问题”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95769, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "正确：“反对”与“赞同”意思相反，表示不同意。"}, {"text": "参加", "is_correct": false, "explanation": "无反义关系：“参加”指加入某项活动，与“赞同”的意思无关。"}, {"text": "讨论", "is_correct": false, "explanation": "无反义关系：“讨论”指共同交流意见，并不表示相反的态度。"}, {"text": "旅行", "is_correct": false, "explanation": "无反义关系：“旅行”指出外游览，与表示同意的“赞同”没有对立关系。"}], "correct_answer": "反对", "explanations": {"反对": "正确：“反对”与“赞同”意思相反，表示不同意。", "参加": "无反义关系：“参加”指加入某项活动，与“赞同”的意思无关。", "讨论": "无反义关系：“讨论”指共同交流意见，并不表示相反的态度。", "旅行": "无反义关系：“旅行”指出外游览，与表示同意的“赞同”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95769, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "正确：“反对”与“赞同”意思相反，表示不同意。"}, {"text": "研究", "is_correct": false, "explanation": "无反义关系：“研究”指深入探讨问题，与“赞同”的态度无对立关系。"}, {"text": "观察", "is_correct": false, "explanation": "无反义关系：“观察”指仔细看，与表示同意的“赞同”没有对立关系。"}, {"text": "决定", "is_correct": false, "explanation": "无反义关系：“决定”指做出选择，与“赞同”的意思无对立关系。"}], "correct_answer": "反对", "explanations": {"反对": "正确：“反对”与“赞同”意思相反，表示不同意。", "研究": "无反义关系：“研究”指深入探讨问题，与“赞同”的态度无对立关系。", "观察": "无反义关系：“观察”指仔细看，与表示同意的“赞同”没有对立关系。", "决定": "无反义关系：“决定”指做出选择，与“赞同”的意思无对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95769, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "赞同是别人说的话，你觉得对，也这样想。", "primary_collocate": null, "pronunciation": "zàn tóng", "ipa": "tsan˥˩ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我赞同你的看法，我们就这样办吧。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都赞同他的意见，没有人反对。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说得很对，我完全赞同。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法我不太赞同。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈赞同我去北京学习。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我赞同小王的说法，这样做更省钱。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说要早点出发，我很赞同。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人赞同这个计划。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸不赞同我一个人去旅行。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的话我赞同，天气不好就别出门了。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赞同了", "label": "体标"}, {"form": "赞同过", "label": "体标"}, {"form": "贊同", "label": "繁体"}], "register": "中性", "sense_fingerprint": "听了别人的话，觉得对，自己也这样想", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6bf5a98-c423-433d-921e-c8cc89de37cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95769, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赞同", "is_correct": true, "explanation": "正确：“赞同”表示认为对而同意，与后文“就这样办吧”一致。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”与后文“就这样办吧”的同意语气相反。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”指出问题，与“就这样办吧”的认可相矛盾。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展览，不能用于“看法”。"}], "explanations": {"赞同": "正确：“赞同”表示认为对而同意，与后文“就这样办吧”一致。", "反对": "语义：“反对”与后文“就这样办吧”的同意语气相反。", "批评": "语义：“批评”指出问题，与“就这样办吧”的认可相矛盾。", "参观": "搭配：“参观”的对象是场所或展览，不能用于“看法”。"}, "sentence_index": 0, "correct_answer": "赞同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很赞同这幅画的色彩。", "explanation": "这里应该用〈欣赏〉。赞同用于意见、做法或计划，评价画的色彩要用欣赏。"}, {"text": "这次演讲太精彩了，我很赞同他的口才。", "explanation": "这里应该用〈称赞〉。赞同针对意见或做法，夸奖别人的口才要用称赞。"}, {"text": "我很赞同你的帮助。", "explanation": "这里应该用〈感激〉。赞同是对意见的态度，对别人的帮助表示谢意要用感激。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95769, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赞同", "is_correct": true, "explanation": "正确：“赞同”表示同意对方的说法，与“你说要早点出发”相符。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”是想念过去的人或事，与现在讨论早点出发的语境不符。"}, {"text": "感动", "is_correct": false, "explanation": "语义：“感动”多用于别人的好意或感人的事，与“早点出发”的安排不搭。"}, {"text": "嘲笑", "is_correct": false, "explanation": "搭配：“嘲笑”需要说出被嘲笑的对象，“很嘲笑”不能这样用。"}], "explanations": {"赞同": "正确：“赞同”表示同意对方的说法，与“你说要早点出发”相符。", "怀念": "语义：“怀念”是想念过去的人或事，与现在讨论早点出发的语境不符。", "感动": "语义：“感动”多用于别人的好意或感人的事，与“早点出发”的安排不搭。", "嘲笑": "搭配：“嘲笑”需要说出被嘲笑的对象，“很嘲笑”不能这样用。"}, "sentence_index": 6, "correct_answer": "赞同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于赞同了自己的错误。", "explanation": "这里应该用〈承认〉。赞同是对别人的意见表示同意，承认自己的错误要用承认。"}, {"text": "我很赞同他的遭遇。", "explanation": "这里应该用〈同情〉。赞同针对意见或做法，对别人的不幸表示关切要用同情。"}, {"text": "我很赞同那段日子。", "explanation": "这里应该用〈怀念〉。赞同不能用于时间或经历，回想过去的时光要用怀念。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95769, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不地赞同这个做法，咱们再想想。", "corrected_sentence": "我不赞同这个做法，咱们再想想。", "error_description": "错误：“不”与“赞同”之间多了助词“地”，“不地赞同”不成立。正确：“我不赞同这个做法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95769, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很地赞同你的安排，我们就这么定。", "corrected_sentence": "我很赞同你的安排，我们就这么定。", "error_description": "错误：“很地赞同”。正确：“很赞同”。“很”作状语修饰动词时直接放在动词前，不加“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95770, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "正确：“反对”与“赞同”意思相反，表示不同意。"}, {"text": "参加", "is_correct": false, "explanation": "无反义关系：“参加”指加入某项活动，与“赞同”的意思无关。"}, {"text": "旅行", "is_correct": false, "explanation": "无反义关系：“旅行”指出外游览，与表示同意的“赞同”没有对立关系。"}, {"text": "观察", "is_correct": false, "explanation": "无反义关系：“观察”指仔细看，与表示同意的“赞同”没有对立关系。"}], "correct_answer": "反对", "explanations": {"反对": "正确：“反对”与“赞同”意思相反，表示不同意。", "参加": "无反义关系：“参加”指加入某项活动，与“赞同”的意思无关。", "旅行": "无反义关系：“旅行”指出外游览，与表示同意的“赞同”没有对立关系。", "观察": "无反义关系：“观察”指仔细看，与表示同意的“赞同”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95770, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "正确：“反对”与“赞同”意思相反，表示不同意。"}, {"text": "研究", "is_correct": false, "explanation": "无反义关系：“研究”指深入探讨问题，与“赞同”的态度无对立关系。"}, {"text": "讨论", "is_correct": false, "explanation": "无反义关系：“讨论”指共同交流意见，并不表示相反的态度。"}, {"text": "决定", "is_correct": false, "explanation": "无反义关系：“决定”指做出选择，与“赞同”的意思无对立关系。"}], "correct_answer": "反对", "explanations": {"反对": "正确：“反对”与“赞同”意思相反，表示不同意。", "研究": "无反义关系：“研究”指深入探讨问题，与“赞同”的态度无对立关系。", "讨论": "无反义关系：“讨论”指共同交流意见，并不表示相反的态度。", "决定": "无反义关系：“决定”指做出选择，与“赞同”的意思无对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95770, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "认为对而表示同意。", "primary_collocate": null, "pronunciation": "zàn tóng", "ipa": "tsan˥˩ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "经理赞同这个计划，让我们马上开始。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们赞同我们的做法，还给了很多帮助。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板赞同了我的建议。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师赞同他每天跑步的做法。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会上，大家一致赞同这个决定。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家人都赞同我换工作。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他点点头，赞同了我的想法。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生赞同病人多休息。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人赞同把会议改到周末。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长赞同学生办一个读书会。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赞同了", "label": "体标"}, {"form": "赞同过", "label": "体标"}, {"form": "贊同", "label": "繁体"}], "register": "中性", "sense_fingerprint": "认为对，并明确表示同意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6bf5a98-c423-433d-921e-c8cc89de37cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95770, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赞同", "is_correct": true, "explanation": "正确：“赞同”表示认为对而同意，与后文“让我们马上开始”一致。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”表示不接受，与后文“让我们马上开始”的认可相反。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”表示不同意，与“让我们马上开始”的态度相矛盾。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展览，不能用于“计划”。"}], "explanations": {"赞同": "正确：“赞同”表示认为对而同意，与后文“让我们马上开始”一致。", "拒绝": "语义：“拒绝”表示不接受，与后文“让我们马上开始”的认可相反。", "反对": "语义：“反对”表示不同意，与“让我们马上开始”的态度相矛盾。", "参观": "搭配：“参观”的对象是场所或展览，不能用于“计划”。"}, "sentence_index": 0, "correct_answer": "赞同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很赞同老师的鼓励。", "explanation": "这里应该用〈感谢〉。赞同是对意见或做法的态度，对别人的鼓励表示谢意要用感谢。"}, {"text": "我很赞同他的勇气。", "explanation": "这里应该用〈佩服〉。赞同针对意见或做法，欣赏别人的品质要用佩服。"}, {"text": "我很赞同那个迷路的孩子。", "explanation": "这里应该用〈同情〉。赞同不用于指人，对迷路的孩子表示怜惜要用同情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95770, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赞同", "is_correct": true, "explanation": "正确：“赞同”表示同意对方的想法，与“点点头”的态度一致。"}, {"text": "反驳", "is_correct": false, "explanation": "语义：“反驳”是提出不同意见，与“点点头”表示认同的动作相矛盾。"}, {"text": "推翻", "is_correct": false, "explanation": "语义：“推翻”指否定原来的观点，与“点点头”的认同态度不符。"}, {"text": "游览", "is_correct": false, "explanation": "搭配：“游览”的对象是景点或地方，不能用于“想法”。"}], "explanations": {"赞同": "正确：“赞同”表示同意对方的想法，与“点点头”的态度一致。", "反驳": "语义：“反驳”是提出不同意见，与“点点头”表示认同的动作相矛盾。", "推翻": "语义：“推翻”指否定原来的观点，与“点点头”的认同态度不符。", "游览": "搭配：“游览”的对象是景点或地方，不能用于“想法”。"}, "sentence_index": 6, "correct_answer": "赞同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他赞同了自己的失误。", "explanation": "这里应该用〈承认〉。赞同是对别人的意见表示同意，承认自己做错要用承认。"}, {"text": "我很赞同那段大学时光。", "explanation": "这里应该用〈怀念〉。赞同不用于时间或经历，回想过去的时光要用怀念。"}, {"text": "我很赞同这首歌的旋律。", "explanation": "这里应该用〈欣赏〉。赞同针对意见或做法，评价音乐的美感要用欣赏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95770, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不地赞同这个提议，咱们再商量一下。", "corrected_sentence": "我不赞同这个提议，咱们再商量一下。", "error_description": "错误：“不”与“赞同”之间多了助词“地”，“不地赞同”不成立。正确：“我不赞同这个提议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95770, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很赞同的你的建议，咱们就这么定。", "corrected_sentence": "我很赞同你的建议，咱们就这么定。", "error_description": "错误：“赞同”是动词，后面直接带宾语“你的建议”，中间不能加“的”。正确：“我很赞同你的建议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
