INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95771, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "轰炸是飞机从天上扔下炸弹，把地方炸坏。", "primary_collocate": null, "pronunciation": "hōng zhà", "ipa": "xʊŋ˥ ʈʂa˥˩", "syllable_count": 2, "sentences": [{"text": "飞机轰炸了那座桥。", "target_word": "轰炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争时，敌机常常轰炸这座城市。", "target_word": "轰炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天夜里，飞机轰炸了工厂。", "target_word": "轰炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机来轰炸过这里一次。", "target_word": "轰炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌机正在轰炸山上的路。", "target_word": "轰炸", "complexity_tier": "T3", "furigana": "dí jī zhèng zài hōng zhà shān shàng de lù", "sentence_source": "generated"}, {"text": "飞机飞来轰炸火车站。", "target_word": "轰炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里，飞机轰炸着河边的村子。", "target_word": "轰炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，小时候飞机轰炸过他的家。", "target_word": "轰炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机为什么要轰炸那个地方？", "target_word": "轰炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天上的飞机开始轰炸了。", "target_word": "轰炸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "轰炸了", "label": "完成体"}, {"form": "轰炸过", "label": "经历体"}, {"form": "轰炸着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "飞机从空中投弹，炸毁某地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b283c72b-36cb-4649-9609-b1e6be703ed2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95771, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "轰炸", "is_correct": true, "explanation": "正确：“轰炸”指飞机投弹攻击目标，与句中的“飞机”和“桥”相符。"}, {"text": "修建", "is_correct": false, "explanation": "语义：“修建”的主体需是人或施工队，飞机不能修建桥梁。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：“驾驶”的宾语须是交通工具，“桥”不能被驾驶。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”的主体须是人，飞机不能参观桥梁。"}], "explanations": {"轰炸": "正确：“轰炸”指飞机投弹攻击目标，与句中的“飞机”和“桥”相符。", "修建": "语义：“修建”的主体需是人或施工队，飞机不能修建桥梁。", "驾驶": "配价：“驾驶”的宾语须是交通工具，“桥”不能被驾驶。", "参观": "语义：“参观”的主体须是人，飞机不能参观桥梁。"}, "sentence_index": 0, "correct_answer": "轰炸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "敌军的士兵用刀轰炸了我们的阵地。", "explanation": "这里应该用〈攻击〉。用刀近身搏斗不叫轰炸；“轰炸”指用飞机或炮火猛烈攻击。"}, {"text": "士兵用手枪轰炸了敌人的车队。", "explanation": "这里应该用〈射击〉。用手枪开火要说〈射击〉；“轰炸”指用飞机或炮火猛烈攻击，不用于手枪。"}, {"text": "飞机向灾区轰炸了一批药品。", "explanation": "这里应该用〈投放〉。运送救灾药品要说〈投放〉；“轰炸”是攻击目标，不能用于送物资。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95771, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轰炸", "is_correct": true, "explanation": "正确：“轰炸”与“飞机”和“村子”的语境相符，表示飞机对村子投弹。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“照顾”的主体须是有意识的人，飞机不能照顾村子。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：“浇灌”的对象是庄稼或田地，不能浇灌村子。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”是人的劳动，飞机不能打扫村子。"}], "explanations": {"轰炸": "正确：“轰炸”与“飞机”和“村子”的语境相符，表示飞机对村子投弹。", "照顾": "语义：“照顾”的主体须是有意识的人，飞机不能照顾村子。", "浇灌": "搭配：“浇灌”的对象是庄稼或田地，不能浇灌村子。", "打扫": "语义：“打扫”是人的劳动，飞机不能打扫村子。"}, "sentence_index": 6, "correct_answer": "轰炸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海盗轰炸了那艘商船。", "explanation": "这里应该用〈袭击〉。海盗不是从空中投弹，不能用“轰炸”；“袭击”指突然攻击，适用于海盗。"}, {"text": "猎人轰炸了一只兔子。", "explanation": "这里应该用〈射击〉。“轰炸”的对象是地面的军事或建筑目标，猎人打猎应说〈射击〉。"}, {"text": "这位医生轰炸了那个病人。", "explanation": "这里应该用〈治疗〉。医生给病人治病要说〈治疗〉；“轰炸”是攻击，不用于医疗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95771, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们把那座小镇轰炸。", "corrected_sentence": "他们把那座小镇轰炸了。", "error_description": "错误：“把”字句中的“轰炸”后缺少补充成分“了”，句子不完整。正确：“把那座小镇轰炸了”。“把”字句的动词后须有补充成分。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95771, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "飞机轰炸了过那座城市。", "corrected_sentence": "飞机轰炸过那座城市。", "error_description": "错误：“轰炸了过”，“了”和“过”不能这样连用。正确：“轰炸过”。表示经历时，“过”直接放在动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
