INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95772, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用飞机投掷炸弹来攻击目标。", "primary_collocate": null, "pronunciation": "hōng zhà", "ipa": "xʊŋ˥ ʈʂa˥˩", "syllable_count": 2, "sentences": [{"text": "军队派飞机去轰炸敌人的基地。", "target_word": "轰炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队计划明天早上用飞机轰炸大桥。", "target_word": "轰炸", "complexity_tier": "T3", "furigana": "jūn duì jì huà míng tiān zǎo shang yòng fēi jī hōng zhà dà qiáo", "sentence_source": "generated"}, {"text": "飞机轰炸目标以前，先要看清楚。", "target_word": "轰炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些飞机要轰炸山后的仓库。", "target_word": "轰炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上写着，飞机曾经轰炸过这个港口。", "target_word": "轰炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们决定派飞机轰炸敌人的雷达站。", "target_word": "轰炸", "complexity_tier": "T3", "furigana": "wǒ men jué dìng pài fēi jī hōng zhà dí rén de léi dá zhàn", "sentence_source": "generated"}, {"text": "飞机轰炸完目标就飞回去了。", "target_word": "轰炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了停止进攻，飞机轰炸了机场。", "target_word": "轰炸", "complexity_tier": "T3", "furigana": "wèi le tíng zhǐ jìn gōng fēi jī hōng zhà le jī chǎng", "sentence_source": "generated"}, {"text": "飞机每天都去轰炸同一个目标。", "target_word": "轰炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的飞机成功轰炸了敌人的车队。", "target_word": "轰炸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "轰炸了", "label": "完成体"}, {"form": "轰炸过", "label": "经历体"}, {"form": "轰炸着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "用飞机投弹攻击军事目标", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b283c72b-36cb-4649-9609-b1e6be703ed2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95772, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "轰炸", "is_correct": true, "explanation": "正确：“轰炸”表示用飞机投弹攻击目标，与“军队”“飞机”“基地”相符。"}, {"text": "拜访", "is_correct": false, "explanation": "语义：“拜访”的主体须是人，飞机不能拜访基地。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的对象是可移动的货物，基地不能被搬运。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：“烘焙”的对象是食物，飞机不能烘焙基地。"}], "explanations": {"轰炸": "正确：“轰炸”表示用飞机投弹攻击目标，与“军队”“飞机”“基地”相符。", "拜访": "语义：“拜访”的主体须是人，飞机不能拜访基地。", "搬运": "搭配：“搬运”的对象是可移动的货物，基地不能被搬运。", "烘焙": "语义：“烘焙”的对象是食物，飞机不能烘焙基地。"}, "sentence_index": 0, "correct_answer": "轰炸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "运输机向灾区轰炸了救灾物资。", "explanation": "这里应该用〈投放〉。运送救灾物资要说〈投放〉；“轰炸”是攻击目标，不能用于送物资。"}, {"text": "他用手枪轰炸了敌人的阵地。", "explanation": "这里应该用〈射击〉。用手枪开火要说〈射击〉；“轰炸”指用飞机或炮火猛烈攻击，不用于手枪。"}, {"text": "狙击手轰炸了远处的敌兵。", "explanation": "这里应该用〈射击〉。狙击手用枪瞄准单个目标，应说〈射击〉；“轰炸”针对地面目标投掷炸弹，不适用于狙击。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95772, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轰炸", "is_correct": true, "explanation": "正确：“轰炸完目标”指飞机投弹攻击目标后离开，与句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，飞机不能吃目标。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物或身体，不能说洗目标。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是液体，飞机不能喝目标。"}], "explanations": {"轰炸": "正确：“轰炸完目标”指飞机投弹攻击目标后离开，与句意相符。", "吃": "语义：“吃”的对象是食物，飞机不能吃目标。", "洗": "搭配：“洗”的对象是衣物或身体，不能说洗目标。", "喝": "语义：“喝”的对象是液体，飞机不能喝目标。"}, "sentence_index": 6, "correct_answer": "轰炸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "战士轰炸了逃跑的敌人。", "explanation": "这里应该用〈追击〉。战士在地面追赶敌人要说〈追击〉；“轰炸”是飞机投弹，战士不能轰炸。"}, {"text": "他向窗外轰炸了一块石头。", "explanation": "这里应该用〈扔〉。手抛石头要说〈扔〉；“轰炸”指投掷炸弹攻击目标，不能用于扔石头。"}, {"text": "他的子弹轰炸了目标。", "explanation": "这里应该用〈打中〉。子弹击中目标要说〈打中〉；“轰炸”是投掷炸弹的攻击方式，子弹不能轰炸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "飞机轰炸了完那个港口。", "corrected_sentence": "飞机轰炸完了那个港口。", "error_description": "错误形式：“轰炸了完”。结果补语“完”须紧跟动词，“了”应放在补语之后；正确形式：“轰炸完了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95772, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "飞机从没轰炸了这里。", "corrected_sentence": "飞机从没轰炸过这里。", "error_description": "错误形式：“从没”表示从未有过的经历，应用体标“过”，与“了”不能同用。正确形式：“轰炸过这里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
