INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95777, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "运转是机器一圈一圈地转动，在工作。", "primary_collocate": null, "pronunciation": "yùn zhuǎn", "ipa": "yn˥˩ ʈʂwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "风车在风里慢慢地运转。", "target_word": "运转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器开始运转，发出很大的声音。", "target_word": "运转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车间里的机器一直在运转。", "target_word": "运转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台发动机运转得很平稳。", "target_word": "运转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水车一天到晚运转着，把水送到田里。", "target_word": "运转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人检查完，机器又运转起来了。", "target_word": "运转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风扇运转时，叶片转得很快。", "target_word": "运转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磨坊里的石磨日夜运转。", "target_word": "运转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅听了听，说机器运转正常。", "target_word": "运转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钟里的齿轮不停地运转，钟才走得准。", "target_word": "运转", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "运转了", "label": "体标"}, {"form": "运转着", "label": "体标"}, {"form": "运转过", "label": "体标"}], "register": "中性", "sense_fingerprint": "运转：机器一圈一圈转动着工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc14243-eedd-4dfd-9576-020da2c00dc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95777, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运转", "is_correct": true, "explanation": "运转指机器一圈一圈转动着工作，风车正是这样转动。"}, {"text": "跳动", "is_correct": false, "explanation": "语义：跳动指一起一伏地动，不是风车转动的样子。"}, {"text": "燃烧", "is_correct": false, "explanation": "语义：燃烧指着火，风车在风里不会燃烧。"}, {"text": "发动", "is_correct": false, "explanation": "搭配：发动多用于发动机、车辆，不说风车发动。"}], "explanations": {"运转": "运转指机器一圈一圈转动着工作，风车正是这样转动。", "跳动": "语义：跳动指一起一伏地动，不是风车转动的样子。", "燃烧": "语义：燃烧指着火，风车在风里不会燃烧。", "发动": "搭配：发动多用于发动机、车辆，不说风车发动。"}, "sentence_index": 0, "correct_answer": "运转"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "杂技演员在台上运转。", "explanation": "这里应该用〈旋转〉。运转指机器一圈一圈转动工作，不用来形容人的身体动作。"}, {"text": "孩子每天都运转。", "explanation": "这里应该用〈运动〉。运转只用于机器、机构的运行，人锻炼身体要说运动。"}, {"text": "这位工人每天在车间运转八小时。", "explanation": "这里应该用〈工作〉。运转指机器整体转动工作，人干活要说工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95777, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运转", "is_correct": true, "explanation": "运转指机器一圈一圈转动着工作，与“叶片转得很快”相符。"}, {"text": "停止", "is_correct": false, "explanation": "语义：停止指不再转动，与“叶片转得很快”矛盾。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：熄灭多指灯火，风扇不说熄灭。"}, {"text": "静止", "is_correct": false, "explanation": "语义：静止指一动不动，与“叶片转得很快”冲突。"}], "explanations": {"运转": "运转指机器一圈一圈转动着工作，与“叶片转得很快”相符。", "停止": "语义：停止指不再转动，与“叶片转得很快”矛盾。", "熄灭": "搭配：熄灭多指灯火，风扇不说熄灭。", "静止": "语义：静止指一动不动，与“叶片转得很快”冲突。"}, "sentence_index": 6, "correct_answer": "运转"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们在教室里运转。", "explanation": "这里应该用〈上课〉。运转用于机器、机构的运行，不用于学生的学习活动。"}, {"text": "他在河里运转。", "explanation": "这里应该用〈游泳〉。运转指机器、天体按路线转动，不用于人在水中的动作。"}, {"text": "妈妈在厨房里运转。", "explanation": "这里应该用〈做饭〉。运转用于机器、机构的运行，不用于人做家务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95777, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车床突然运转上来了。", "corrected_sentence": "车床突然运转起来了。", "error_description": "“运转上来”错误。“上来”表示向上移动，不能表示机器开始转动；应改为“运转起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95777, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台水泵终于运转过起来了。", "corrected_sentence": "这台水泵终于运转起来了。", "error_description": "“过”表示曾经历，不能插在“运转”和“起来”之间表示开始；应去掉“过”，说“运转起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
