INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95778, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "沿着一定的路线转动；也指机构或机器正常工作。", "primary_collocate": null, "pronunciation": "yùn zhuǎn", "ipa": "yn˥˩ ʈʂwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "地球一直围着太阳运转。", "target_word": "运转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的机器二十四小时运转。", "target_word": "运转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司现在运转得很好。", "target_word": "运转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮围着地球运转，一圈要二十几天。", "target_word": "运转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑坏了，整个办公室没法运转。", "target_word": "运转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台洗衣机运转时声音很小。", "target_word": "运转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的各项工作都在正常运转。", "target_word": "运转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停电以后，医院靠备用发电机运转。", "target_word": "运转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器运转了一整天，需要休息一下。", "target_word": "运转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个系统运转了三年，没出过大问题。", "target_word": "运转", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "运转了", "label": "体标"}, {"form": "运转着", "label": "体标"}, {"form": "运转过", "label": "体标"}], "register": "中性", "sense_fingerprint": "运转：沿固定路线转动，或机构、机器正常工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc14243-eedd-4dfd-9576-020da2c00dc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95778, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运转", "is_correct": true, "explanation": "运转指沿轨道绕行，地球绕太阳运行正是这种运转。"}, {"text": "跳动", "is_correct": false, "explanation": "语义：跳动指一起一伏地动，不能描述地球绕太阳的运行。"}, {"text": "燃烧", "is_correct": false, "explanation": "语义：燃烧指物体着火发热，与绕着太阳转动无关。"}, {"text": "开动", "is_correct": false, "explanation": "搭配：开动多用于车辆、机器，不说地球开动。"}], "explanations": {"运转": "运转指沿轨道绕行，地球绕太阳运行正是这种运转。", "跳动": "语义：跳动指一起一伏地动，不能描述地球绕太阳的运行。", "燃烧": "语义：燃烧指物体着火发热，与绕着太阳转动无关。", "开动": "搭配：开动多用于车辆、机器，不说地球开动。"}, "sentence_index": 0, "correct_answer": "运转"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "芭蕾舞演员在台上运转。", "explanation": "这里应该用〈旋转〉。运转指机器或天体按路线转动，不用来形容人的身体动作。"}, {"text": "他每天早上都运转。", "explanation": "这里应该用〈运动〉。运转只说机器、机构整体运行或天体绕行，人锻炼身体要说运动。"}, {"text": "他每天在公司运转八小时。", "explanation": "这里应该用〈工作〉。运转指机器或机构整体正常运行，人在岗位上干活要说工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95778, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运转", "is_correct": true, "explanation": "运转指机构或机器正常工作，与句中的“正常”相符。"}, {"text": "停摆", "is_correct": false, "explanation": "语义：停摆指停下不动，与“正常”矛盾，工作不能正常停摆。"}, {"text": "失灵", "is_correct": false, "explanation": "搭配：失灵多指仪器、装置失效，不说各项工作失灵。"}, {"text": "瘫痪", "is_correct": false, "explanation": "语义：瘫痪指失去作用、陷入停顿，与“正常”的语义冲突。"}], "explanations": {"运转": "运转指机构或机器正常工作，与句中的“正常”相符。", "停摆": "语义：停摆指停下不动，与“正常”矛盾，工作不能正常停摆。", "失灵": "搭配：失灵多指仪器、装置失效，不说各项工作失灵。", "瘫痪": "语义：瘫痪指失去作用、陷入停顿，与“正常”的语义冲突。"}, "sentence_index": 6, "correct_answer": "运转"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "卡车每天运转大量的货物。", "explanation": "这里应该用〈运输〉。运转说机器、机构的转动或正常工作，不带“货物”作宾语；运送货物要用运输。"}, {"text": "我每天在公园里运转。", "explanation": "这里应该用〈跑步〉。运转用于机器、机构或天体，不用于人的跑步等动作。"}, {"text": "这只猫每天晚上运转。", "explanation": "这里应该用〈睡觉〉。运转用于机器、机构的运行，不用于动物的日常活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95778, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电风扇开始运转下来了。", "corrected_sentence": "电风扇开始运转起来了。", "error_description": "“运转下来”错误。“下来”表示停止或落下，不能表示开始运转；应改为“运转起来”，用“起来”表示开始并持续。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95778, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "空调一直运转了着。", "corrected_sentence": "空调一直运转着。", "error_description": "“了着”错误。“了”表示完成，“着”表示持续，二者不能同时用在同一动词后；表示持续的状态只用“着”，应说“运转着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
