INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95779, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "闭是把开着的东西关上。比如闭上眼睛、闭上嘴。", "primary_collocate": null, "pronunciation": "bì", "ipa": "pi˥˩", "syllable_count": 1, "sentences": [{"text": "请你先把眼睛闭上，我给你一个惊喜。", "target_word": "闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说：“请闭上嘴，不要说话。”", "target_word": "闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累得坐在椅子上，慢慢闭了眼。", "target_word": "闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子一听到打雷，马上闭上了眼睛。", "target_word": "闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我闭着眼睛许愿。", "target_word": "闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“大家闭嘴，听我讲。”", "target_word": "闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她太困了，眼睛一闭就睡着了。", "target_word": "闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他闭着嘴，一句话也不说。", "target_word": "闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照相的时候，你别闭眼睛。", "target_word": "闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看电影到可怕的地方，我就闭上眼睛。", "target_word": "闭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "闭了", "label": "体标"}, {"form": "闭着", "label": "体标"}, {"form": "闭过", "label": "体标"}], "register": "中性", "sense_fingerprint": "闭：把眼睛、嘴等开着的东西关上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc14243-eedd-4dfd-9576-020da2c00dc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95779, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "闭", "is_correct": true, "explanation": "bì 是把开着的东西关上，如闭眼、闭嘴。"}, {"text": "比", "is_correct": false, "explanation": "bǐ（第三声）与 bì（第四声）声调不同，意思是比较。"}, {"text": "鼻", "is_correct": false, "explanation": "bí（第二声）与 bì（第四声）声调不同，意思是鼻子。"}, {"text": "密", "is_correct": false, "explanation": "mì 与 bì 声母不同（m / b），意思是密集、秘密。"}, {"text": "逼", "is_correct": false, "explanation": "bī（第一声）与 bì（第四声）声调不同，意思是逼迫。"}], "explanations": {"闭": "bì 是把开着的东西关上，如闭眼、闭嘴。", "比": "bǐ（第三声）与 bì（第四声）声调不同，意思是比较。", "鼻": "bí（第二声）与 bì（第四声）声调不同，意思是鼻子。", "密": "mì 与 bì 声母不同（m / b），意思是密集、秘密。", "逼": "bī（第一声）与 bì（第四声）声调不同，意思是逼迫。"}, "sentence_index": null, "correct_answer": "闭"}, "level_3": {"options": [{"text": "闭", "is_correct": true, "explanation": "闭是把开着的眼睛关上，与“请你先把眼睛……上”相符。"}, {"text": "睁", "is_correct": false, "explanation": "语义：睁是打开眼睛，与句中要求的闭眼动作相反。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：戴多用于眼镜、帽子，不说戴眼睛。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔指抛出，与眼睛的动作完全不相干。"}], "explanations": {"闭": "闭是把开着的眼睛关上，与“请你先把眼睛……上”相符。", "睁": "语义：睁是打开眼睛，与句中要求的闭眼动作相反。", "戴": "搭配：戴多用于眼镜、帽子，不说戴眼睛。", "扔": "语义：扔指抛出，与眼睛的动作完全不相干。"}, "sentence_index": 0, "correct_answer": "闭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他闭上了书，然后站起来。", "explanation": "这里应该用〈合上〉。闭多用于眼睛、嘴等，书本合拢要说合上。"}, {"text": "他闭上了鞋带，然后出门。", "explanation": "这里应该用〈系上〉。闭用于眼睛、嘴等可合拢的部位，鞋带要说系上。"}, {"text": "他闭了灯就睡觉。", "explanation": "这里应该用〈关〉。闭用于眼睛、嘴等可以合拢的东西，电灯开关要说关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95779, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "闭", "is_correct": true, "explanation": "bì 是把开着的东西关上，如闭眼、闭嘴。"}, {"text": "笔", "is_correct": false, "explanation": "bǐ（第三声）与 bì（第四声）声调不同，意思是笔。"}, {"text": "地", "is_correct": false, "explanation": "dì（第四声）指土地，与 bì 只是声母不同（d / b）。"}, {"text": "譬", "is_correct": false, "explanation": "pì（第四声）指比方，与 bì 只是声母送气与否不同（p / b）。"}], "explanations": {"闭": "bì 是把开着的东西关上，如闭眼、闭嘴。", "笔": "bǐ（第三声）与 bì（第四声）声调不同，意思是笔。", "地": "dì（第四声）指土地，与 bì 只是声母不同（d / b）。", "譬": "pì（第四声）指比方，与 bì 只是声母送气与否不同（p / b）。"}, "sentence_index": null, "correct_answer": "闭"}, "level_3": {"options": [{"text": "闭", "is_correct": true, "explanation": "闭是把开着的眼睛合上，与“眼睛一……就睡着了”相符。"}, {"text": "睁", "is_correct": false, "explanation": "语义：睁是打开眼睛，与句中合眼入睡的动作相反。"}, {"text": "摇", "is_correct": false, "explanation": "搭配：摇多用于头、身体或物件，不说摇眼睛。"}, {"text": "放", "is_correct": false, "explanation": "语义：放指放开、放置，与眼睛的开合动作不符。"}], "explanations": {"闭": "闭是把开着的眼睛合上，与“眼睛一……就睡着了”相符。", "睁": "语义：睁是打开眼睛，与句中合眼入睡的动作相反。", "摇": "搭配：摇多用于头、身体或物件，不说摇眼睛。", "放": "语义：放指放开、放置，与眼睛的开合动作不符。"}, "sentence_index": 6, "correct_answer": "闭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他闭上了书包拉链，然后出门。", "explanation": "这里应该用〈拉上〉。闭用于眼睛、嘴等可合拢的部位，拉链要说拉上。"}, {"text": "他闭上了衬衫的扣子。", "explanation": "这里应该用〈扣上〉。闭用于眼睛、嘴等，扣子要说扣上。"}, {"text": "妈妈闭上了锅盖。", "explanation": "这里应该用〈盖上〉。闭用于眼睛、嘴等，锅盖要说盖上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95779, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你先把嘴闭开，我再告诉你。", "corrected_sentence": "请你先把嘴闭上，我再告诉你。", "error_description": "“闭开”错误。“闭”表示关上，结果补语应为“上”，说“闭上”，不说“闭开”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95779, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你闭了眼睛听我说。", "corrected_sentence": "请你闭着眼睛听我说。", "error_description": "“闭了”错误。请求或命令要表示保持的状态，应用“着”；“了”表示完成，不能用于请求。应改为“请你闭着眼睛听我说”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
