INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95780, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "合上；关上；使开着的东西合拢。", "primary_collocate": null, "pronunciation": "bì", "ipa": "pi˥˩", "syllable_count": 1, "sentences": [{"text": "他深深吸了一口气，然后闭上眼睛。", "target_word": "闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大了，她闭紧了嘴不说话。", "target_word": "闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳一下山，这种花就闭起来了。", "target_word": "闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他闭着眼睛听音乐。", "target_word": "闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶坐在椅子上，闭眼休息了一会儿。", "target_word": "闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你闭上嘴，让我把话说完。", "target_word": "闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让他张开嘴，再慢慢闭上。", "target_word": "闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水进了眼睛，我马上闭了一下眼。", "target_word": "闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他闭上眼想了很久，才开口说话。", "target_word": "闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗闭着嘴，不肯吃药。", "target_word": "闭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "闭了", "label": "体标"}, {"form": "闭着", "label": "体标"}, {"form": "闭过", "label": "体标"}], "register": "中性", "sense_fingerprint": "闭：使开着的东西合拢、关上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc14243-eedd-4dfd-9576-020da2c00dc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
