INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95780, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "闭", "is_correct": true, "explanation": "bì 是合上、关上，使开着的东西合拢。"}, {"text": "比", "is_correct": false, "explanation": "bǐ（第三声）与 bì（第四声）声调不同，意思是比较。"}, {"text": "地", "is_correct": false, "explanation": "dì（第四声）指土地，与 bì 只是声母不同（d / b）。"}, {"text": "譬", "is_correct": false, "explanation": "pì（第四声）指比方，与 bì 只是声母送气与否不同（p / b）。"}], "explanations": {"闭": "bì 是合上、关上，使开着的东西合拢。", "比": "bǐ（第三声）与 bì（第四声）声调不同，意思是比较。", "地": "dì（第四声）指土地，与 bì 只是声母不同（d / b）。", "譬": "pì（第四声）指比方，与 bì 只是声母送气与否不同（p / b）。"}, "sentence_index": null, "correct_answer": "闭"}, "level_3": {"options": [{"text": "闭", "is_correct": true, "explanation": "闭是合上嘴，与“医生让他张开嘴，再慢慢……上”的动作相符。"}, {"text": "张", "is_correct": false, "explanation": "搭配：张指张开，句中已说张开嘴，且“张上”不成搭配。"}, {"text": "洗", "is_correct": false, "explanation": "语义：洗指用水清洁，“慢慢洗上”不成话，也与嘴的开合动作无关。"}, {"text": "撑", "is_correct": false, "explanation": "语义：撑是支撑、顶住，与嘴合拢的动作无关。"}], "explanations": {"闭": "闭是合上嘴，与“医生让他张开嘴，再慢慢……上”的动作相符。", "张": "搭配：张指张开，句中已说张开嘴，且“张上”不成搭配。", "洗": "语义：洗指用水清洁，“慢慢洗上”不成话，也与嘴的开合动作无关。", "撑": "语义：撑是支撑、顶住，与嘴合拢的动作无关。"}, "sentence_index": 6, "correct_answer": "闭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用袖子闭住了脸，不想让人看见。", "explanation": "这里应该用〈掩住〉。闭用于眼睛、嘴等可合拢的部位，遮住脸要说掩住。"}, {"text": "他闭上了被子，然后睡觉。", "explanation": "这里应该用〈盖上〉。闭用于眼睛、嘴等可合拢的部位，被子要说盖上。"}, {"text": "他闭了蜡烛就睡觉。", "explanation": "这里应该用〈熄〉。闭用于眼睛、嘴等，蜡烛要说熄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他闭着了眼睛，不说话。", "corrected_sentence": "他闭上了眼睛，不说话。", "error_description": "“闭着了”错误。“着”表示持续，不能与“了”连用表示完成；闭合的结果要用结果补语“上”，应改为“闭上了眼睛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小猫闭嘴着，不吃东西。", "corrected_sentence": "小猫闭着嘴，不吃东西。", "error_description": "“着”位置错误。“着”要紧跟动词“闭”，表示闭嘴的状态持续，应说“闭着嘴”，不说“闭嘴着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
