INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95783, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "颗是数小小圆圆的东西时用的字，比如一颗糖、一颗星星。", "primary_collocate": null, "pronunciation": "kē", "ipa": "kʰɤ˥", "syllable_count": 1, "sentences": [{"text": "我吃了一颗糖。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天上有很多颗星星。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹手里有一颗红色的小珠子。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盘子里还有三颗葡萄。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给了我两颗巧克力。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，我看见了一颗很亮的星星。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗樱桃又红又甜。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗找到了一颗小球。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把一颗豆子放在桌子上。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人掉了一颗牙。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颗颗", "label": "重叠"}, {"form": "颗粒", "label": "复合"}, {"form": "顆", "label": "繁体"}], "register": "中性", "sense_fingerprint": "量词：数小而圆的东西，如糖、星星、葡萄", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03215d03-95c8-4cd4-8139-5091553db1e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95783, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "颗", "is_correct": true, "explanation": "正确答案。颗：kē，量词，用于小而圆的东西，如糖、星星。"}, {"text": "哥", "is_correct": false, "explanation": "gē 与 kē 声母不同（g 与 k），意思是哥哥，不是量词。"}, {"text": "课", "is_correct": false, "explanation": "kè 与 kē 声调不同，意思是课程，不是量词。"}, {"text": "可", "is_correct": false, "explanation": "kě 与 kē 声调不同，意思是可以，不是量词。"}, {"text": "咳", "is_correct": false, "explanation": "ké 与 kē 声调不同，意思是咳嗽，不是量词。"}], "explanations": {"颗": "正确答案。颗：kē，量词，用于小而圆的东西，如糖、星星。", "哥": "gē 与 kē 声母不同（g 与 k），意思是哥哥，不是量词。", "课": "kè 与 kē 声调不同，意思是课程，不是量词。", "可": "kě 与 kē 声调不同，意思是可以，不是量词。", "咳": "ké 与 kē 声调不同，意思是咳嗽，不是量词。"}, "sentence_index": null, "correct_answer": "颗"}, "level_3": {"options": [{"text": "颗", "is_correct": true, "explanation": "正确答案。颗：用于小而圆的东西，糖是这类东西。"}, {"text": "本", "is_correct": false, "explanation": "语义：“本”指书籍、本子，与“糖”的意思不合。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于纸张、桌子等平面的东西，不说“一张糖”。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”多用于动物或成对东西中的一个，不说“一只糖”。"}], "explanations": {"颗": "正确答案。颗：用于小而圆的东西，糖是这类东西。", "本": "语义：“本”指书籍、本子，与“糖”的意思不合。", "张": "搭配：“张”用于纸张、桌子等平面的东西，不说“一张糖”。", "只": "搭配：“只”多用于动物或成对东西中的一个，不说“一只糖”。"}, "sentence_index": 0, "correct_answer": "颗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家养了三颗小鸟。", "explanation": "这里应该用〈只〉。“颗”用于小而圆的东西，动物要用“只”。"}, {"text": "他买了两颗书。", "explanation": "这里应该用〈本〉。“颗”用于小而圆的东西，书要用“本”。"}, {"text": "屋里放着一颗椅子。", "explanation": "这里应该用〈把〉。“颗”用于小而圆的东西，椅子要用“把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95783, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "颗", "is_correct": true, "explanation": "正确答案。颗：kē，量词，用于小而圆的东西。"}, {"text": "客", "is_correct": false, "explanation": "kè 与 kē 声调不同，意思是客人，不是量词。"}, {"text": "渴", "is_correct": false, "explanation": "kě 与 kē 声调不同，意思是口渴，不是量词。"}, {"text": "壳", "is_correct": false, "explanation": "ké 与 kē 声调不同，意思是外壳，不是量词。"}], "explanations": {"颗": "正确答案。颗：kē，量词，用于小而圆的东西。", "客": "kè 与 kē 声调不同，意思是客人，不是量词。", "渴": "kě 与 kē 声调不同，意思是口渴，不是量词。", "壳": "ké 与 kē 声调不同，意思是外壳，不是量词。"}, "sentence_index": null, "correct_answer": "颗"}, "level_3": {"options": [{"text": "颗", "is_correct": true, "explanation": "正确答案。颗：用于小而圆的东西，樱桃是这类东西。"}, {"text": "支", "is_correct": false, "explanation": "搭配：“支”用于杆状的东西，不说“这支樱桃”。"}, {"text": "条", "is_correct": false, "explanation": "语义：“条”指细长的东西，樱桃不是这种形状。"}, {"text": "座", "is_correct": false, "explanation": "搭配：“座”用于山、楼等大型固定的东西，樱桃很小，不说“这座樱桃”。"}], "explanations": {"颗": "正确答案。颗：用于小而圆的东西，樱桃是这类东西。", "支": "搭配：“支”用于杆状的东西，不说“这支樱桃”。", "条": "语义：“条”指细长的东西，樱桃不是这种形状。", "座": "搭配：“座”用于山、楼等大型固定的东西，樱桃很小，不说“这座樱桃”。"}, "sentence_index": 6, "correct_answer": "颗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家门口有一颗大树。", "explanation": "这里应该用〈棵〉。“颗”用于小而圆的东西，树要用“棵”。"}, {"text": "他们新买了一颗房子。", "explanation": "这里应该用〈栋〉。“颗”用于小而圆的东西，房子要用“栋”。"}, {"text": "河里游着一颗大鱼。", "explanation": "这里应该用〈条〉。“颗”用于小而圆的东西，鱼要用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95783, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桌上有一个颗红色的樱桃。", "corrected_sentence": "桌上有一颗红色的樱桃。", "error_description": "量词错误：“颗”前面不应再加“个”；正确：应说“一颗红色的樱桃”，不说“一个颗红色的樱桃”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95783, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹找到了一个颗玻璃珠。", "corrected_sentence": "妹妹找到了一颗玻璃珠。", "error_description": "量词叠用错误：“一个”与“颗”同时修饰“玻璃珠”，只能保留一个量词；正确：应说“一颗玻璃珠”，不说“一个颗玻璃珠”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
