INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95784, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于颗粒状的小东西。", "primary_collocate": null, "pronunciation": "kē", "ipa": "kʰɤ˥", "syllable_count": 1, "sentences": [{"text": "他在花盆里放了一颗种子。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的项链上有一颗珍珠。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让我每天吃一颗药。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鞋里有一颗小石头，我走路很疼。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗钻石很贵。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤里放了五颗红豆。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟吃了一颗红色的小果子。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他口袋里有一颗小纽扣。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗小珠子是奶奶留给我的。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把一颗花生放进嘴里。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颗颗", "label": "重叠"}, {"form": "颗粒", "label": "复合"}, {"form": "顆", "label": "繁体"}], "register": "中性", "sense_fingerprint": "量词：颗粒状的小东西，如种子、珍珠、药、石头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03215d03-95c8-4cd4-8139-5091553db1e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95784, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "颗", "is_correct": true, "explanation": "正确答案。颗：kē，量词，用于颗粒状的小东西，如种子、珍珠。"}, {"text": "哥", "is_correct": false, "explanation": "gē 与 kē 声母不同（g 与 k），意思是哥哥，不是量词。"}, {"text": "课", "is_correct": false, "explanation": "kè 与 kē 声调不同，意思是课程，不是量词。"}, {"text": "渴", "is_correct": false, "explanation": "kě 与 kē 声调不同，意思是口渴，不是量词。"}, {"text": "咳", "is_correct": false, "explanation": "ké 与 kē 声调不同，意思是咳嗽，不是量词。"}], "explanations": {"颗": "正确答案。颗：kē，量词，用于颗粒状的小东西，如种子、珍珠。", "哥": "gē 与 kē 声母不同（g 与 k），意思是哥哥，不是量词。", "课": "kè 与 kē 声调不同，意思是课程，不是量词。", "渴": "kě 与 kē 声调不同，意思是口渴，不是量词。", "咳": "ké 与 kē 声调不同，意思是咳嗽，不是量词。"}, "sentence_index": null, "correct_answer": "颗"}, "level_3": {"options": [{"text": "颗", "is_correct": true, "explanation": "正确答案。颗：用于颗粒状的小东西，种子是这类东西。"}, {"text": "棵", "is_correct": false, "explanation": "搭配：“棵”用于整株植物，种子还没长成植物，不说“一棵种子”。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于平面的东西，不说“一张种子”。"}, {"text": "座", "is_correct": false, "explanation": "搭配：“座”用于山、楼等大型固定的东西，种子很小，不说“一座种子”。"}], "explanations": {"颗": "正确答案。颗：用于颗粒状的小东西，种子是这类东西。", "棵": "搭配：“棵”用于整株植物，种子还没长成植物，不说“一棵种子”。", "张": "搭配：“张”用于平面的东西，不说“一张种子”。", "座": "搭配：“座”用于山、楼等大型固定的东西，种子很小，不说“一座种子”。"}, "sentence_index": 0, "correct_answer": "颗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他口袋里有一颗钥匙。", "explanation": "这里应该用〈把〉。“颗”用于颗粒状的小东西，钥匙要用“把”。"}, {"text": "我戴了一颗眼镜。", "explanation": "这里应该用〈副〉。“颗”用于颗粒状的小东西，眼镜要用“副”。"}, {"text": "她脖子上挂着一颗项链。", "explanation": "这里应该用〈条〉。“颗”用于颗粒状的小东西，项链要用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95784, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "颗", "is_correct": true, "explanation": "正确答案。颗：kē，量词，用于颗粒状的小东西。"}, {"text": "客", "is_correct": false, "explanation": "kè 与 kē 声调不同，意思是客人，不是量词。"}, {"text": "可", "is_correct": false, "explanation": "kě 与 kē 声调不同，意思是可以，不是量词。"}, {"text": "壳", "is_correct": false, "explanation": "ké 与 kē 声调不同，意思是外壳，不是量词。"}], "explanations": {"颗": "正确答案。颗：kē，量词，用于颗粒状的小东西。", "客": "kè 与 kē 声调不同，意思是客人，不是量词。", "可": "kě 与 kē 声调不同，意思是可以，不是量词。", "壳": "ké 与 kē 声调不同，意思是外壳，不是量词。"}, "sentence_index": null, "correct_answer": "颗"}, "level_3": {"options": [{"text": "颗", "is_correct": true, "explanation": "正确答案。颗：用于颗粒状的小东西，小果子是这类东西。"}, {"text": "头", "is_correct": false, "explanation": "搭配：“头”用于大型动物，不说“一头红色的小果子”。"}, {"text": "幅", "is_correct": false, "explanation": "语义：“幅”用于画、布等平面的东西，与小果子的意思不合。"}, {"text": "条", "is_correct": false, "explanation": "语义：“条”指细长的东西，小果子不是这种形状。"}], "explanations": {"颗": "正确答案。颗：用于颗粒状的小东西，小果子是这类东西。", "头": "搭配：“头”用于大型动物，不说“一头红色的小果子”。", "幅": "语义：“幅”用于画、布等平面的东西，与小果子的意思不合。", "条": "语义：“条”指细长的东西，小果子不是这种形状。"}, "sentence_index": 6, "correct_answer": "颗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我收到了一颗信。", "explanation": "这里应该用〈封〉。“颗”用于颗粒状的小东西，信要用“封”。"}, {"text": "教室里放着一颗桌子。", "explanation": "这里应该用〈张〉。“颗”用于颗粒状的小东西，桌子要用“张”。"}, {"text": "河里游着一颗鱼。", "explanation": "这里应该用〈条〉。“颗”用于颗粒状的小东西，鱼要用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_