INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95784, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的戒指上镶着颗一钻石。", "corrected_sentence": "她的戒指上镶着一颗钻石。", "error_description": "语序错误：数词“一”应放在量词“颗”前面；正确：应说“一颗钻石”，不说“颗一钻石”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95784, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈的戒指上有一个颗小钻石。", "corrected_sentence": "妈妈的戒指上有一颗小钻石。", "error_description": "量词多用：“颗”前面不能再加“个”；正确：应说“一颗小钻石”，不说“一个颗小钻石”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
