INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95786, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一个一个地，逐个。", "primary_collocate": null, "pronunciation": "yī yī", "ipa": "i˥ i˥", "syllable_count": 2, "sentences": [{"text": "老师把名字一一念给大家听。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这些问题一一回答。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人来了，他一一和他们握手。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生把每个病人一一检查了一遍。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把书一一放回了书架上。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们一一走上台，说出自己的名字。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把礼物一一拿出来给我们看。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把箱子里的东西一一拿了出来。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口的保安一一看了大家的证件。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把每位老人的名字一一记在本子上。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一一", "label": "原形"}], "register": "书面", "sense_fingerprint": "一个一个地逐个做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9cbe6ac-6e27-417b-92b2-2981f60beb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95786, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一一", "is_correct": true, "explanation": "正确：一一，读作 yī yī，意思是一个一个地、逐个地。"}, {"text": "一亿", "is_correct": false, "explanation": "一亿 yī yì：第二个音节声调不同（yì 为第四声，与 yī 的第一声不同），意思是一亿。"}, {"text": "意义", "is_correct": false, "explanation": "意义 yì yì：两个音节的声调都与 yī yī 不同，意思是意义。"}, {"text": "姨姨", "is_correct": false, "explanation": "yí yí（两个音节都是第二声）与 yī yī 声调不同，口语中是对年长女性的称呼。"}], "explanations": {"一一": "正确：一一，读作 yī yī，意思是一个一个地、逐个地。", "一亿": "一亿 yī yì：第二个音节声调不同（yì 为第四声，与 yī 的第一声不同），意思是一亿。", "意义": "意义 yì yì：两个音节的声调都与 yī yī 不同，意思是意义。", "姨姨": "yí yí（两个音节都是第二声）与 yī yī 声调不同，口语中是对年长女性的称呼。"}, "sentence_index": null, "correct_answer": "一一"}, "level_3": {"options": [{"text": "非常", "is_correct": false, "explanation": "语法：“非常”是程度副词，不能修饰“念”这样的动作动词。"}, {"text": "一一", "is_correct": true, "explanation": "正确：“一一”表示逐个依次进行，与“把名字……念给大家听”的语境相符。"}, {"text": "逐渐", "is_correct": false, "explanation": "搭配：“逐渐”表示变化的过程，不能修饰一次性的朗读动作。"}, {"text": "悄悄", "is_correct": false, "explanation": "语义：“悄悄”指不声张，与“念给大家听”的公开性矛盾。"}], "explanations": {"非常": "语法：“非常”是程度副词，不能修饰“念”这样的动作动词。", "一一": "正确：“一一”表示逐个依次进行，与“把名字……念给大家听”的语境相符。", "逐渐": "搭配：“逐渐”表示变化的过程，不能修饰一次性的朗读动作。", "悄悄": "语义：“悄悄”指不声张，与“念给大家听”的公开性矛盾。"}, "sentence_index": 0, "correct_answer": "一一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们一一去公园，玩得很开心。", "explanation": "这里应该用〈一起〉。“一一”表示逐个依次进行，不表示共同行动，几个人一起去公园不能用“一一”。"}, {"text": "他一一跑了一整夜。", "explanation": "这里应该用〈一直〉。“一一”要求依次逐个进行，句中只有一个人，连续奔跑应用“一直”。"}, {"text": "爸爸一一喜欢这个礼物。", "explanation": "这里应该用〈很〉。“一一”表示逐个依次进行，不能修饰“喜欢”这类心理状态，表示程度应用“很”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95786, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "胡乱", "is_correct": false, "explanation": "语义：“胡乱”表示随意、不认真，与“逐个、有序地拿出来给我们看”的动作相反。"}, {"text": "一一", "is_correct": true, "explanation": "正确：“一一”表示逐个拿出，与“把礼物……拿出来”的语境相符。"}, {"text": "渐渐", "is_correct": false, "explanation": "搭配：“渐渐”表示逐步变化，不能修饰一次性的拿出动作。"}, {"text": "暗暗", "is_correct": false, "explanation": "语义：“暗暗”指背地里、不声张，与“给我们看”的行为矛盾。"}], "explanations": {"胡乱": "语义：“胡乱”表示随意、不认真，与“逐个、有序地拿出来给我们看”的动作相反。", "一一": "正确：“一一”表示逐个拿出，与“把礼物……拿出来”的语境相符。", "渐渐": "搭配：“渐渐”表示逐步变化，不能修饰一次性的拿出动作。", "暗暗": "语义：“暗暗”指背地里、不声张，与“给我们看”的行为矛盾。"}, "sentence_index": 6, "correct_answer": "一一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷一一去世了。", "explanation": "这里应该用〈突然〉。“一一”要求多个对象依次进行，句中只有爷爷一人，去世是一次性的事件，应用“突然”。"}, {"text": "天一一亮了。", "explanation": "这里应该用〈渐渐〉。“一一”表示依次逐个进行，天色由暗变亮是逐步的变化，应用“渐渐”，不能分成一个一个。"}, {"text": "一个人一一来了。", "explanation": "这里应该用〈独自〉。“一一”要求多个对象依次进行，句中只有一个人，单独行动应用“独自”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95786, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把碗一一洗一一干净了。", "corrected_sentence": "妈妈把碗一一洗干净了。", "error_description": "错误：“一一”重复出现，多出的“一一”插在了动词“洗”和补语“干净”之间。正确：“一一”只放在动词“洗”的前面，写作“把碗一一洗干净了”，表示逐个依次洗。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95786, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶把相片一一挂一一在墙上。", "corrected_sentence": "奶奶把相片一一挂在墙上。", "error_description": "错误：“一一”重复出现，多出的“一一”插在了动词“挂”和介词“在”之间。正确：“一一”只放在动词“挂”的前面，写作“把相片一一挂在墙上”，表示逐个挂。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
