INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95787, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "上周是这个星期的前一个星期。", "primary_collocate": null, "pronunciation": "shàng zhōu", "ipa": "ʂɑŋ˥˩ ʈʂoʊ̯˥", "syllable_count": 2, "sentences": [{"text": "这周很忙，上周比较轻松。", "target_word": "上周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上周下了三天雨。", "target_word": "上周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上周把车卖了。", "target_word": "上周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上周的电影很好看，我想再看一次。", "target_word": "上周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上周我和朋友去爬山了。", "target_word": "上周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把上周的照片发给你。", "target_word": "上周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上周孩子们都在学校里考试。", "target_word": "上周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上周我很累，这周好多了。", "target_word": "上周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说上周的考试很难。", "target_word": "上周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上周小王过生日，我们送了礼物。", "target_word": "上周", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上週", "label": "繁体"}], "register": "中性", "sense_fingerprint": "时间名词，指这个星期的前一个星期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a720de0-ac80-4bf6-b407-5b4e7acb898f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95787, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上周", "is_correct": true, "explanation": "上周：指这周的前一周，与“这周很忙”形成对比，符合句意。"}, {"text": "每周", "is_correct": false, "explanation": "语义：“每周”表示反复出现，不能与“这周”形成一次性的时间对比。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：“食堂”不是时间词，不能与“这周”形成时间上的对比。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”不是时间词，不能与“这周”形成时间对比。"}], "explanations": {"上周": "上周：指这周的前一周，与“这周很忙”形成对比，符合句意。", "每周": "语义：“每周”表示反复出现，不能与“这周”形成一次性的时间对比。", "食堂": "语义：“食堂”不是时间词，不能与“这周”形成时间上的对比。", "书包": "语义：“书包”不是时间词，不能与“这周”形成时间对比。"}, "sentence_index": 0, "correct_answer": "上周"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上周我们将搬到北京。", "explanation": "这里应该用〈下周〉。上周已经过去，“将搬到北京”指将来的安排，不能与上周搭配。"}, {"text": "上周我们现在开会。", "explanation": "这里应该用〈这周〉。上周指已经过去的一周，“现在开会”说的是当下，应该用这周。"}, {"text": "上周我们马上就要考试。", "explanation": "这里应该用〈这周〉。上周已经过去，“马上就要考试”说的是眼前的事，应该用这周。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95787, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上周", "is_correct": true, "explanation": "上周：指上一个星期，符合“考试”发生的时间，句意通顺。"}, {"text": "午夜", "is_correct": false, "explanation": "语义：学校不会在午夜组织考试，与“都在学校里考试”不合。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”不是时间词，无法作为考试发生的时间，与句意不合。"}, {"text": "深夜", "is_correct": false, "explanation": "语义：深夜不适合学校集体考试，与句意不合。"}], "explanations": {"上周": "上周：指上一个星期，符合“考试”发生的时间，句意通顺。", "午夜": "语义：学校不会在午夜组织考试，与“都在学校里考试”不合。", "厨房": "语义：“厨房”不是时间词，无法作为考试发生的时间，与句意不合。", "深夜": "语义：深夜不适合学校集体考试，与句意不合。"}, "sentence_index": 6, "correct_answer": "上周"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上周小王过生日，我们将送礼物。", "explanation": "这里应该用〈明天〉。上周已经过去，“将送礼物”指还没发生的事，应该用明天。"}, {"text": "上周我们即将去美国留学。", "explanation": "这里应该用〈将来〉。上周已经过去，“即将去美国留学”指将来的计划，不能与上周搭配。"}, {"text": "上周我们会搬家。", "explanation": "这里应该用〈下个月〉。上周已经过去，“会搬家”表示将来的事，不能与上周搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95787, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他上周的去看了医生。", "corrected_sentence": "他上周去看了医生。", "error_description": "错误：“上周”后面多加了“的”。“上周”是时间词，后面不能加“的”再接动词“去”，正确应为“他上周去看了医生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95787, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们上周的一起吃了晚饭。", "corrected_sentence": "我们上周一起吃了晚饭。", "error_description": "错误：“上周”后面多加了“的”。“上周”是时间词，后面不能加“的”再接状语“一起”，正确应为“我们上周一起吃了晚饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95789, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下线", "is_correct": true, "explanation": "与“上线”相对，指网站或软件停止对外开放，也指退出网络登录。"}, {"text": "下载", "is_correct": false, "explanation": "下载是把网上的文件存到本地，与“上线”不构成反义。"}, {"text": "注册", "is_correct": false, "explanation": "注册是在系统里登记身份，与“上线”不构成反义。"}, {"text": "升级", "is_correct": false, "explanation": "升级是把软件换成新版本，与“上线”不构成反义。"}], "correct_answer": "下线", "explanations": {"下线": "与“上线”相对，指网站或软件停止对外开放，也指退出网络登录。", "下载": "下载是把网上的文件存到本地，与“上线”不构成反义。", "注册": "注册是在系统里登记身份，与“上线”不构成反义。", "升级": "升级是把软件换成新版本，与“上线”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95789, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下线", "is_correct": true, "explanation": "与“上线”相对，指网站或软件停止对外开放，也指退出网络登录。"}, {"text": "打印", "is_correct": false, "explanation": "打印是把文件印在纸上，与“上线”不构成反义。"}, {"text": "翻译", "is_correct": false, "explanation": "翻译是把一种语言转换成另一种语言，与“上线”不构成反义。"}, {"text": "排队", "is_correct": false, "explanation": "排队是按顺序等候，与“上线”不构成反义。"}], "correct_answer": "下线", "explanations": {"下线": "与“上线”相对，指网站或软件停止对外开放，也指退出网络登录。", "打印": "打印是把文件印在纸上，与“上线”不构成反义。", "翻译": "翻译是把一种语言转换成另一种语言，与“上线”不构成反义。", "排队": "排队是按顺序等候，与“上线”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95789, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "上线是让网站或软件开始让大家使用。", "primary_collocate": null, "pronunciation": "shàng xiàn", "ipa": "ʂɑŋ˥˩ ɕiɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这个网站今天上线。", "target_word": "上线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新游戏什么时候上线？", "target_word": "上线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们的手机软件下周上线。", "target_word": "上线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的新网站昨天上线了。", "target_word": "上线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个功能还没上线，请再等几天。", "target_word": "上线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司准备把新产品放到网上，下个月上线。", "target_word": "上线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那家书店的网上商城快要上线了。", "target_word": "上线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "程序员改完错误以后，软件才能上线。", "target_word": "上线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个学习软件上线第一天，就有一万人下载。", "target_word": "上线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的新平台上线后，受到了很多人欢迎。", "target_word": "上线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上线了", "label": "体标"}, {"form": "上线过", "label": "体标"}], "register": "中性", "sense_fingerprint": "网站或软件开始对大家开放使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a78e25c3-ee67-45e4-a792-d0210b249480') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95789, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上线", "is_correct": true, "explanation": "正确答案：网站或软件开始对大家开放使用。"}, {"text": "上仙", "is_correct": false, "explanation": "上仙 shàng xiān（第一声）与 shàng xiàn（第四声）声调不同，意思是神仙。"}, {"text": "上相", "is_correct": false, "explanation": "xiàng 与 xiàn 韵母不同（-iàng 与 -iàn），意思是人拍照好看。"}, {"text": "上弦", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，意思是月亮的上半月。"}], "explanations": {"上线": "正确答案：网站或软件开始对大家开放使用。", "上仙": "上仙 shàng xiān（第一声）与 shàng xiàn（第四声）声调不同，意思是神仙。", "上相": "xiàng 与 xiàn 韵母不同（-iàng 与 -iàn），意思是人拍照好看。", "上弦": "xián（第二声）与 xiàn（第四声）声调不同，意思是月亮的上半月。"}, "sentence_index": null, "correct_answer": "上线"}, "level_3": {"options": [{"text": "上线", "is_correct": true, "explanation": "正确：“这个网站今天上线”指网站今天开始对外开放。"}, {"text": "生病", "is_correct": false, "explanation": "语义：网站不会生病，“这个网站今天生病”说不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：网站不能结婚，这句话说的是网站开通。"}, {"text": "进行", "is_correct": false, "explanation": "配价：“进行”后面要带宾语，如“进行改版”，单独放在句末不完整。"}], "explanations": {"上线": "正确：“这个网站今天上线”指网站今天开始对外开放。", "生病": "语义：网站不会生病，“这个网站今天生病”说不通。", "结婚": "语义：网站不能结婚，这句话说的是网站开通。", "进行": "配价：“进行”后面要带宾语，如“进行改版”，单独放在句末不完整。"}, "sentence_index": 0, "correct_answer": "上线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校昨天上线了。", "explanation": "这里应该用〈开学〉。学校开始上课要说“开学”，“上线”用于网站、软件。"}, {"text": "这座大楼昨天上线了。", "explanation": "这里应该用〈建成〉。大楼盖好要说“建成”，“上线”不用于建筑。"}, {"text": "这个公园昨天上线了。", "explanation": "这里应该用〈开放〉。公园对游客开放要说“开放”，“上线”不用于公园。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95789, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上线", "is_correct": true, "explanation": "正确：“快要上线了”指网上商城即将对外开放。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：商城不能毕业，“快要毕业了”说不通。"}, {"text": "出差", "is_correct": false, "explanation": "语义：商城不会出差，这句话说的是网上商城快要开放。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”要带宾语，如“参加活动”，“快要参加了”句子不完整。"}], "explanations": {"上线": "正确：“快要上线了”指网上商城即将对外开放。", "毕业": "语义：商城不能毕业，“快要毕业了”说不通。", "出差": "语义：商城不会出差，这句话说的是网上商城快要开放。", "参加": "配价：“参加”要带宾语，如“参加活动”，“快要参加了”句子不完整。"}, "sentence_index": 6, "correct_answer": "上线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座体育馆昨天上线了。", "explanation": "这里应该用〈竣工〉。工程完工要说“竣工”，“上线”不用于建筑。"}, {"text": "这座火车站昨天上线了。", "explanation": "这里应该用〈投入使用〉。车站等设施建成后开始使用要说“投入使用”，“上线”只用于网站、软件等。"}, {"text": "比赛昨天上线了。", "explanation": "这里应该用〈开赛〉。比赛开始要说“开赛”，“上线”不用于比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95789, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个功能下周把上线。", "corrected_sentence": "这个功能下周上线。", "error_description": "错误：多用了“把”，“把”后面没有宾语。正确：应为“这个功能下周上线”。主语“这个功能”本身就是上线的对象，不需要“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95789, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个新功能下个月会正式的上线。", "corrected_sentence": "这个新功能下个月会正式上线。", "error_description": "错误：状语“正式”修饰动词“上线”时用了“的”。正确：应为“正式上线”。“的”用于修饰名词，状语后直接接动词，不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
