INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95791, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不简单是说一个人或一件事很厉害，不容易。", "primary_collocate": null, "pronunciation": "bù jiǎn dān", "ipa": "pu˥˩ tɕjɛn˨˩˦ tan˥", "syllable_count": 3, "sentences": [{"text": "他一个人做完了，真不简单。", "target_word": "不简单", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子才五岁就会写字，不简单！", "target_word": "不简单", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能学会三种语言，真不简单。", "target_word": "不简单", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是个不简单的人。", "target_word": "不简单", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说她很不简单，一个人带大了三个孩子。", "target_word": "不简单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小公司能做到这样，很不简单。", "target_word": "不简单", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们从小山村走到大城市，真不简单。", "target_word": "不简单", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有人帮忙，你自己就做好了，不简单。", "target_word": "不简单", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "八十岁的奶奶还在学电脑，真不简单。", "target_word": "不简单", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把这么多事都做好了，实在不简单。", "target_word": "不简单", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不簡單", "label": "繁体"}], "register": "口语", "sense_fingerprint": "夸人做成了不容易的事，很厉害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '277212ec-c05c-4f82-b617-5b3b2e2110c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95791, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不简单", "is_correct": true, "explanation": "“真不简单”是口语中夸人做成了不容易的事，与“一个人做完了”呼应，句意通顺。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“冷”是温度，不能用来评价做事的本领。"}, {"text": "巍峨", "is_correct": false, "explanation": "语域：“巍峨”是书面语，口语中不用来夸人做事。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”是身体的感觉，不能用来评价做完的事情。"}], "explanations": {"不简单": "“真不简单”是口语中夸人做成了不容易的事，与“一个人做完了”呼应，句意通顺。", "冷": "语义：“冷”是温度，不能用来评价做事的本领。", "巍峨": "语域：“巍峨”是书面语，口语中不用来夸人做事。", "饿": "语义：“饿”是身体的感觉，不能用来评价做完的事情。"}, "sentence_index": 0, "correct_answer": "不简单"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的字很不简单，写得歪歪扭扭的。", "explanation": "这里应该用〈潦草〉。不简单用于夸人有本领或事情难做，不用来形容字迹的样子。"}, {"text": "他哭得很不简单，一直停不下来。", "explanation": "这里应该用〈伤心〉。不简单是夸人有本领、事情不容易做到，不用来形容哭个不停的伤心样子。"}, {"text": "那条狗的尾巴很不简单，又细又长。", "explanation": "这里应该用〈长〉。不简单用于夸人有本领或事情难做，不用来形容尾巴的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95791, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不简单", "is_correct": true, "explanation": "“真不简单”夸人从小山村走到大城市很了不起，句意通顺。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容身材，不能用来评价走到大城市这件事。"}, {"text": "红", "is_correct": false, "explanation": "语义：“红”是颜色，不能用来形容走路或奋斗的过程。"}, {"text": "轻", "is_correct": false, "explanation": "语义：“轻”形容重量，与“走到大城市”的语境不合。"}], "explanations": {"不简单": "“真不简单”夸人从小山村走到大城市很了不起，句意通顺。", "瘦": "体貌：“瘦”形容身材，不能用来评价走到大城市这件事。", "红": "语义：“红”是颜色，不能用来形容走路或奋斗的过程。", "轻": "语义：“轻”形容重量，与“走到大城市”的语境不合。"}, "sentence_index": 6, "correct_answer": "不简单"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的头发很不简单，全白了。", "explanation": "这里应该用〈白〉。不简单用于夸人有本领或事情难做，不用来形容头发的颜色。"}, {"text": "妈妈轻轻地抱住我，很不简单。", "explanation": "这里应该用〈温柔〉。不简单评价能力或事情的难度，不用来描述拥抱时的温柔态度。"}, {"text": "她一见陌生人就脸红，很不简单。", "explanation": "这里应该用〈害羞〉。不简单用于夸人，不用来描述性格上的羞涩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95791, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是个不简单医生，救过很多人。", "corrected_sentence": "他是个不简单的医生，救过很多人。", "error_description": "错误：“不简单医生”；正确：“不简单的医生”。形容词“不简单”修饰名词时，后面要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95791, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事他一个人做成了，不简单真。", "corrected_sentence": "这件事他一个人做成了，真不简单。", "error_description": "错误：“不简单真”；正确：“真不简单”。程度副词“真”要放在“不简单”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
