INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95792, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容人很有本领，或事情不容易做到。", "primary_collocate": null, "pronunciation": "bù jiǎn dān", "ipa": "pu˥˩ tɕjɛn˨˩˦ tan˥", "syllable_count": 3, "sentences": [{"text": "要在一年内学会开车，这件事不简单。", "target_word": "不简单", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "写好一篇文章，其实不简单。", "target_word": "不简单", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题看起来容易，做起来不简单。", "target_word": "不简单", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他能当上经理，说明他不简单。", "target_word": "不简单", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在国外一个人生活，真的不简单。", "target_word": "不简单", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事不简单，我们要想好再做。", "target_word": "不简单", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "能把大家带到一起，这个人不简单。", "target_word": "不简单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看上去很普通，其实是个不简单的人。", "target_word": "不简单", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要让孩子听话，真不简单。", "target_word": "不简单", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一个人做三份工作，还要照顾家人，不简单。", "target_word": "不简单", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不簡單", "label": "繁体"}], "register": "口语", "sense_fingerprint": "形容人有本领，或事情难做、不容易办到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '277212ec-c05c-4f82-b617-5b3b2e2110c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95792, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不简单", "is_correct": true, "explanation": "“这件事不简单”说明学会开车并不容易，与“一年内学会”呼应，句意通顺。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”说的是价钱，不说学车这件事“便宜”。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”形容人的年龄，不用来形容一件事的难度。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人或动物的体形，不用来形容事情。"}], "explanations": {"不简单": "“这件事不简单”说明学会开车并不容易，与“一年内学会”呼应，句意通顺。", "便宜": "搭配：“便宜”说的是价钱，不说学车这件事“便宜”。", "年轻": "语义：“年轻”形容人的年龄，不用来形容一件事的难度。", "胖": "体貌：“胖”形容人或动物的体形，不用来形容事情。"}, "sentence_index": 0, "correct_answer": "不简单"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的鞋很不简单，总是太小。", "explanation": "这里应该用〈小〉。不简单用于夸人有本领或事情难做，不用来形容鞋子的大小。"}, {"text": "他对客人特别不简单，连一杯水都不给。", "explanation": "这里应该用〈冷淡〉。不简单用于夸人有本领或事情难做，不用来形容待客的态度。"}, {"text": "这场雨下得很不简单，路上都是水。", "explanation": "这里应该用〈厉害〉。不简单评价人的本领或事情的难度，不用来形容雨势。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95792, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不简单", "is_correct": true, "explanation": "“这个人不简单”是夸人有本领，与“能把大家带到一起”呼应，句意通顺。"}, {"text": "好吃", "is_correct": false, "explanation": "语义：“好吃”形容食物的味道，不用来形容人的能力。"}, {"text": "懒", "is_correct": false, "explanation": "语义：“懒”与“能把大家带到一起”的能力相矛盾，不能用来形容这个人。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容身高，不能用来评价一个人带领大家的能力。"}], "explanations": {"不简单": "“这个人不简单”是夸人有本领，与“能把大家带到一起”呼应，句意通顺。", "好吃": "语义：“好吃”形容食物的味道，不用来形容人的能力。", "懒": "语义：“懒”与“能把大家带到一起”的能力相矛盾，不能用来形容这个人。", "矮": "体貌：“矮”形容身高，不能用来评价一个人带领大家的能力。"}, "sentence_index": 6, "correct_answer": "不简单"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对未来很不简单，总觉得没有希望。", "explanation": "这里应该用〈悲观〉。不简单夸人有本领，不用来形容对未来的态度。"}, {"text": "考试前他很不简单，一直坐立不安。", "explanation": "这里应该用〈紧张〉。不简单是夸人的话，不用来描述考前的心神不定。"}, {"text": "他对人很不简单，从不关心别人。", "explanation": "这里应该用〈冷漠〉。不简单是褒义的夸奖，与“从不关心别人”的态度正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她能同时管理三家公司，是个不简单人。", "corrected_sentence": "她能同时管理三家公司，是个不简单的人。", "error_description": "错误：“是个不简单人”；正确：“是个不简单的人”。形容词“不简单”作定语，后面要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她能把这么大的活动组织好，不简单很。", "corrected_sentence": "她能把这么大的活动组织好，很不简单。", "error_description": "错误：“不简单很”；正确：“很不简单”。程度副词“很”要放在“不简单”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
