INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95793, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中水是用过的水处理干净后再用的水。这种水不能喝，可以冲厕所。", "primary_collocate": null, "pronunciation": "zhōng shuǐ", "ipa": "tʂʊŋ˥ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "中水是处理过的水。", "target_word": "中水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的厕所用中水。", "target_word": "中水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是中水，请不要喝。", "target_word": "中水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校用中水给树浇水。", "target_word": "中水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用过的水变成中水，可以再用。", "target_word": "中水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中水看起来很干净，但是不能喝。", "target_word": "中水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用中水洗地。", "target_word": "中水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼里有一个中水的水箱。", "target_word": "中水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用中水，可以省很多自来水。", "target_word": "中水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋楼的地下室把生活污水变成中水。", "target_word": "中水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中水系统", "label": "复合"}, {"form": "中水回用", "label": "复合"}], "register": "中性", "sense_fingerprint": "用过的水处理干净后再用的水，不能喝，可冲厕所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '849abdb4-e94e-41e7-b194-cd99807ededa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95793, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "墨水", "is_correct": false, "explanation": "搭配：“处理过的水”指的是水类，不说墨水是处理过的水。"}, {"text": "中水", "is_correct": true, "explanation": "正确：中水就是用过的水处理干净后再用的水，句意完全吻合。"}, {"text": "果汁", "is_correct": false, "explanation": "语义：果汁是饮品，不是经过处理的废水，不能这样定义。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油不是水，更谈不上是处理过的水。"}], "explanations": {"墨水": "搭配：“处理过的水”指的是水类，不说墨水是处理过的水。", "中水": "正确：中水就是用过的水处理干净后再用的水，句意完全吻合。", "果汁": "语义：果汁是饮品，不是经过处理的废水，不能这样定义。", "汽油": "语义：汽油不是水，更谈不上是处理过的水。"}, "sentence_index": 0, "correct_answer": "中水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子渴了，我给他倒了一杯中水。", "explanation": "这里应该用〈矿泉水〉。中水不能喝，不能用来给人解渴。"}, {"text": "早上我用中水刷牙。", "explanation": "这里应该用〈自来水〉。中水不能进嘴，不能用来刷牙。"}, {"text": "妈妈每天用中水做饭。", "explanation": "这里应该用〈自来水〉。中水不能食用，不能用来做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95793, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶是乳制品，不能用来洗地，句意不通。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是给人喝的，不能用来洗地。"}, {"text": "中水", "is_correct": true, "explanation": "正确：中水是处理过的水，可以用来洗地。"}, {"text": "啤酒", "is_correct": false, "explanation": "搭配：洗地用的是水或清洁剂，不说“用啤酒洗地”。"}], "explanations": {"牛奶": "语义：牛奶是乳制品，不能用来洗地，句意不通。", "饮料": "语义：饮料是给人喝的，不能用来洗地。", "中水": "正确：中水是处理过的水，可以用来洗地。", "啤酒": "搭配：洗地用的是水或清洁剂，不说“用啤酒洗地”。"}, "sentence_index": 6, "correct_answer": "中水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "宝宝洗澡要先用中水试一试。", "explanation": "这里应该用〈温水〉。中水不能用于给宝宝洗澡等直接接触身体的用途。"}, {"text": "这种检测必须用中水做。", "explanation": "这里应该用〈蒸馏水〉。中水含有杂质，不能代替蒸馏水做检测。"}, {"text": "这瓶中水专门用来杀菌。", "explanation": "这里应该用〈消毒液〉。中水没有杀菌作用，不能用来杀菌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95793, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座水厂每天要运出一个中水。", "corrected_sentence": "这座水厂每天要运出一车中水。", "error_description": "“中水”是液体，计量时应用“车”“桶”“罐”等量词。说“一个中水”是量词用错，应为“一车中水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95793, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "楼顶的水箱里装着一个中水。", "corrected_sentence": "楼顶的水箱里装着一桶中水。", "error_description": "“中水”是液体，计量时应用“桶”“车”“罐”等量词。说“一个中水”是量词用错，应为“一桶中水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
