INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95796, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "彼此谈话。", "primary_collocate": null, "pronunciation": "jiāo tán", "ipa": "tɕjɑʊ̯˥ tʰan˧˥", "syllable_count": 2, "sentences": [{"text": "会议开始前，大家互相交谈。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩交谈得很开心。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生耐心地和病人交谈。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在电话里交谈了一个小时。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者与市长交谈了二十分钟。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚饭后，一家人坐在一起交谈。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很害羞，不敢和陌生人交谈。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国代表友好地交谈着。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用汉语交谈，没有问题。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们交谈过几次，彼此很了解。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交谈了", "label": "体标"}, {"form": "交谈过", "label": "体标"}, {"form": "交谈着", "label": "体标"}, {"form": "交談", "label": "繁体"}], "register": "中性", "sense_fingerprint": "彼此谈话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9cbe6ac-6e27-417b-92b2-2981f60beb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95796, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交谈", "is_correct": true, "explanation": "正确。交谈表示彼此说话，与“互相”相符。"}, {"text": "独处", "is_correct": false, "explanation": "语义：独处是一个人待着，与“互相”的双方关系矛盾。"}, {"text": "隔离", "is_correct": false, "explanation": "语义：隔离是使人分开，与“互相”的交流意味相反。"}, {"text": "散开", "is_correct": false, "explanation": "搭配：“散开”指各自离去、分散，不能与“互相”搭配。"}], "explanations": {"交谈": "正确。交谈表示彼此说话，与“互相”相符。", "独处": "语义：独处是一个人待着，与“互相”的双方关系矛盾。", "隔离": "语义：隔离是使人分开，与“互相”的交流意味相反。", "散开": "搭配：“散开”指各自离去、分散，不能与“互相”搭配。"}, "sentence_index": 0, "correct_answer": "交谈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "校长在大会上交谈了一个小时。", "explanation": "这里应该用〈讲话〉。讲话是一方对听众说，交谈要求彼此都说话。"}, {"text": "他一个人对着镜子交谈了半天。", "explanation": "这里不能用〈交谈〉。交谈需要彼此对话，一个人对着镜子不能算交谈。"}, {"text": "两个人为这件事交谈了很久，却一句话也没说。", "explanation": "这里不能用〈交谈〉。交谈要求彼此都开口，谁也没说话就不是交谈，应说“沉默”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95796, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交谈", "is_correct": true, "explanation": "正确。交谈指和陌生人说话，符合“不敢”的语境。"}, {"text": "投诉", "is_correct": false, "explanation": "配价：“投诉”需要带对象（投诉谁或什么），句中没有，且“和陌生人投诉”不成立。"}, {"text": "大笑", "is_correct": false, "explanation": "语义：大笑是放声地笑，与“害羞”矛盾。"}, {"text": "孤独", "is_correct": false, "explanation": "语法：“孤独”是形容词，不能用在“和陌生人……”中作谓语动词。"}], "explanations": {"交谈": "正确。交谈指和陌生人说话，符合“不敢”的语境。", "投诉": "配价：“投诉”需要带对象（投诉谁或什么），句中没有，且“和陌生人投诉”不成立。", "大笑": "语义：大笑是放声地笑，与“害羞”矛盾。", "孤独": "语法：“孤独”是形容词，不能用在“和陌生人……”中作谓语动词。"}, "sentence_index": 6, "correct_answer": "交谈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这封信他交谈了很久。", "explanation": "这里应该用〈读〉。交谈是不及物动词，不能带“信”这样的宾语，应说“读信”。"}, {"text": "他们俩交谈了那扇门，结果门坏了。", "explanation": "这里应该用〈踢〉。交谈是不及物动词，不能带“门”作宾语，应说“踢门”。"}, {"text": "这只狗交谈了那根骨头，然后就走了。", "explanation": "这里应该用〈啃〉。交谈是不及物动词，不能带“骨头”作宾语，应说“啃骨头”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95796, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们俩在公园里和交谈得很开心。", "corrected_sentence": "他们俩在公园里交谈得很开心。", "error_description": "错误：介词“和”后面必须接名词性对象，不能直接接动词“交谈”。删去多余的“和”，即为“他们俩在公园里交谈得很开心。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95796, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在饭店里被交谈了很久。", "corrected_sentence": "他们在饭店里交谈了很久。", "error_description": "“被”字句不能用于不及物动词“交谈”，应为“他们在饭店里交谈了很久”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
