INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95797, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "企业集团是很多公司联合在一起的大团体。", "primary_collocate": null, "pronunciation": "qǐ yè jí tuán", "ipa": "tɕʰi˨˩ je˥˩ tɕi˧˥ tʰwan˧˥", "syllable_count": 4, "sentences": [{"text": "这个企业集团有二十家公司。", "target_word": "企业集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家大型企业集团工作。", "target_word": "企业集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个企业集团在很多城市都有工厂。", "target_word": "企业集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几家公司合起来，成了一个企业集团。", "target_word": "企业集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个企业集团今年赚了不少钱。", "target_word": "企业集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家企业集团的老板很有名。", "target_word": "企业集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企业集团里的公司互相帮助。", "target_word": "企业集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥想进那个大企业集团。", "target_word": "企业集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个企业集团已经有五十年的历史了。", "target_word": "企业集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家企业集团做汽车，也做电脑。", "target_word": "企业集团", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "大型企业集团", "label": "复合"}, {"form": "企業集團", "label": "繁体"}], "register": "正式", "sense_fingerprint": "很多公司联合在一起的大团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0aa27f-22fc-4bb2-b50a-1b53150bdc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95797, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "企业集团", "is_correct": true, "explanation": "正确：“这个……有二十家公司”指多家公司联合起来的大团体。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是教育机构，不会拥有二十家公司。"}, {"text": "班级", "is_correct": false, "explanation": "语义：班级是学生集体，与“有二十家公司”的说法不符。"}, {"text": "医院", "is_correct": false, "explanation": "搭配：“医院”一般不与“有……家公司”这种拥有关系搭配。"}], "explanations": {"企业集团": "正确：“这个……有二十家公司”指多家公司联合起来的大团体。", "学校": "语义：学校是教育机构，不会拥有二十家公司。", "班级": "语义：班级是学生集体，与“有二十家公司”的说法不符。", "医院": "搭配：“医院”一般不与“有……家公司”这种拥有关系搭配。"}, "sentence_index": 0, "correct_answer": "企业集团"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我开了一家企业集团，只有我一个员工。", "explanation": "这里应该用〈公司〉。企业集团指多家公司联合组成的大团体，只有一家公司或一个人时要说〈公司〉。"}, {"text": "那只企业集团在上海有三个工厂。", "explanation": "这里不能用〈只〉作量词。“只”多用于动物，企业集团应该用“个”或“家”。"}, {"text": "我和同事组成了一个企业集团，一起去爬山。", "explanation": "这里应该用〈团体〉。企业集团是多家公司联合的组织，不能指由人组成的团体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95797, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "企业集团", "is_correct": true, "explanation": "正确：“……里的公司互相帮助”指同一个集团内部的公司。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园不是经营单位，里面没有可以互相帮助的公司。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆不设公司，“公司互相帮助”说不通。"}, {"text": "博物馆", "is_correct": false, "explanation": "搭配：“博物馆里的公司”不是常见说法，与“互相帮助”的经营含义不搭。"}], "explanations": {"企业集团": "正确：“……里的公司互相帮助”指同一个集团内部的公司。", "公园": "语义：公园不是经营单位，里面没有可以互相帮助的公司。", "图书馆": "语义：图书馆不设公司，“公司互相帮助”说不通。", "博物馆": "搭配：“博物馆里的公司”不是常见说法，与“互相帮助”的经营含义不搭。"}, "sentence_index": 6, "correct_answer": "企业集团"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个国家建立了企业集团。", "explanation": "这里应该用〈联盟〉。企业集团是企业联合组成的经济组织，国家之间结成的合作要说〈联盟〉。"}, {"text": "这家企业集团每天接待很多病人，急诊室很忙。", "explanation": "这里应该用〈医院〉。企业集团是经济组织，不接待病人，也没有急诊室，要说〈医院〉。"}, {"text": "这个企业集团有五千名士兵。", "explanation": "这里应该用〈军队〉。企业集团是经济组织，不能指有士兵的武装力量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95797, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只企业集团在很多国家都有分公司。", "corrected_sentence": "这家企业集团在很多国家都有分公司。", "error_description": "量词错误：“只”用于动物，“企业集团”应用“家”或“个”，正确应为“这家企业集团”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95797, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我表哥在一位企业集团做销售。", "corrected_sentence": "我表哥在一家企业集团做销售。", "error_description": "量词错误：“位”用于人，“企业集团”是组织，应用“家”，正确应为“一家企业集团”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
