INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95798, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以一个大企业为核心，联合若干企业组成的经济组织。", "primary_collocate": null, "pronunciation": "qǐ yè jí tuán", "ipa": "tɕʰi˨˩ je˥˩ tɕi˧˥ tʰwan˧˥", "syllable_count": 4, "sentences": [{"text": "这个企业集团以一家大公司为中心。", "target_word": "企业集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "该企业集团由十家公司组成。", "target_word": "企业集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个企业集团的总公司在上海。", "target_word": "企业集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家支持大型企业集团发展。", "target_word": "企业集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个企业集团里有银行和工厂。", "target_word": "企业集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想建一个新的企业集团。", "target_word": "企业集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家企业集团的核心公司很大。", "target_word": "企业集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个企业集团每年都会开大会。", "target_word": "企业集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，这个企业集团要上市。", "target_word": "企业集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个企业集团管理着很多子公司。", "target_word": "企业集团", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "大型企业集团", "label": "复合"}, {"form": "企業集團", "label": "繁体"}], "register": "正式", "sense_fingerprint": "以大企业为核心组成的经济组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0aa27f-22fc-4bb2-b50a-1b53150bdc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95798, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "企业集团", "is_correct": true, "explanation": "正确：“以一家大公司为中心”描述的是由多家企业组成的经济组织。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校不以公司为中心组成经济组织，句子说不通。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是医疗机构，不是以大公司为核心的经济组织，句子说不通。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是经济组织，不能“以一家大公司为中心”。"}], "explanations": {"企业集团": "正确：“以一家大公司为中心”描述的是由多家企业组成的经济组织。", "学校": "语义：学校不以公司为中心组成经济组织，句子说不通。", "医院": "语义：医院是医疗机构，不是以大公司为核心的经济组织，句子说不通。", "花园": "语义：花园不是经济组织，不能“以一家大公司为中心”。"}, "sentence_index": 0, "correct_answer": "企业集团"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是企业集团，一个人经营一家小店。", "explanation": "这里应该用〈个体户〉。企业集团要由多家公司联合组成，一个人经营的小店不能称为企业集团。"}, {"text": "这条企业集团有很多分公司。", "explanation": "这里不能用〈条〉作量词。“条”多用于河流、路等细长的东西，企业集团应该用“个”或“家”。"}, {"text": "我们这个企业集团有五口人，都住在一起。", "explanation": "这里应该用〈家庭〉。企业集团是多家公司的联合，不能说几口人住在一起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "企业集团", "is_correct": true, "explanation": "正确：“那家……的核心公司很大”指由多家公司组成的集团。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：幼儿园是教育机构，没有“核心公司”。"}, {"text": "剧院", "is_correct": false, "explanation": "语义：剧院不设核心公司，句子说不通。"}, {"text": "体育馆", "is_correct": false, "explanation": "搭配：“体育馆”不与“核心公司”搭配，场馆不说有核心公司。"}], "explanations": {"企业集团": "正确：“那家……的核心公司很大”指由多家公司组成的集团。", "幼儿园": "语义：幼儿园是教育机构，没有“核心公司”。", "剧院": "语义：剧院不设核心公司，句子说不通。", "体育馆": "搭配：“体育馆”不与“核心公司”搭配，场馆不说有核心公司。"}, "sentence_index": 6, "correct_answer": "企业集团"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家企业集团有八个年级，每个年级都有很多班。", "explanation": "这里应该用〈学校〉。企业集团是企业联合组成的经济组织，没有年级和班级，不能指学校。"}, {"text": "这家企业集团藏书三十万册，每天有很多读者借书。", "explanation": "这里应该用〈图书馆〉。企业集团不藏书，也不对读者开放借阅，这类场所要说〈图书馆〉。"}, {"text": "这个企业集团有一百多种动物，每天都有很多游客。", "explanation": "这里应该用〈动物园〉。企业集团是经济组织，不养动物，也不接待游客，要说〈动物园〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那座企业集团去年收购了三家公司。", "corrected_sentence": "那家企业集团去年收购了三家公司。", "error_description": "量词错误：“座”多用于山、楼等大型固定的东西，“企业集团”应用“家”，正确应为“那家企业集团”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹去了一位企业集团实习。", "corrected_sentence": "我妹妹去了一家企业集团实习。", "error_description": "量词错误：“位”用于人，“企业集团”应用“家”，正确应为“一家企业集团”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95801, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "困难", "is_correct": true, "explanation": "正确答案。“便利”与“困难”相反：便利指做事方便、不费力，困难指做事不容易。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外貌好看，与“便利”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容人的智力，与“便利”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”与“吵闹”相对，与“便利”没有反义关系。"}], "correct_answer": "困难", "explanations": {"困难": "正确答案。“便利”与“困难”相反：便利指做事方便、不费力，困难指做事不容易。", "漂亮": "“漂亮”形容外貌好看，与“便利”没有反义关系。", "聪明": "“聪明”形容人的智力，与“便利”没有反义关系。", "安静": "“安静”与“吵闹”相对，与“便利”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95801, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "困难", "is_correct": true, "explanation": "正确答案。“便利”与“困难”相反：便利指做事方便、不费力，困难指做事不容易。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线或颜色，与“便利”没有反义关系。"}, {"text": "高大", "is_correct": false, "explanation": "“高大”形容身材或体积，与“便利”没有反义关系。"}, {"text": "勇敢", "is_correct": false, "explanation": "“勇敢”形容人的胆量，与“便利”没有反义关系。"}], "correct_answer": "困难", "explanations": {"困难": "正确答案。“便利”与“困难”相反：便利指做事方便、不费力，困难指做事不容易。", "明亮": "“明亮”形容光线或颜色，与“便利”没有反义关系。", "高大": "“高大”形容身材或体积，与“便利”没有反义关系。", "勇敢": "“勇敢”形容人的胆量，与“便利”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95801, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "便利是做事很方便，不费力。", "primary_collocate": null, "pronunciation": "biàn lì", "ipa": "pʰjɛn˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "这里的交通很便利。", "target_word": "便利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上买东西非常便利。", "target_word": "便利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在地铁站旁边，上班很便利。", "target_word": "便利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机让我们的生活更便利。", "target_word": "便利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行离我家很近，去办事很便利。", "target_word": "便利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的机器用起来很便利。", "target_word": "便利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家附近买菜很便利。", "target_word": "便利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络让学习变得便利了。", "target_word": "便利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼下就有药店，买药很便利。", "target_word": "便利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了车，去山上便利多了。", "target_word": "便利", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "便利店", "label": "复合"}, {"form": "便利贴", "label": "复合"}], "register": "中性", "sense_fingerprint": "做事方便、不费力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97fe4c13-4834-4860-bdf7-8fe0ba852eb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95801, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "便利", "is_correct": true, "explanation": "正确答案。便利指做事很方便、不费力。"}, {"text": "电力", "is_correct": false, "explanation": "diàn（第四声）与 biàn（第四声）声母不同（d 与 b），意思是电力。"}, {"text": "建立", "is_correct": false, "explanation": "jiàn（第四声）与 biàn（第四声）声母不同（j 与 b），意思是建立。"}, {"text": "便秘", "is_correct": false, "explanation": "mì（第四声）与 lì（第四声）声母不同（m 与 l），意思是便秘。"}], "explanations": {"便利": "正确答案。便利指做事很方便、不费力。", "电力": "diàn（第四声）与 biàn（第四声）声母不同（d 与 b），意思是电力。", "建立": "jiàn（第四声）与 biàn（第四声）声母不同（j 与 b），意思是建立。", "便秘": "mì（第四声）与 lì（第四声）声母不同（m 与 l），意思是便秘。"}, "sentence_index": null, "correct_answer": "便利"}, "level_3": {"options": [{"text": "便利", "is_correct": true, "explanation": "正确答案。“这里的交通很便利”说明交通方便，与“很”搭配。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，不能用来形容交通。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”形容人的态度，交通不会热情，句子说不通。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物体的外形，不能说“交通很高大”。"}], "explanations": {"便利": "正确答案。“这里的交通很便利”说明交通方便，与“很”搭配。", "聪明": "语义：“聪明”形容人的智力，不能用来形容交通。", "热情": "语义：“热情”形容人的态度，交通不会热情，句子说不通。", "高大": "体貌：“高大”形容人或物体的外形，不能说“交通很高大”。"}, "sentence_index": 0, "correct_answer": "便利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服很便利，只要十块钱。", "explanation": "这里应该用〈便宜〉。便利说做事方便、不费力，说价格低要用“便宜”。"}, {"text": "今天的考试很便利。", "explanation": "这里应该用〈顺利〉。便利指办事方便、省力，说事情进展顺利要用“顺利”。"}, {"text": "他很便利，随时都能帮我。", "explanation": "这里应该用〈方便〉。便利用于事物或办事的条件，不用来形容人有空、可以找。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95801, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "便利", "is_correct": true, "explanation": "正确答案。“他家附近”买菜方便，“很便利”说明买菜方便。"}, {"text": "遥远", "is_correct": false, "explanation": "语义：“他家附近”说明距离近，“遥远”与“附近”矛盾。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”形容人的说话风格，买菜不能幽默，句子说不通。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容人或物体的外形，不能说“买菜很矮小”。"}], "explanations": {"便利": "正确答案。“他家附近”买菜方便，“很便利”说明买菜方便。", "遥远": "语义：“他家附近”说明距离近，“遥远”与“附近”矛盾。", "幽默": "语义：“幽默”形容人的说话风格，买菜不能幽默，句子说不通。", "矮小": "体貌：“矮小”形容人或物体的外形，不能说“买菜很矮小”。"}, "sentence_index": 6, "correct_answer": "便利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的汉语很便利，说得又快又好。", "explanation": "这里应该用〈流利〉。便利形容做事方便，说外语熟练要用“流利”。"}, {"text": "面试前我很便利。", "explanation": "这里应该用〈紧张〉。便利形容事情方便，不能用来形容人的心理状态。"}, {"text": "这场比赛很便利，选手们都很兴奋。", "explanation": "这里应该用〈精彩〉。便利说做事方便，比赛的好坏不用“便利”来评价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95801, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "网上可以便利的查到资料。", "corrected_sentence": "网上可以便利地查到资料。", "error_description": "的地误用：“便利”修饰动词“查到”时要用“地”，不用“的”。正确的说法是“便利地查到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95801, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "有了地铁，上班便利的多了。", "corrected_sentence": "有了地铁，上班便利得多了。", "error_description": "程度补语误用：“便利”后表示程度的补语要用“得”，不用“的”。正确的说法是“便利得多了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
