INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95803, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "保护国是一个很小的国家，要靠别的大国来保护。", "primary_collocate": null, "pronunciation": "bǎo hù guó", "ipa": "pau̯˨˩ xu˥˩ kuo˧˥", "syllable_count": 3, "sentences": [{"text": "这个小国很弱，是大国的保护国。", "target_word": "保护国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护国自己的力量不够，要靠大国。", "target_word": "保护国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的国家是一个保护国，没有军队。", "target_word": "保护国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护国需要大国帮忙守住边界。", "target_word": "保护国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个保护国很小，只有几万人。", "target_word": "保护国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，小岛国曾经是一个保护国。", "target_word": "保护国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护国的安全要靠大国来保障。", "target_word": "保护国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为太小，这个国家变成了保护国。", "target_word": "保护国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大国答应保护它，它就成了保护国。", "target_word": "保护国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上那个保护国比一个城市还小。", "target_word": "保护国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "保護國", "label": "繁体"}], "register": "书面", "sense_fingerprint": "弱小、要靠大国保护的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc14243-eedd-4dfd-9576-020da2c00dc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95803, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保护国", "is_correct": true, "explanation": "正确：保护国指弱小、要靠大国保护的国家，符合“很弱”的语境。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“学生”指求学的人，不能说小国是大国的学生。"}, {"text": "饭馆", "is_correct": false, "explanation": "语义：“饭馆”是餐饮场所，与国家的强弱关系无关，不能填入此处。"}, {"text": "哥们", "is_correct": false, "explanation": "语域：“哥们”是口语，与本句语体不合，也不能说明小国与大国的关系。"}], "explanations": {"保护国": "正确：保护国指弱小、要靠大国保护的国家，符合“很弱”的语境。", "学生": "语义：“学生”指求学的人，不能说小国是大国的学生。", "饭馆": "语义：“饭馆”是餐饮场所，与国家的强弱关系无关，不能填入此处。", "哥们": "语域：“哥们”是口语，与本句语体不合，也不能说明小国与大国的关系。"}, "sentence_index": 0, "correct_answer": "保护国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家很强大，是世界上的保护国。", "explanation": "这里应该用〈强国〉。保护国指弱小、要靠大国保护的国家，与“很强大”相矛盾。"}, {"text": "这个保护国很强大，还保护着周围的小国。", "explanation": "这里应该用〈强国〉。保护国自己弱小、要靠大国保护，不能反过来保护别的国家；强大、能保护别国的国家应说〈强国〉。"}, {"text": "二战时，英国和美国是保护国，共同对抗德国。", "explanation": "这里应该用〈盟国〉。保护国弱小、要靠大国保护；两个大国平等结盟、共同对抗敌人的应说〈盟国〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95803, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保护国", "is_correct": true, "explanation": "正确：保护国指需要大国保障安全的弱小国家，符合句意。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是个人通讯工具，句子说的是国家的安全，不能指它。"}, {"text": "水杯", "is_correct": false, "explanation": "搭配：保障的对象应是国家、人民或生命，不说保障水杯的安全。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是学习用的书，与大国保障安全的对象无关。"}], "explanations": {"保护国": "正确：保护国指需要大国保障安全的弱小国家，符合句意。", "手机": "语义：“手机”是个人通讯工具，句子说的是国家的安全，不能指它。", "水杯": "搭配：保障的对象应是国家、人民或生命，不说保障水杯的安全。", "课本": "语义：“课本”是学习用的书，与大国保障安全的对象无关。"}, "sentence_index": 6, "correct_answer": "保护国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "保护国统治着这个国家。", "explanation": "这里应该用〈国王〉。保护国是被保护的国家，不能统治别的国家；统治者应说〈国王〉。"}, {"text": "这个保护国是一个很大的港口。", "explanation": "这里应该用〈海港〉。保护国指一个弱小、要靠大国保护的国家，不是港口；这里说的是港口，应说〈海港〉。"}, {"text": "他是一名保护国。", "explanation": "这里应该用〈保镖〉。保护国指国家，不能用来指人；保护别人的人应说〈保镖〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95803, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个弱小的国家是大国的一座保护国。", "corrected_sentence": "那个弱小的国家是大国的一个保护国。", "error_description": "量词错误：“保护国”是国家，应说“一个保护国”，不能用“一座”（“座”多用于山、桥、建筑等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95803, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个岛国就成了大国的保护国们。", "corrected_sentence": "那个岛国就成了大国的保护国。", "error_description": "后缀错误：“们”只用于指人的名词，国家不能加“们”，应说“保护国”，不能说“保护国们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
