INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95804, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在国际关系中，受另一国保护而主权不完整的国家。", "primary_collocate": null, "pronunciation": "bǎo hù guó", "ipa": "pau̯˨˩ xu˥˩ kuo˧˥", "syllable_count": 3, "sentences": [{"text": "这个小国在那时成了邻国的保护国。", "target_word": "保护国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护国的外交由大国来管。", "target_word": "保护国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十九世纪，这个岛国是英国的保护国。", "target_word": "保护国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成为保护国以后，它不能自己决定外交。", "target_word": "保护国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护国没有完整的主权。", "target_word": "保护国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家曾经是法国的保护国。", "target_word": "保护国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书上说，这里以前是一个保护国。", "target_word": "保护国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大国常常把弱小的邻国变成保护国。", "target_word": "保护国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护国的人民希望早日独立。", "target_word": "保护国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲了保护国和殖民地有什么不同。", "target_word": "保护国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "保護國", "label": "繁体"}], "register": "书面", "sense_fingerprint": "国际关系中主权不完整、受别国保护的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc14243-eedd-4dfd-9576-020da2c00dc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95804, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保护国", "is_correct": true, "explanation": "正确：保护国指主权不完整、受别国保护的国家，符合“成了邻国的”这一语境。"}, {"text": "大学", "is_correct": false, "explanation": "语义：“大学”是教育机构，小国不能成为邻国的大学。"}, {"text": "饭馆", "is_correct": false, "explanation": "语义：“饭馆”是经营餐饮的场所，与国家的主权关系无关。"}, {"text": "教室", "is_correct": false, "explanation": "语义：“教室”是上课的地方，不能指国家，“成了邻国的教室”说不通。"}], "explanations": {"保护国": "正确：保护国指主权不完整、受别国保护的国家，符合“成了邻国的”这一语境。", "大学": "语义：“大学”是教育机构，小国不能成为邻国的大学。", "饭馆": "语义：“饭馆”是经营餐饮的场所，与国家的主权关系无关。", "教室": "语义：“教室”是上课的地方，不能指国家，“成了邻国的教室”说不通。"}, "sentence_index": 0, "correct_answer": "保护国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个国家是我们的保护国，两国一直平等合作。", "explanation": "这里应该用〈盟国〉。保护国指主权不完整、受别国保护的国家；与我们平等合作的伙伴应说〈盟国〉。"}, {"text": "战争结束后，这个国家成了保护国，开始自己管理内政外交。", "explanation": "这里应该用〈独立国家〉。保护国的外交要由保护它的大国决定，不能自己管理外交；战后获得完全主权、自己管理内政外交的国家应说〈独立国家〉。"}, {"text": "英国直接派总督统治这个岛屿，当地人没有任何自治权，它是英国的保护国。", "explanation": "这里应该用〈殖民地〉。保护国保留当地的统治者和政府，主权不完整；由宗主国直接派总督统治、当地没有自治权的应说〈殖民地〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95804, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保护国", "is_correct": true, "explanation": "正确：保护国指受别国保护的国家，“这里以前是一个……”可以指曾经的保护国。"}, {"text": "国王", "is_correct": false, "explanation": "语义：“国王”指人，不能用来说明这里曾经是什么地方。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”指人，与“这里”不能同指。"}, {"text": "庄稼", "is_correct": false, "explanation": "搭配：“庄稼”是不可数名词，不能与量词“个”搭配。"}], "explanations": {"保护国": "正确：保护国指受别国保护的国家，“这里以前是一个……”可以指曾经的保护国。", "国王": "语义：“国王”指人，不能用来说明这里曾经是什么地方。", "老师": "语义：“老师”指人，与“这里”不能同指。", "庄稼": "搭配：“庄稼”是不可数名词，不能与量词“个”搭配。"}, "sentence_index": 6, "correct_answer": "保护国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的邻居是一个保护国，每天都来串门。", "explanation": "这里应该用〈街坊〉。保护国指受别国保护、主权不完整的国家，不能用来指住在附近、常来串门的人；这类人应说〈街坊〉。"}, {"text": "英国保护国统治了这里。", "explanation": "这里应该用〈殖民者〉。保护国是被保护的国家，不能统治别的地方；统治者应说〈殖民者〉。"}, {"text": "保护国是一个国际组织，总部在纽约。", "explanation": "这里应该用〈联合国〉。保护国指受别国保护、主权不完整的国家，不是国际机构；总部设在纽约的国际机构应说〈联合国〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95804, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个小国在一百年前成了英国的一只保护国。", "corrected_sentence": "那个小国在一百年前成了英国的一个保护国。", "error_description": "量词错误：“保护国”是国家，应说“一个保护国”，不能用“一只”（“只”多用于动物或成对的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95804, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个岛国后来成了法国的保护国们。", "corrected_sentence": "那个岛国后来成了法国的保护国。", "error_description": "后缀错误：“们”只用于指人的名词，国家不能加“们”，应说“保护国”，不能说“保护国们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95805, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正", "is_correct": true, "explanation": "“正”与“偏”是反义词，偏指不在中间，正指位于正中，二者在“不在正中间”这一义项上相对。"}, {"text": "厚", "is_correct": false, "explanation": "“厚”与“偏”没有反义关系，“厚”说物体的厚薄，与位置无关。"}, {"text": "深", "is_correct": false, "explanation": "“深”与“偏”没有反义关系，“深”说距离或颜色，与位置无关。"}, {"text": "快", "is_correct": false, "explanation": "“快”与“偏”没有反义关系，“快”说速度，与位置无关。"}], "correct_answer": "正", "explanations": {"正": "“正”与“偏”是反义词，偏指不在中间，正指位于正中，二者在“不在正中间”这一义项上相对。", "厚": "“厚”与“偏”没有反义关系，“厚”说物体的厚薄，与位置无关。", "深": "“深”与“偏”没有反义关系，“深”说距离或颜色，与位置无关。", "快": "“快”与“偏”没有反义关系，“快”说速度，与位置无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95805, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正", "is_correct": true, "explanation": "“正”与“偏”是反义词，偏指不在中间，正指位于正中，二者在“不在正中间”这一义项上相对。"}, {"text": "重", "is_correct": false, "explanation": "“重”与“偏”没有反义关系，“重”说分量，与位置无关。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”与“偏”没有反义关系，“慢”说速度，与位置无关。"}, {"text": "高", "is_correct": false, "explanation": "“高”与“偏”没有反义关系，“高”说高度，与是否居中无关。"}], "correct_answer": "正", "explanations": {"正": "“正”与“偏”是反义词，偏指不在中间，正指位于正中，二者在“不在正中间”这一义项上相对。", "重": "“重”与“偏”没有反义关系，“重”说分量，与位置无关。", "慢": "“慢”与“偏”没有反义关系，“慢”说速度，与位置无关。", "高": "“高”与“偏”没有反义关系，“高”说高度，与是否居中无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95805, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "偏是不在中间，歪向一边。", "primary_collocate": null, "pronunciation": "piān", "ipa": "pʰiɛn˥", "syllable_count": 1, "sentences": [{"text": "桌子上的花瓶放偏了。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的头有点偏。", "target_word": "偏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那张地图贴得太偏了。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个字写得偏了，不在格子中间。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "椅子摆偏了，不在桌子正前面。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把杯子放偏了，水洒了一桌子。", "target_word": "偏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯挂得太偏，屋子中间很暗。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把相机对准我，别拍偏了。", "target_word": "偏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球门在中间，这个球射得太偏了。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把名字写偏了，一半写到了纸外面。", "target_word": "偏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "偏了", "label": "体标"}], "register": "中性", "sense_fingerprint": "不在中间，歪向一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a78e25c3-ee67-45e4-a792-d0210b249480') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95805, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "偏", "is_correct": true, "explanation": "偏（piān）意思是不在中间、歪向一边，是正确答案。"}, {"text": "片", "is_correct": false, "explanation": "片（piàn）与偏（piān）声调不同，意思是薄片。"}, {"text": "骗", "is_correct": false, "explanation": "骗（piàn）与偏（piān）声调不同，意思是欺骗。"}, {"text": "边", "is_correct": false, "explanation": "边（biān）与偏（piān）声母不同（b 与 p），意思是边缘。"}, {"text": "天", "is_correct": false, "explanation": "天（tiān）与偏（piān）声母不同（t 与 p），意思是天空。"}, {"text": "煎", "is_correct": false, "explanation": "煎（jiān）与偏（piān）声母不同（j 与 p），意思是用油加热。"}], "explanations": {"偏": "偏（piān）意思是不在中间、歪向一边，是正确答案。", "片": "片（piàn）与偏（piān）声调不同，意思是薄片。", "骗": "骗（piàn）与偏（piān）声调不同，意思是欺骗。", "边": "边（biān）与偏（piān）声母不同（b 与 p），意思是边缘。", "天": "天（tiān）与偏（piān）声母不同（t 与 p），意思是天空。", "煎": "煎（jiān）与偏（piān）声母不同（j 与 p），意思是用油加热。"}, "sentence_index": null, "correct_answer": "偏"}, "level_3": {"options": [{"text": "偏", "is_correct": true, "explanation": "“偏”作形容词，说位置歪向一边，可以作补语说“放偏了”，符合句意。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说光线明亮，与花瓶的摆放位置无关，“放亮了”讲不通。"}, {"text": "软", "is_correct": false, "explanation": "搭配：“软”说质地柔软，不能用来说放置的结果，“放软了”不成立。"}, {"text": "白", "is_correct": false, "explanation": "语义：“白”说颜色，与摆放的位置无关，“放白了”讲不通。"}], "explanations": {"偏": "“偏”作形容词，说位置歪向一边，可以作补语说“放偏了”，符合句意。", "亮": "语义：“亮”说光线明亮，与花瓶的摆放位置无关，“放亮了”讲不通。", "软": "搭配：“软”说质地柔软，不能用来说放置的结果，“放软了”不成立。", "白": "语义：“白”说颜色，与摆放的位置无关，“放白了”讲不通。"}, "sentence_index": 0, "correct_answer": "偏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他偏了三本书，老师让他还回图书馆。", "explanation": "这里应该用〈借〉。“偏”是形容词，不能带宾语；“借书”要说“借”。"}, {"text": "她小时候眼睛偏视，后来做了手术。", "explanation": "这里应该用〈斜〉。“斜视”是固定说法，“偏视”不成词。"}, {"text": "他偏了一个大学，全家都很高兴。", "explanation": "这里应该用〈考上〉。“偏”不能带宾语；“考上大学”要说“考上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95805, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "偏", "is_correct": true, "explanation": "偏（piān）意思是不在中间、歪向一边，是正确答案。"}, {"text": "千", "is_correct": false, "explanation": "千（qiān）与偏（piān）声母不同（q 与 p），意思是一千。"}, {"text": "先", "is_correct": false, "explanation": "先（xiān）与偏（piān）声母不同（x 与 p），意思是先后的先。"}, {"text": "尖", "is_correct": false, "explanation": "尖（jiān）与偏（piān）声母不同（j 与 p），意思是尖端。"}, {"text": "飘", "is_correct": false, "explanation": "飘（piāo）与偏（piān）韵母不同（ao 与 an），意思是在空中漂浮。"}], "explanations": {"偏": "偏（piān）意思是不在中间、歪向一边，是正确答案。", "千": "千（qiān）与偏（piān）声母不同（q 与 p），意思是一千。", "先": "先（xiān）与偏（piān）声母不同（x 与 p），意思是先后的先。", "尖": "尖（jiān）与偏（piān）声母不同（j 与 p），意思是尖端。", "飘": "飘（piāo）与偏（piān）韵母不同（ao 与 an），意思是在空中漂浮。"}, "sentence_index": null, "correct_answer": "偏"}, "level_3": {"options": [{"text": "偏", "is_correct": true, "explanation": "“偏”作形容词，说位置不在中间，可以作补语说“挂得太偏”，符合句意。"}, {"text": "脏", "is_correct": false, "explanation": "搭配：“脏”说物体不干净，不描述悬挂的位置，“挂得太脏”不成立。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”说质地坚硬，不能用来说灯挂的状态，“挂得太硬”不成立。"}, {"text": "黑", "is_correct": false, "explanation": "语义：“黑”说颜色深暗，与灯挂的位置无关，“挂得太黑”讲不通。"}], "explanations": {"偏": "“偏”作形容词，说位置不在中间，可以作补语说“挂得太偏”，符合句意。", "脏": "搭配：“脏”说物体不干净，不描述悬挂的位置，“挂得太脏”不成立。", "硬": "搭配：“硬”说质地坚硬，不能用来说灯挂的状态，“挂得太硬”不成立。", "黑": "语义：“黑”说颜色深暗，与灯挂的位置无关，“挂得太黑”讲不通。"}, "sentence_index": 6, "correct_answer": "偏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他偏了一杯水，喝完就走了。", "explanation": "这里应该用〈倒〉。“偏”是形容词，不能带宾语；“倒水”要说“倒”。"}, {"text": "他偏了一个电话，很快就走了。", "explanation": "这里应该用〈打〉。“偏”不能带宾语；“打电话”要说“打”。"}, {"text": "他偏了一张桌子，放到了门口。", "explanation": "这里应该用〈搬〉。“偏”不能带宾语；“搬桌子”要说“搬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95805, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这盆花放了偏，要挪到中间。", "corrected_sentence": "这盆花放偏了，要挪到中间。", "error_description": "“偏”作补语要紧跟动词，“了”应放在补语之后：应说“放偏了”。“放了偏”的语序错误，“了”不能插在动词与补语之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95805, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把杯子放很偏。", "corrected_sentence": "他把杯子放得很偏。", "error_description": "“偏”作补语时，动词与补语之间要用“得”连接，说“放得很偏”；省去“得”，说“放很偏”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
