INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95806, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不正；倾向一边；不在正中间。", "primary_collocate": null, "pronunciation": "piān", "ipa": "pʰiɛn˥", "syllable_count": 1, "sentences": [{"text": "这幅画挂得有点偏。", "target_word": "偏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你坐得太偏了，往中间坐一点。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "照片里他的位置偏左。", "target_word": "偏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条线画偏了，要重新画。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "帽子戴偏了，你照照镜子。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的球踢偏了，没有进球门。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张桌子放得偏了一点，门打不开。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图片中的小树偏右，看起来不太好看。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "照相的时候，你站得太偏，只拍到一半。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个镜框有点偏，请帮我把它扶正。", "target_word": "偏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "偏了", "label": "体标"}], "register": "中性", "sense_fingerprint": "位置或方向不正，偏向一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a78e25c3-ee67-45e4-a792-d0210b249480') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95806, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "偏", "is_correct": true, "explanation": "偏（piān）意思是不正、偏向一边，是正确答案。"}, {"text": "片", "is_correct": false, "explanation": "片（piàn）与偏（piān）声调不同，意思是薄片。"}, {"text": "骗", "is_correct": false, "explanation": "骗（piàn）与偏（piān）声调不同，意思是欺骗。"}, {"text": "边", "is_correct": false, "explanation": "边（biān）与偏（piān）声母不同（b 与 p），意思是边缘。"}, {"text": "天", "is_correct": false, "explanation": "天（tiān）与偏（piān）声母不同（t 与 p），意思是天空。"}, {"text": "煎", "is_correct": false, "explanation": "煎（jiān）与偏（piān）声母不同（j 与 p），意思是用油加热。"}], "explanations": {"偏": "偏（piān）意思是不正、偏向一边，是正确答案。", "片": "片（piàn）与偏（piān）声调不同，意思是薄片。", "骗": "骗（piàn）与偏（piān）声调不同，意思是欺骗。", "边": "边（biān）与偏（piān）声母不同（b 与 p），意思是边缘。", "天": "天（tiān）与偏（piān）声母不同（t 与 p），意思是天空。", "煎": "煎（jiān）与偏（piān）声母不同（j 与 p），意思是用油加热。"}, "sentence_index": null, "correct_answer": "偏"}, "level_3": {"options": [{"text": "偏", "is_correct": true, "explanation": "“偏”作形容词，说位置不正，可以作补语说“挂得有点偏”，符合句意。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说光线明亮，与画挂得正不正无关，“挂得有点亮”讲不通。"}, {"text": "软", "is_correct": false, "explanation": "搭配：“软”说质地柔软，不能用来描述画挂的状态，“挂得有点软”不成立。"}, {"text": "脏", "is_correct": false, "explanation": "搭配：“脏”说物体不干净，不描述悬挂的位置，“挂得有点脏”不成立。"}], "explanations": {"偏": "“偏”作形容词，说位置不正，可以作补语说“挂得有点偏”，符合句意。", "亮": "语义：“亮”说光线明亮，与画挂得正不正无关，“挂得有点亮”讲不通。", "软": "搭配：“软”说质地柔软，不能用来描述画挂的状态，“挂得有点软”不成立。", "脏": "搭配：“脏”说物体不干净，不描述悬挂的位置，“挂得有点脏”不成立。"}, "sentence_index": 0, "correct_answer": "偏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他偏了一份报纸，很快就看完了。", "explanation": "这里应该用〈读〉。“偏”是形容词，不能带宾语；“读报纸”要说“读”。"}, {"text": "他小时候有偏视，后来做了手术。", "explanation": "这里应该用〈斜〉。“斜视”指眼球偏斜，是固定说法；“偏视”不成词，“偏”不能用于眼睛的视向。"}, {"text": "老板偏了一个会议，大家都很惊讶。", "explanation": "这里应该用〈开〉。“偏”不能带宾语；“开会”要说“开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95806, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "偏", "is_correct": true, "explanation": "偏（piān）意思是不正、偏向一边，是正确答案。"}, {"text": "千", "is_correct": false, "explanation": "千（qiān）与偏（piān）声母不同（q 与 p），意思是一千。"}, {"text": "先", "is_correct": false, "explanation": "先（xiān）与偏（piān）声母不同（x 与 p），意思是先后的先。"}, {"text": "尖", "is_correct": false, "explanation": "尖（jiān）与偏（piān）声母不同（j 与 p），意思是尖端。"}, {"text": "飘", "is_correct": false, "explanation": "飘（piāo）与偏（piān）韵母不同（ao 与 an），意思是在空中漂浮。"}], "explanations": {"偏": "偏（piān）意思是不正、偏向一边，是正确答案。", "千": "千（qiān）与偏（piān）声母不同（q 与 p），意思是一千。", "先": "先（xiān）与偏（piān）声母不同（x 与 p），意思是先后的先。", "尖": "尖（jiān）与偏（piān）声母不同（j 与 p），意思是尖端。", "飘": "飘（piāo）与偏（piān）韵母不同（ao 与 an），意思是在空中漂浮。"}, "sentence_index": null, "correct_answer": "偏"}, "level_3": {"options": [{"text": "偏", "is_correct": true, "explanation": "“偏”作形容词，说位置不正，可以作补语说“放得偏了一点”，符合句意。"}, {"text": "黑", "is_correct": false, "explanation": "语义：“黑”说颜色深暗，与桌子的摆放位置无关，“放得黑了一点”讲不通。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”描写人或动物的体形，不用来描述桌子的摆放。"}, {"text": "白", "is_correct": false, "explanation": "语义：“白”说颜色，不能表示摆放的结果，“放得白了一点”不成立。"}], "explanations": {"偏": "“偏”作形容词，说位置不正，可以作补语说“放得偏了一点”，符合句意。", "黑": "语义：“黑”说颜色深暗，与桌子的摆放位置无关，“放得黑了一点”讲不通。", "瘦": "体貌：“瘦”描写人或动物的体形，不用来描述桌子的摆放。", "白": "语义：“白”说颜色，不能表示摆放的结果，“放得白了一点”不成立。"}, "sentence_index": 6, "correct_answer": "偏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他偏了一封信，寄给了妈妈。", "explanation": "这里应该用〈写〉。“偏”是形容词，不能带宾语；“写信”要说“写”。"}, {"text": "他偏了一句话，大家都没听清。", "explanation": "这里应该用〈说〉。“偏”不能带宾语；“说话”要说“说”。"}, {"text": "他偏了一碗饭，很快就吃完了。", "explanation": "这里应该用〈盛〉。“偏”是形容词，不能带宾语；“盛饭”要说“盛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这幅画挂了偏。", "corrected_sentence": "这幅画挂偏了。", "error_description": "“偏”作补语要紧跟动词，“了”应放在补语之后：应说“挂偏了”。“挂了偏”的语序错误，“了”不能插在动词与补语之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个镜框挂很偏，要扶正。", "corrected_sentence": "这个镜框挂得很偏，要扶正。", "error_description": "“偏”作补语时，动词与补语之间要用“得”连接，说“挂得很偏”；省去“得”，说“挂很偏”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0489f8da-db73-4c65-bb89-c81dbedacac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
