INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95807, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "价钱是买一样东西要给多少钱。", "primary_collocate": null, "pronunciation": "jià qián", "ipa": "tɕja˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "请问，这个杯子的价钱是多少？", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋的价钱不便宜，我再想想。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜市场的蔬菜价钱很便宜。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买菜的时候总是先看价钱。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天西瓜的价钱比冬天低。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的价钱写在后面。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家饭馆的菜差不多，价钱却不一样。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嫌价钱太高，没有买手机。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个价钱我可以接受。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价钱合适的话，我就买两个。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "價錢", "label": "繁体"}], "register": "中性", "sense_fingerprint": "买一样东西要给的钱数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9cbe6ac-6e27-417b-92b2-2981f60beb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95807, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "价钱", "is_correct": true, "explanation": "正确：价钱，读作 jià qián，指买一样东西要给的钱数。"}, {"text": "假钱", "is_correct": false, "explanation": "jiǎ qián（第三声）与 jià 声调不同，意思是假币。"}, {"text": "加钱", "is_correct": false, "explanation": "jiā qián（第一声）与 jià 声调不同，意思是额外付钱。"}, {"text": "价签", "is_correct": false, "explanation": "qiān（第一声）与 qián（第二声）声调不同，意思是标着价格的签子。"}], "explanations": {"价钱": "正确：价钱，读作 jià qián，指买一样东西要给的钱数。", "假钱": "jiǎ qián（第三声）与 jià 声调不同，意思是假币。", "加钱": "jiā qián（第一声）与 jià 声调不同，意思是额外付钱。", "价签": "qiān（第一声）与 qián（第二声）声调不同，意思是标着价格的签子。"}, "sentence_index": null, "correct_answer": "价钱"}, "level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“是多少”问的是数量，颜色不能用数量来问。"}, {"text": "价钱", "is_correct": true, "explanation": "正确：“价钱”可以用“是多少”来问，“这个杯子的价钱是多少”符合句意。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不能用“多少”来问，句子语义不通。"}, {"text": "材料", "is_correct": false, "explanation": "搭配：“材料”不能和“是多少”搭配，问材料时不说多少。"}], "explanations": {"颜色": "语义：“是多少”问的是数量，颜色不能用数量来问。", "价钱": "正确：“价钱”可以用“是多少”来问，“这个杯子的价钱是多少”符合句意。", "名字": "语义：“名字”不能用“多少”来问，句子语义不通。", "材料": "搭配：“材料”不能和“是多少”搭配，问材料时不说多少。"}, "sentence_index": 0, "correct_answer": "价钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影的价钱有两个小时。", "explanation": "这里应该用〈片长〉。“价钱”是买东西要付的钱数，不能用时间长短来说，电影的长短应说“片长”。"}, {"text": "妈妈把价钱切成了块。", "explanation": "这里应该用〈蛋糕〉。“价钱”是买东西要付的数额，不能被切成块，切的应是蛋糕一类的食物。"}, {"text": "孩子在沙滩上堆起了价钱。", "explanation": "这里应该用〈沙堡〉。“价钱”是买东西要付的钱数，不能被堆起来，堆起的应是沙堡一类的实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95807, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的体态特征，不能用来说饭馆的菜。"}, {"text": "价钱", "is_correct": true, "explanation": "正确：“价钱”可以表示饭馆菜的价格差异，“价钱却不一样”符合句意。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指存在的年限，不能用来说饭馆的菜。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：“寿命”指存在的期限，不能用来说两家饭馆的菜。"}], "explanations": {"身高": "体貌：“身高”是人的体态特征，不能用来说饭馆的菜。", "价钱": "正确：“价钱”可以表示饭馆菜的价格差异，“价钱却不一样”符合句意。", "年龄": "语义：“年龄”指存在的年限，不能用来说饭馆的菜。", "寿命": "语义：“寿命”指存在的期限，不能用来说两家饭馆的菜。"}, "sentence_index": 6, "correct_answer": "价钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药的价钱很快。", "explanation": "这里应该用〈药效〉。“价钱”指买卖的钱数，不能用来形容起效的快慢，应说“药效很快”。"}, {"text": "他跑了很远的价钱。", "explanation": "这里应该用〈路〉。“跑了很远”的对象是路程，价钱是买东西要付的数额，不能被跑，表示行程应用“路”。"}, {"text": "他是我最好的价钱。", "explanation": "这里应该用〈朋友〉。“价钱”只指买东西要付的钱数，不能用来指人，指人应用“朋友”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95807, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去店里先问了一价钱。", "corrected_sentence": "他去店里先问了价钱。", "error_description": "错误：“价钱”前多了数词“一”，却没有量词。正确：去掉“一”，写作“先问了价钱”，“价钱”直接作宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95807, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他开进了很高的价钱。", "corrected_sentence": "他开出了很高的价钱。", "error_description": "错误：趋向补语“进”用错了。正确：“开出价钱”，补语应为“出”，表示把价钱报出来。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
