INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95808, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "商品的价格，买卖东西所需要的钱数。", "primary_collocate": null, "pronunciation": "jià qián", "ipa": "tɕja˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这件衣服的价钱太贵了，我不想买。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先问一下价钱，再决定买不买。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的价钱比别家便宜很多。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果的价钱每天都不一样。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说这个价钱不能再低了。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这个价钱很合理。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西以前，我喜欢比较一下价钱。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆自行车的价钱是多少？", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和老板讲了半天价钱。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价钱写在盒子上，你自己看吧。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "價錢", "label": "繁体"}], "register": "中性", "sense_fingerprint": "商品的价格，买东西要付的钱数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9cbe6ac-6e27-417b-92b2-2981f60beb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95808, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "价钱", "is_correct": true, "explanation": "正确：价钱，读作 jià qián，指买东西要付的钱数。"}, {"text": "假钱", "is_correct": false, "explanation": "jiǎ qián（第三声）与 jià 声调不同，意思是假币。"}, {"text": "加钱", "is_correct": false, "explanation": "jiā qián（第一声）与 jià 声调不同，意思是额外付钱。"}, {"text": "价签", "is_correct": false, "explanation": "qiān（第一声）与 qián（第二声）声调不同，意思是标着价格的签子。"}], "explanations": {"价钱": "正确：价钱，读作 jià qián，指买东西要付的钱数。", "假钱": "jiǎ qián（第三声）与 jià 声调不同，意思是假币。", "加钱": "jiā qián（第一声）与 jià 声调不同，意思是额外付钱。", "价签": "qiān（第一声）与 qián（第二声）声调不同，意思是标着价格的签子。"}, "sentence_index": null, "correct_answer": "价钱"}, "level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“太贵”说的是价格，不能用来形容颜色。"}, {"text": "价钱", "is_correct": true, "explanation": "正确：“价钱”指价格，“这件衣服的价钱太贵了”符合句意。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“太贵”形容价格，不能用来形容尺寸。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不是可以标价的东西，与“太贵”的说法矛盾。"}], "explanations": {"颜色": "搭配：“太贵”说的是价格，不能用来形容颜色。", "价钱": "正确：“价钱”指价格，“这件衣服的价钱太贵了”符合句意。", "尺寸": "搭配：“太贵”形容价格，不能用来形容尺寸。", "时间": "语义：“时间”不是可以标价的东西，与“太贵”的说法矛盾。"}, "sentence_index": 0, "correct_answer": "价钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说的话有很深的价钱。", "explanation": "这里应该用〈道理〉。“价钱”是买东西要付的钱数，不能用“很深”来形容，应说“有很深的道理”。"}, {"text": "他已经吃光了那些价钱。", "explanation": "这里应该用〈食物〉。“价钱”是买东西要付的钱数，不能被吃，可以吃光的应是食物。"}, {"text": "我把价钱放进了冰箱。", "explanation": "这里应该用〈牛奶〉。“价钱”是买东西要付的钱数，不是实物，不能放进冰箱，能放进冰箱的应是牛奶一类的食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95808, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心情", "is_correct": false, "explanation": "语义：“心情”不能拿来和其他东西比较价格，与买东西的语境不符。"}, {"text": "价钱", "is_correct": true, "explanation": "正确：“价钱”是买东西时可以比较的对象，符合“买东西以前……比较一下”的语境。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的体态特征，不能作为买东西时比较的对象。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指存在的年限，与买东西时比较的对象不相符。"}], "explanations": {"心情": "语义：“心情”不能拿来和其他东西比较价格，与买东西的语境不符。", "价钱": "正确：“价钱”是买东西时可以比较的对象，符合“买东西以前……比较一下”的语境。", "身高": "体貌：“身高”是人的体态特征，不能作为买东西时比较的对象。", "年龄": "语义：“年龄”指存在的年限，与买东西时比较的对象不相符。"}, "sentence_index": 6, "correct_answer": "价钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次活动的价钱很精彩。", "explanation": "这里应该用〈表演〉。“价钱”指买卖的钱数，不能用来形容好坏，应说“表演很精彩”。"}, {"text": "他一下子赚了很多价钱。", "explanation": "这里应该用〈利润〉。“价钱”是商品的标价，不能被赚，赚到的应是利润这类收益。"}, {"text": "我们在价钱见面。", "explanation": "这里应该用〈集市〉。“价钱”指买卖的钱数，不能当作见面的地点，买卖的场所应用“集市”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95808, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板说这本价钱已经很便宜了。", "corrected_sentence": "老板说这个价钱已经很便宜了。", "error_description": "错误：量词“本”用错了，“本”用于书本，不能用于“价钱”。正确：“价钱”用量词“个”，写作“这个价钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95808, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "买东西以前，我喜欢先比较一下价钱一下。", "corrected_sentence": "买东西以前，我喜欢先比较一下价钱。", "error_description": "错误：动量补语“一下”重复出现，多出的“一下”放在了“价钱”后面。正确：“一下”只紧跟动词“比较”，写作“比较一下价钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
