INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95809, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95809, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "共产主义是一种想法：大家的东西都归大家，没有穷人和富人。", "primary_collocate": null, "pronunciation": "gòng chǎn zhǔ yì", "ipa": "kʊŋ˥˩ ʈʂʰan˨˩˦ ʈʂu˨˩˦ i˥˩", "syllable_count": 4, "sentences": [{"text": "他在书里学习共产主义。", "target_word": "共产主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共产主义是一种想法。", "target_word": "共产主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了共产主义。", "target_word": "共产主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就相信共产主义。", "target_word": "共产主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是写共产主义的。", "target_word": "共产主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共产主义的理想是让大家都有饭吃。", "target_word": "共产主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道共产主义是什么意思吗？", "target_word": "共产主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在共产主义社会里，没有穷人和富人。", "target_word": "共产主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷常常说起共产主义。", "target_word": "共产主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对共产主义很有兴趣。", "target_word": "共产主义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "共產主義", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一种想法：财产归大家，没有穷人和富人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a720de0-ac80-4bf6-b407-5b4e7acb898f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95809, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不是可以在书里学习的内容。"}, {"text": "共产主义", "is_correct": true, "explanation": "正确。“共产主义”是一种思想体系，可以在书里学习，与句意相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不是可以在书里学习的知识。"}, {"text": "米饭", "is_correct": false, "explanation": "搭配：“学习”的对象是知识或技能，“米饭”不能作“在书里学习”的对象。"}], "explanations": {"太阳": "语义：太阳是天体，不是可以在书里学习的内容。", "共产主义": "正确。“共产主义”是一种思想体系，可以在书里学习，与句意相符。", "冰箱": "语义：冰箱是家用电器，不是可以在书里学习的知识。", "米饭": "搭配：“学习”的对象是知识或技能，“米饭”不能作“在书里学习”的对象。"}, "sentence_index": 0, "correct_answer": "共产主义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去超市买了一斤共产主义。", "explanation": "共产主义是一种抽象的思想，不是商品，不能在超市买，也不能用〈斤〉称重。"}, {"text": "他的共产主义是当一名医生。", "explanation": "这里应该用〈理想〉。理想指个人的人生目标；共产主义是社会思想体系，不能指个人的职业选择。"}, {"text": "他在考试中得了共产主义的满分。", "explanation": "此处“得满分”指考试成绩，共产主义是思想体系，不能作为分数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95809, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "皮鞋", "is_correct": false, "explanation": "搭配：“是什么意思”用于询问词语或概念，“皮鞋”是具体物品，一般不这样问。"}, {"text": "共产主义", "is_correct": true, "explanation": "正确。“共产主义”是需要解释的词语，问它的意思符合句意。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜是水果，人们不会问它“是什么意思”。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：问“是什么意思”的对象是词语，“窗户”是具体事物，搭配不当。"}], "explanations": {"皮鞋": "搭配：“是什么意思”用于询问词语或概念，“皮鞋”是具体物品，一般不这样问。", "共产主义": "正确。“共产主义”是需要解释的词语，问它的意思符合句意。", "西瓜": "语义：西瓜是水果，人们不会问它“是什么意思”。", "窗户": "搭配：问“是什么意思”的对象是词语，“窗户”是具体事物，搭配不当。"}, "sentence_index": 6, "correct_answer": "共产主义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在共产主义里工作了三年。", "explanation": "“在……里”要求具体的场所，共产主义是抽象思想，不能当作工作的地方。"}, {"text": "我把共产主义放进了书包。", "explanation": "“放进书包”要求具体的物品，共产主义是抽象的思想体系，不能被装进书包。"}, {"text": "这家餐厅的共产主义很好吃。", "explanation": "“好吃”用于食物，共产主义是思想体系，不能说好吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95809, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对共产主义的很感兴趣。", "corrected_sentence": "他对共产主义很感兴趣。", "error_description": "错误：在“共产主义”后面多加了“的”。正确应为“对共产主义很感兴趣”，“对……很感兴趣”中间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95809, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书跟共产主义的有关。", "corrected_sentence": "这本书跟共产主义有关。", "error_description": "错误：在“共产主义”后面多加了“的”。“跟……有关”中间不能插入“的”，正确应为“这本书跟共产主义有关”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
