INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95810, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种主张生产资料公有、消灭阶级和剥削的社会理想与思想体系。", "primary_collocate": null, "pronunciation": "gòng chǎn zhǔ yì", "ipa": "kʊŋ˥˩ ʈʂʰan˨˩˦ ʈʂu˨˩˦ i˥˩", "syllable_count": 4, "sentences": [{"text": "共产主义主张生产资料归大家所有。", "target_word": "共产主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共产主义的目标是消灭阶级和剥削。", "target_word": "共产主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究共产主义思想已经十年了。", "target_word": "共产主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共产主义是一种社会理想。", "target_word": "共产主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学者写过很多关于共产主义的书。", "target_word": "共产主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共产主义的理想是人人平等。", "target_word": "共产主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在大学里讨论共产主义。", "target_word": "共产主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共产主义思想对很多国家有影响。", "target_word": "共产主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马克思是共产主义思想的重要人物。", "target_word": "共产主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书中说，共产主义要消灭剥削。", "target_word": "共产主义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "共產主義", "label": "繁体"}], "register": "正式", "sense_fingerprint": "主张生产资料公有、消灭阶级和剥削的社会理想与思想体系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a720de0-ac80-4bf6-b407-5b4e7acb898f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95810, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不会主张生产资料归大家所有，句意不通。"}, {"text": "共产主义", "is_correct": true, "explanation": "正确。只有“共产主义”主张生产资料归大家所有，符合句意。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不能作为“主张”的主体。"}, {"text": "米饭", "is_correct": false, "explanation": "搭配：“主张”的主体应是人、学说或思想，“米饭”不能搭配。"}], "explanations": {"冰箱": "语义：冰箱不会主张生产资料归大家所有，句意不通。", "共产主义": "正确。只有“共产主义”主张生产资料归大家所有，符合句意。", "太阳": "语义：太阳是天体，不能作为“主张”的主体。", "米饭": "搭配：“主张”的主体应是人、学说或思想，“米饭”不能搭配。"}, "sentence_index": 0, "correct_answer": "共产主义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "共产主义是一个政党。", "explanation": "这里应该用〈共产党〉。共产党是政党，指组织；共产主义是思想体系，不能指政党。"}, {"text": "这是一座共产主义。", "explanation": "这里不能用〈座〉。〈座〉用于山、楼房等大型固定的物体；共产主义是抽象思想，应使用〈种〉。"}, {"text": "他每天早上都要去共产主义上班。", "explanation": "“去……上班”要求工作的场所，共产主义是思想体系，不能作为上班的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95810, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜是水果，不是大学里讨论的话题。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“讨论”的对象是问题、观点或话题，“窗户”是具体物件。"}, {"text": "共产主义", "is_correct": true, "explanation": "正确。“共产主义”是可以讨论的思想话题，与句意相符。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：地毯是家居用品，不是需要讨论的话题。"}], "explanations": {"西瓜": "语义：西瓜是水果，不是大学里讨论的话题。", "窗户": "搭配：“讨论”的对象是问题、观点或话题，“窗户”是具体物件。", "共产主义": "正确。“共产主义”是可以讨论的思想话题，与句意相符。", "地毯": "语义：地毯是家居用品，不是需要讨论的话题。"}, "sentence_index": 6, "correct_answer": "共产主义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个共产主义是用木头做的。", "explanation": "“用木头做的”说的是实物材料，共产主义是抽象的思想体系，没有材料可言。"}, {"text": "这次比赛他拿到了共产主义的满分。", "explanation": "“拿到满分”指分数，共产主义是思想体系，不是可以得到的分数。"}, {"text": "这首歌是共产主义写的。", "explanation": "“写”需要有行为能力的人作主语，共产主义是思想体系，不能写歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对一位共产主义很感兴趣。", "corrected_sentence": "他对共产主义很感兴趣。", "error_description": "错误：“共产主义”前面误加了量词“位”。“位”用于人，共产主义是思想体系，不能用“位”计量，应直接说“对共产主义很感兴趣”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师给我们介绍了一位共产主义。", "corrected_sentence": "老师给我们介绍了共产主义。", "error_description": "错误：“共产主义”前误加了量词“位”。“位”用于人，共产主义是思想体系，不能用“位”计量，应直接说“介绍了共产主义”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95811, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一致", "is_correct": true, "explanation": "正确：“一致”与“分歧”意思相反，是反义关系。"}, {"text": "严重", "is_correct": false, "explanation": "与“分歧”没有反义关系，“严重”说的是程度很重。"}, {"text": "紧张", "is_correct": false, "explanation": "与“分歧”没有反义关系，“紧张”说的是心情或气氛不放松。"}, {"text": "普通", "is_correct": false, "explanation": "与“分歧”没有反义关系，“普通”说的是平常、不特别。"}], "correct_answer": "一致", "explanations": {"一致": "正确：“一致”与“分歧”意思相反，是反义关系。", "严重": "与“分歧”没有反义关系，“严重”说的是程度很重。", "紧张": "与“分歧”没有反义关系，“紧张”说的是心情或气氛不放松。", "普通": "与“分歧”没有反义关系，“普通”说的是平常、不特别。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
