INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95811, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "分歧是大家的想法不一样，没法统一。", "primary_collocate": null, "pronunciation": "fēn qí", "ipa": "fən˥ tɕʰi˧˥", "syllable_count": 2, "sentences": [{"text": "大家有分歧，所以没法决定。", "target_word": "分歧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为有分歧，会议开了很久。", "target_word": "分歧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的分歧一直没有解决。", "target_word": "分歧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事上，家人之间有分歧。", "target_word": "分歧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们的分歧到底在哪儿？", "target_word": "分歧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的分歧不算大。", "target_word": "分歧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话以后，大家的分歧更大了。", "target_word": "分歧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们对去哪儿玩有分歧。", "target_word": "分歧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想先找出分歧在哪里。", "target_word": "分歧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有分歧不要紧，慢慢谈。", "target_word": "分歧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "意见分歧", "label": "复合"}], "register": "中性", "sense_fingerprint": "大家想法不一样、没法统一", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0aa27f-22fc-4bb2-b50a-1b53150bdc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95811, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分歧", "is_correct": true, "explanation": "正确：分歧（fēn qí）指意见或做法上的不一致。"}, {"text": "分机", "is_correct": false, "explanation": "分机（fēn jī）：声母 q 与 j 不同，声调变为第一声，意思是总机下面的分机电话。"}, {"text": "分期", "is_correct": false, "explanation": "分期（fēn qī）：只有声调不同（qī 为第一声），意思是分阶段进行。"}, {"text": "奋起", "is_correct": false, "explanation": "奋起（fèn qǐ）：声母韵母相同，声调不同，意思是振作起来。"}, {"text": "风气", "is_correct": false, "explanation": "风气（fēng qì）：fēng 与 fēn 只差前后鼻音，qì 为第四声，意思是社会上流行的习惯。"}], "explanations": {"分歧": "正确：分歧（fēn qí）指意见或做法上的不一致。", "分机": "分机（fēn jī）：声母 q 与 j 不同，声调变为第一声，意思是总机下面的分机电话。", "分期": "分期（fēn qī）：只有声调不同（qī 为第一声），意思是分阶段进行。", "奋起": "奋起（fèn qǐ）：声母韵母相同，声调不同，意思是振作起来。", "风气": "风气（fēng qì）：fēng 与 fēn 只差前后鼻音，qì 为第四声，意思是社会上流行的习惯。"}, "sentence_index": null, "correct_answer": "分歧"}, "level_3": {"options": [{"text": "分歧", "is_correct": true, "explanation": "正确：“大家有分歧，所以没法决定”因果通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与“没法决定”没有因果关系，句子不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“大家”不与“身高”搭配，人群不说有身高。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重与“没法决定”没有因果关系，句子不通。"}], "explanations": {"分歧": "正确：“大家有分歧，所以没法决定”因果通顺。", "颜色": "语义：颜色与“没法决定”没有因果关系，句子不通。", "身高": "搭配：“大家”不与“身高”搭配，人群不说有身高。", "体重": "语义：体重与“没法决定”没有因果关系，句子不通。"}, "sentence_index": 0, "correct_answer": "分歧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的分歧很小，测量很准确。", "explanation": "这里应该用〈误差〉。分歧指意见不一致，测量时的偏差要说〈误差〉。"}, {"text": "这根绳子的分歧是两米。", "explanation": "这里应该用〈长度〉。分歧不表示长短，绳子的长短要说〈长度〉。"}, {"text": "他们之间有一只分歧。", "explanation": "这里不能用〈只〉作量词。“只”多用于动物，抽象的“分歧”应说“一种分歧”或“一个分歧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95811, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "分歧", "is_correct": true, "explanation": "正确：分歧（fēn qí）指意见或做法上的不一致。"}, {"text": "分析", "is_correct": false, "explanation": "分析（fēn xī）：声母 q 与 x 不同，声调也不同，意思是把事物分开来研究。"}, {"text": "分期", "is_correct": false, "explanation": "分期（fēn qī）：只有声调不同（qí 为第二声，qī 为第一声），意思是分阶段进行。"}, {"text": "分级", "is_correct": false, "explanation": "分级（fēn jí）：声母 q 与 j 不同，声调相同，意思是按等级划分。"}, {"text": "奋起", "is_correct": false, "explanation": "奋起（fèn qǐ）：声母韵母相同，声调不同，意思是振作起来。"}], "explanations": {"分歧": "正确：分歧（fēn qí）指意见或做法上的不一致。", "分析": "分析（fēn xī）：声母 q 与 x 不同，声调也不同，意思是把事物分开来研究。", "分期": "分期（fēn qī）：只有声调不同（qí 为第二声，qī 为第一声），意思是分阶段进行。", "分级": "分级（fēn jí）：声母 q 与 j 不同，声调相同，意思是按等级划分。", "奋起": "奋起（fèn qǐ）：声母韵母相同，声调不同，意思是振作起来。"}, "sentence_index": null, "correct_answer": "分歧"}, "level_3": {"options": [{"text": "分歧", "is_correct": true, "explanation": "正确：“大家的分歧更大了”指意见不一致的程度加深。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温不会因为说话而“更大”，句子说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能说“更大了”，句子说不通。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：温度的程度用“高”，不说“更大了”。"}], "explanations": {"分歧": "正确：“大家的分歧更大了”指意见不一致的程度加深。", "体温": "语义：体温不会因为说话而“更大”，句子说不通。", "味道": "语义：味道不能说“更大了”，句子说不通。", "温度": "搭配：温度的程度用“高”，不说“更大了”。"}, "sentence_index": 6, "correct_answer": "分歧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个分歧每天吃三碗饭，长得很快。", "explanation": "这里应该用〈孩子〉。分歧是抽象的意见不一致，不会吃饭长个子，要说〈孩子〉。"}, {"text": "他的分歧很好，老师很满意。", "explanation": "这里应该用〈成绩〉。分歧没有好坏之分，老师满意的是〈成绩〉。"}, {"text": "这朵花的分歧很鲜艳。", "explanation": "这里应该用〈颜色〉。分歧是抽象的不一致，不能用“鲜艳”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_use