INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95811, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们想消除这座分歧。", "corrected_sentence": "我们想消除这种分歧。", "error_description": "量词错误：“座”多用于山、楼等大型固定的东西，抽象的“分歧”应用“种”，正确应为“这种分歧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95811, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只分歧很难消除。", "corrected_sentence": "这种分歧很难消除。", "error_description": "量词错误：“只”用于动物，抽象的“分歧”应用“种”，正确应为“这种分歧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95812, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一致", "is_correct": true, "explanation": "正确：“一致”与“分歧”意思相反，是反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "与“分歧”没有反义关系，“清楚”说的是明白，不是意见不统一。"}, {"text": "复杂", "is_correct": false, "explanation": "与“分歧”没有反义关系，“复杂”说的是情况繁多，不是意见相反。"}, {"text": "安静", "is_correct": false, "explanation": "与“分歧”没有反义关系，“安静”说的是声音小或不吵闹。"}], "correct_answer": "一致", "explanations": {"一致": "正确：“一致”与“分歧”意思相反，是反义关系。", "清楚": "与“分歧”没有反义关系，“清楚”说的是明白，不是意见不统一。", "复杂": "与“分歧”没有反义关系，“复杂”说的是情况繁多，不是意见相反。", "安静": "与“分歧”没有反义关系，“安静”说的是声音小或不吵闹。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95812, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一致", "is_correct": true, "explanation": "正确：“一致”与“分歧”意思相反，是反义关系。"}, {"text": "明显", "is_correct": false, "explanation": "与“分歧”没有反义关系，“明显”说的是容易看出来。"}, {"text": "热闹", "is_correct": false, "explanation": "与“分歧”没有反义关系，“热闹”说的是人多、喧闹。"}, {"text": "平常", "is_correct": false, "explanation": "与“分歧”没有反义关系，“平常”说的是普通、不特别。"}], "correct_answer": "一致", "explanations": {"一致": "正确：“一致”与“分歧”意思相反，是反义关系。", "明显": "与“分歧”没有反义关系，“明显”说的是容易看出来。", "热闹": "与“分歧”没有反义关系，“热闹”说的是人多、喧闹。", "平常": "与“分歧”没有反义关系，“平常”说的是普通、不特别。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95812, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "思想、意见或做法上的不一致。", "primary_collocate": null, "pronunciation": "fēn qí", "ipa": "fən˥ tɕʰi˧˥", "syllable_count": 2, "sentences": [{"text": "我们对这个问题有分歧。", "target_word": "分歧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人的意见出现了分歧。", "target_word": "分歧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在做法上有很大的分歧。", "target_word": "分歧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过讨论，大家的分歧小了。", "target_word": "分歧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和学生在看法上有分歧。", "target_word": "分歧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的分歧很大，没有办法决定。", "target_word": "分歧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了解决分歧，他们开了一个会。", "target_word": "分歧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夫妻之间的分歧越来越多。", "target_word": "分歧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的分歧主要是钱的问题。", "target_word": "分歧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和朋友在旅行计划上有分歧。", "target_word": "分歧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "意见分歧", "label": "复合"}], "register": "中性", "sense_fingerprint": "思想、意见或做法上的不一致", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0aa27f-22fc-4bb2-b50a-1b53150bdc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95812, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分歧", "is_correct": true, "explanation": "正确：分歧（fēn qí）指意见或做法上的不一致。"}, {"text": "分析", "is_correct": false, "explanation": "分析（fēn xī）：声母 q 与 x 不同，声调也不同，意思是把事物分开来研究。"}, {"text": "分期", "is_correct": false, "explanation": "分期（fēn qī）：只有声调不同（qí 为第二声，qī 为第一声），意思是分阶段进行。"}, {"text": "分级", "is_correct": false, "explanation": "分级（fēn jí）：声母 q 与 j 不同，声调相同，意思是按等级划分。"}, {"text": "奋起", "is_correct": false, "explanation": "奋起（fèn qǐ）：声母韵母相同，声调不同，意思是振作起来。"}], "explanations": {"分歧": "正确：分歧（fēn qí）指意见或做法上的不一致。", "分析": "分析（fēn xī）：声母 q 与 x 不同，声调也不同，意思是把事物分开来研究。", "分期": "分期（fēn qī）：只有声调不同（qí 为第二声，qī 为第一声），意思是分阶段进行。", "分级": "分级（fēn jí）：声母 q 与 j 不同，声调相同，意思是按等级划分。", "奋起": "奋起（fèn qǐ）：声母韵母相同，声调不同，意思是振作起来。"}, "sentence_index": null, "correct_answer": "分歧"}, "level_3": {"options": [{"text": "分歧", "is_correct": true, "explanation": "正确：分歧指意见或做法上的不一致，与“对这个问题有”搭配。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是人或物的重量，与“问题”无关，不能说“对问题有体重”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的外观特征，与“对这个问题”的意见无关。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”不与“对这个问题有”搭配，问题不能有身高。"}], "explanations": {"分歧": "正确：分歧指意见或做法上的不一致，与“对这个问题有”搭配。", "体重": "语义：体重是人或物的重量，与“问题”无关，不能说“对问题有体重”。", "颜色": "语义：颜色是事物的外观特征，与“对这个问题”的意见无关。", "身高": "搭配：“身高”不与“对这个问题有”搭配，问题不能有身高。"}, "sentence_index": 0, "correct_answer": "分歧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两种颜色有明显的分歧。", "explanation": "这里应该用〈差异〉。分歧用于意见、做法，颜色这类客观事物的不同要说〈差异〉。"}, {"text": "两座城市的分歧很远，坐车要三个小时。", "explanation": "这里应该用〈距离〉。分歧指意见不一致，不能用来说地点远近，表示远近要说〈距离〉。"}, {"text": "我们之间有一张分歧。", "explanation": "这里应该用〈种〉。“张”用于纸、桌子等平面物件，“分歧”是抽象名词，应说“一种分歧”或“一个分歧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95812, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "分歧", "is_correct": true, "explanation": "正确：分歧（fēn qí）指意见或做法上的不一致。"}, {"text": "分机", "is_correct": false, "explanation": "分机（fēn jī）：声母 q 与 j 不同，声调变为第一声，意思是总机下面的分机电话。"}, {"text": "分期", "is_correct": false, "explanation": "分期（fēn qī）：只有声调不同（qī 为第一声），意思是分阶段进行。"}, {"text": "奋起", "is_correct": false, "explanation": "奋起（fèn qǐ）：声母韵母相同，声调不同，意思是振作起来。"}, {"text": "风气", "is_correct": false, "explanation": "风气（fēng qì）：fēng 与 fēn 只差前后鼻音，qì 为第四声，意思是社会上流行的习惯。"}], "explanations": {"分歧": "正确：分歧（fēn qí）指意见或做法上的不一致。", "分机": "分机（fēn jī）：声母 q 与 j 不同，声调变为第一声，意思是总机下面的分机电话。", "分期": "分期（fēn qī）：只有声调不同（qī 为第一声），意思是分阶段进行。", "奋起": "奋起（fèn qǐ）：声母韵母相同，声调不同，意思是振作起来。", "风气": "风气（fēng qì）：fēng 与 fēn 只差前后鼻音，qì 为第四声，意思是社会上流行的习惯。"}, "sentence_index": null, "correct_answer": "分歧"}, "level_3": {"options": [{"text": "分歧", "is_correct": true, "explanation": "正确：“为了解决分歧”中，“分歧”是需要解决的对象。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是身体的温度，不是需要开会解决的对象。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不是需要开会解决的问题，句子说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“解决”的对象一般是问题、矛盾，不说“解决年龄”。"}], "explanations": {"分歧": "正确：“为了解决分歧”中，“分歧”是需要解决的对象。", "体温": "语义：体温是身体的温度，不是需要开会解决的对象。", "味道": "语义：味道不是需要开会解决的问题，句子说不通。", "年龄": "搭配：“解决”的对象一般是问题、矛盾，不说“解决年龄”。"}, "sentence_index": 6, "correct_answer": "分歧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我的好分歧，每次比赛都很认真。", "explanation": "这里应该用〈对手〉。分歧指意见不一致，不能用来指人。"}, {"text": "这个项目取得了很大分歧。", "explanation": "这里应该用〈进展〉。“取得”搭配进展、成绩，分歧是意见不同，不能取得。"}, {"text": "她的分歧很好听。", "explanation": "这里应该用〈声音〉。分歧不是声音，不能用“好听”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们终于解决了这条分歧。", "corrected_sentence": "他们终于解决了这种分歧。", "error_description": "量词错误：“条”多用于河流、路等细长的东西，抽象的“分歧”应用“种”，正确应为“这种分歧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在这个问题上有一位分歧。", "corrected_sentence": "他们在这个问题上有一些分歧。", "error_description": "量词错误：“位”用于人，抽象的“分歧”不能用“位”计量，应改为“一些”，正确应为“有一些分歧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95817, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "责怪", "is_correct": true, "explanation": "正确。“原谅”与“责怪”相对，指对别人的错误不再怪罪。"}, {"text": "感谢", "is_correct": false, "explanation": "无反义关系：“感谢”是对别人的好意表示谢意，与“原谅”不构成反义。"}, {"text": "同意", "is_correct": false, "explanation": "无反义关系：“同意”是赞成某事，与“原谅”不构成反义。"}, {"text": "称赞", "is_correct": false, "explanation": "无反义关系：“称赞”是夸奖别人，与“原谅”不构成反义。"}], "correct_answer": "责怪", "explanations": {"责怪": "正确。“原谅”与“责怪”相对，指对别人的错误不再怪罪。", "感谢": "无反义关系：“感谢”是对别人的好意表示谢意，与“原谅”不构成反义。", "同意": "无反义关系：“同意”是赞成某事，与“原谅”不构成反义。", "称赞": "无反义关系：“称赞”是夸奖别人，与“原谅”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95817, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "责备", "is_correct": true, "explanation": "正确。“原谅”与“责备”相对，指对别人的过错不再批评。"}, {"text": "鼓励", "is_correct": false, "explanation": "无反义关系：“鼓励”是给人信心，与“原谅”不构成反义。"}, {"text": "答应", "is_correct": false, "explanation": "无反义关系：“答应”是同意做某事，与“原谅”不构成反义。"}, {"text": "批准", "is_correct": false, "explanation": "无反义关系：“批准”是正式同意，与“原谅”不构成反义。"}], "correct_answer": "责备", "explanations": {"责备": "正确。“原谅”与“责备”相对，指对别人的过错不再批评。", "鼓励": "无反义关系：“鼓励”是给人信心，与“原谅”不构成反义。", "答应": "无反义关系：“答应”是同意做某事，与“原谅”不构成反义。", "批准": "无反义关系：“批准”是正式同意，与“原谅”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95817, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "原谅是别人做错了事，你不生气了，不怪他了。", "primary_collocate": null, "pronunciation": "yuán liàng", "ipa": "ɥɛn˧˥ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "你快去跟妈妈说对不起，她会原谅你的。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打坏了我的杯子，可我很快就原谅他了。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友说了谎，我不想原谅他。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我原谅你了，你不要难过。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟道歉以后，姐姐原谅了他。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你做错了事，别人不一定会原谅你。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没有原谅过那个骗她的人。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每次犯错，奶奶都原谅他。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我知道你是无心的，所以原谅你。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然他伤过我的心，但我已经原谅他了。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "原谅了", "label": "完成体"}, {"form": "原谅过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "别人做错事后，不再生气、不再责怪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ce3a876-3c1d-44d7-b39d-01649e9db7d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95817, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原谅", "is_correct": true, "explanation": "正确。“原谅”指对别人的过错不再计较，与“说对不起”的语境相合。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：打扫是清理场所，与道歉的语境无关，“她会打扫你的”说不通。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理的对象是坏了的东西，不能说“她会修理你的”来回应道歉，句子不通。"}, {"text": "拆开", "is_correct": false, "explanation": "语义：拆开是打开包裹或信件，与道歉的语境无关，句子说不通。"}], "explanations": {"原谅": "正确。“原谅”指对别人的过错不再计较，与“说对不起”的语境相合。", "打扫": "语义：打扫是清理场所，与道歉的语境无关，“她会打扫你的”说不通。", "修理": "语义：修理的对象是坏了的东西，不能说“她会修理你的”来回应道歉，句子不通。", "拆开": "语义：拆开是打开包裹或信件，与道歉的语境无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "原谅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这顿饭很好吃，我原谅你了。", "explanation": "这里应该用〈夸奖〉。“原谅”针对别人做错的事，饭做得好吃应当夸奖，不能说“原谅”。"}, {"text": "我原谅你考上了大学。", "explanation": "这里应该用〈恭喜〉。“原谅”针对过错，考上大学是喜事，应说“恭喜”。"}, {"text": "我的朋友生病了，我原谅了他的病。", "explanation": "这里应该用〈关心〉。生病不是别人的过错，对病人应表示关心，不能说“原谅”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95817, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原谅", "is_correct": true, "explanation": "正确。“原谅”用于骗人者所做的过错，与“没有……过”的说法相合。"}, {"text": "感激", "is_correct": false, "explanation": "语义：感激是对别人的好处表示谢意，不能用于骗她的人，句子说不通。"}, {"text": "拆开", "is_correct": false, "explanation": "语义：拆开的对象是包裹、信件等东西，不能拆开一个人，句子说不通。"}, {"text": "表彰", "is_correct": false, "explanation": "语义：表彰是公开表扬，与骗人的人不相称，句子不通。"}], "explanations": {"原谅": "正确。“原谅”用于骗人者所做的过错，与“没有……过”的说法相合。", "感激": "语义：感激是对别人的好处表示谢意，不能用于骗她的人，句子说不通。", "拆开": "语义：拆开的对象是包裹、信件等东西，不能拆开一个人，句子说不通。", "表彰": "语义：表彰是公开表扬，与骗人的人不相称，句子不通。"}, "sentence_index": 6, "correct_answer": "原谅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你帮了我很多，我原谅了你的帮助。", "explanation": "这里应该用〈感激〉。“原谅”针对别人的过错，别人的帮助不是过错，不能说“原谅”。"}, {"text": "他拿了冠军，我原谅了他的冠军。", "explanation": "这里应该用〈祝贺〉。“原谅”针对过错，对拿冠军应表示祝贺，不能用“原谅”。"}, {"text": "这件衣服很贵，我原谅了它的价格。", "explanation": "这里应该用〈接受〉。“原谅”针对人的过错，对价格这类情况应说“接受”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95817, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你做错事，我不原谅了你。", "corrected_sentence": "你做错事，我不原谅你。", "error_description": "体标错误：否定句中不能在“原谅”后加“了”。错误句是“不原谅了你”，正确句是“不原谅你”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95817, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经把他的错原谅。", "corrected_sentence": "我已经把他的错原谅了。", "error_description": "句式错误：“把”字句的动词后面要有其他成分（如“了”），“把他的错原谅”不完整，应说“把他的错原谅了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
