INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95818, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对人的过错或失礼不再责备或计较。", "primary_collocate": null, "pronunciation": "yuán liàng", "ipa": "ɥɛn˧˥ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "请原谅我，我真的不是故意的。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他迟到了，老师原谅了他。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈原谅过我很多次。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个错误太大，我没办法原谅他。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能原谅我昨天说的话吗？", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她终于原谅了朋友的失礼。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对不起，请原谅我来晚了。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子认错以后，爸爸就原谅他了。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直没有原谅过自己。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家原谅我的失礼。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "原谅了", "label": "完成体"}, {"form": "原谅过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "对别人的过错或失礼不再责备、不再计较", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ce3a876-3c1d-44d7-b39d-01649e9db7d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95818, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原谅", "is_correct": true, "explanation": "正确。“原谅”指对别人的过错不再责备，与“我真的不是故意的”的道歉语境相合。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：表扬是夸奖别人的好表现，与“不是故意”的道歉语境冲突。"}, {"text": "感谢", "is_correct": false, "explanation": "搭配：“感谢我”不能对应道歉的语境，“请感谢我，我不是故意的”搭配不通。"}, {"text": "邀请", "is_correct": false, "explanation": "语义：邀请是请对方来做某事，与道歉的语境无关，句子不通。"}], "explanations": {"原谅": "正确。“原谅”指对别人的过错不再责备，与“我真的不是故意的”的道歉语境相合。", "表扬": "语义：表扬是夸奖别人的好表现，与“不是故意”的道歉语境冲突。", "感谢": "搭配：“感谢我”不能对应道歉的语境，“请感谢我，我不是故意的”搭配不通。", "邀请": "语义：邀请是请对方来做某事，与道歉的语境无关，句子不通。"}, "sentence_index": 0, "correct_answer": "原谅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈原谅了我的请求。", "explanation": "这里应该用〈同意〉。“原谅”针对别人的过错，不用于对请求的答复。"}, {"text": "老师原谅了他的努力。", "explanation": "这里应该用〈表扬〉。“原谅”针对过错，努力应当被表扬，不能说“原谅”。"}, {"text": "大家原谅他的到来。", "explanation": "这里应该用〈欢迎〉。“原谅”针对过错，不用于迎接别人的到来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95818, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原谅", "is_correct": true, "explanation": "正确。“原谅”用于对方的过错，与“对不起”的道歉语境相合。"}, {"text": "问候", "is_correct": false, "explanation": "语义：问候是打招呼，与“对不起”的道歉语境不符，句子不通。"}, {"text": "催促", "is_correct": false, "explanation": "搭配：“催促”是催对方快做，不能对已经来晚的人说“请催促我来晚了”，搭配不通。"}, {"text": "讽刺", "is_correct": false, "explanation": "语义：讽刺是挖苦对方，与“对不起”的道歉语境冲突。"}], "explanations": {"原谅": "正确。“原谅”用于对方的过错，与“对不起”的道歉语境相合。", "问候": "语义：问候是打招呼，与“对不起”的道歉语境不符，句子不通。", "催促": "搭配：“催促”是催对方快做，不能对已经来晚的人说“请催促我来晚了”，搭配不通。", "讽刺": "语义：讽刺是挖苦对方，与“对不起”的道歉语境冲突。"}, "sentence_index": 6, "correct_answer": "原谅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈很喜欢这份礼物，所以原谅了它。", "explanation": "这里应该用〈收下〉。“原谅”针对别人做错的事，对礼物应说“收下”。"}, {"text": "我很信任朋友，于是原谅了这份信任。", "explanation": "这里应该用〈珍惜〉。“原谅”针对过错，对这份信任应当珍惜，不能说“原谅”。"}, {"text": "这次比赛的结果很好，大家都原谅了它。", "explanation": "这里应该用〈满意〉。“原谅”针对别人的过错，对好的结果应表示满意，不能用“原谅”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95818, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前原谅他过两次。", "corrected_sentence": "我以前原谅过他两次。", "error_description": "体标位置错误：经历体“过”应紧跟动词“原谅”，说“原谅过他”；“原谅他过”的语序是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95818, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶很原谅了他。", "corrected_sentence": "奶奶终于原谅了他。", "error_description": "副词错误：“很”不能修饰动词“原谅”，应用“终于”表示最后的结果。错误句是“很原谅”，正确句是“终于原谅”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
