INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95819, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "受听是别人说的话，你听了觉得舒服，愿意听。", "primary_collocate": null, "pronunciation": "shòu tīng", "ipa": "ʂou˥˩ tʰiŋ˥", "syllable_count": 2, "sentences": [{"text": "他的话很受听，我们都爱跟他聊天。", "target_word": "受听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样说，我听着挺受听的。", "target_word": "受听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师先夸我，再提意见，这话受听多了。", "target_word": "受听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几句话说得客气，听起来很受听。", "target_word": "受听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的话不太受听，但是很有道理。", "target_word": "受听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说得太直，我觉得不受听。", "target_word": "受听", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友的安慰让我觉得很受听。", "target_word": "受听", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比起批评，表扬的话当然更受听。", "target_word": "受听", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这句话听着受听，可是不一定是真的。", "target_word": "受听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说话很受听，同事都喜欢和他聊天。", "target_word": "受听", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "别人的话听着舒服、愿意听", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '849abdb4-e94e-41e7-b194-cd99807ededa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95819, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刺耳", "is_correct": false, "explanation": "语义：刺耳形容声音难听，与“我们都爱跟他聊天”矛盾。"}, {"text": "受听", "is_correct": true, "explanation": "正确：受听形容别人的话听着舒服，符合“我们都爱跟他聊天”。"}, {"text": "粗鲁", "is_correct": false, "explanation": "语义：粗鲁形容态度不好，与“我们都爱跟他聊天”相矛盾。"}, {"text": "寂寞", "is_correct": false, "explanation": "搭配：寂寞形容人的心情，不用来修饰“话”。"}], "explanations": {"刺耳": "语义：刺耳形容声音难听，与“我们都爱跟他聊天”矛盾。", "受听": "正确：受听形容别人的话听着舒服，符合“我们都爱跟他聊天”。", "粗鲁": "语义：粗鲁形容态度不好，与“我们都爱跟他聊天”相矛盾。", "寂寞": "搭配：寂寞形容人的心情，不用来修饰“话”。"}, "sentence_index": 0, "correct_answer": "受听"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画很受听，很多人都来看。", "explanation": "这里应该用〈好看〉。受听只用来形容别人说的话，不用于形容画作。"}, {"text": "这块石头很受听，大家都喜欢它。", "explanation": "这里应该用〈好看〉。受听只用来形容别人说的话，不用于形容物品。"}, {"text": "这个孩子长得很受听，大家都夸她。", "explanation": "这里应该用〈好看〉。受听只形容别人说的话，不用于形容长相。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95819, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰冷", "is_correct": false, "explanation": "语义：冰冷形容温度或态度，不用来形容安慰带来的感觉。"}, {"text": "烫手", "is_correct": false, "explanation": "搭配：烫手描述触感，不能用来形容“让我觉得”的感受。"}, {"text": "受听", "is_correct": true, "explanation": "正确：受听形容别人的话听着舒服，符合“让我觉得很受听”。"}, {"text": "凶狠", "is_correct": false, "explanation": "语义：凶狠形容人的态度凶恶，与安慰的温和意思矛盾。"}], "explanations": {"冰冷": "语义：冰冷形容温度或态度，不用来形容安慰带来的感觉。", "烫手": "搭配：烫手描述触感，不能用来形容“让我觉得”的感受。", "受听": "正确：受听形容别人的话听着舒服，符合“让我觉得很受听”。", "凶狠": "语义：凶狠形容人的态度凶恶，与安慰的温和意思矛盾。"}, "sentence_index": 6, "correct_answer": "受听"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜很受听，大家吃得很开心。", "explanation": "这里应该用〈好吃〉。受听只形容别人说的话，不用于形容食物的味道。"}, {"text": "这束花很受听，闻起来很香。", "explanation": "这里应该用〈好闻〉。受听只形容话说得中听，不用于形容气味。"}, {"text": "这场比赛很受听，大家看得很激动。", "explanation": "这里应该用〈精彩〉。受听只用于形容话语，不用于形容比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95819, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这话没受听，我不爱听。", "corrected_sentence": "这话不受听，我不爱听。", "error_description": "形容词“受听”否定时要用“不”，不用“没”。说成“没受听”是错误的，应为“不受听”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95819, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一句很受听话，大家都爱听。", "corrected_sentence": "这是一句很受听的话，大家都爱听。", "error_description": "“受听”修饰名词“话”时要加“的”。说成“很受听话”是错误的，应为“很受听的话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
