INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95822, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "代数中的特殊元素，与任何元素运算后都保持该元素不变，如加法中的零、乘法中的一。", "primary_collocate": null, "pronunciation": "dān wèi yuán", "ipa": "tan˥ uei˥˩ ɥæn˧˥", "syllable_count": 3, "sentences": [{"text": "加法的单位元是零。", "target_word": "单位元", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "乘法的单位元是一。", "target_word": "单位元", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "整数集在加法下有一个单位元。", "target_word": "单位元", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师问我们乘法的单位元是什么。", "target_word": "单位元", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "任何数加上单位元都不变。", "target_word": "单位元", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这个群里，单位元只有一个。", "target_word": "单位元", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你找出这个运算的单位元。", "target_word": "单位元", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "零是加法的单位元，一是乘法的单位元。", "target_word": "单位元", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "单位元和别的元素运算，结果不变。", "target_word": "单位元", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书上说，每个群都必须有单位元。", "target_word": "单位元", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "代数里与任何元素运算都不改变它的特殊元素", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '849abdb4-e94e-41e7-b194-cd99807ededa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95822, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乘数", "is_correct": false, "explanation": "搭配：“乘数”属于乘法，不能说加法的乘数"}, {"text": "单位元", "is_correct": true, "explanation": "单位元是加法中的特殊元素，与任何数相加结果都不变，零正是加法的单位元"}, {"text": "质数", "is_correct": false, "explanation": "语义：零不是质数，质数不可能是零"}, {"text": "括号", "is_correct": false, "explanation": "语义：括号是符号，不是数，不能说加法的括号是零"}], "explanations": {"乘数": "搭配：“乘数”属于乘法，不能说加法的乘数", "单位元": "单位元是加法中的特殊元素，与任何数相加结果都不变，零正是加法的单位元", "质数": "语义：零不是质数，质数不可能是零", "括号": "语义：括号是符号，不是数，不能说加法的括号是零"}, "sentence_index": 0, "correct_answer": "单位元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在这个群里，每个元素都有唯一的单位元。", "explanation": "这里应该用〈逆元〉。单位元在一个群里只有一个，每个元素各有的是逆元，不能说每个元素都有单位元。"}, {"text": "与自身运算后保持不变的元素叫做单位元。", "explanation": "这里应该用〈幂等元〉。与自身运算后保持不变的是幂等元；单位元要求与任何元素运算后结果都不变。"}, {"text": "任何数乘以单位元都得零。", "explanation": "这里应该用〈零元〉。乘法中的单位元是一，乘以它结果不变；只有乘以零元才得零。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“运算”没有颜色，“颜色”不能和“运算”搭配"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的物件，运算不是书包，不能这样说"}, {"text": "单位元", "is_correct": true, "explanation": "单位元是运算中与任何元素运算都不改变对方的元素，这里指找出这样的元素"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”只用于人或动物，不能说运算的体重"}], "explanations": {"颜色": "搭配：“运算”没有颜色，“颜色”不能和“运算”搭配", "书包": "语义：书包是装东西的物件，运算不是书包，不能这样说", "单位元": "单位元是运算中与任何元素运算都不改变对方的元素，这里指找出这样的元素", "体重": "搭配：“体重”只用于人或动物，不能说运算的体重"}, "sentence_index": 6, "correct_answer": "单位元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个物理量的单位元是米。", "explanation": "这里应该用〈单位〉。“单位”是计量标准，单位元是代数中的特殊元素，不能用来说物理量的单位。"}, {"text": "半径为一的圆叫做单位元。", "explanation": "这里应该用〈单位圆〉。单位圆指半径为一的圆，与代数中的单位元不是同一个概念。"}, {"text": "这个向量长度为一，是一个单位元。", "explanation": "这里应该用〈单位向量〉。长度为一的向量叫单位向量，单位元指代数中的元素，不指向量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个群里只有一只单位元。", "corrected_sentence": "这个群里只有一个单位元。", "error_description": "量词错误：“单位元”应该用量词“个”，写成“一只单位元”不符合用法，“只”不用于这类抽象的数学概念。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每个群都必须是一个单位元。", "corrected_sentence": "每个群都必须有一个单位元。", "error_description": "动词错误：表示群里存在单位元应该用“有”，写成“是一个单位元”，意思错误，也不符合用法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77568508-8360-419d-8082-00a744674320') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
