INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95823, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95823, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地心是地球最中间的地方。", "primary_collocate": null, "pronunciation": "dì xīn", "ipa": "ti˥˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "地心离地面很远。", "target_word": "地心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地心的温度非常高。", "target_word": "地心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用仪器测量地心的压力。", "target_word": "地心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人说，地心有很热的铁。", "target_word": "地心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从地面到地心有六千多公里。", "target_word": "地心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想挖一个洞，一直挖到地心。", "target_word": "地心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了地心的图片。", "target_word": "地心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也没有去过地心。", "target_word": "地心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地心里的情况，人们还不太清楚。", "target_word": "地心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上画着地心的样子。", "target_word": "地心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "地球最中间的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97fe4c13-4834-4860-bdf7-8fe0ba852eb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95823, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地心", "is_correct": true, "explanation": "正确：地心是地球最中间的地方，离地面很远。"}, {"text": "地表", "is_correct": false, "explanation": "语义：地表本身就是地面的一部分，“离地面很远”说的是与地面不同的位置，地表与之矛盾。"}, {"text": "地面", "is_correct": false, "explanation": "语义：句中的参照点就是地面，“地面离地面很远”自相矛盾。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“离……很远”说的是具体的位置，心情不能用来测量距离。"}], "explanations": {"地心": "正确：地心是地球最中间的地方，离地面很远。", "地表": "语义：地表本身就是地面的一部分，“离地面很远”说的是与地面不同的位置，地表与之矛盾。", "地面": "语义：句中的参照点就是地面，“地面离地面很远”自相矛盾。", "心情": "搭配：“离……很远”说的是具体的位置，心情不能用来测量距离。"}, "sentence_index": 0, "correct_answer": "地心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们每天在平坦的地心上散步。", "explanation": "这里应该用〈地面〉。地心在地球最中间，人不能站在那里散步，散步的地方是地面。"}, {"text": "地心是人类居住的地方，城市都建在它上面。", "explanation": "这里应该用〈地球〉。地心只是地球中心的一个点，人类住在地球表面，不住在地心。"}, {"text": "地心的厚度大约有几十公里。", "explanation": "这里应该用〈地壳〉。地心在地球最中间，说地球外层有多厚要用〈地壳〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95823, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地心", "is_correct": true, "explanation": "正确：老师给我们看的是地心的图片。"}, {"text": "味道", "is_correct": false, "explanation": "语义：图片只能呈现看得见的东西，味道无法画成图片。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“看了……的图片”的宾语应是可以画出来的事物，脾气不能这样搭配。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“看了……的图片”的宾语应是具体可见的事物，重量不能这样搭配。"}], "explanations": {"地心": "正确：老师给我们看的是地心的图片。", "味道": "语义：图片只能呈现看得见的东西，味道无法画成图片。", "脾气": "搭配：“看了……的图片”的宾语应是可以画出来的事物，脾气不能这样搭配。", "重量": "搭配：“看了……的图片”的宾语应是具体可见的事物，重量不能这样搭配。"}, "sentence_index": 6, "correct_answer": "地心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人在地心挖了一条很长的隧道。", "explanation": "这里应该用〈地底〉。地底指地面以下的地方，可以挖隧道；地心是地球最中间的地方，离地面几千公里，不能在那里挖隧道。"}, {"text": "沙漠的地心白天非常热，晚上却很冷。", "explanation": "这里应该用〈地表〉。地表指地面，才有昼夜温差；地心在地球最中间，不随昼夜变化，不能用来说沙漠的温度。"}, {"text": "这个城市的地心有一座大公园。", "explanation": "这里应该用〈中心〉。地心专指地球的中心，不能用来指城市的中心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95823, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从来没有到了地心。", "corrected_sentence": "他从来没有到过地心。", "error_description": "错误：“没有”后面不能用“了”，写成“没有到了”。正确：“没有到过”，“过”表示从来没有过这种经历。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95823, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直想地心去。", "corrected_sentence": "他一直想到地心去。", "error_description": "错误：漏掉了“到”，写成“想地心去”。正确：“想到地心去”，“到”引出要去的地方，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
